-- The Generation 3 (Game Boy Advance) cartridge extractor.
--
-- WHY THIS IS NOT A BRANCH INSIDE RomExtractorGen2.
--
-- Gold, Silver, Crystal, Prism and Polished Crystal share one extractor
-- because they share a machine: banked ROM, 2bpp tiles, four greys, one text
-- engine, a `layout` key per cartridge for the strides that moved.  Emerald
-- shares none of that.  It is flat-addressed, 4bpp against sixteen colours of
-- 15-bit BGR, its assets are LZ77-compressed, its species are numbered in an
-- order that is not the Pokedex, and it has concepts the Gen 2 tables have no
-- column for at all -- abilities, natures, a split Special stat, EVs.
--
-- And it has no symbol table.  Every address this reads comes from
-- tools/gen3_discover.py, which finds each table structurally against the
-- cartridge and refuses to emit a manifest if any one of them is unproved.
-- Nothing here hardcodes an address; if the manifest lacks a symbol, the
-- stage that needs it says so and is skipped rather than reading whatever
-- happens to be at offset zero.
--
-- The CONTRACT is the same as Gen 2's, because the runtime's is: `new` takes
-- (romData, version, manifest, progress), `run` walks DATA_STAGES then
-- ASSET_STAGES, `write(name, table)` lands a module in data/generated, and
-- `saveImage` lands a PNG in assets/generated.

local RomGba = require("src.import.RomGba")
local Gen3ScriptOps = require("src.import.Gen3ScriptOps")
-- the flag NAMING lives with the VM that reads those names back, so an
-- object's eventFlag and a script's `setflag` cannot drift apart
local Gen3ScriptVM = require("src.script.Gen3ScriptVM")
local LuaWriter = require("src.import.LuaWriter")
local ImageWriter = require("src.import.ImageWriter")
local Logger = require("src.core.Logger")

local RomExtractorGen3 = {}
RomExtractorGen3.__index = RomExtractorGen3

-- The progress denominator.  Kept honest with the two stage lists below: a
-- mismatch does not break anything, it just makes the bar lie, which is the
-- kind of small wrongness that survives for months.
local STAGE_COUNT = 90

function RomExtractorGen3.new(romData, version, manifest, progress)
  return setmetatable({
    rom = RomGba.new(romData),
    version = version,
    manifest = manifest or {},
    symbols = (manifest or {}).symbols or {},
    layout = (manifest or {}).layout or {},
    progress = progress,
    stage = 0,
    counts = {},
  }, RomExtractorGen3)
end

-- ---------------------------------------------------------------------------
-- Manifest access
-- ---------------------------------------------------------------------------

-- A Gen 3 symbol is a FLAT offset, not Gen 2's [bank, address] pair: there
-- are no banks to name.  Returns nil rather than raising, so a stage can
-- degrade to "not extracted" instead of taking the whole import down.
function RomExtractorGen3:symbol(name)
  local value = self.symbols[name]
  if type(value) == "number" then return value end
  -- tolerate the Gen 2 pair shape if a manifest is ever written that way
  if type(value) == "table" and value[2] then return value[2] end
  return nil
end

function RomExtractorGen3:need(name, stage)
  local off = self:symbol(name)
  if not off then
    Logger.warn("gen3: %s is not in the manifest -- %s skipped", name, stage)
  end
  return off
end

function RomExtractorGen3:layoutValue(key, default)
  local v = tonumber(self.layout[key])
  return v or default
end

-- ---------------------------------------------------------------------------
-- Progress, output
-- ---------------------------------------------------------------------------

function RomExtractorGen3:beginStage(name)
  self.stage = self.stage + 1
  if self.progress then
    self.progress(self.stage - 1, STAGE_COUNT, name, 0, 1)
  end
end

function RomExtractorGen3:tick(name, current, total)
  if self.progress and total > 0 then
    self.progress(self.stage - 1 + current / total, STAGE_COUNT, name,
                  current, total)
  end
end

function RomExtractorGen3:write(name, value)
  LuaWriter.write("data/generated/" .. name .. ".lua", value)
end

function RomExtractorGen3:saveImage(image, relative)
  ImageWriter.save(image, "assets/generated/" .. relative)
end

-- ---------------------------------------------------------------------------
-- Text
--
-- Only the printable half is needed by the tables below -- names are plain
-- character runs closed by $FF.  The control block ($FA-$FE) belongs to the
-- dialogue decoder, which is its own piece of work; a name that contains one
-- would be a bug in the table, not something to paper over here.
-- ---------------------------------------------------------------------------

local EOS, NEWLINE = 0xFF, 0xFE

-- THE CONTROL BLOCK, verified by decoding the cartridge's own dialogue and
-- reading whether it makes sense -- not by assuming pokeemerald's constants.
--
--   $FA  scroll up one line and carry on (rendered "\v", as Gen 2's does)
--   $FB  wait for A, then clear the box and carry on ("\f")
--   $FC  an EXTENDED command: one selector byte, then that command's own
--        operands.  Rare -- 165 uses in the whole cartridge.
--   $FD  a PLACEHOLDER: one id byte naming what to splice in
--   $FE  line break
--   $FF  end of string
--
-- The placeholder ids were each confirmed against a line that uses them:
-- "{PLAYER} received the EFFORT RIBBON", "Oh, {RIVAL} went out to ROUTE 103",
-- and -- the decisive one -- "...to notice that you came\vto visit,
-- {PLAYER}{KUN}", which is exactly how Gen 3 spells the player's name plus
-- the honorific that is empty in English.
local TEXT_SCROLL, TEXT_PAGE = 0xFA, 0xFB
local TEXT_EXTENDED, TEXT_PLACEHOLDER = 0xFC, 0xFD

local PLACEHOLDERS = {
  [0x00] = "{UNKNOWN}", [0x01] = "{PLAYER}",
  [0x02] = "{VAR1}", [0x03] = "{VAR2}", [0x04] = "{VAR3}",
  [0x05] = "{KUN}", [0x06] = "{RIVAL}", [0x07] = "{VERSION}",
  [0x08] = "{AQUA}", [0x09] = "{MAGMA}", [0x0A] = "{ARCHIE}",
  [0x0B] = "{MAXIE}", [0x0C] = "{KYOGRE}", [0x0D] = "{GROUDON}",
}

-- How many operand bytes each $FC command takes, after its selector.  A wrong
-- width here does not raise -- it shifts the rest of the string and the line
-- comes out as garbage from that point on, which is the same failure mode a
-- wrong script operand width has.
local EXTENDED_OPERANDS = {
  [0x01] = 1,   -- colour
  [0x02] = 1,   -- highlight
  [0x03] = 1,   -- shadow
  [0x04] = 3,   -- colour + highlight + shadow together
  [0x05] = 1,   -- palette
  [0x06] = 1,   -- font size
  [0x07] = 0,   -- reset size
  [0x08] = 1,   -- pause n frames
  [0x09] = 0,   -- pause until the player presses A
  [0x0A] = 0,   -- wait for the sound effect to finish
  [0x0B] = 2,   -- play bgm
  [0x0C] = 1,   -- escape: the next byte is a literal, not a control code
  [0x0D] = 1,   -- shift right
  [0x0E] = 1,   -- shift down
  [0x0F] = 0,   -- fill window
  [0x10] = 2,   -- play sound effect
  [0x11] = 1,   -- clear n pixels
  [0x12] = 1,   -- skip to column n
  [0x13] = 1,   -- clear to column n
  [0x14] = 1,   -- minimum letter spacing
  [0x15] = 0, [0x16] = 0,   -- japanese / latin
  [0x17] = 0, [0x18] = 0,   -- pause and resume music
}

-- How many CHARACTERS a glyph is, not how many bytes: the cartridge's accented
-- e is two bytes of UTF-8 and one character, and telling a two-letter ligature
-- from an accented letter is the whole point of counting.
function RomExtractorGen3.utf8len(s)
  local n = 0
  for _ in tostring(s):gmatch("[^\128-\191]") do n = n + 1 end
  return n
end

function RomExtractorGen3:charmap()
  if self._charmap then return self._charmap end
  local map = {}
  for key, glyph in pairs(self.manifest.charmap or {}) do
    local code = tonumber(key)
    if code then map[code] = glyph end
  end
  self._charmap = map
  return map
end

-- GOING THE OTHER WAY: which byte spells a character.
--
-- Four stages need this -- they find a block of text by ENCODING a word they
-- already know and searching for it -- and all four built the same map the
-- same way: the lowest code that spells a glyph wins.
--
-- THAT RULE BROKE THE MOMENT THE POKéBLOCK LIGATURES WERE ADDED.  $55-$59
-- draw PO Ké BL OC K as one word, and the last of them is a single "K" --
-- at $59, far below the ordinary K at $C5.  "Lowest wins" therefore started
-- spelling ATTACK with a ligature, every needle stopped matching, and the
-- summary screen quietly went back to the port's own English.
--
-- A LIGATURE IS RECOGNISABLE FROM THE MAP ITSELF, which is what makes this a
-- rule rather than a list of exceptions: a ligature glyph is either longer
-- than one character, or it is the single-character TAIL of a run of them.
-- $53 PK, $54 MN, $55 PO, $56 Ké, $57 BL and $58 OC are all multi-character;
-- $59 K follows $58 and is the last letter of the same word.  Neither kind
-- may ever be the answer to "which byte spells K".
function RomExtractorGen3:charmapReverse()
  if self._charmapReverse then return self._charmapReverse end
  local map = self:charmap()
  local ligature = {}
  for code, glyph in pairs(map) do
    if type(glyph) == "string" and RomExtractorGen3.utf8len(glyph) > 1 then
      ligature[code] = true
    end
  end
  -- ...and the tail: a single-character glyph immediately after one
  local grew = true
  while grew do
    grew = false
    for code in pairs(map) do
      if not ligature[code] and ligature[code - 1] then
        ligature[code] = true
        grew = true
      end
    end
  end
  -- ONE CHARACTER PER BYTE, and ligatures out entirely.  The callers spell
  -- ordinary English words to search for -- ABLE, ATTACK, the keyboard's
  -- alphabet -- and the cartridge spells those with ordinary letters.  A map
  -- that could also spell "BL" as one byte turned ABLE into three bytes and
  -- the needle stopped matching; a ligature is for READING text, never for
  -- writing it.  "é" stays, because it is two bytes of UTF-8 and one
  -- character, which is the distinction being drawn.
  local reverse = {}
  for code, glyph in pairs(map) do
    if type(glyph) == "string" and not ligature[code]
       and RomExtractorGen3.utf8len(glyph) == 1
       and (reverse[glyph] == nil or code < reverse[glyph]) then
      reverse[glyph] = code
    end
  end
  self._charmapReverse = reverse
  return reverse
end

-- A NAME or other plain field: characters and line breaks only.  A control
-- code in one of these would be a bug in the table rather than something to
-- render, so they are spelled out as {BYTE:xx} instead of interpreted.
function RomExtractorGen3:readString(off, maxLength)
  local map = self:charmap()
  local out = {}
  for i = 0, (maxLength or 64) - 1 do
    local b = self.rom:u8(off + i)
    if b == EOS then break end
    if b == NEWLINE then
      out[#out + 1] = "\n"
    else
      out[#out + 1] = map[b] or ("{BYTE:%02X}"):format(b)
    end
  end
  return table.concat(out)
end

-- DIALOGUE: the full control block.  Returns the decoded text and how many
-- bytes it consumed, or nil when the run is not text at all -- which is what
-- makes it usable as a probe over unknown ROM as well as a reader for a
-- pointer that is known good.
-- `spacers` is how a caller keeps a control code that MEANS something on
-- screen.  The cartridge lays a price out with CLEAR_TO -- print the name,
-- jump the pen to column n, print the number -- and dropping it silently runs
-- the two together: "PROTEIN1,000".  A caller that is reading a menu row
-- passes { [0x13] = "  " } and gets the gap back; everything else is
-- unaffected, because an unlisted command is dropped exactly as before.
function RomExtractorGen3:readText(off, maxBytes, spacers)
  local map = self:charmap()
  local out = {}
  local i = 0
  local limit = maxBytes or 1024
  while i < limit do
    local ok, b = pcall(self.rom.u8, self.rom, off + i)
    if not ok then return nil end
    if b == EOS then
      return table.concat(out), i + 1
    elseif b == NEWLINE then
      out[#out + 1] = "\n"; i = i + 1
    elseif b == TEXT_SCROLL then
      out[#out + 1] = "\v"; i = i + 1
    elseif b == TEXT_PAGE then
      out[#out + 1] = "\f"; i = i + 1
    elseif b == TEXT_PLACEHOLDER then
      -- Only $00-$0D are placeholders.  Spelling an unknown id as
      -- "{PLACEHOLDER:BF}" and carrying on made the SCAN believe graphics data
      -- was dialogue -- the token's own letters satisfied the letter gate.
      local id = self.rom:u8(off + i + 1)
      local name = PLACEHOLDERS[id]
      if not name then return nil end
      out[#out + 1] = name
      i = i + 2
    elseif b == TEXT_EXTENDED then
      local cmd = self.rom:u8(off + i + 1)
      local operands = EXTENDED_OPERANDS[cmd]
      if not operands then return nil end     -- an unknown command means this
      if cmd == 0x0C then                     -- was never a string
        -- ESCAPE: the operand is a literal byte, control code or not
        out[#out + 1] = map[self.rom:u8(off + i + 2)] or ""
      elseif spacers and spacers[cmd] then
        out[#out + 1] = spacers[cmd]
      end
      i = i + 2 + operands
    else
      local glyph = map[b]
      if glyph == nil then return nil end
      out[#out + 1] = glyph
      i = i + 1
    end
  end
  return nil
end

-- A fixed-width name table: `count` slots of `stride` bytes each.
function RomExtractorGen3:names(symbolName, stride, count, stage)
  local base = self:need(symbolName, stage)
  if not base then return nil end
  local out = {}
  for i = 0, count - 1 do
    out[i] = self:readString(base + i * stride, stride)
  end
  return out
end

-- ---------------------------------------------------------------------------
-- Identifiers
--
-- The engine keys everything by a STRING id, and Gen 3's names are not
-- unique-safe on their own: "?" appears 25 times in the species table (the
-- unused internal slots), and names carry spaces, the cartridge's own e-acute
-- and, in the item table, punctuation.  So an id is the name upper-cased and
-- reduced to [A-Z0-9_], with the internal index appended whenever that would
-- otherwise collide -- never silently overwriting a row.
-- ---------------------------------------------------------------------------

local function slug(name)
  local s = tostring(name or ""):upper()
  s = s:gsub("\195\169", "E")          -- the cartridge's e-acute
  s = s:gsub("[^A-Z0-9]+", "_")
  s = s:gsub("^_+", ""):gsub("_+$", "")
  return s
end

local function uniqueId(taken, base, index, prefix)
  if base == "" or base == nil then
    base = ("%s_%03d"):format(prefix, index)
  end
  if not taken[base] then
    taken[base] = true
    return base
  end
  local id = ("%s_%03d"):format(base, index)
  taken[id] = true
  return id
end

-- ---------------------------------------------------------------------------
-- STAGE: constants
--
-- The order arrays every other module is indexed against.  Gen 3's species
-- numbering is INTERNAL: 1-251 agree with the National Dex, 252-276 are 25
-- unused slots the cartridge fills with "?", and Hoenn runs 277-411.  The
-- unused slots are kept in the order array rather than skipped, because every
-- other table in the ROM is indexed by that same internal number -- dropping
-- them would shift all of Hoenn by 25.
-- ---------------------------------------------------------------------------

-- struct ObjectEventGraphicsInfo, the fields the player-avatar derivation
-- reads.  The packed byte at +12 is `paletteSlot:4, shadowSize:2,
-- inanimate:1, disableReflectionPaletteLoad:1`, so the reflection flag is its
-- top bit; `tracks` at +13 is TRACKS_NONE / TRACKS_FOOT / TRACKS_BIKE_TIRE.
local GEN3_GFX_INFO_PALETTE = 2
local GEN3_GFX_INFO_WIDTH = 8
local GEN3_GFX_INFO_FLAGS = 12
local GEN3_GFX_INFO_TRACKS = 13
local GEN3_GFX_NO_REFLECTION = 0x80
local GEN3_GFX_TRACKS_BIKE = 2

-- WHICH MOVEMENT TYPE HIDES ITS OBJECT, read out of the callbacks.
--
-- The chain is the same for all eighty-one: the type's callback names a
-- sub-callback in its literal pool, the sub-callback names a step table in
-- its own, and the step table's first word is step 0.  Step 0 of exactly one
-- of them sets bit 5 of the object's byte 1, which is `invisible`.
--
-- `poolWords` reads the words a PC-relative `ldr` in the first few
-- instructions of a function would load -- which is the only way a Thumb
-- function can name an address at all.
RomExtractorGen3.MOVEMENT_HIDES = {
  -- ldrb r0,[r4,#1] / mov r1,#32 / orr r0,r1 / strb r0,[r4,#1]
  SET_INVISIBLE = { 0x7860, 0x2120, 0x4308, 0x7060 },
  SCAN = 24,      -- halfwords of step 0 to look through
  POOL = 16,      -- instructions of a function to collect literals from
}

function RomExtractorGen3:poolWords(at, count)
  local out = {}
  for i = 0, (count or 16) - 1 do
    local h = self.rom:u16(at + i * 2)
    -- LDR Rd, [PC, #imm8]
    if math.floor(h / 2048) == 0x09 then
      local pc = at + i * 2 + 4
      local base = pc - (pc % 4)
      local ok, word = pcall(self.rom.u32, self.rom, base + (h % 256) * 4)
      if ok then out[#out + 1] = word end
    end
  end
  return out
end


-- A ROM pointer as a flat offset, or nil when the word is not one.  On the
-- class rather than a file local: this chunk is already at Lua's 200-local
-- ceiling and one more at file scope will not load.
function RomExtractorGen3.romOffset(word)
  if type(word) ~= "number" then return nil end
  local flat = word - 0x08000000
  if flat < 0 or flat >= 0x02000000 then return nil end
  return flat
end

-- The BL targets in the first `count` instructions of a Thumb function.  A
-- Thumb BL is two halfwords -- 0xF000 | hi11, 0xF800 | lo11 -- and the pair
-- reaches +-4MB, which is the only way one of these callbacks names a shared
-- helper (the helpers are not in its literal pool; only data and *stored*
-- function pointers are).
function RomExtractorGen3:blTargets(at, count)
  local out = {}
  local i = 0
  while i < (count or 64) - 1 do
    local okA, hi = pcall(self.rom.u16, self.rom, at + i * 2)
    local okB, lo = pcall(self.rom.u16, self.rom, at + i * 2 + 2)
    if not (okA and okB) then break end
    if math.floor(hi / 2048) == 0x1E and math.floor(lo / 2048) == 0x1F then
      local high = hi % 2048
      if high >= 1024 then high = high - 2048 end
      local pc = at + i * 2 + 4
      out[#out + 1] = pc + high * 4096 + (lo % 2048) * 2
      i = i + 2
    else
      i = i + 1
    end
  end
  return out
end

-- ---------------------------------------------------------------------------
-- WHERE A PARTICLE GOES
--
-- Reported from play: "Many move animations/fx arent working properly ... surf
-- isnt showing the wave going through and hitting the enemy pokemon ... i
-- think many more are missing".  This screen's own header used to say why, and
-- said it was unknowable: "where a particle GOES after it is spawned is a C
-- function in the cartridge, and no symbol names it".
--
-- That is true of the four hundred move-specific ones.  It is NOT true of the
-- handful they all lean on, because those are shared -- and a function shared
-- by two hundred callers can be found by its shape and then confirmed by what
-- the moves that use it are known to look like.
--
--   StartAnimLinearTranslation (080A6EEC) is four halfwords long before its
--   first call: data[1] = pos1.x, data[3] = pos1.y -- ldrh/strh from +32 to
--   +48 and +34 to +52 -- then InitAnimLinearTranslation and a handoff.  Any
--   callback with that address in its literal pool AND stored to sprite+28
--   (the callback field) is translating its particle from where it stands to
--   data[2],data[4] over data[0] frames.
--
--   InitSpritePosToAnimAttacker (080A69CC) and InitSpritePosToAnimTarget
--   (080A6980) are the same routine over two adjacent bytes -- gBattleAnimAttacker
--   at $02038436 and gBattleAnimTarget at $02038437 -- and each puts the
--   sprite on ITS battler before anything else happens.  Cmd_createsprite
--   spawns every particle on the target, so a callback that calls the
--   attacker one has moved it to the other side of the field first: that
--   particle FLIES ACROSS.
--
-- WHERE IT LANDS is the one step that is inferred rather than read.
-- StartAnimLinearTranslation carries the sprite to data[2],data[4], and the
-- callbacks that set those do it through a helper rather than naming
-- gBattleAnimTarget in their own literal pool -- none of the 288 does.  What
-- IS read is the sequence: the particle spawns on the target, its callback
-- moves it to the attacker, and then it translates.  A projectile that did
-- that and landed anywhere but back on the target would be a bug on hardware,
-- and the three moves below behave as they do on a Game Boy Advance, so the
-- destination is taken to be the target and nothing else is claimed.
--
-- Each address is checked before it is believed -- the two shapes above, and
-- the two RAM bytes in the right order -- and if any check fails no particle
-- gets a motion and the screen draws exactly what it drew before.
--
-- THE CORROBORATION, which is the part that matters: classified this way,
-- EMBER's three flames and ICE BEAM's five beam segments come out
-- attacker-to-target, THUNDERBOLT's seventeen come out fixed on the target,
-- and SWORDS DANCE -- whose target IS its user -- comes out translating
-- between two points that are the same place.  That is what those four moves
-- look like on a Game Boy Advance.
RomExtractorGen3.ANIM_MOTION = {
  START_LINEAR = 0x0A6EEC,
  DRIFT        = 0x0A656C,
  INIT_ATTACKER = 0x0A69CC,
  INIT_TARGET   = 0x0A6980,
  ATTACKER_BYTE = 0x02038436,
  TARGET_BYTE   = 0x02038437,
  -- data[1] = pos1.x ; data[3] = pos1.y
  LINEAR_SHAPE = { 0x8c20, 0x8620, 0x8c60, 0x86a0 },
  LINEAR_AT = 2,
  -- ldrh r1,[r2,#46] -- the drift routine opens on data[0]
  DRIFT_SHAPE = { 0x8dd1 },
  DRIFT_AT = 2,
  SCAN = 200,
  -- a duration operand has to look like one
  MIN_FRAMES = 1, MAX_FRAMES = 120,
}

-- ---------------------------------------------------------------------------
-- THE MON THAT SPLITS IN TWO
--
-- Reported from play: "double team doesnt show the pokemon shift back and
-- forth".  It showed nothing at all: DOUBLE TEAM spawns no particles, its
-- whole animation is one `createvisualtask`, and there is no general decode
-- for those -- 174 distinct task functions, most of them one move's own.
--
-- This one is worth reading by hand because it is the shape the report names,
-- and because everything it does is arithmetic that can be reproduced exactly.
-- The task (08:$1029B4):
--
--     GetAnimBattlerSpriteId(ANIM_ATTACKER) -> the mon to copy
--     AllocSpritePalette($2771)             -- a palette of its own
--     for i = 0, 1:                          -- TWO copies, and no more
--         copy->data[1] = i * 128            -- half a sine period apart
--         copy->data[2] = the attacker's sprite
--         copy->callback = 08:$102B3D
--
-- ...and the copy's callback is the motion:
--
--     data[3]++; every SECOND frame data[0]++
--     data[0] > 64  -> the copy is destroyed        (so 64 steps, 128 frames)
--     data[4] = gSineTable[data[0]] / 6             -- the radius, GROWING
--     data[5] = gSineTable[data[0]] / 13            -- the angular step
--     data[1] = (data[1] + data[5]) & 255           -- the angle, advancing
--     pos2.x  = Sin(data[1], data[4])               -- and only x is written
--
-- Two ghosts of the Pokemon swinging HORIZONTALLY, in opposite phase, over an
-- arc that widens as the animation runs.  That is "shift back and forth", and
-- every constant in it -- the two copies, the 64 steps, the two frames a step,
-- the half-period offset, the divisors 6 and 13 -- is the cartridge's.
--
-- gSineTable is taken whole rather than recomputed: the motion is integer
-- division of the table's own values, and a sine computed here would round
-- differently in the low digits.
RomExtractorGen3.ANIM_AFTERIMAGE = {
  TASK = 0x1029B4,
  COPY = 0x08102B3D,    -- the per-copy callback the task installs
  SINE = 0x08329F40,    -- gSineTable, which the copy's callback indexes
  SINE_ENTRIES = 256,
  COPIES = 2, STEPS = 64, FRAMES_PER_STEP = 2,
  PHASE_STEP = 128, RADIUS_DIV = 6, ANGLE_DIV = 13,
  POOL = 120,
}

-- ---------------------------------------------------------------------------
-- THE POKEMON THAT SQUASHES, AND THIS TIME IT IS DATA
--
-- SPLASH, MEDITATE and TELEPORT drew the coarse flash.  All three hand their
-- battler to one shared routine, PrepareAffineAnimInTaskData (08:$0A7CFC),
-- with a POINTER TO A TABLE -- and that table is the whole animation.
--
-- The routine gives itself away: it zeroes the task's own affine fields, sets
-- both scales to 256, and then splits its third argument into two halves
-- stashed at task+34 and task+36 (08:$0A8048 does exactly that and nothing
-- else) before handing the sprite to the rot/scale preparer.  A 32-bit
-- pointer kept in two halfwords is a pointer being kept, and what it points
-- at is a run of eight-byte records:
--
--     s16 xScale ; s16 yScale ; u8 rotation ; u8 duration ; u16 padding
--
-- closed by $7FFF.  The scales are DELTAS PER FRAME, added for `duration`
-- frames, and GBA affine scale is a divisor -- so a NEGATIVE delta makes the
-- Pokemon wider, not narrower.
--
--     SPLASH    (-6,+4) x8   (+10,-10) x8  (-4,+6) x8    -- squash, stretch, settle
--     MEDITATE  (-8,+10) x16 (+18,-18) x16 (-20,+16) x8
--     TELEPORT  (+64,-4) x20 (0,0) x200                  -- squeezes thin and holds
--
-- AND THE FIRST TWO CLOSE ON THEMSELVES: sum(delta * duration) is zero on
-- both axes, so the Pokemon ends the animation exactly the size it started.
-- That is the check on the whole table at once -- a stride or a sign read
-- wrong does not come back to zero.  TELEPORT does not close, and should not:
-- it leaves.
RomExtractorGen3.MON_AFFINE = {
  PREPARE = 0x0A7CFC,         -- PrepareAffineAnimInTaskData
  SPLIT = 0x0A8048,           -- the two-halfword stash it uses for the pointer
  ROTSCALE = 0x0A7270,        -- ...and the preparer it ends on
  END = 0x7FFF, LOOP = 0x7FFD, JUMP = 0x7FFE,
  STRIDE = 8, MAX_STEPS = 16, MIN_STEPS = 2,
  BASE = 256,                 -- what the routine sets both scales to
  MAX_DELTA = 512, MAX_DURATION = 255,
  SCAN = 240,
}

-- Is the shared preparer the one this stage was read from?
function RomExtractorGen3:affinePreparer()
  if self._affinePrep ~= nil then return self._affinePrep or nil end
  local A = RomExtractorGen3.MON_AFFINE
  local split, prep = false, false
  for _, t in ipairs(self:blTargets(A.PREPARE, 32)) do
    if t == A.SPLIT then split = true end
    if t == A.ROTSCALE then prep = true end
  end
  if not (split and prep) then
    Logger.warn("gen3 move animations: the affine preparer does not read as "
                  .. "itself, so no Pokemon squashes")
    self._affinePrep = false
    return nil
  end
  self._affinePrep = true
  return true
end

-- The table one task hands it, read whole, or nil.
function RomExtractorGen3:affineTable(taskFn)
  local A = RomExtractorGen3.MON_AFFINE
  if not self:affinePreparer() then return nil end
  local at = taskFn - (taskFn % 2)
  local calls = false
  for _, t in ipairs(self:blTargets(at, A.SCAN)) do
    if t == A.PREPARE then calls = true break end
  end
  if not calls then return nil end
  local rom = self.rom
  for _, w in ipairs(self:poolWords(at, A.SCAN)) do
    if w >= 0x08000000 and w < 0x09000000 then
      local flat = w - 0x08000000
      local steps, ok = {}, false
      for i = 0, A.MAX_STEPS - 1 do
        local okA, first = pcall(rom.u16, rom, flat + i * A.STRIDE)
        if not okA then break end
        if first == A.END then ok = #steps >= A.MIN_STEPS break end
        if first == A.LOOP or first == A.JUMP then break end
        local dx = first >= 32768 and first - 65536 or first
        local okB, second = pcall(rom.u16, rom, flat + i * A.STRIDE + 2)
        local okC, rot = pcall(rom.u8, rom, flat + i * A.STRIDE + 4)
        local okD, dur = pcall(rom.u8, rom, flat + i * A.STRIDE + 5)
        local okE, pad = pcall(rom.u16, rom, flat + i * A.STRIDE + 6)
        if not (okB and okC and okD and okE) then break end
        -- the two padding bytes are what says the stride is eight and not six
        if pad ~= 0 then break end
        local dy = second >= 32768 and second - 65536 or second
        if math.abs(dx) > A.MAX_DELTA or math.abs(dy) > A.MAX_DELTA then break end
        if dur < 1 or dur > A.MAX_DURATION then break end
        steps[#steps + 1] = { dx = dx, dy = dy, rot = rot, dur = dur }
      end
      if ok then
        local life, sx, sy = 0, 0, 0
        for _, st in ipairs(steps) do
          life = life + st.dur
          sx = sx + st.dx * st.dur
          sy = sy + st.dy * st.dur
        end
        return { at = flat, steps = steps, life = life, base = A.BASE,
                 -- whether it comes back the size it started, which is a fact
                 -- about the table rather than a requirement of it
                 closes = (sx == 0 and sy == 0) or nil }
      end
    end
  end
  return nil
end

-- ---------------------------------------------------------------------------
-- THE SAME FADE, ASKED FOR THE OTHER WAY
--
-- Forty-three moves ask for a palette fade and none of them got one, and the
-- reason is the same door the run-up came through: they ask with an INVISIBLE
-- SPRITE rather than with a task.  The blend pass reads `createvisualtask`
-- calls and this is a `createsprite` whose template has no art -- the sprite
-- hides itself on its first line and exists only to make the call.
--
-- And the call is one the blend pass ALREADY KNOWS HOW TO READ.  The callback
-- unpacks its first argument through the same seven-bit unpacker the
-- six-argument blend uses (08:$A75AC) and hands the other four to
-- BeginNormalPaletteFade (08:$A1AD4) -- so the five arguments are
--
--     (selector, delay, from, to, colour)
--
-- in the same order, with the same meanings.  Nothing new has to be read:
-- what was missing was the door, not the reader.
RomExtractorGen3.MON_FADE = {
  CALLBACK = 0x1157FC,        -- the invisible sprite's own callback
  UNPACK = 0x11583C,          -- ...which unpacks the selector
  MASK = 0x0A75AC,            -- ...through the blend pass's own mask builder
  FADE = 0x0A1AD4,            -- BeginNormalPaletteFade
  INVISIBLE = { at = 0x26, op = 0x2100, bit = 4 },  -- mov r1,#4, the OAM bit
  ARGS = 5,
  SCAN = 40,
}

function RomExtractorGen3:monFade()
  if self._monFade ~= nil then return self._monFade or nil end
  local F = RomExtractorGen3.MON_FADE
  local rom = self.rom
  local function fail(why)
    Logger.warn("gen3 move animations: %s, so the moves that fade a palette "
                  .. "through an invisible sprite keep whatever they had", why)
    self._monFade = false
    return nil
  end
  local okI, hid = pcall(rom.u16, rom, F.CALLBACK + F.INVISIBLE.at)
  if not (okI and math.floor(hid / 256) * 256 == F.INVISIBLE.op
          and hid % 256 == F.INVISIBLE.bit) then
    return fail("the fade's sprite does not hide itself")
  end
  local unpacks, fades = false, false
  for _, t in ipairs(self:blTargets(F.CALLBACK, F.SCAN)) do
    if t == F.UNPACK then unpacks = true end
    if t == F.FADE then fades = true end
  end
  local masks = false
  for _, t in ipairs(self:blTargets(F.UNPACK, F.SCAN)) do
    if t == F.MASK then masks = true break end
  end
  if not (unpacks and fades and masks) then
    return fail("the fade's sprite does not unpack a selector and start a "
                  .. "palette fade")
  end
  self._monFade = {
    callback = F.CALLBACK,
    source = ("ROM:the fade sprite's callback at %07X, its unpacker at %07X "
              .. "and BeginNormalPaletteFade %07X")
             :format(F.CALLBACK, F.UNPACK, F.FADE),
  }
  return self._monFade
end

-- ---------------------------------------------------------------------------
-- THE RUN-UP
--
-- Twenty-five moves -- TACKLE and SPARK and ROCK BLAST among them -- move the
-- Pokemon at the one it is hitting and back again, and none of them did.  The
-- reason they were missed is worth stating, because it is a whole door rather
-- than one move: this is not a `createvisualtask`, it is a `createsprite`
-- WHOSE SPRITE IS NOT A PICTURE.
--
-- The template has no tile tag -- it draws nothing, and the particle reader
-- refuses it for exactly that reason -- and the sprite exists only so that
-- its CALLBACK can push the battler around.  The first thing that callback
-- does is set its own invisible bit, which is the cartridge saying so out
-- loud.
--
--     args = (frames, pixels a frame)
--
-- It hands the sprite to a translator (08:$A6630) that adds those pixels to
-- the ATTACKER's own pos2 every frame for that many frames, then to a second
-- callback (08:$D58D4) that refills the counter, NEGATES the step, and runs
-- the same translator again -- so it goes out and comes back, and comes back
-- exactly as far as it went.  TACKLE's four-by-four is sixteen pixels of
-- run-up over four frames and sixteen back over four.
--
-- WHICH WAY IS FORWARD.  The step is negated when the attacker is NOT on the
-- player's side, which says the number in the script is the PLAYER's -- and
-- that is a fact the renderer needs, because its own mirror assumes the
-- opposite for the offsets a particle carries.
RomExtractorGen3.MON_RUNUP = {
  CALLBACK = 0x0D5860,        -- the dummy sprite's own callback
  TRANSLATE = 0x0A6630,       -- adds data[1],data[2] to the battler each frame
  RETURN = 0x0D58D4,          -- ...and the one that sends it back
  STORE = 0x0A62D4,           -- StoreSpriteCallbackInData6
  SIDE = 0x0A6A30,            -- GetBattlerSide, which decides the sign
  INVISIBLE = { at = 0x0A, op = 0x2100, bit = 4 },   -- mov r1,#4, the OAM bit
  ARGS = 2, MAX_FRAMES = 60, MAX_STEP = 64,
  SCAN = 60,
}

function RomExtractorGen3:monRunup()
  if self._monRunup ~= nil then return self._monRunup or nil end
  local R = RomExtractorGen3.MON_RUNUP
  local rom = self.rom
  local function fail(why)
    Logger.warn("gen3 move animations: %s, so the twenty-five moves that run "
                  .. "at their target keep whatever they had", why)
    self._monRunup = false
    return nil
  end
  -- IT HIDES ITSELF FIRST.  A sprite that draws nothing and says so is the
  -- one this is looking for; a template with art that happened to have no tag
  -- would not.
  local okI, hid = pcall(rom.u16, rom, R.CALLBACK + R.INVISIBLE.at)
  if not (okI and math.floor(hid / 256) * 256 == R.INVISIBLE.op
          and hid % 256 == R.INVISIBLE.bit) then
    return fail("the run-up's sprite does not hide itself")
  end
  local side, store = false, false
  for _, t in ipairs(self:blTargets(R.CALLBACK, R.SCAN)) do
    if t == R.SIDE then side = true end
    if t == R.STORE then store = true end
  end
  local installs, returns = false, false
  for _, w in ipairs(self:poolWords(R.CALLBACK, R.SCAN)) do
    if w == R.TRANSLATE + 1 + 0x08000000 then installs = true end
    if w == R.RETURN + 1 + 0x08000000 then returns = true end
  end
  if not (side and store and installs and returns) then
    return fail("the run-up does not ask which side it is on and install a "
                  .. "translator with a way back")
  end
  -- ...and the way back really does negate and re-run
  local negates, again = false, false
  local okN, neg = pcall(rom.u16, rom, R.RETURN + 0x08)
  if okN and neg == 0x4249 then negates = true end       -- neg r1,r1
  for _, w in ipairs(self:poolWords(R.RETURN, 32)) do
    if w == R.TRANSLATE + 1 + 0x08000000 then again = true end
  end
  if not (negates and again) then
    return fail("the run-up's second leg does not turn round")
  end
  self._monRunup = {
    callback = R.CALLBACK,
    source = ("ROM:the run-up sprite's callback at %07X, the translator at "
              .. "%07X and its way back at %07X")
             :format(R.CALLBACK, R.TRANSLATE, R.RETURN),
  }
  return self._monRunup
end

-- One script's call, walked into the track it produces.
function RomExtractorGen3:runupTrack(args, shape)
  local R = RomExtractorGen3.MON_RUNUP
  if type(args) ~= "table" or #args < R.ARGS then return nil end
  local frames, pixels = args[1], args[2]
  if frames < 1 or frames > R.MAX_FRAMES then return nil end
  if pixels == 0 or math.abs(pixels) > R.MAX_STEP then return nil end
  local xs, at = {}, 0
  for _ = 1, frames do
    at = at + pixels
    xs[#xs + 1] = at
  end
  for _ = 1, frames do
    at = at - pixels
    xs[#xs + 1] = at
  end
  -- ...AND IT COMES BACK TO WHERE IT STARTED, because the second leg is the
  -- first one negated and the counter is refilled from a copy of the same
  -- argument.  A track that did not would leave the Pokemon off its platform.
  if xs[#xs] ~= 0 then return nil end
  return {
    callback = shape.callback,
    xs = xs, life = #xs,
    authoredForPlayer = true,
    source = shape.source,
  }
end

-- ---------------------------------------------------------------------------
-- THE POKEMON THAT CHANGES COLOUR, ON ITS OWN SPRITE PALETTE
--
-- Eleven moves -- RAGE, SUPER FANG, FLAME WHEEL, FORESIGHT, HIDDEN POWER,
-- TORMENT, HELPING HAND, RECYCLE, ENDEAVOR, SKILL SWAP and EXTRASENSORY --
-- call a pair of functions (08:$A7B98 into 08:$A7BF4) that the blend pass
-- does not recognise, and every one of those calls was thrown away.
--
-- The blend pass reads the calls whose FIRST argument is a bitfield of
-- battlers.  This one's first argument is a battler INDEX, and the wrapper's
-- whole job is to turn that into a palette: it fetches the sprite, reads the
-- OAM's own palette number out of it, and builds the offset-and-count word
-- BlendPalette wants.  A move that names one Pokemon's own palette rather
-- than a set of them takes this door instead, and both doors lead to the same
-- ramp.
--
--     args = (battler, colour, coefficient, frames per step, cycles)
--
-- and the step is the ramp every other blend in this engine already is: the
-- coefficient climbs to `coefficient`, comes back to zero, and that is one
-- cycle spent.  `colour` is a raw 15-bit GBA colour -- 31 is red, 32767 is
-- white, 891 is the yellow EXTRASENSORY flashes -- and a coefficient above
-- SIXTEEN would be one BlendPalette cannot take, which is the check.
--
-- A first argument of 2 names the attacker's PARTNER.  In a single battle the
-- cartridge's own lookup answers 255 and the task destroys itself on the
-- spot; this port draws one Pokemon a side, so those calls are dropped here
-- for the same reason.
RomExtractorGen3.MON_CYCLE = {
  WRAP = 0x0A7B98,            -- takes a battler, finds its palette
  SETUP = 0x0A7BF4,           -- ...and stashes the rest of the arguments
  STEP_FN = 0x080A7C1D,
  STEP = 0x0A7C1C,
  SPRITE = 0x0A6240,          -- GetAnimBattlerSpriteId
  BLEND = 0x06F98C,           -- BlendPalette
  -- the four arguments the setup copies, as the four instructions that copy
  -- them, at their offsets from SETUP
  COPY = { { at = 0x02, word = 0x8859 }, { at = 0x0A, word = 0x8899 },
           { at = 0x10, word = 0x88D9 }, { at = 0x16, word = 0x8919 } },
  ARGS = 5,
  MAX_COEFF = 16,             -- BlendPalette's coefficient is 0..16
  MAX_COLOUR = 0x7FFF,        -- ...and a GBA colour is fifteen bits
  MAX_STEP = 32, MAX_CYCLES = 32,
  PARTNER = 2,                -- the selector a single battle has nobody for
  SCAN = 120,
}

function RomExtractorGen3:monCycle()
  if self._monCycle ~= nil then return self._monCycle or nil end
  local C = RomExtractorGen3.MON_CYCLE
  local rom = self.rom
  local function fail(why)
    Logger.warn("gen3 move animations: %s, so the eleven moves that flash one "
                  .. "Pokemon's own palette keep whatever they had", why)
    self._monCycle = false
    return nil
  end
  local sprite, setup = false, false
  for _, t in ipairs(self:blTargets(C.WRAP, C.SCAN)) do
    if t == C.SPRITE then sprite = true end
    if t == C.SETUP then setup = true end
  end
  if not (sprite and setup) then
    return fail("the colour-cycle wrapper does not fetch a sprite and hand on")
  end
  local installs = false
  for _, w in ipairs(self:poolWords(C.SETUP, C.SCAN)) do
    if w == C.STEP_FN then installs = true break end
  end
  local blends = false
  for _, t in ipairs(self:blTargets(C.STEP, C.SCAN)) do
    if t == C.BLEND then blends = true break end
  end
  if not (installs and blends) then
    return fail("the colour cycle does not install a step that blends a "
                  .. "palette")
  end
  for i, spec in ipairs(C.COPY) do
    local ok, h = pcall(rom.u16, rom, C.SETUP + spec.at)
    if not (ok and h == spec.word) then
      return fail(("argument %d is not copied where the cycle keeps it")
                  :format(i))
    end
  end
  self._monCycle = {
    task = C.WRAP,
    source = ("ROM:the colour cycle at %07X into %07X, its step at %07X and "
              .. "BlendPalette %07X"):format(C.WRAP, C.SETUP, C.STEP, C.BLEND),
  }
  return self._monCycle
end

-- One script's call, as the blend record this engine already plays.
function RomExtractorGen3:cycleBlend(args, shape)
  local C = RomExtractorGen3.MON_CYCLE
  if type(args) ~= "table" or #args < C.ARGS then return nil end
  local battler, colour, coeff, step, cycles = args[1], args[2], args[3],
                                               args[4], args[5]
  -- the partner selector, which a single battle has nobody for
  if battler == C.PARTNER then return nil end
  if battler < 0 or battler > 1 then return nil end
  if colour < 0 or colour > C.MAX_COLOUR then return nil end
  if coeff < 1 or coeff > C.MAX_COEFF then return nil end
  if step < 1 or step > C.MAX_STEP then return nil end
  if cycles < 1 or cycles > C.MAX_CYCLES then return nil end
  return {
    task = shape.task,
    target = battler == 1 or nil,
    from = 0, to = coeff, step = step, cycles = cycles,
    colour = colour,
    source = shape.source,
  }
end

-- ---------------------------------------------------------------------------
-- THE POKEMON THAT LUNGES
--
-- TAKE DOWN, BRICK BREAK, SPIKE CANNON and SNATCH share a task (08:$D5C50)
-- that carries SEVEN arguments -- the widest in the family -- and every one
-- of those calls was thrown away.  It is the run-up: the Pokemon slides
-- across the field on an arc, waits, and slides back.
--
--     args = (battler, out, arc, outFrames, wait, back, backFrames)
--
-- Both slides are kept in EIGHTHS OF A PIXEL: the setup divides the distance
-- by the frame count with the numerator shifted eight left, and the step
-- shifts the accumulator eight right on the way to the sprite.  That is the
-- cartridge doing fixed point with two instructions, and it is why a slide of
-- twelve pixels over ten frames does not stutter.
--
-- The arc is a Sin over the first phase: the accumulator gains 32768 divided
-- by the frame count each frame and its top byte indexes the table, so the
-- index travels exactly 128 -- HALF a period, one hump -- over the slide,
-- however long the slide is.  That is the check on the whole first phase at
-- once: a frame count read wrong and the hop no longer lands where the slide
-- does.
--
-- Then a wait of `args[4]` frames, then the second slide, and the task simply
-- ends -- it does not put the Pokemon back, because on the cartridge the
-- battle controller does.  In this port the track running out is the same
-- thing: an offset with no frame left is no offset.
RomExtractorGen3.MON_LUNGE = {
  TASK = 0x0D5C50, OUT = 0x0D5CE4, BACK = 0x0D5D48,
  OUT_FN = 0x080D5CE5, BACK_FN = 0x080D5D49,
  SIN = 0x06F534,
  DIV = 0x2E7540,             -- __divsi3, which both slides are cut with
  ARGS = 7,
  HALF_TURN = 32768,          -- what the arc's accumulator covers in phase one
  FIXED = 256,                -- ...and the eighth-of-a-pixel the slides use
  MAX_TRAVEL = 160, MAX_FRAMES = 120, MAX_ARC = 64,
  SCAN = 200,
}

-- The lunge's shape, without any move's numbers.
function RomExtractorGen3:monLunge()
  if self._monLunge ~= nil then return self._monLunge or nil end
  local L = RomExtractorGen3.MON_LUNGE
  local function fail(why)
    Logger.warn("gen3 move animations: %s, so the four moves that lunge keep "
                  .. "whatever they had", why)
    self._monLunge = false
    return nil
  end
  -- the setup cuts two distances with __divsi3 and installs the first slide
  local divs = 0
  for _, t in ipairs(self:blTargets(L.TASK, L.SCAN)) do
    if t == L.DIV then divs = divs + 1 end
  end
  local installs = false
  for _, w in ipairs(self:poolWords(L.TASK, L.SCAN)) do
    if w == L.OUT_FN then installs = true break end
  end
  if not (divs >= 3 and installs) then
    return fail(("the lunge task cuts %d distances rather than three and "
                 .. "%sinstall its first slide"):format(divs,
                 installs and "does " or "does not "))
  end
  -- the first slide takes a sine and hands on to the second
  local sins = false
  for _, t in ipairs(self:blTargets(L.OUT, L.SCAN)) do
    if t == L.SIN then sins = true break end
  end
  local handsOn = false
  for _, w in ipairs(self:poolWords(L.OUT, L.SCAN)) do
    if w == L.BACK_FN then handsOn = true break end
  end
  if not (sins and handsOn) then
    return fail("the lunge's first slide does not arc and hand on to a second")
  end
  self._monLunge = {
    task = L.TASK,
    source = ("ROM:the lunge task at %07X, its slides at %07X and %07X, "
              .. "and Sin %07X"):format(L.TASK, L.OUT, L.BACK, L.SIN),
  }
  return self._monLunge
end

-- One script's call, walked frame by frame into the track it produces.
function RomExtractorGen3:lungeTrack(args, shape, sine)
  local L = RomExtractorGen3.MON_LUNGE
  if type(args) ~= "table" or #args < L.ARGS then return nil end
  local battler, out, arc = args[1], args[2], args[3]
  local outFrames, wait, back, backFrames = args[4], args[5], args[6], args[7]
  if battler < 0 or battler > 1 then return nil end
  if outFrames < 1 or outFrames > L.MAX_FRAMES then return nil end
  if backFrames < 1 or backFrames > L.MAX_FRAMES then return nil end
  if wait < 0 or wait > L.MAX_FRAMES then return nil end
  if math.abs(out) > L.MAX_TRAVEL or math.abs(back) > L.MAX_TRAVEL then
    return nil
  end
  if math.abs(arc) > L.MAX_ARC then return nil end
  -- C's integer division truncates toward zero, which is not Lua's floor
  local function quot(a, b)
    local q = a / b
    return q >= 0 and math.floor(q) or -math.floor(-q)
  end
  -- ...and the shift the sprite is written through is ARITHMETIC, which is
  -- floor and not truncation.  The two are different on the negative half and
  -- both are here on purpose.
  local function shifted(v) return math.floor(v / L.FIXED) end
  local xStep = quot(out * L.FIXED, outFrames)
  local backStep = quot(back * L.FIXED, backFrames)
  local arcStep = quot(L.HALF_TURN, outFrames)
  local xs, ys = {}, {}
  local acc, phase = 0, 0
  for _ = 1, outFrames do
    acc = acc + xStep
    xs[#xs + 1] = shifted(acc)
    local index = math.floor(phase / L.FIXED) % 256
    ys[#ys + 1] = math.floor(sine[index] * arc / 256)
    phase = phase + arcStep
  end
  local held, heldY = xs[#xs] or 0, ys[#ys] or 0
  for _ = 1, wait do
    xs[#xs + 1] = held
    ys[#ys + 1] = heldY
  end
  local acc2 = 0
  for _ = 1, backFrames do
    acc2 = acc2 + backStep
    xs[#xs + 1] = shifted(acc2) + shifted(acc)
    ys[#ys + 1] = heldY
  end
  if #xs < 2 then return nil end
  return {
    task = shape.task,
    xs = xs, ys = ys,
    target = battler == 1 or nil,
    -- ...and so does this one, for the same reason
    authoredForPlayer = true,
    life = #xs,
    source = shape.source,
  }
end

-- ---------------------------------------------------------------------------
-- THE POKEMON THAT SWAYS
--
-- Nine moves -- ATTRACT, ENCORE, SLEEP TALK, TICKLE, PSYCH UP, BIND, WRAP and
-- two more -- call one task (08:$D5EB8) with five arguments and every call
-- was thrown away.  It is a SINE, not the square-wave judder the shake pass
-- already reads: the mon leans one way, back through the middle, and out the
-- other, smoothly, for as many half-waves as the script asks for.
--
--     args = (axis, amplitude, phase step, half-waves, battler)
--
-- The step is four lines: an accumulator gains `phase step` a frame, its top
-- byte indexes gSineTable, Sin of that against `amplitude` is written to the
-- sprite's pos2 on the named axis -- and each time the index crosses the
-- half-way mark in either direction, one half-wave is spent.  When they run
-- out the offset is set back to zero and the task ends, which is why a mon
-- that swayed and stayed leaning would be a misreading.
--
-- WHAT IS STORED IS THE OFFSETS THEMSELVES, one per frame, rather than the
-- five arguments.  The arithmetic is integer and the shift is ARITHMETIC --
-- it floors, so it is asymmetric across zero -- and doing it once here off
-- the cartridge's own table is exact where doing it again at runtime off a
-- floating-point sine would not be.  Nine moves at a few dozen frames each is
-- a few hundred numbers.
RomExtractorGen3.MON_SWAY = {
  TASK = 0x0D5EB8, STEP = 0x0D5F3C,
  INSTALLS = 0x080D5F3D,
  SIN = 0x06F534,             -- Sin, which the step calls every frame
  -- the four arguments the setup copies into its own task data, as the four
  -- `ldrh r1,[r4,#n]` that copy them
  COPY = { { at = 0x32, word = 0x8821 }, { at = 0x36, word = 0x8861 },
           { at = 0x3A, word = 0x88A1 }, { at = 0x3E, word = 0x88E1 } },
  HALF = { at = 0xA0, op = 0x2D00 },    -- cmp r5,#127, the half-way mark
  SINE = 0x08329F40, SINE_ENTRIES = 256,
  INDEX_MASK = 0xFF, INDEX_SHIFT = 256, ACC_MASK = 0xFFFF,
  MAX_AMP = 64, MAX_HALVES = 32, MAX_LIFE = 600,
  SCAN = 200,
}

-- The sway's shape, without any move's numbers, plus the cartridge's sine.
function RomExtractorGen3:monSway()
  if self._monSway ~= nil then return self._monSway or nil end
  local W = RomExtractorGen3.MON_SWAY
  local rom = self.rom
  local function fail(why)
    Logger.warn("gen3 move animations: %s, so the nine moves that sway the "
                  .. "Pokemon keep whatever they had", why)
    self._monSway = false
    return nil
  end
  local installs = false
  for _, w in ipairs(self:poolWords(W.TASK, W.SCAN)) do
    if w == W.INSTALLS then installs = true break end
  end
  local sins = false
  for _, t in ipairs(self:blTargets(W.STEP, W.SCAN)) do
    if t == W.SIN then sins = true break end
  end
  if not (installs and sins) then
    return fail("the sway task does not install a step that takes a sine")
  end
  -- THE FOUR ARGUMENTS, read as the four instructions that read them.  A
  -- setup that copied three of its five arguments, or copied them from
  -- somewhere else, is not this setup.
  for i, spec in ipairs(W.COPY) do
    local ok, h = pcall(rom.u16, rom, W.TASK + spec.at)
    if not (ok and h == spec.word) then
      return fail(("argument %d is not copied where the sway keeps it")
                  :format(i - 1))
    end
  end
  local okH, half = pcall(rom.u16, rom, W.STEP + W.HALF.at)
  if not (okH and math.floor(half / 256) * 256 == W.HALF.op) then
    return fail("the sway does not count its half-waves at a half-way mark")
  end
  half = half % 256
  if half ~= math.floor(W.SINE_ENTRIES / 2) - 1 then
    return fail(("%d is not half of a %d-entry sine table")
                :format(half, W.SINE_ENTRIES))
  end
  local sine = {}
  local flat = W.SINE - 0x08000000
  for i = 0, W.SINE_ENTRIES - 1 do
    local ok, v = pcall(rom.u16, rom, flat + i * 2)
    if not ok then return fail("the sine table is off the end of the dump") end
    sine[i] = v >= 32768 and v - 65536 or v
  end
  if not (sine[0] == 0 and sine[64] == 256 and sine[128] == 0
          and sine[192] == -256) then
    return fail(("%07X is not a sine table"):format(flat))
  end
  self._monSway = {
    task = W.TASK, sine = sine, half = half,
    source = ("ROM:the sway task at %07X, its step at %07X and Sin %07X")
             :format(W.TASK, W.STEP, W.SIN),
  }
  return self._monSway
end

-- One script's call, walked frame by frame into the offsets it produces.
function RomExtractorGen3:swayOffsets(args, shape)
  local W = RomExtractorGen3.MON_SWAY
  if type(args) ~= "table" or #args < 5 then return nil end
  local axis, amp, step, halves, battler = args[1], args[2], args[3],
                                           args[4], args[5]
  if math.abs(amp) > W.MAX_AMP or amp == 0 then return nil end
  if step <= 0 or step > W.ACC_MASK then return nil end
  if halves < 1 or halves > W.MAX_HALVES then return nil end
  if battler < 0 or battler > 1 then return nil end
  local sine = shape.sine
  local acc, left = 0, halves
  -- the two flags the step toggles, which are what count a crossing once
  local upper, lower = 0, 1
  local offsets = {}
  for _ = 1, W.MAX_LIFE do
    acc = (acc + step) % (W.ACC_MASK + 1)
    local index = math.floor(acc / W.INDEX_SHIFT) % (W.INDEX_MASK + 1)
    -- Sin(index, amp) is `(gSineTable[index] * amp) >> 8`, and that shift is
    -- ARITHMETIC -- it floors, so it is not symmetric across zero
    offsets[#offsets + 1] = math.floor(sine[index] * amp / 256)
    if index > shape.half and upper == 0 and lower == 1 then
      upper, lower = 1, 0
      left = left - 1
    elseif index <= shape.half - 1 and upper == 1 and lower == 0 then
      upper, lower = 0, 1
      left = left - 1
    end
    if left <= 0 then break end
  end
  if #offsets < 2 or left > 0 then return nil end
  -- the last thing the task does is put the Pokemon back
  offsets[#offsets] = 0
  return {
    task = shape.task,
    -- argument zero picks the axis, argument four picks whose Pokemon
    xs = axis == 0 and offsets or nil,
    ys = axis ~= 0 and offsets or nil,
    target = battler == 1 or nil,
    -- the task negates its own amplitude when the attacker is not on the
    -- player's side, which says the script's number is the player's
    authoredForPlayer = true,
    life = #offsets,
    source = shape.source,
  }
end

-- ---------------------------------------------------------------------------
-- THE POKEMON THAT PULSES, AND THE SCRIPT SAYS BY HOW MUCH
--
-- Fourteen moves call one task (08:$D6064) and hand it five arguments, and
-- until now every one of them threw the call away.  It is the third member of
-- the rot/scale family MINIMIZE and WITHDRAW opened, and the only one that is
-- PARAMETRISED -- the shape lives in the script rather than in the code, so
-- one decode covers all fourteen and each keeps its own numbers.
--
--     args = (xDelta, yDelta, frames, battler, prepare)
--
-- The setup stashes those and installs a step (08:$D60BD) that is four lines
-- long:
--
--     xScale += xDelta ; yScale += yDelta ; SetSpriteRotScale
--     frames-- ; when it runs out, NEGATE both deltas, refill the counter
--     and run it again -- and the second time, reset and finish
--
-- So it is out and back, and IT CLOSES EXACTLY -- which is not a hope, it is
-- something the setup guarantees and something this can check: the SAME
-- argument is written to both counters, by the same instruction at two
-- offsets (08:$D6094 and 08:$D6098 are both `ldrh r1,[r6,#4]`).  Two phases
-- of equal length with equal and opposite deltas end where they began, so a
-- Pokemon that pulsed and stayed pulsed would be a misreading.
--
-- GBA affine scale is a DIVISOR, so a NEGATIVE delta makes the Pokemon
-- BIGGER.  LEER's (-5,-5) over ten frames is a mon swelling a quarter and
-- settling; BIND's (+10,-5) is one being squeezed narrow and tall, which is
-- what being wrapped looks like.  And BIND's argument names the TARGET rather
-- than the attacker, which is the whole reason the fourth argument exists.
RomExtractorGen3.MON_PULSE = {
  TASK = 0x0D6064, STEP = 0x0D60BC,
  INSTALLS = 0x080D60BD,
  PREPARE = 0x0A7270,         -- PrepareBattlerSpriteForRotScale
  ROTSCALE = 0x0A71B4,        -- SetSpriteRotScale, every frame
  RESET = 0x0A7344,           -- ...and the reset it ends on
  BASE  = { at = 0x3A, op = 0x2100, shift = { at = 0x3C, op = 0x0049 } },
  -- the two reads of the same argument, which is what makes it close
  COUNT_A = { at = 0x30, word = 0x88B1 },
  COUNT_B = { at = 0x34, word = 0x88B1 },
  ARGS = 5, MAX_DELTA = 64, MAX_FRAMES = 64, MAX_BATTLER = 1,
  SCAN = 120,
}

-- The pulse's SHAPE, without any move's numbers in it -- those come off each
-- script's own call.  nil if the task is not the task.
function RomExtractorGen3:monPulse()
  if self._monPulse ~= nil then return self._monPulse or nil end
  local P = RomExtractorGen3.MON_PULSE
  local rom = self.rom
  local function fail(why)
    Logger.warn("gen3 move animations: %s, so the fourteen moves that pulse "
                  .. "the Pokemon keep whatever they had", why)
    self._monPulse = false
    return nil
  end
  local prep = false
  for _, t in ipairs(self:blTargets(P.TASK, P.SCAN)) do
    if t == P.PREPARE then prep = true break end
  end
  local installs = false
  for _, w in ipairs(self:poolWords(P.TASK, P.SCAN)) do
    if w == P.INSTALLS then installs = true break end
  end
  local rot, reset = false, false
  for _, t in ipairs(self:blTargets(P.STEP, P.SCAN)) do
    if t == P.ROTSCALE then rot = true end
    if t == P.RESET then reset = true end
  end
  if not (prep and installs and rot and reset) then
    return fail("the pulse task does not prepare a sprite and install a step "
                  .. "that turns and resets one")
  end
  local okB, base = pcall(rom.u16, rom, P.TASK + P.BASE.at)
  local okS, shift = pcall(rom.u16, rom, P.TASK + P.BASE.shift.at)
  if not (okB and okS and math.floor(base / 256) * 256 == P.BASE.op
          and shift == P.BASE.shift.op) then
    return fail("the pulse does not start from a scale of its own")
  end
  base = (base % 256) * 2
  if base ~= 256 then
    return fail(("the pulse starts from %d rather than the hardware's 256")
                :format(base))
  end
  -- ...AND BOTH COUNTERS COME FROM ONE ARGUMENT, which is the closure.
  local okA, wordA = pcall(rom.u16, rom, P.TASK + P.COUNT_A.at)
  local okC, wordB = pcall(rom.u16, rom, P.TASK + P.COUNT_B.at)
  if not (okA and okC and wordA == P.COUNT_A.word and wordB == P.COUNT_B.word)
  then
    return fail("the pulse's two phases are not filled from the same argument, "
                  .. "so it would not come back to the size it started")
  end
  self._monPulse = {
    task = P.TASK, base = base,
    source = ("ROM:the pulse task at %07X, its step at %07X and "
              .. "SetSpriteRotScale %07X"):format(P.TASK, P.STEP, P.ROTSCALE),
  }
  return self._monPulse
end

-- One script's call, turned into the affine shape the engine already plays.
function RomExtractorGen3:pulseShape(args, shape)
  local P = RomExtractorGen3.MON_PULSE
  if type(args) ~= "table" or #args < P.ARGS then return nil end
  local dx, dy, frames, battler = args[1], args[2], args[3], args[4]
  if math.abs(dx) > P.MAX_DELTA or math.abs(dy) > P.MAX_DELTA then return nil end
  if frames < 1 or frames > P.MAX_FRAMES then return nil end
  if battler < 0 or battler > P.MAX_BATTLER then return nil end
  -- ...and a scale that reached zero would be a divide by zero on hardware
  local base = shape.base
  if base + dx * frames <= 0 or base + dy * frames <= 0 then return nil end
  return {
    task = shape.task, base = base,
    steps = { { dx = dx, dy = dy, rot = 0, dur = frames },
              { dx = -dx, dy = -dy, rot = 0, dur = frames } },
    life = frames * 2,
    closes = true,
    -- argument three: 0 is the attacker, 1 is whoever is being hit
    onTarget = battler == 1 or nil,
    repeats = 1,
    source = shape.source,
  }
end

-- ---------------------------------------------------------------------------
-- THE POKEMON THAT SQUEEZES AND GOES
--
-- SUBSTITUTE drew a screen flash.  What the cartridge does is the same
-- rot/scale pair MINIMIZE and WITHDRAW use, but written out in the task
-- rather than kept in a table -- which is why the affine pass, which looks
-- for the table, walked straight past it.
--
-- Its task (08:$15F20C) is two states over the attacker's own sprite:
--
--     state 0   PrepareBattlerSpriteForRotScale, both scales set to 256
--     state 1   xScale += 96, yScale -= 13, SetSpriteRotScale, for NINE
--               frames -- then ResetSpriteRotScale and the invisible bit
--
-- GBA affine scale is a DIVISOR, so that is the Pokemon squeezing to a
-- vertical sliver -- a fifth of its width and nearly twice its height -- and
-- then vanishing, which is the doll taking its place.
--
-- AND THE CHECK IS THE ONE THE HARDWARE ITSELF IMPOSES: yScale is a divisor,
-- so a reading in which it reached zero would be a divide by zero on the
-- cartridge.  256 less nine thirteens is 139, comfortably alive; a step read
-- as 130 rather than 13 would be -914, and this refuses that reading rather
-- than shipping it.
RomExtractorGen3.MON_SQUEEZE = {
  TASK = 0x15F20C,
  PREPARE = 0x0A7270,         -- PrepareBattlerSpriteForRotScale
  ROTSCALE = 0x0A71B4,        -- SetSpriteRotScale, called every frame
  RESET = 0x0A7344,           -- ...and the reset it ends on
  BASE  = { at = 0x38, op = 0x2000, shift = { at = 0x3A, op = 0x0040 } },
  WIDE  = { at = 0x4E, op = 0x3000 },   -- add r0,#96   (xScale)
  TALL  = { at = 0x54, op = 0x3800 },   -- sub r0,#13   (yScale)
  FRAMES = { at = 0x72, op = 0x2800 },  -- cmp r0,#9
  MAX_STEP = 512, MAX_FRAMES = 64,
  SCAN = 120,
}

-- The squeeze, checked, as the same shape the affine table produces -- so the
-- engine plays it with the code it already has.
function RomExtractorGen3:monSqueeze()
  if self._monSqueeze ~= nil then return self._monSqueeze or nil end
  local Q = RomExtractorGen3.MON_SQUEEZE
  local rom = self.rom
  local function fail(why)
    Logger.warn("gen3 move animations: %s, so SUBSTITUTE keeps the screen "
                  .. "flash", why)
    self._monSqueeze = false
    return nil
  end
  local function imm(spec)
    local ok, h = pcall(rom.u16, rom, Q.TASK + spec.at)
    if not (ok and math.floor(h / 256) * 256 == spec.op) then return nil end
    return h % 256
  end
  local prep, rot, reset = false, false, false
  for _, t in ipairs(self:blTargets(Q.TASK, Q.SCAN)) do
    if t == Q.PREPARE then prep = true end
    if t == Q.ROTSCALE then rot = true end
    if t == Q.RESET then reset = true end
  end
  if not (prep and rot and reset) then
    return fail("the squeeze task does not prepare, turn and reset a sprite")
  end
  local base = imm(Q.BASE)
  local okShift, shifted = pcall(rom.u16, rom, Q.TASK + Q.BASE.shift.at)
  local wide = imm(Q.WIDE)
  local tall = imm(Q.TALL)
  local frames = imm(Q.FRAMES)
  if not (base and wide and tall and frames
          and okShift and shifted == Q.BASE.shift.op) then
    return fail("the squeeze's own numbers are not where it keeps them")
  end
  base = base * 2                       -- `lsl r0,#1`
  if base ~= 256 then
    return fail(("the squeeze starts from %d rather than the hardware's 256")
                :format(base))
  end
  if wide < 1 or wide > Q.MAX_STEP or tall < 1 or tall > Q.MAX_STEP then
    return fail("the squeeze's steps are not steps")
  end
  -- the counter is `== frames`, so it runs exactly that many
  if frames < 1 or frames > Q.MAX_FRAMES then
    return fail(("%d frames is not a squeeze"):format(frames))
  end
  -- ...AND THE HARDWARE'S OWN CONSTRAINT.  yScale is a divisor: a reading in
  -- which it reaches zero is a reading of a cartridge that divides by zero.
  if base - tall * frames <= 0 then
    return fail(("a %d-a-frame shrink over %d frames drives the height "
                 .. "divisor to %d"):format(tall, frames, base - tall * frames))
  end
  self._monSqueeze = {
    task = Q.TASK,
    -- the shape the affine player already takes: deltas a frame, held for
    -- `dur` frames, against a base of 256
    steps = { { dx = wide, dy = -tall, rot = 0, dur = frames } },
    life = frames, base = base, repeats = 1,
    wide = wide, tall = tall, frames = frames,
    source = ("ROM:the squeeze task at %07X, through SetSpriteRotScale %07X")
             :format(Q.TASK, Q.ROTSCALE),
  }
  return self._monSqueeze
end

-- ---------------------------------------------------------------------------
-- THE SCREEN THAT GOES WHITE
--
-- FLASH shook the Pokemon, because the coarse fallback shakes anything that
-- has no particles and does not touch the background.  What the cartridge
-- does is the other reaction the fallback already knows how to draw -- and
-- FLASH, of all moves, should have had it.
--
-- Its task (08:$117494) has no sprites in it at all.  It builds two masks of
-- palettes (08:$A76C4 and 08:$A75AC), writes $FFFF over every colour in both
-- of them through a fill helper (08:$1175C4) -- which is the whole screen
-- turning white in one frame -- stashes the masks in its own task data, and
-- installs a step (08:$117501) that fades the white back out:
--
--     state 0   hold, 7 frames
--     state 1   sixteen steps of BlendPalette, two frames each, the
--               coefficient counting 16 down to 0 against $FFFF
--
-- So it is a 39-frame whiteout, and every number in that sentence is an
-- immediate in the step: `cmp r0,#6` is the hold, `mov r0,#16` the steps and
-- `cmp r0,#1` the two frames each.  A move that calls this gets the flash the
-- fallback would have given it anyway -- but for the right reason and for the
-- cartridge's own length.
RomExtractorGen3.SCREEN_WHITE = {
  TASK = 0x117494, STEP = 0x117500,
  INSTALLS = 0x08117501,      -- the step the task installs, Thumb
  FILL = 0x1175C4,            -- writes one colour over a masked palette
  MASK_A = 0x0A76C4, MASK_B = 0x0A75AC,   -- the two mask builders
  BLEND = 0x06F98C,           -- BlendPalette, which the fade calls
  HOLD  = { at = 0x38, op = 0x2800 },     -- cmp r0,#6
  STEPS = { at = 0x3E, op = 0x2000 },     -- mov r0,#16
  EVERY = { at = 0x4E, op = 0x2800 },     -- cmp r0,#1
  MAX_HOLD = 60, MAX_STEPS = 32,
  SCAN = 140,
}

-- The whiteout, checked, or nil.
function RomExtractorGen3:screenWhite()
  if self._screenWhite ~= nil then return self._screenWhite or nil end
  local W = RomExtractorGen3.SCREEN_WHITE
  local rom = self.rom
  local function fail(why)
    Logger.warn("gen3 move animations: %s, so FLASH keeps the coarse "
                  .. "reaction", why)
    self._screenWhite = false
    return nil
  end
  local function imm(base, spec)
    local ok, h = pcall(rom.u16, rom, base + spec.at)
    if not (ok and math.floor(h / 256) * 256 == spec.op) then return nil end
    return h % 256
  end
  -- THE TASK HAS TO BE THE ONE THAT WHITENS.  Two mask builders, a fill, and
  -- a step of its own: a task that does three of those four is some other
  -- task.
  local maskA, maskB, fills = false, false, false
  for _, t in ipairs(self:blTargets(W.TASK, W.SCAN)) do
    if t == W.MASK_A then maskA = true end
    if t == W.MASK_B then maskB = true end
    if t == W.FILL then fills = true end
  end
  local installs = false
  for _, w in ipairs(self:poolWords(W.TASK, W.SCAN)) do
    if w == W.INSTALLS then installs = true break end
  end
  if not (maskA and maskB and fills and installs) then
    return fail("the whiteout task does not mask, fill and install a fade")
  end
  local blends = false
  for _, t in ipairs(self:blTargets(W.STEP, W.SCAN)) do
    if t == W.BLEND then blends = true break end
  end
  if not blends then
    return fail("the fade step does not blend a palette")
  end
  local hold = imm(W.STEP, W.HOLD)
  local steps = imm(W.STEP, W.STEPS)
  local every = imm(W.STEP, W.EVERY)
  if not (hold and steps and every) then
    return fail("the fade's own numbers are not where it keeps them")
  end
  if hold > W.MAX_HOLD or steps < 1 or steps > W.MAX_STEPS then
    return fail(("a %d-frame hold and %d steps is not a fade"):format(hold, steps))
  end
  -- the counters are `> n`, not `>= n`, so each spends one frame more than it
  -- compares against
  local life = (hold + 1) + steps * (every + 1)
  self._screenWhite = {
    task = W.TASK, hold = hold + 1, steps = steps, every = every + 1,
    life = life,
    source = ("ROM:the whiteout task at %07X, its fade at %07X and "
              .. "BlendPalette at %07X"):format(W.TASK, W.STEP, W.BLEND),
  }
  return self._screenWhite
end

-- ---------------------------------------------------------------------------
-- THE POKEMON THAT TIPS
--
-- WITHDRAW drew a screen flash.  What the cartridge does is the other half of
-- the pair MINIMIZE opened: the same helper, SetSpriteRotScale (08:$0A71B4),
-- but the ROTATION argument rather than the scale.
--
-- Its task (08:$1036A0) installs a step (08:$1036DC) that runs three states
-- over the attacker's own sprite:
--
--     state 0   angle += 176, pos2.y += 1, until the angle reaches 242 << 4
--     state 1   hold, 30 frames
--     state 2   angle -= 176, pos2.y -= 1, back to nothing
--
-- 3872 over 176 is TWENTY-TWO exactly, and that is the check that ties the
-- limit and the step together: a climb that did not land on its own limit
-- would run forever on the cartridge, so a reading where it does not is a
-- misreading.  Twenty-two up, thirty held, twenty-two back: 74 frames.
--
-- 3872 of a 65536-unit turn is about twenty-one degrees, and the sprite rises
-- twenty-two pixels while it tips -- a Pokemon pulling into its shell.  The
-- angle is NEGATED for the near side, so it always tips away from whoever is
-- watching, which is the one line of this that is a fact about sides rather
-- than about numbers.
RomExtractorGen3.MON_ROTATE = {
  TASK = 0x1036A0, STEP = 0x1036DC,
  ROTSCALE = 0x0A71B4,        -- SetSpriteRotScale, which the step calls
  INSTALLS = 0x081036DD,      -- the step the task installs, Thumb
  TIP   = { at = 0x68, op = 0x3000 },   -- add r0,#176
  RISE  = { at = 0x78, op = 0x3100 },   -- add r1,#1   -- pos2.y (r1, not r0)
  HOLD  = { at = 0x92, op = 0x2800 },   -- cmp r0,#30
  BACK  = { at = 0x9C, op = 0x3800 },   -- sub r0,#176
  -- the limit, `mov r0,#242 ; lsl r0,#4`
  LIMIT = { at = 0xC2, op = 0x2000, shift = { at = 0xC4, op = 0x0100 } },
  TURN = 65536,               -- the hardware's units for a whole turn
  SCAN = 200,
}

-- The tip, checked, or nil.
function RomExtractorGen3:monRotate()
  if self._monRotate ~= nil then return self._monRotate or nil end
  local M = RomExtractorGen3.MON_ROTATE
  local rom = self.rom
  local function fail(why)
    Logger.warn("gen3 move animations: %s, so WITHDRAW keeps the screen "
                  .. "flash", why)
    self._monRotate = false
    return nil
  end
  local function imm(base, spec)
    local ok, h = pcall(rom.u16, rom, base + spec.at)
    if not (ok and math.floor(h / 256) * 256 == spec.op) then return nil end
    return h % 256
  end
  local installs = false
  for _, w in ipairs(self:poolWords(M.TASK, M.SCAN)) do
    if w == M.INSTALLS then installs = true break end
  end
  local rotates = false
  for _, t in ipairs(self:blTargets(M.STEP, M.SCAN)) do
    if t == M.ROTSCALE then rotates = true break end
  end
  if not (installs and rotates) then
    return fail("the tip task does not install a step that turns a sprite")
  end
  local tip = imm(M.STEP, M.TIP)
  local rise = imm(M.STEP, M.RISE)
  local hold = imm(M.STEP, M.HOLD)
  local back = imm(M.STEP, M.BACK)
  local limit = imm(M.STEP, M.LIMIT)
  local okShift, shifted = pcall(rom.u16, rom, M.STEP + M.LIMIT.shift.at)
  if not (tip and rise and hold and back and limit
          and okShift and shifted == M.LIMIT.shift.op) then
    return fail("the tip task's own numbers are not where it keeps them")
  end
  limit = limit * 16                     -- `lsl r0,#4`
  if tip ~= back then
    return fail(("the tip (%d) and the return (%d) are not the same step")
                :format(tip, back))
  end
  -- ...AND THE CLIMB HAS TO LAND ON ITS OWN LIMIT.  On the cartridge a climb
  -- that stepped past it would never stop, so a reading where it does not is
  -- a misreading of one of the two numbers.
  if tip <= 0 or limit % tip ~= 0 then
    return fail(("a climb of %d does not land on %d"):format(tip, limit))
  end
  local frames = math.floor(limit / tip)
  self._monRotate = {
    task = M.TASK, step = tip, limit = limit, rise = rise,
    frames = frames, hold = hold, turn = M.TURN,
    life = frames * 2 + hold,
    source = ("ROM:the tip task at %07X, its step at %07X and "
              .. "SetSpriteRotScale at %07X"):format(M.TASK, M.STEP,
                                                     M.ROTSCALE),
  }
  return self._monRotate
end

-- ---------------------------------------------------------------------------
-- THE FLOURISH A STAT-UP MOVE MAKES
--
-- HARDEN, IRON DEFENSE and four more drew this port's coarse SCREEN FLASH:
-- the whole field going white for a fixed sixteen frames, invented here.
-- What the cartridge does is a background layer, and it is a much smaller
-- and better thing than a flash.
--
-- Their task (08:$1144F8) brings in one 256x256 layer -- tiles $C1D0AC, a
-- tilemap $C1D210 and a palette $C1D1E8 -- and the palette is the giveaway:
-- of its sixteen entries the tiles use exactly two, index 0 and index 1, and
-- index 1 is $7FFF.  WHITE, on a transparent ground.  The tilemap is 963
-- cells of nothing and sixty-two single tiles scattered through it.  It is a
-- sparse sparkle, not a wash.
--
-- WHERE IT SITS is the attacker, not the screen: the task ends with
--
--     BG1_X = 96 - sprite->pos1.x ;  BG1_Y = 32 - sprite->pos1.y
--
-- so the layer is centred on the Pokemon whose stat went up.
--
-- HOW IT MOVES, out of the step it installs (08:$114748):
--
--     counter += 4 ; BG1_X -= 4          -- the sparkle drifts, 4px a frame
--     counter == 128 -> counter = 0, BG1_X += 124, laps++
--     laps == 3      -> the layer is torn down
--
-- ...which is 32 frames a lap and 96 in all.  And it is BLENDED, not drawn:
-- the task writes BLDALPHA $0C08, which is eight sixteenths of the layer
-- over twelve sixteenths of what is behind it.
--
-- Every one of those numbers is an immediate in one of those two functions,
-- and each is checked to be the instruction it came out of.
RomExtractorGen3.STAT_FLOURISH = {
  TASK = 0x1144F8,
  STEP = 0x114748,
  TILES = 0x08C1D0AC, MAP = 0x08C1D210, PAL = 0x08C1D1E8,
  TILE_BYTES = 2048, MAP_BYTES = 2048, PAL_BYTES = 32,
  BLDALPHA = 0x00000C08,      -- the literal the task loads into $52
  CELLS = 32, ROWS = 32,
  -- the immediates, by byte offset from each function's first instruction
  DRIFT  = { at = 0x16, op = 0x3000 },   -- add r0,#4    -- and BG1_X -= 4
  BACK   = { at = 0x20, op = 0x1F19, exact = true },  -- sub r1,r3,#4
  LAP    = { at = 0x28, op = 0x2800 },   -- cmp r0,#128
  WRAP   = { at = 0x32, op = 0x3000 },   -- add r0,#124
  LAPS   = { at = 0xDC, op = 0x2800 },   -- cmp r0,#3
  CENTRE_X = { at = 0x1BC, op = 0x3000 },-- add r0,#96
  CENTRE_Y = { at = 0x1C6, op = 0x3000 },-- add r0,#32
  SCAN = 260,
}

-- The flourish, checked, or nil.
function RomExtractorGen3:statFlourish()
  if self._statFlourish ~= nil then return self._statFlourish or nil end
  local F = RomExtractorGen3.STAT_FLOURISH
  local rom = self.rom
  local function fail(why)
    Logger.warn("gen3 move animations: %s, so the stat-up moves keep the "
                  .. "coarse flash", why)
    self._statFlourish = false
    return nil
  end
  local function imm(base, spec)
    local ok, h = pcall(rom.u16, rom, base + spec.at)
    if not ok then return nil end
    if spec.exact then return (h == spec.op) and 0 or nil end
    if math.floor(h / 256) * 256 ~= spec.op then return nil end
    return h % 256
  end
  -- the task has to name all three blobs and the blend it writes
  local seen = {}
  for _, w in ipairs(self:poolWords(F.TASK, F.SCAN)) do seen[w] = true end
  for _, w in ipairs({ F.TILES, F.MAP, F.PAL, F.BLDALPHA }) do
    if not seen[w] then
      return fail(("the stat-up task does not name %08X"):format(w))
    end
  end
  local drift = imm(F.STEP, F.DRIFT)
  local back = imm(F.STEP, F.BACK)
  local lap = imm(F.STEP, F.LAP)
  local wrap = imm(F.STEP, F.WRAP)
  local laps = imm(F.STEP, F.LAPS)
  local cx = imm(F.TASK, F.CENTRE_X)
  local cy = imm(F.TASK, F.CENTRE_Y)
  if not (drift and back and lap and wrap and laps and cx and cy) then
    return fail("the stat-up task's own numbers are not where it keeps them")
  end
  -- ...and the wrap has to bring the lap back where it started, less one
  -- step: 128 out, 124 back, and the step itself is the 4 that is missing
  if wrap + drift ~= lap then
    return fail(("the lap (%d), the wrap (%d) and the step (%d) do not close")
                :format(lap, wrap, drift))
  end
  local function blob(at, want)
    local flat = at - 0x08000000
    if flat < 0 or flat + 4 >= rom.size then return nil end
    if rom:u8(flat) ~= 0x10 then return nil end
    local ok, raw = pcall(rom.lz77, rom, flat)
    if not (ok and raw and #raw == want) then return nil end
    return raw
  end
  local tiles = blob(F.TILES, F.TILE_BYTES)
  local tmap = blob(F.MAP, F.MAP_BYTES)
  local praw = blob(F.PAL, F.PAL_BYTES)
  if not (tiles and tmap and praw) then
    return fail("the stat-up layer does not decompress to its own sizes")
  end
  local colors = {}
  for i = 0, F.PAL_BYTES / 2 - 1 do
    local r, g, b = RomGba.bgr555(praw[i * 2 + 1] + praw[i * 2 + 2] * 256)
    colors[i] = { r, g, b }
  end
  local image = nil
  local okArt, artErr = pcall(function()
    image = ImageWriter.blank(F.CELLS * 8, F.ROWS * 8)
    for cy2 = 0, F.ROWS - 1 do
      for cx2 = 0, F.CELLS - 1 do
        local c = cy2 * F.CELLS + cx2
        local entry = (tmap[c * 2 + 1] or 0) + (tmap[c * 2 + 2] or 0) * 256
        local tid = entry % 1024
        local hflip = math.floor(entry / 1024) % 2 == 1
        local vflip = math.floor(entry / 2048) % 2 == 1
        for py = 0, 7 do
          for px = 0, 7 do
            local sx = hflip and (7 - px) or px
            local sy = vflip and (7 - py) or py
            local byte = tiles[tid * 32 + sy * 4 + math.floor(sx / 2) + 1]
            local idx = byte and ((sx % 2 == 0) and byte % 16
                                  or math.floor(byte / 16))
            -- THE TILEMAP'S PALETTE BANK IS NOT AN INDEX INTO THIS
            -- TABLE.  The task loads one sixteen-colour palette, and the
            -- animation's own background machinery puts it in bank 8 --
            -- which is what every cell here names.  The bank says where the
            -- hardware kept the colours, not which colours; there is only
            -- one palette and these are it.
            local col = idx and idx ~= 0 and colors[idx]
            if col then
              image:setPixel(cx2 * 8 + px, cy2 * 8 + py,
                             col[1] / 255, col[2] / 255, col[3] / 255, 1)
            else
              image:setPixel(cx2 * 8 + px, cy2 * 8 + py, 0, 0, 0, 0)
            end
          end
        end
      end
    end
    self:saveImage(image, "battle_anim/stat_flourish.png")
  end)
  if not okArt then
    return fail(("the stat-up layer could not be composed (%s)")
                :format(tostring(artErr)))
  end
  self._statFlourish = {
    image = "assets/generated/battle_anim/stat_flourish.png",
    width = F.CELLS * 8, height = F.ROWS * 8,
    drift = drift, lap = lap, laps = laps,
    centreX = cx, centreY = cy,
    -- BLDALPHA is EVB in the high byte and EVA in the low one
    alpha = (F.BLDALPHA % 256) / 16,
    life = math.floor(lap / drift) * laps,
    source = ("ROM:the stat-up task at %07X, its step at %07X, tiles %07X, "
              .. "tilemap %07X and palette %07X"):format(F.TASK, F.STEP,
              F.TILES - 0x08000000, F.MAP - 0x08000000, F.PAL - 0x08000000),
  }
  return self._statFlourish
end

-- ---------------------------------------------------------------------------
-- THE POKEMON THAT SHRINKS
--
-- MINIMIZE drew a screen flash.  Its whole animation is one task
-- (08:$104674), and what that task does is scale the attacker's own sprite --
-- which is a thing this port could not do at all until now.
--
-- The task hands the sprite to SetSpriteRotScale (08:$0A71B4) every frame
-- with a scale it keeps in its own data, and runs a six-state machine over
-- it.  GBA affine scale is a DIVISOR -- the matrix maps screen back to
-- texture -- so a scale going UP is the Pokemon getting smaller, and 256 is
-- life size.
--
--     state 0  32 frames: scale += 40      (256 -> 1536, a sixth of itself)
--     state 1  once the third pass is done, on to state 3; otherwise put the
--              scale back to 256 and go round again
--     state 3  33 frames: hold, at the smallest
--     state 4  16 frames: scale -= 80 twice a step (1536 -> 256 exactly)
--     state 5  ResetSpriteRotScale, and the task is destroyed
--
-- Three shrinks, a pause and one grow back, and every number in it is an
-- immediate in that function -- read here, and checked to be the instruction
-- it came out of before it is believed.
RomExtractorGen3.MON_SCALE = {
  TASK = 0x104674,
  STEP = 0x1046CC,
  ROTSCALE = 0x0A71B4,        -- SetSpriteRotScale, which the step calls
  INSTALLS = 0x081046CD,      -- ...and the step the task installs, Thumb
  -- the base scale, `mov r0,#128 ; lsl r0,#1`, in the task itself
  BASE   = { at = 0x2A, op = 0x2000, shift = { at = 0x2C, op = 0x0040 } },
  -- ...and the rest, by byte offset from the step's first instruction
  SHRINK_STEP  = { at = 0x64, op = 0x3000 },  -- add r0,#40
  SHRINK_UNTIL = { at = 0x80, op = 0x2800 },  -- cmp r0,#32
  ROUNDS       = { at = 0x98, op = 0x2900 },  -- cmp r1,#3
  HOLD_UNTIL   = { at = 0xD2, op = 0x2800 },  -- cmp r0,#32
  GROW_EVERY   = { at = 0xDA, op = 0x3000 },  -- add r0,#2
  GROW_STEP    = { at = 0xE0, op = 0x3800 },  -- sub r0,#80
  GROW_UNTIL   = { at = 0xFC, op = 0x2800 },  -- cmp r0,#32
  MAX_SCALE = 4096,
  SCAN = 200,
}

-- The shrink, checked, or nil.
function RomExtractorGen3:monScale()
  if self._monScale ~= nil then return self._monScale or nil end
  local M = RomExtractorGen3.MON_SCALE
  local function fail(why)
    Logger.warn("gen3 move animations: %s, so MINIMIZE keeps the screen "
                  .. "flash", why)
    self._monScale = false
    return nil
  end
  local function imm(base, spec)
    local ok, h = pcall(self.rom.u16, self.rom, base + spec.at)
    if not (ok and math.floor(h / 256) * 256 == spec.op) then return nil end
    return h % 256
  end
  -- the task has to install that step, and the step has to hand the sprite to
  -- the cartridge's own rot/scale routine, or none of the numbers are its
  local installs = false
  for _, w in ipairs(self:poolWords(M.TASK, M.SCAN)) do
    if w == M.INSTALLS then installs = true break end
  end
  local scales = false
  for _, t in ipairs(self:blTargets(M.STEP, M.SCAN)) do
    if t == M.ROTSCALE then scales = true break end
  end
  if not (installs and scales) then
    return fail("the shrink task does not install a step that scales a sprite")
  end
  local base = imm(M.TASK, M.BASE)
  local shiftOk = select(2, pcall(self.rom.u16, self.rom,
                                  M.TASK + M.BASE.shift.at)) == M.BASE.shift.op
  local shrinkStep = imm(M.STEP, M.SHRINK_STEP)
  local shrinkUntil = imm(M.STEP, M.SHRINK_UNTIL)
  local rounds = imm(M.STEP, M.ROUNDS)
  local holdUntil = imm(M.STEP, M.HOLD_UNTIL)
  local growEvery = imm(M.STEP, M.GROW_EVERY)
  local growStep = imm(M.STEP, M.GROW_STEP)
  local growUntil = imm(M.STEP, M.GROW_UNTIL)
  if not (base and shiftOk and shrinkStep and shrinkUntil and rounds
          and holdUntil and growEvery and growStep and growUntil) then
    return fail("the shrink task's own numbers are not where it keeps them")
  end
  base = base * 2          -- `mov r0,#128 ; lsl r0,#1` is 256, life size
  -- ...and the growth has to undo the shrink exactly, which is the whole
  -- check on the two step sizes at once: 32 x 40 up, 16 x 80 down
  local up = shrinkUntil * shrinkStep
  local down = math.floor(growUntil / growEvery) * growStep
  if up ~= down then
    return fail(("the shrink (%d) and the grow (%d) do not cancel")
                :format(up, down))
  end
  if base + up > M.MAX_SCALE then
    return fail("the shrink goes further than a sprite can be scaled")
  end
  self._monScale = {
    base = base, shrinkStep = shrinkStep, shrinkFrames = shrinkUntil,
    rounds = rounds, holdFrames = holdUntil + 1,
    growStep = growStep, growEvery = growEvery,
    growFrames = math.floor(growUntil / growEvery),
    task = M.TASK,
    source = ("ROM:the shrink task at %07X, its step at %07X and "
              .. "SetSpriteRotScale at %07X"):format(M.TASK, M.STEP,
                                                     M.ROTSCALE),
  }
  return self._monScale
end

-- ---------------------------------------------------------------------------
-- THE GROUND THAT HEAVES
--
-- EARTHQUAKE spawned no particles, so it fell through to this port's coarse
-- reaction: a two-pixel wobble for a fixed 24 frames, invented here.  The
-- cartridge's own number is nothing like it.
--
-- Its script calls one task (08:$1152DC) twice, and that task's three
-- arguments are a MODE and the shake itself:
--
--     args[0] = 5   shake the terrain    (the step writes gBattle_BG3_X)
--     args[0] = 4   shake the battlers   (it collects their sprite ids)
--     args[1]       the amplitude, less three -- `add r0,r2,#3`
--     args[2]       how many times it swings
--
-- ...and the step alternates the register between origin+amplitude and
-- origin-amplitude, acting every SECOND frame (`data[1]++; if data[1] <= 1
-- return`).  EARTHQUAKE passes (5,10,50) and (4,10,50): THIRTEEN pixels,
-- fifty swings, a hundred frames.  Two pixels for twenty-four frames was not
-- in the same country.
--
-- This port draws one field and shifts the whole of it, so the two calls are
-- one heave rather than two: the ground and the Pokemon standing on it move
-- together, which is what a screen-wide BG3 shake plus a sprite shake of the
-- same amplitude and the same period looks like.
RomExtractorGen3.SCREEN_HEAVE = {
  TASK = 0x1152DC,
  STEP = 0x1153AC,            -- the arm that shakes the terrain
  BG_X = 0x02022E20,          -- gBattle_BG3_X, which that step writes
  -- the immediates, by byte offset from each function's first instruction,
  -- each with the instruction it has to be
  BIAS   = { at = 0x1E, op = 0x1CD0, add = 3 },  -- add r0,r2,#3
  MONS   = { at = 0x46, op = 0x2804, mode = 4 }, -- cmp r0,#4
  GROUND = { at = 0x4A, op = 0x2805, mode = 5 }, -- cmp r0,#5
  BEAT   = { at = 0x38, op = 0x2801, every = 2 },-- cmp r0,#1 ; ble return
  MAX_AMPLITUDE = 64,         -- a heave bigger than a battler's box is not one
  MAX_SWINGS = 400,
  SCAN = 120,
}

-- The heave, checked, or nil.
function RomExtractorGen3:screenHeave()
  if self._screenHeave ~= nil then return self._screenHeave or nil end
  local H = RomExtractorGen3.SCREEN_HEAVE
  local function fail(why)
    Logger.warn("gen3 move animations: %s, so EARTHQUAKE keeps the coarse "
                  .. "wobble", why)
    self._screenHeave = false
    return nil
  end
  local function shaped(base, spec)
    local ok, h = pcall(self.rom.u16, self.rom, base + spec.at)
    return ok and h == spec.op
  end
  if not (shaped(H.TASK, H.BIAS) and shaped(H.TASK, H.MONS)
          and shaped(H.TASK, H.GROUND) and shaped(H.STEP, H.BEAT)) then
    return fail("the heave task does not read as itself")
  end
  -- ...and the step it installs has to be the one that writes the terrain's
  -- own scroll register, or it is shaking something else
  local names = false
  for _, w in ipairs(self:poolWords(H.STEP, H.SCAN)) do
    if w == H.BG_X then names = true break end
  end
  if not names then
    return fail("the heave step does not write the terrain's scroll register")
  end
  self._screenHeave = {
    task = H.TASK, bias = H.BIAS.add, every = H.BEAT.every,
    ground = H.GROUND.mode, mons = H.MONS.mode,
    source = ("ROM:the heave task at %07X and its terrain step at %07X")
             :format(H.TASK, H.STEP),
  }
  return self._screenHeave
end

-- ---------------------------------------------------------------------------
-- THE WAVE THAT CROSSES THE FIELD
--
-- Reported from play: "surf isnt showing the wave going through and hitting
-- the enemy pokemon".  It showed nothing: SURF's whole animation is one
-- `createvisualtask` (08:$107954) and it does not spawn a single particle --
-- the wave is a BACKGROUND LAYER, an eight-kilobyte tileset laid out by a
-- 64x32 tilemap and scrolled across the screen.
--
-- The task reads whole, and every address below is in its own literal pool:
--
--     AnimLoadCompressedBgGfx  (bg, $D94AB8)          -- 256 tiles, 4bpp
--     AnimLoadCompressedBgTilemap(bg, $D95E00)        -- attacker on side 1
--                              (bg, $D960D0)          -- ...and on side 0
--     LoadCompressedPalette    ($D95DD8, ..., 32)     -- SURF passes arg 0 = 0
--
--     side 1:  BG1_X = -224, BG1_Y =  256, step (+2, -1)
--     side 0:  BG1_X =    0, BG1_Y =  -48, step (-2, +1)
--
-- ...and its step function adds those to the scroll registers every frame,
-- ramping an alpha blend up over its first 13 double-frames, holding it, and
-- ramping it back down once the 54th has passed.  When the blend reaches zero
-- the layer is torn down, which is 134 frames.
--
-- +2/-1 from the upper right and -2/+1 from the lower left is the wave
-- sweeping DOWN AND ACROSS from whoever used it to whoever is being hit,
-- which is what the report says is missing.
--
-- WHAT THIS PORT DOES NOT DO is the scanline effect.  The cartridge hands a
-- per-scanline table of horizontal offsets to the HBlank handler (a second
-- task, 08:$107D58, writing gScanlineEffectRegBuffers), which shears the wave
-- row by row as it passes.  This renderer has no scanline hook, so the layer
-- is drawn flat.  The wave crosses the field, blended, at the cartridge's own
-- speed and in the cartridge's own direction; it does not ripple.  That is a
-- real difference and it is said here rather than papered over.
RomExtractorGen3.SURF_WAVE = {
  TASK = 0x107954,
  TILES = 0x08D94AB8, TILE_BYTES = 8192,
  MAP_OPPONENT = 0x08D95E00,      -- GetBattlerSide(attacker) == 1
  MAP_PLAYER = 0x08D960D0,        -- ...and the other arm
  MAP_BYTES = 4096,
  PALETTE = 0x08D95DD8, PAL_BYTES = 32,
  -- a 4096-byte tilemap is two 32x32 screenblocks, which is a 512x256 layer
  CELLS = 32, BLOCKS = 2, ROWS = 32,
  -- the literal halfwords the two arms load, checked in the pool before the
  -- table below is believed
  POOL = { 0x0000FF20, 0x0000FFD0, 0x0000FFFE, 0x0000FFFF },
  PLAYER = { x = 0, y = -48, dx = -2, dy = 1 },
  OPPONENT = { x = -224, y = 256, dx = 2, dy = -1 },
  -- the blend, in double-frames: up over 13, held to 54, then down again
  FADE = 13, HOLD = 54, STEP = 2, BLEND_OF = 16,
  SCAN = 260,
}

-- The wave, composed, or nil.  Two pictures -- one per side, because the
-- cartridge has two tilemaps and they are not each other's mirror -- and the
-- numbers that move them.
function RomExtractorGen3:surfWave()
  if self._surfWave ~= nil then return self._surfWave or nil end
  local S = RomExtractorGen3.SURF_WAVE
  local rom = self.rom
  local function fail(why)
    Logger.warn("gen3 move animations: %s, so SURF keeps drawing nothing",
                why)
    self._surfWave = false
    return nil
  end
  -- the task has to NAME all four blobs and both arms' offsets, or the
  -- addresses below are somebody else's
  local seen = {}
  for _, w in ipairs(self:poolWords(S.TASK, S.SCAN)) do seen[w] = true end
  for _, w in ipairs({ S.TILES, S.MAP_OPPONENT, S.MAP_PLAYER, S.PALETTE,
                       S.POOL[1], S.POOL[2], S.POOL[3], S.POOL[4] }) do
    if not seen[w] then
      return fail(("the surf task does not name %08X"):format(w))
    end
  end
  local function blob(at, want)
    local flat = at - 0x08000000
    if flat < 0 or flat + 4 >= rom.size then return nil end
    if rom:u8(flat) ~= 0x10 then return nil end
    local ok, raw = pcall(rom.lz77, rom, flat)
    if not (ok and raw and #raw == want) then return nil end
    return raw
  end
  local tiles = blob(S.TILES, S.TILE_BYTES)
  local praw = blob(S.PALETTE, S.PAL_BYTES)
  if not (tiles and praw) then
    return fail("the surf tiles or palette do not decompress to their size")
  end
  local colors = {}
  for i = 0, S.PAL_BYTES / 2 - 1 do
    local v = praw[i * 2 + 1] + praw[i * 2 + 2] * 256
    colors[i] = { (v % 32) * 8, (math.floor(v / 32) % 32) * 8,
                  (math.floor(v / 1024) % 32) * 8 }
  end
  -- one 512x256 picture out of a tilemap that is two screenblocks wide.  A
  -- BG's colour 0 is the transparent one, and here it is what lets the field
  -- show through where the wave has not reached.
  local function compose(at)
    local tmap = blob(at, S.MAP_BYTES)
    if not tmap then return nil end
    local wide = S.CELLS * S.BLOCKS
    local image = ImageWriter.blank(wide * 8, S.ROWS * 8)
    for cy = 0, S.ROWS - 1 do
      for cx = 0, wide - 1 do
        local block = math.floor(cx / S.CELLS)
        local c = block * S.CELLS * S.ROWS + cy * S.CELLS + (cx % S.CELLS)
        local entry = (tmap[c * 2 + 1] or 0) + (tmap[c * 2 + 2] or 0) * 256
        local tid = entry % 1024
        local hflip = math.floor(entry / 1024) % 2 == 1
        local vflip = math.floor(entry / 2048) % 2 == 1
        for py = 0, 7 do
          for px = 0, 7 do
            local sx = hflip and (7 - px) or px
            local sy = vflip and (7 - py) or py
            local byte = tiles[tid * 32 + sy * 4 + math.floor(sx / 2) + 1]
            local idx = byte and ((sx % 2 == 0) and byte % 16
                                  or math.floor(byte / 16))
            local col = idx and idx ~= 0 and colors[idx]
            if col then
              image:setPixel(cx * 8 + px, cy * 8 + py,
                             col[1] / 255, col[2] / 255, col[3] / 255, 1)
            else
              image:setPixel(cx * 8 + px, cy * 8 + py, 0, 0, 0, 0)
            end
          end
        end
      end
    end
    return image
  end
  -- COMPOSING IS THE PART THAT CAN FAIL FOR REASONS THAT ARE NOT THE
  -- CARTRIDGE'S.  A harness with no image backend cannot make a picture, and
  -- an import that cannot make a picture must still finish -- the rest of
  -- this stage is 354 moves' worth of sound and particles.  Same guard the
  -- particle sheets already have.
  local sides = {}
  local okArt, artErr = pcall(function()
    for key, at in pairs({ player = S.MAP_PLAYER,
                           opponent = S.MAP_OPPONENT }) do
      local image = compose(at)
      if not image then
        error(("the tilemap for the %s side does not decompress"):format(key))
      end
      local rel = ("battle_anim/surf_%s.png"):format(key)
      self:saveImage(image, rel)
      local move = key == "player" and S.PLAYER or S.OPPONENT
      sides[key] = { image = "assets/generated/" .. rel,
                     x = move.x, y = move.y, dx = move.dx, dy = move.dy }
    end
  end)
  if not (okArt and sides.player and sides.opponent) then
    return fail(("the surf wave could not be composed (%s)")
                :format(tostring(artErr)))
  end
  self._surfWave = {
    width = S.CELLS * S.BLOCKS * 8, height = S.ROWS * 8,
    player = sides.player, opponent = sides.opponent,
    fade = S.FADE, hold = S.HOLD, step = S.STEP, blendOf = S.BLEND_OF,
    life = (S.HOLD + S.FADE) * S.STEP,
    source = ("ROM:the surf task at %07X, tiles %07X, tilemaps %07X/%07X "
              .. "and palette %07X"):format(S.TASK, S.TILES - 0x08000000,
                                            S.MAP_PLAYER - 0x08000000,
                                            S.MAP_OPPONENT - 0x08000000,
                                            S.PALETTE - 0x08000000),
  }
  return self._surfWave
end

-- ---------------------------------------------------------------------------
-- THE NOTES THAT CIRCLE THE SCREEN
--
-- Reported from play: "perish song the symbols arent moving properly".  They
-- were not moving at all.  PERISH SONG spawns sixteen music notes -- sixteen
-- `createsprite` of one template, tag 10206 -- and their callback is not one
-- of the shared translation helpers animMotionOf knows, so every note sat
-- where it was born.
--
-- The callback (08:$106F60) is pure arithmetic and reads whole:
--
--   first frame:  pos1 = (120, args[0] / 2 - 15)   -- SCREEN coordinates
--                 StartSpriteAnim(sprite, args[1]) -- which of the pictures
--                 data[5] = 120                    -- and how long it lives
--                 data[3] = args[2]                -- its phase, 0..240
--   every frame:  data[0]++
--                 data[1] = data[0] / 2                    -- the slow fall
--                 data[6] = (data[6] + 10) & 255           -- a fast wobble
--                 angle   = (data[0] * 3 + data[3]) & 255
--                 pos2.x  = Cos(angle, 100)
--                 pos2.y  = Sin(angle, 10) + Cos(data[6], 4) + data[1]
--                 data[0] > data[5] -> the note is destroyed
--
-- Sixteen notes a sixteenth of a turn apart, each riding a wide flat ellipse
-- across the screen while drifting down and shivering.  That is what the
-- report says is missing.
--
-- Sin and Cos are the cartridge's own (08:$06F534 and 08:$06F550), and both
-- are one line: `(gSineTable[i] * a) >> 8`, Cos indexing a quarter turn on.
-- The table is taken whole for the same reason the afterimage takes it: the
-- motion is an arithmetic shift of the table's own values.
--
-- EVERY NUMBER IN IT IS READ, not typed: the four amplitudes, the wobble
-- step, the fall bias and the lifetime are immediates in that function, and
-- each is checked to be the instruction it should be before its byte is
-- believed.  A dump that does not read as itself gets no orbit at all and
-- the notes sit still, which is what they did before.
RomExtractorGen3.ANIM_ORBIT = {
  CALLBACK = 0x106F60,     -- flat, even; the script stores it Thumb
  -- flat offsets, because that is what blTargets and poolWords speak
  SIN = 0x06F534,          -- Sin(i, a) = (gSineTable[i]      * a) >> 8
  COS = 0x06F550,          -- Cos(i, a) = (gSineTable[i + 64] * a) >> 8
  SINE = 0x08329F40,
  SINE_ENTRIES = 256,
  QUARTER = 64,            -- how far Cos indexes past Sin
  -- the immediates, by halfword offset from the callback's first instruction,
  -- each with the instruction it has to be
  LIFE   = { at = 0x0C, op = 0x2500 },  -- mov r5,#120 -- the life, and pos1.x
  TOP    = { at = 0x1C, op = 0x3800 },  -- sub r0,#15  -- where the note opens
  WOBBLE = { at = 0x52, op = 0x3000 },  -- add r0,#10  -- the shiver's step
  AMP_X  = { at = 0x5E, op = 0x2100 },  -- mov r1,#100 -- the ellipse, across
  AMP_Y  = { at = 0x68, op = 0x2100 },  -- mov r1,#10  -- ...and down
  AMP_W  = { at = 0x74, op = 0x2100 },  -- mov r1,#4   -- the shiver itself
  -- angle = data[0] * 3 + phase, which is `lsl r4,r0,#1 ; add r4,r4,r0`
  TRIPLE = { at = 0x46, shape = { 0x0044, 0x1824 } },
  -- THE SEVENTEENTH SPRITE.  The script makes one more of these than there
  -- are notes, off a second template with its own callback -- and that one's
  -- first act is to make itself INVISIBLE and count down to the sound.  It is
  -- a timer wearing a sprite, and drawing it puts a seventeenth note on the
  -- screen that never moves.  Recognised by the six instructions that set the
  -- bit: `add r2,r4,#0 ; add r2,#62 ; ldrb r0,[r2] ; mov r1,#4 ; orr r0,r1 ;
  -- strb r0,[r2]`, +62 being the sprite's bitfield byte and 4 its invisible
  -- bit.
  SILENT = { at = 0x106F00, from = 0x16,
             shape = { 0x1C22, 0x323E, 0x7810, 0x2104, 0x4308, 0x7010 } },
  ANGLE_MUL = 3,
  FALL_DIV = 2,            -- data[1] = data[0] / 2
  -- and the three calls it makes, in the order it makes them
  CALLS = { 0x06F550, 0x06F534, 0x06F550 },
  SCAN = 96,
}

-- The note's motion, checked, or nil.  Memoised like the rest: one import
-- asks for it once per particle.
function RomExtractorGen3:animOrbit()
  if self._animOrbit ~= nil then return self._animOrbit or nil end
  local O = RomExtractorGen3.ANIM_ORBIT
  local function fail(why)
    Logger.warn("gen3 move animations: %s, so PERISH SONG's notes stay "
                  .. "where they are born", why)
    self._animOrbit = false
    return nil
  end
  local function imm(spec)
    local ok, h = pcall(self.rom.u16, self.rom, O.CALLBACK + spec.at)
    -- a Thumb `mov rN,#imm` / `add rN,#imm` / `sub rN,#imm` keeps the operand
    -- in the LOW byte and the opcode-plus-register in the high one
    if not (ok and math.floor(h / 256) * 256 == spec.op) then return nil end
    return h % 256
  end
  for k, want in ipairs(O.TRIPLE.shape) do
    local ok, h = pcall(self.rom.u16, self.rom,
                        O.CALLBACK + O.TRIPLE.at + (k - 1) * 2)
    if not (ok and h == want) then
      return fail("the note callback does not multiply its step by three")
    end
  end
  local life = imm(O.LIFE)
  local top = imm(O.TOP)
  local wobble = imm(O.WOBBLE)
  local ampX = imm(O.AMP_X)
  local ampY = imm(O.AMP_Y)
  local ampW = imm(O.AMP_W)
  if not (life and top and wobble and ampX and ampY and ampW) then
    return fail("the note callback's own numbers are not where it keeps them")
  end
  -- the three calls, in order: Cos for the wide sweep, Sin for the dip, Cos
  -- again for the shiver.  If they are not these, the arithmetic below is
  -- not this function's arithmetic.
  local calls = self:blTargets(O.CALLBACK, O.SCAN)
  local seen = 0
  for _, t in ipairs(calls) do
    if t == O.SIN or t == O.COS then
      seen = seen + 1
      if seen <= #O.CALLS and t ~= O.CALLS[seen] then
        return fail("the note callback's sine calls are not in its own order")
      end
    end
  end
  if seen < #O.CALLS then
    return fail("the note callback does not call the cartridge's sine")
  end
  -- ...and those two have to be the sine, which means naming the table
  local function names(at, word)
    for _, w in ipairs(self:poolWords(at, 16)) do
      if w == word then return true end
    end
    return false
  end
  if not (names(O.SIN, O.SINE) and names(O.COS, O.SINE)) then
    return fail("Sin and Cos do not read the sine table")
  end
  local sine = {}
  local flat = O.SINE - 0x08000000
  for i = 0, O.SINE_ENTRIES - 1 do
    local ok, v = pcall(self.rom.u16, self.rom, flat + i * 2)
    if not ok then return fail("the sine table is off the end of the dump") end
    sine[i] = v >= 32768 and v - 65536 or v
  end
  if not (sine[0] == 0 and sine[64] == 256 and sine[128] == 0
          and sine[192] == -256) then
    return fail(("%07X is not a sine table"):format(flat))
  end
  -- ...and the timer sprite, which is only believed if it really does hide
  -- itself.  If it does not read that way it keeps being drawn, exactly as it
  -- was before -- a stray note is a smaller wrong than a missing one.
  local silent = nil
  do
    local ok = true
    for k, want in ipairs(O.SILENT.shape) do
      local okRead, h = pcall(self.rom.u16, self.rom,
                              O.SILENT.at + O.SILENT.from + (k - 1) * 2)
      if not (okRead and h == want) then ok = false break end
    end
    if ok then silent = O.SILENT.at end
  end
  self._animOrbit = {
    life = life, centreX = life,   -- `mov r5,#120` is BOTH: pos1.x and data[5]
    silent = silent,
    top = -top, ampX = ampX, ampY = ampY, ampW = ampW,
    wobbleStep = wobble, angleMul = O.ANGLE_MUL, fallDiv = O.FALL_DIV,
    quarter = O.QUARTER, sine = sine,
    source = ("ROM:the note callback at %07X, Sin %07X, Cos %07X and "
              .. "gSineTable at %07X"):format(O.CALLBACK, O.SIN, O.COS,
                                              flat),
  }
  return self._animOrbit
end

-- Checked before it is believed: the task has to name that copy callback, and
-- the copy callback has to name the sine table.  Either miss and DOUBLE TEAM
-- keeps drawing nothing, which is what it drew before.
function RomExtractorGen3:animAfterimage()
  if self._animAfterimage ~= nil then return self._animAfterimage or nil end
  local A = RomExtractorGen3.ANIM_AFTERIMAGE
  local function names(at, word)
    for _, w in ipairs(self:poolWords(at, A.POOL)) do
      if w == word then return true end
    end
    return false
  end
  if not (names(A.TASK, A.COPY)
          and names(A.COPY - (A.COPY % 2) - 0x08000000, A.SINE)) then
    Logger.warn("gen3 move animations: the afterimage task does not read as "
                  .. "itself, so DOUBLE TEAM keeps its silence")
    self._animAfterimage = false
    return nil
  end
  local sine = {}
  local flat = A.SINE - 0x08000000
  for i = 0, A.SINE_ENTRIES - 1 do
    local ok, v = pcall(self.rom.u16, self.rom, flat + i * 2)
    if not ok then self._animAfterimage = false return nil end
    sine[i] = v >= 32768 and v - 65536 or v
  end
  -- the table has to BE a sine: zero at 0, +256 at a quarter turn, back to
  -- zero at a half and -256 at three quarters.  Anything else is not it.
  if not (sine[0] == 0 and sine[64] == 256 and sine[128] == 0
          and sine[192] == -256) then
    Logger.warn("gen3 move animations: %07X is not a sine table -- "
                  .. "DOUBLE TEAM keeps its silence", flat)
    self._animAfterimage = false
    return nil
  end
  self._animAfterimage = {
    copies = A.COPIES, steps = A.STEPS, framesPerStep = A.FRAMES_PER_STEP,
    phaseStep = A.PHASE_STEP, radiusDiv = A.RADIUS_DIV,
    angleDiv = A.ANGLE_DIV, sine = sine,
    source = ("ROM:the task at %07X, its copy callback at %07X and "
              .. "gSineTable at %07X"):format(A.TASK, A.COPY - 1, flat),
  }
  return self._animAfterimage
end

-- The four addresses, checked, or nil.  Memoised: this runs once per import
-- and is asked about eleven hundred times.
function RomExtractorGen3:animMotionHelpers()
  if self._animMotion ~= nil then
    return self._animMotion or nil
  end
  local M = RomExtractorGen3.ANIM_MOTION
  local function shaped(at, want, from)
    for k, h in ipairs(want) do
      local ok, got = pcall(self.rom.u16, self.rom, at + (from + k - 1) * 2)
      if not (ok and got == h) then return false end
    end
    return true
  end
  local function loads(at, word)
    for _, w in ipairs(self:poolWords(at, 24)) do
      if w == word then return true end
    end
    return false
  end
  local ok = shaped(M.START_LINEAR, M.LINEAR_SHAPE, M.LINEAR_AT)
    and shaped(M.DRIFT, M.DRIFT_SHAPE, M.DRIFT_AT)
    and loads(M.INIT_ATTACKER, M.ATTACKER_BYTE)
    and loads(M.INIT_TARGET, M.TARGET_BYTE)
  if not ok then
    Logger.warn("gen3 move animations: the shared translation helpers do not "
                  .. "read as themselves, so no particle is given a motion")
    self._animMotion = false
    return nil
  end
  self._animMotion = M
  return M
end

-- What this particle's callback does with it: where it starts, and whether it
-- moves.  Both come off the callback's own code.
function RomExtractorGen3:animMotionOf(callback)
  local M = self:animMotionHelpers()
  if not (M and callback) then return nil, nil end
  self._animMotionCache = self._animMotionCache or {}
  local hit = self._animMotionCache[callback]
  if hit then return hit[1], hit[2] end
  local at = callback - (callback % 2)
  local from, motion = nil, nil
  for _, w in ipairs(self:poolWords(at, M.SCAN)) do
    local flat = w - (w % 2)
    if flat == M.START_LINEAR + 0x08000000 then motion = "linear"
    elseif flat == M.DRIFT + 0x08000000 and not motion then motion = "drift" end
  end
  for _, t in ipairs(self:blTargets(at, M.SCAN)) do
    if t == M.INIT_ATTACKER then from = "attacker"
    elseif t == M.INIT_TARGET and not from then from = "target" end
  end
  self._animMotionCache[callback] = { from, motion }
  return from, motion
end

function RomExtractorGen3:hiddenMovementType(callbacksAt, count)
  local romOffset = RomExtractorGen3.romOffset
  local H = RomExtractorGen3.MOVEMENT_HIDES
  local function setsInvisible(at)
    for i = 0, H.SCAN - 1 do
      local ok = true
      for k, want in ipairs(H.SET_INVISIBLE) do
        local okRead, h = pcall(self.rom.u16, self.rom, at + (i + k - 1) * 2)
        if not (okRead and h == want) then ok = false break end
      end
      if ok then return true end
    end
    return false
  end

  local found, hits = nil, 0
  for m = 0, count - 1 do
    local okCb, raw = pcall(self.rom.u32, self.rom, callbacksAt + m * 4)
    local cb = okCb and romOffset(raw - (raw % 2)) or nil
    local hit = false
    if cb then
      for _, sub in ipairs(self:poolWords(cb, H.POOL)) do
        -- a THUMB code pointer: odd, and in the cartridge
        if sub % 2 == 1 then
          local subAt = romOffset(sub - 1)
          if subAt then
            for _, tbl in ipairs(self:poolWords(subAt, H.POOL)) do
              -- ...and a DATA pointer, whose first word is code
              if tbl % 2 == 0 then
                local tblAt = romOffset(tbl)
                if tblAt then
                  local okE, entry = pcall(self.rom.u32, self.rom, tblAt)
                  if okE and entry % 2 == 1 then
                    local step0 = romOffset(entry - 1)
                    if step0 and setsInvisible(step0) then hit = true end
                  end
                end
              end
            end
          end
        end
      end
    end
    if hit then found, hits = m, hits + 1 end
  end
  if hits ~= 1 then
    Logger.warn("gen3 movement: %d of %d types reach an instruction that "
                  .. "hides their object, so which one is MOVEMENT_TYPE_HIDDEN "
                  .. "cannot be told -- nothing will be hidden", hits, count)
    return nil
  end
  return found
end

-- WHICH SPECIAL PUTS THE STARTER IN YOUR HAND, and where it writes down what
-- you picked.  See the note beside gen3Starters below: the answer is inside
-- the special, not in the script that calls it.  On the class rather than a
-- file local because this file is already at Lua's ceiling of two hundred.
RomExtractorGen3.STARTER = {
  SPECIAL = 159,
  AT_CB = 0x0A,     -- ldr r0,=CB2_GiveStarter
  AT_VAR = 0x04,    -- ldr r0,=VAR_STARTER_MON
}

function RomExtractorGen3:extractConstants()
  self:beginStage("Gen3 constants")
  local L = self.layoutValue
  local numSpecies = self:layoutValue("numSpecies", 412)
  local numMoves = self:layoutValue("numMoves", 355)
  local numItems = self:layoutValue("numItems", 377)
  local numTypes = self:layoutValue("numTypes", 18)
  local numAbilities = self:layoutValue("numAbilities", 78)

  local speciesNames = self:names("gSpeciesNames",
    self:layoutValue("speciesNameLength", 11), numSpecies, "constants")
  local moveNames = self:names("gMoveNames",
    self:layoutValue("moveNameLength", 13), numMoves, "constants")
  local typeNames = self:names("gTypeNames",
    self:layoutValue("typeNameLength", 7), numTypes, "constants")
  local abilityNames = self:names("gAbilityNames",
    self:layoutValue("abilityNameLength", 13), numAbilities, "constants")

  local constants = { source = "ROM:Emerald" }

  -- WHERE A NEW GAME STARTS, and it is not a constant anywhere on the
  -- cartridge -- it is the argument list of WarpToTruck, the only call to
  -- SetWarpDestination in 16 MiB whose map is a pair of immediates and whose
  -- warp id and coordinates are all -1.  Minus one is not "unset": it is a
  -- request for the CENTRE of the map, which is what SetPlayerCoordsFromWarp
  -- resolves it to.  The discovery pass follows all of that and hands over
  -- the group, the number and the halved layout dimensions; naming the map
  -- the way the map stage names it is all that is left to do here.
  -- ...and the intro that runs before the player ever reaches it
  constants.gen3Intro = self:introRecord()

  -- WHICH ROWS OF THE GRAPHICS TABLE THE PLAYER WEARS.  Not marked anywhere
  -- on the cartridge, but their shape is: one 16x32 walking sprite followed
  -- by 32x32 ones for the bike, the water and the field-move pose, all of
  -- them on the CHARACTER'S OWN palette -- and the palette tag is what ends
  -- the block, because the next row along wears somebody else's.
  --
  -- COUNTING FROM THE FIRST ROW DOES NOT WORK, and getting it wrong is what
  -- put the player on the water standing up: the boy's block is four rows
  -- and the girl's is FIVE -- she has a second bicycle and he does not -- so
  -- `first + 3` is her surfing sprite and his FIELD-MOVE pose, which is a
  -- boy standing still with a Poke Ball held out.  That is exactly what
  -- Hoenn's sea looked like.
  --
  -- SO EACH ROW IS ASKED WHAT IT IS, out of two fields the struct names:
  --   * `tracks` is what the sprite leaves behind in sand -- foot, bike tyre
  --     or nothing -- and the BICYCLE is the only row in a player's block
  --     that leaves a tyre;
  --   * `disableReflectionPaletteLoad` turns off the sprite's own mirror
  --     image in water, and the SURFING row is the only one in the block
  --     that does, because a surfer's reflection belongs to the thing
  --     underneath rather than to him.
  -- Both hold for the boy and the girl, and neither counts rows.
  local avatars = self.manifest.playerSprites
  local gfxTable = self:symbol("gObjectEventGraphicsInfoPointers")
  if type(avatars) == "table" and avatars.boy and avatars.girl and gfxTable then
    local gfxCount = self:layoutValue("objectEventGfxCount", 0)

    -- one row of gObjectEventGraphicsInfoPointers, in the fields this needs
    local function infoRow(id)
      if id < 0 or id >= gfxCount then return nil end
      local at = self.rom:pointer(gfxTable + id * 4)
      if not at then return nil end
      local flags = self.rom:u8(at + GEN3_GFX_INFO_FLAGS)
      return {
        palette = self.rom:u16(at + GEN3_GFX_INFO_PALETTE),
        width = self.rom:u16(at + GEN3_GFX_INFO_WIDTH),
        tracks = self.rom:u8(at + GEN3_GFX_INFO_TRACKS),
        -- the top bit of the packed byte; the low nibble is the palette slot
        noReflection = flags >= GEN3_GFX_NO_REFLECTION,
      }
    end

    -- the block: rows from `first` on that wear the same palette as it does
    local function avatarBlock(first)
      local base = infoRow(first)
      if not base then return nil end
      local block = { first }
      local id = first + 1
      while true do
        local row = infoRow(id)
        if not (row and row.palette == base.palette) then break end
        block[#block + 1] = id
        id = id + 1
      end
      local out = { walk = first }
      for _, member in ipairs(block) do
        local row = infoRow(member)
        if row.tracks == GEN3_GFX_TRACKS_BIKE and not out.bike then
          out.bike = member
        end
        if row.noReflection and member ~= first and not out.surf then
          out.surf = member
        end
      end
      return out
    end

    local boy, girl = avatarBlock(avatars.boy), avatarBlock(avatars.girl)
    if boy and girl and boy.surf and girl.surf and boy.bike and girl.bike then
      local function name(id) return ("SPRITE_G3_%03d"):format(id) end
      -- ...AND THE ONE THE BLOCK CANNOT REACH: THE DIVING SUIT.
      --
      -- Reported from play: "the surf sprite and character sprite that
      -- appears when diving isnt appearing as well when underwater".  It was
      -- not appearing because it had never been found: the underwater sprite
      -- is NOT in the player's palette block.  It wears its own palette (tag
      -- 4373) and sits at 111 and 112, seventy rows past the walking sheet,
      -- so a walk outward from row 0 can never reach it.
      --
      -- What names it is a TABLE -- sPlayerAvatarGfxIds, one { boy, girl }
      -- pair per avatar state -- and finding that table is what makes this a
      -- derivation rather than two numbers typed in:
      --
      --   [0] {  0,  89}  on foot        [3] {  2,  92}  surfing
      --   [1] {  1,  90}  MACH BIKE      [4] {111, 112}  UNDERWATER
      --   [2] { 63,  91}  ACRO BIKE      [5] {  3,  93}  using a field move
      --
      -- It is found by its FIRST pair -- the two walking rows, which the
      -- manifest already names -- and then CHECKED against row 3, which has
      -- to be the surfing pair the block derivation above worked out on its
      -- own, from palettes and reflection flags, without ever seeing this
      -- table.  Two ways to the same two numbers; if they disagree the table
      -- is not this table and nothing is written.
      --
      -- (Row 2 is why the block walk alone was never going to be enough: the
      -- boy's ACRO BIKE is row 63, sixty rows outside his own block, so the
      -- five states are not contiguous for him at all.)
      local under = self:playerAvatarStates(boy, girl)
      constants.gen3PlayerSprites = {
        boy = name(boy.walk), boyBike = name(boy.bike),
        boySurf = name(boy.surf),
        girl = name(girl.walk), girlBike = name(girl.bike),
        girlSurf = name(girl.surf),
        boyUnderwater = under and name(under.boy) or nil,
        girlUnderwater = under and name(under.girl) or nil,
        underwaterSource = under and under.source or nil,
        source = ("ROM:gObjectEventGraphicsInfoPointers[%d]=walk,%d=bike,"
                  .. "%d=surf and [%d],%d,%d")
                 :format(boy.walk, boy.bike, boy.surf,
                         girl.walk, girl.bike, girl.surf),
      }
      if under then
        Logger.info("Gen3 player sprites: underwater %d/%d, from %s",
                    under.boy, under.girl, under.source)
      else
        Logger.warn("gen3 player sprites: sPlayerAvatarGfxIds was not found "
                      .. "(or disagreed with the surfing rows), so diving "
                      .. "keeps the walking sheet")
      end
    else
      Logger.warn("gen3 player sprites: the boy's or the girl's block does "
                    .. "not name a bicycle and a surfing row, so the player "
                    .. "keeps one sheet everywhere")
    end
  end

  -- HOW AN OBJECT MOVES, which a Gen 3 template says only by a number.
  --
  -- Gen 2's object_events carry `movement` and `range` as STRINGS
  -- ("WALK", "SPIN", "ANY_DIR"), and NPC.new reads exactly those. A Gen 3
  -- object carries one byte, and the meaning of that byte lives in three
  -- tables the discovery pass corroborates against each other -- so without
  -- this every NPC in Hoenn stood facing south and never moved, including
  -- the ones the cartridge has walking laps around a room.
  --
  -- Two facts per movement type, both read straight off the cartridge:
  -- which way the object stands when the map loads, and whether it wanders
  -- inside the range its own template gives it. The third table (the step
  -- callbacks) is not decoded -- it is machine code -- but types SHARING a
  -- callback behave identically, so its pointer is kept as a behaviour class
  -- id: two types with the same `behaviour` differ only in the facing above.
  local facingAt = self:symbol("gInitialMovementTypeFacingDirections")
  local rangedAt = self:symbol("gRangedMovementTypes")
  local callbacksAt = self:symbol("sMovementTypeCallbacks")
  local moveCount = self:layoutValue("movementTypeCount", 0)
  if facingAt and rangedAt and moveCount > 0 then
    local FACING = { [1] = "down", [2] = "up", [3] = "left", [4] = "right" }
    local moves, wander = {}, 0
    for i = 0, moveCount - 1 do
      local facing = FACING[self.rom:u8(facingAt + i)]
      local ranged = self.rom:u8(rangedAt + i) == 1
      if ranged then wander = wander + 1 end
      moves[i] = {
        facing = facing or "down",
        wanders = ranged or nil,
        behaviour = callbacksAt and self.rom:u32(callbacksAt + i * 4) or nil,
      }
    end

    -- ...AND WHICH TYPE KEEPS ITS OBJECT INVISIBLE, which is machine code
    -- and is therefore read as machine code.
    --
    -- Reported from play: "all kekleons are visible without using the scope".
    -- They were, because nothing in this port knew that one movement type
    -- means "you cannot see me".  Emerald's invisible KECLEON are ordinary
    -- object events with the ordinary KECLEON sprite; what hides them is
    -- MOVEMENT_TYPE_HIDDEN, whose step-0 callback sets the object's own
    -- invisible bit and nothing else.
    --
    -- THE INSTRUCTIONS ARE THE DERIVATION.  Every movement type's callback
    -- has the same three-level shape -- a wrapper that names a sub-callback
    -- in its literal pool, a sub-callback that names a step table in its
    -- own, and a step table whose first entry is step 0 -- so the walk is
    -- mechanical.  What is looked for at the end of it is the four
    -- halfwords that set bit 5 of the object's byte 1:
    --
    --     7860  ldrb r0,[r4,#1]
    --     2120  mov  r1,#32
    --     4308  orr  r0,r1
    --     7060  strb r0,[r4,#1]
    --
    -- Exactly one of the eighty-one types reaches that, and it is 76.  Six
    -- places in the whole cartridge contain those four halfwords; the other
    -- five are movement ACTIONS and the visibility script command, none of
    -- which a movement type's step table reaches.
    --
    -- Type 76 is not Kecleon-specific -- sixteen objects use it, and only
    -- nine of them are Kecleon -- which is exactly why it is worth finding
    -- rather than special-casing a sprite id.
    local hiddenType
    if callbacksAt then
      hiddenType = self:hiddenMovementType(callbacksAt, moveCount)
      if hiddenType then moves[hiddenType].hides = true end
    end

    -- WHICH WAY a wandering object wanders, derived rather than named.
    --
    -- The cartridge has no enum here to read; what it has is that types
    -- sharing a step callback run the same code, so a group's members differ
    -- only in the facing table. Take the facings a group spans: a pair that
    -- covers up and down is an object walking a VERTICAL line, one covering
    -- left and right a horizontal one, and anything else -- a lone type, or a
    -- group spanning all four -- roams freely.
    --
    -- No names were needed to get there, and the answer is the one the
    -- cartridge behaves like: of the 41 wandering types exactly two are
    -- vertical and exactly two horizontal, which is the up/down and
    -- left/right pair each sharing one callback.
    if callbacksAt then
      local members = {}
      for i = 0, moveCount - 1 do
        local key = moves[i].behaviour
        members[key] = members[key] or {}
        table.insert(members[key], i)
      end
      for _, group in pairs(members) do
        local seen = {}
        for _, i in ipairs(group) do seen[moves[i].facing] = true end
        local axis
        if seen.up and seen.down and not seen.left and not seen.right then
          axis = "vertical"
        elseif seen.left and seen.right and not seen.up and not seen.down then
          axis = "horizontal"
        end
        if axis then
          for _, i in ipairs(group) do moves[i].axis = axis end
        end
      end
    end
    -- ----------------------------------------------------------- TURNING
    --
    -- 697 objects in Hoenn stand still and TURN, and not one of them did.
    -- The wander flag answers "does this one walk"; nothing answered "does
    -- this one look around", so every guard who should glance left and right
    -- and every trainer who should watch two ways stared in one direction
    -- for the whole game.
    --
    -- The cartridge keeps the direction SETS in code, not in a table -- each
    -- of these types is one step callback with its own hard-coded sequence --
    -- so the sets are TAKEN BY NAME from pret, and then checked against the
    -- one thing the ROM does state: the initial facing of every type.
    --
    -- That check is not a formality.  The ten pair/triple types run
    -- down, left, up, up, down, down, down, down, up, down -- a distinctive
    -- enough sequence that sliding the names by even one lands "left" where
    -- "down" belongs.  The four FACE_<dir> types are checked too, as the
    -- anchor the ten are counted from: they are the one four-member group
    -- whose members face up, down, left and right in that order.
    local TURN_SETS = {
      [1]  = { "down", "up", "left", "right" },   -- LOOK_AROUND, at random
      [13] = { "down", "up" },
      [14] = { "left", "right" },
      [15] = { "up", "left" },
      [16] = { "up", "right" },
      [17] = { "down", "left" },
      [18] = { "down", "right" },
      [19] = { "down", "up", "left" },
      [20] = { "down", "up", "right" },
      [21] = { "up", "left", "right" },
      [22] = { "down", "left", "right" },
    }
    local ROTATE = { [23] = "ccw", [24] = "cw" }
    local FACE_QUAD = { [7] = "up", [8] = "down", [9] = "left", [10] = "right" }

    local anchored = true
    local quadGroup = moves[7] and moves[7].behaviour
    for i, want in pairs(FACE_QUAD) do
      local e = moves[i]
      if not (e and e.behaviour == quadGroup and e.facing == want
              and not e.wanders) then
        anchored = false
      end
    end
    local disagree = {}
    for i, set in pairs(TURN_SETS) do
      local e = moves[i]
      if not (e and e.facing == set[1] and not e.wanders) then
        disagree[#disagree + 1] = ("%d wanted %s got %s"):format(
          i, set[1], e and tostring(e.facing) or "nothing")
      end
    end
    table.sort(disagree)
    if not anchored or #disagree > 0 then
      Logger.warn("gen3 movement: the turning types do not line up with this "
                    .. "cartridge (%s anchor, %d facing disagreement(s): %s) "
                    .. "-- leaving them all standing still rather than "
                    .. "turning the wrong ones",
                  anchored and "good" or "no", #disagree,
                  table.concat(disagree, " ", 1, math.min(#disagree, 4)))
    else
      local turners = 0
      for i, set in pairs(TURN_SETS) do
        moves[i].turns = set
        moves[i].look = (i == 1) or nil
        turners = turners + 1
      end
      for i, way in pairs(ROTATE) do
        if moves[i] and not moves[i].wanders then
          moves[i].rotate = way
          turners = turners + 1
        end
      end
      Logger.info("Gen3 movement: %d types stand still and turn, anchored on "
                    .. "the four FACE_<dir> types and agreeing with the "
                    .. "cartridge's own initial facing on every one",
                  turners)
    end

    -- index 0 is a real movement type, so the table is written as a map
    -- rather than an array: a Lua array starting at 0 loses its first entry
    -- to every `ipairs` that ever touches it.
    constants.gen3MovementTypes = moves
    constants.gen3MovementTypeCount = moveCount
    constants.gen3HiddenMovement = hiddenType
    local vert, horiz = 0, 0
    for i = 0, moveCount - 1 do
      if moves[i].wanders and moves[i].axis == "vertical" then vert = vert + 1 end
      if moves[i].wanders and moves[i].axis == "horizontal" then horiz = horiz + 1 end
    end
    Logger.info("Gen3 movement types: %d, %d wandering (%d up-down, %d "
                .. "left-right, %d free) -- "
                .. "ROM:gInitialMovementTypeFacingDirections + "
                .. "gRangedMovementTypes + sMovementTypeCallbacks%s",
                moveCount, wander, vert, horiz, wander - vert - horiz,
                hiddenType
                  and (("; type %d keeps its object invisible"):format(hiddenType))
                  or "; NO type was found to keep an object invisible")
  end

  -- THE FRONT-END MENUS, in the cartridge's own words and its own order.
  -- (startMenuPokenavFlag, below the stage, reads the one flag that hides a
  -- row; it is defined out of line so the stage stays readable.)
  --
  -- Nothing on the cartridge declares what the START menu contains: the item
  -- list is an array of {label, handler} pairs and only the label half is
  -- data. But the labels sit consecutively in the text region IN THE ORDER
  -- THE MENU DRAWS THEM, so the run is the layout, and the discovery pass
  -- pins it by the one thing that separates it from the POKéNAV's menu of
  -- the same four words -- the player's own name between POKéNAV and SAVE.
  --
  -- Read here rather than written down, because "POKéDEX, POKéMON, BAG" from
  -- memory is exactly the kind of thing that is right for Emerald and wrong
  -- for FireRed, and this file is meant to work off the cartridge in front
  -- of it.
  local startAt = self:symbol("sStartMenuText")
  if startAt then
    local labels, at = {}, startAt
    for i = 1, 10 do
      local text, used = self:readText(at, 32)
      if not (text and used) then break end
      labels[i] = text
      at = at + used
    end
    if #labels >= 8 then
      constants.gen3StartMenu = {
        -- the eight the overworld shows; RETIRE and REST are the Safari
        -- Zone's and the Battle Pyramid's and belong to those, not here
        items = { labels[1], labels[2], labels[3], labels[4], labels[5],
                  labels[6], labels[7], labels[8] },
        retire = labels[9],
        rest = labels[10],
        source = ("ROM:sStartMenuText %07X"):format(startAt),
      }
      -- WHICH FLAGS HIDE WHICH ROWS, read where the menu is built.
      --
      -- BuildStartMenuActions adds the rows in the order above and gates TWO
      -- of them the same way: `ldr r0,=<flag> / bl FlagGet / cmp r0,#1` and
      -- only then `mov r0,#<row>`.  Row 0 is the POKeDEX on $861 and row 3
      -- the POKeNAV on $862.  Both had a name borrowed from pret's header,
      -- which no Gen 3 save can ever carry -- flags are spelled
      -- FLAG_G3_%04X on this side -- so neither row could ever appear.
      for key, value in pairs(self:startMenuRowFlags()) do
        constants.gen3StartMenu[key] = value
      end
      Logger.info("Gen3 start menu: %s", table.concat(
        constants.gen3StartMenu.items, ", "))
    end
  end

  -- The OPTION screen. Its rows are NOT in screen order in memory -- BUTTON
  -- MODE sits after CANCEL -- so the order is stated here and checked by the
  -- suite against the screen; what the cartridge supplies is the vocabulary,
  -- which is the part that would otherwise be invented.
  local optionAt = self:symbol("sOptionMenuText")
  if optionAt then
    local words, at = {}, optionAt
    for i = 1, 24 do
      local text, used = self:readText(at, 32)
      if not (text and used) then break end
      if text ~= "" then words[#words + 1] = text end
      at = at + used
    end
    local function has(w)
      for _, v in ipairs(words) do if v == w then return w end end
      return nil
    end
    if has("TEXT SPEED") and has("CANCEL") then
      constants.gen3Options = {
        -- screen order, top to bottom
        rows = {
          { key = "textSpeed", label = has("TEXT SPEED"),
            values = { has("SLOW"), has("MID"), has("FAST") } },
          { key = "battleScene", label = has("BATTLE SCENE"),
            values = { has("ON"), has("OFF") } },
          { key = "battleStyle", label = has("BATTLE STYLE"),
            values = { has("SHIFT"), has("SET") } },
          { key = "sound", label = has("SOUND"),
            values = { has("MONO"), has("STEREO") } },
          -- "L=A" and not "A": $35 is the equals sign, which the cartridge
          -- proves by putting C6 35 BB between LR and the next entry in this
          -- very block. Before the charmap had it the row read NORMAL / LR
          -- and lost its third setting entirely.
          { key = "buttonMode", label = has("BUTTON MODE"),
            values = { has("NORMAL"), has("LR"), has("L=A") } },
          { key = "frame", label = has("FRAME"), value = has("TYPE") },
        },
        cancel = has("CANCEL"),
        source = ("ROM:sOptionMenuText %07X"):format(optionAt),
      }
      Logger.info("Gen3 options: %d rows, cancel %q",
                  #constants.gen3Options.rows,
                  tostring(constants.gen3Options.cancel))
    end
  end

  -- THE REST OF THE FRONT END'S VOCABULARY.
  --
  -- The same finding the START menu rests on, applied to the four screens
  -- that still had none: the BAG, the party menu, the trainer card and the
  -- save panel.  Each is a run of labels sitting end to end in the text
  -- region in the order its screen lists them, and the discovery pass
  -- records the address of each run once it has checked the run is UNIQUE.
  --
  -- The pockets are the case that matters.  Two runs of the same five words
  -- exist -- the BAG's tab order and the PC deposit list's -- and nothing
  -- but the order tells them apart, so both are recorded and this reads the
  -- BAG's.  Guessing would have put KEY ITEMS where POKe BALLS goes.
  local screens = self.manifest.screenText
  if type(screens) == "table" then
    local out = {}
    for key, record in pairs(screens) do
      if type(record) == "table" and record.at then
        -- EACH LABEL AT ITS OWN ADDRESS, not N strings walked end to end.
        -- The trainer card's block has the money symbol sitting between
        -- MONEY and POKéDEX, so a sequential reader takes the glyph as the
        -- fourth label and drops TIME off the end.
        local labels = {}
        for i, offset in ipairs(record.offsets or {}) do
          local text = self:readText(offset, 40)
          if not text then break end
          labels[i] = text
        end
        if not labels[1] then
          local at = record.at
          for _ = 1, #(record.items or {}) do
            local text, used = self:readText(at, 40)
            if not (text and used) then break end
            labels[#labels + 1] = text
            at = at + used
          end
        end
        if labels[1] then
          out[key] = { items = labels,
                       source = ("ROM:%07X"):format(record.at) }
        end
      end
    end
    if next(out) then
      constants.gen3Screens = out
      local names = {}
      for key, rec in pairs(out) do
        names[#names + 1] = ("%s(%d)"):format(key, #rec.items)
      end
      table.sort(names)
      Logger.info("Gen3 screen text: %s", table.concat(names, " "))
    end
  end

  -- THE BAG PICTURE.
  --
  -- The biggest object on the BAG screen is the bag, and the screen had a
  -- rectangle of empty green where it belongs -- because the bag is a SPRITE
  -- and every graphics pass here reads backgrounds.  The discovery pass finds
  -- it as what it is: a same-tag pair of compressed sprite sheets (the boy's
  -- bag and the girl's), six 64x64 frames each, with the sprite palette
  -- carrying that tag right behind them.
  --
  -- Both are written, because which one the screen draws is the player's own
  -- answer to Birch's question and not a property of the cartridge.
  local bag = self.manifest.bagSprite
  if type(bag) == "table" and bag.male and love and love.image
     and love.image.newImageData then
    local ok, err = pcall(function()
      -- the bag's palette is a COMPRESSED one: `CompressedSpritePalette` and
      -- `SpritePalette` are the same {pointer, tag} shape, and read raw this
      -- one comes out as a scatter of reds and blues rather than the ramp of
      -- greens the bag is drawn in
      local raw = bag.paletteCompressed and self.rom:lz77(bag.palette)
                  or self.rom:bytes(bag.palette, 32)
      if not raw then error("the palette did not decompress") end
      local colors = RomGba.palette(raw)
      local frames = math.max(1, math.floor(tonumber(bag.frames) or 1))
      local fw = math.floor(tonumber(bag.frameWidth) or 64)
      local fh = math.floor(tonumber(bag.frameHeight) or 64)
      local written = {}
      for _, which in ipairs({ "male", "female" }) do
        local art = self.rom:lz77(bag[which])
        if art then
          local image = ImageWriter.blank(fw * frames, fh)
          local tilesWide = fw / 8
          for frame = 0, frames - 1 do
            for t = 0, (fw * fh / 64) - 1 do
              local ox = (t % tilesWide) * 8 + frame * fw
              local oy = math.floor(t / tilesWide) * 8
              local base = (frame * (fw * fh / 64) + t) * 32
              for y = 0, 7 do
                for px = 0, 7 do
                  local byte = art[base + y * 4 + math.floor(px / 2) + 1]
                  local index = byte
                    and ((px % 2 == 0) and byte % 16 or math.floor(byte / 16))
                  local c = index and index ~= 0 and colors[index + 1]
                  if c then
                    image:setPixel(ox + px, oy + y,
                                   c[1] / 255, c[2] / 255, c[3] / 255, 1)
                  end
                end
              end
            end
          end
          self:saveImage(image, ("ui/gen3_bag_%s.png"):format(which))
          written[which] = ("assets/generated/ui/gen3_bag_%s.png"):format(which)
        end
      end
      if written.male or written.female then
        constants.gen3Bag = {
          male = written.male, female = written.female,
          frames = frames, frameWidth = fw, frameHeight = fh,
          source = ("ROM:sBagSpriteSheet %07X (boy %07X, girl %07X, palette "
                    .. "%07X)"):format(bag.record or 0, bag.male,
                                       bag.female or 0, bag.palette or 0),
        }
        Logger.info("Gen3 bag sprite: %d frames of %dx%d, boy and girl",
                    frames, fw, fh)
      end
    end)
    if not ok then
      Logger.warn("gen3 bag sprite: %s", tostring(err))
    end
  end

  -- THE WALL CLOCK'S FACE.
  --
  -- The new game's clock screen is a full-screen background the scene pass
  -- cannot see -- that pass only records a layer whose loader it can read a
  -- palette out of, and this one loads its two through a path the sweep does
  -- not follow -- so the port drew the clock with shapes.  The discovery pass
  -- finds it by shape and confirms it by its caller: the sheet has to be
  -- named beside special 157's own callback, and 157 is the clock.
  --
  -- Two tilemaps, because the boy's clock and the girl's differ, and both are
  -- written for the same reason both bags are.
  local clock = self.manifest.wallClock
  if type(clock) == "table" and clock.graphics and love and love.image
     and love.image.newImageData then
    local ok, err = pcall(function()
      local art = self.rom:lz77(clock.graphics)
      if not art then error("the face did not decompress") end
      local bank = {}
      for slot, at in ipairs(clock.palettes or {}) do
        local colors = RomGba.palette(self.rom:bytes(at, 32))
        for i = 1, 16 do bank[(slot - 1) * 16 + i] = colors[i] end
      end
      local cols = math.floor(tonumber(clock.width) or 32)
      local rows = math.floor(tonumber(clock.height) or 20)
      local written = {}
      for n, mapAt in ipairs(clock.tilemaps or {}) do
        local tmap = self.rom:lz77(mapAt)
        if tmap then
          local image = ImageWriter.blank(cols * 8, rows * 8)
          for cell = 0, math.min(math.floor(#tmap / 2), cols * rows) - 1 do
            local e = tmap[cell * 2 + 1] + tmap[cell * 2 + 2] * 256
            local tid = e % 1024
            local flipX = math.floor(e / 1024) % 2 == 1
            local flipY = math.floor(e / 2048) % 2 == 1
            local pl = math.floor(e / 4096) % 16
            local cx, cy = (cell % cols) * 8, math.floor(cell / cols) * 8
            for y = 0, 7 do
              local sy = flipY and (7 - y) or y
              for x = 0, 7 do
                local sx = flipX and (7 - x) or x
                local byte = art[tid * 32 + sy * 4 + math.floor(sx / 2) + 1]
                local index = byte and ((sx % 2 == 0) and byte % 16
                                        or math.floor(byte / 16)) or 0
                -- index 0 is the clock screen's own backdrop, not
                -- transparency: this picture is the whole screen
                local c = bank[pl * 16 + index + 1]
                if c then
                  image:setPixel(cx + x, cy + y,
                                 c[1] / 255, c[2] / 255, c[3] / 255, 1)
                end
              end
            end
          end
          local which = (n == 1) and "male" or "female"
          self:saveImage(image, ("ui/gen3_wallclock_%s.png"):format(which))
          written[which] = ("assets/generated/ui/gen3_wallclock_%s.png")
                           :format(which)
        end
      end
      if written.male or written.female then
        constants.gen3WallClock = {
          male = written.male, female = written.female,
          width = cols * 8, height = rows * 8,
          source = ("ROM:sWallClockGfx %07X (%d tiles, palettes %07X/%07X)")
                   :format(clock.graphics, clock.tiles or 0,
                           (clock.palettes or {})[1] or 0,
                           (clock.palettes or {})[2] or 0),
        }
        Logger.info("Gen3 wall clock: %dx%d face, boy and girl",
                    cols * 8, rows * 8)
      end
    end)
    if not ok then Logger.warn("gen3 wall clock: %s", tostring(err)) end
  end

  -- HOW WIDE A LINE OF DIALOGUE IS.
  --
  -- This is the one number in the front end that was silently wrong in a way
  -- that read as a timing bug.  The engine had ONE text box -- the Game Boy's
  -- 20-tile window with an 18-column budget -- and Emerald's text was being
  -- wrapped into it.  Every authored line that fits the cartridge's own
  -- window came out as two, a two-line page came out as four, and a page with
  -- more lines than the window shows does not stop for the reader: it scrolls
  -- them past.  The report was "some text is auto scrolling without needing
  -- me to press a", and this is it.
  --
  -- The window is the cartridge's own record: 26 columns by 4 rows at tile
  -- (2,15).  The FRAME around it is one tile out on every side, which is how
  -- every window on this cartridge is drawn, so the box the engine draws is
  -- (1,14) by 28x6 with 26 columns of text inside it.
  local window = self.manifest.messageWindow
  if type(window) == "table" and window.width and window.height then
    constants.gen3MessageWindow = {
      left = window.left, top = window.top,
      width = window.width, height = window.height,
      source = ("ROM:sWindowTemplate_Message %07X (%d refs, %d records agree)")
               :format(window.at or 0, window.refs or 0, window.agree or 0),
    }
    Logger.info("Gen3 message window: %d columns by %d rows at (%d,%d)",
                window.width, window.height, window.left, window.top)
  end

  -- THE ATTRACT SEQUENCE'S CAST.
  --
  -- Its backdrops come out of the scene pass; its choreography is task code
  -- and is reconstructed.  The ACTORS are data, and they are what the opening
  -- was missing: a bike ride with nobody on the bike is not the opening.
  -- Compressed sprite sheets picked by their own tag and byte count, each cut
  -- into frames at the shape the discovery pass names for it.  The rider's
  -- pedal cycle is seven 64x64 frames and he is ALREADY ON THE BICYCLE, so
  -- the separate bicycle sheet -- a black silhouette, four 64x32 frames -- is
  -- extracted and not drawn under him.  The Pokemon is one 128x64 picture,
  -- not two 64x64 ones.  Both riders are written, because which one a save
  -- shows is the player's own answer to Birch's question, and the three that
  -- run alongside come with them.
  local cast = self.manifest.introCast
  if type(cast) == "table" and love and love.image and love.image.newImageData
  then
    local record = {}
    for name, spec in pairs(cast) do
      local ok, err = pcall(function()
        local art = self.rom:lz77(spec.graphics)
        if not art then error("did not decompress") end
        local colors = RomGba.palette(self.rom:bytes(spec.palette, 32))
        local fw = math.floor(tonumber(spec.frameWidth) or 64)
        local fh = math.floor(tonumber(spec.frameHeight) or 64)
        local frames = math.max(1, math.floor(tonumber(spec.frames) or 1))
        local wide = fw / 8
        local perFrame = (fw * fh) / 64
        local image = ImageWriter.blank(fw * frames, fh)
        for frame = 0, frames - 1 do
          for t = 0, perFrame - 1 do
            local ox = (t % wide) * 8 + frame * fw
            local oy = math.floor(t / wide) * 8
            local base = (frame * perFrame + t) * 32
            for y = 0, 7 do
              for px = 0, 7 do
                local byte = art[base + y * 4 + math.floor(px / 2) + 1]
                local index = byte and ((px % 2 == 0) and byte % 16
                                        or math.floor(byte / 16))
                local c = index and index ~= 0 and colors[index + 1]
                if c then
                  image:setPixel(ox + px, oy + y,
                                 c[1] / 255, c[2] / 255, c[3] / 255, 1)
                end
              end
            end
          end
        end
        self:saveImage(image, ("ui/gen3_intro_%s.png"):format(name))
        record[name] = {
          image = ("assets/generated/ui/gen3_intro_%s.png"):format(name),
          frames = frames, frameWidth = fw, frameHeight = fh,
          -- how many of those frames are one animation: a sheet can hold two
          -- (Torchic's six are four of it running and two of it on its side)
          runFrames = math.max(1, math.floor(tonumber(spec.runFrames)
                                             or frames)),
          source = ("ROM:%07X tag %04X, palette %07X")
                   :format(spec.graphics, spec.tag or 0, spec.palette or 0),
        }
      end)
      if not ok then
        Logger.warn("gen3 intro cast %s: %s", name, tostring(err))
      end
    end
    if next(record) then
      constants.gen3IntroCast = record
      local names = {}
      for k in pairs(record) do names[#names + 1] = k end
      table.sort(names)
      Logger.info("Gen3 intro cast: %s", table.concat(names, " "))
    end
  end

  -- THE OPENING SHOT: the wet leaves the intro starts on.
  --
  -- The scene pass pairs ONE sheet with ONE tilemap, and this shot is one
  -- sheet with FOUR -- four backgrounds stacked, which is how the leaves sit
  -- in front of the plants in front of the hills.  So the pass could not see
  -- it and the port opened on nothing.
  --
  -- Each layer is composed on its own, in the order the cartridge loads them,
  -- with index 0 left TRANSPARENT except on the backdrop -- the cut-outs in
  -- front have to let what is behind them through, which is the whole point
  -- of there being four.
  local shots = self.manifest.introShots
  if type(shots) == "table" and love and love.image and love.image.newImageData
  then
    local out = {}
    for name, shot in pairs(shots) do
      local ok, err = pcall(function()
        local art = self.rom:lz77(shot.graphics)
        if not art then error("the sheet did not decompress") end
        local bank = {}
        do
          -- the whole 256-colour background bank: these maps pick a palette
          -- per cell like any other Gen 3 background
          local raw = self.rom:bytes(shot.palette, 512)
          for i = 0, 255 do
            local lo, hi = raw[i * 2 + 1], raw[i * 2 + 2]
            if lo and hi then bank[i] = { RomGba.bgr555(lo + hi * 256) } end
          end
        end
        local cols = math.floor(tonumber(shot.width) or 32)
        local rows = math.floor(tonumber(shot.height) or 32)
        local layers = {}
        for n, layer in ipairs(shot.layers or {}) do
          local tmap = self.rom:lz77(layer.tilemap)
          if tmap then
            local image = ImageWriter.blank(cols * 8, rows * 8)
            for cell = 0, math.min(math.floor(#tmap / 2), cols * rows) - 1 do
              local e = tmap[cell * 2 + 1] + tmap[cell * 2 + 2] * 256
              local tid = e % 1024
              local flipX = math.floor(e / 1024) % 2 == 1
              local flipY = math.floor(e / 2048) % 2 == 1
              local pl = math.floor(e / 4096) % 16
              local cx, cy = (cell % cols) * 8, math.floor(cell / cols) * 8
              for y = 0, 7 do
                local sy = flipY and (7 - y) or y
                for x = 0, 7 do
                  local sx = flipX and (7 - x) or x
                  local byte = art[tid * 32 + sy * 4 + math.floor(sx / 2) + 1]
                  local index = byte and ((sx % 2 == 0) and byte % 16
                                          or math.floor(byte / 16)) or 0
                  if index ~= 0 or layer.backdrop then
                    local c = bank[pl * 16 + index]
                    if c then
                      image:setPixel(cx + x, cy + y,
                                     c[1] / 255, c[2] / 255, c[3] / 255, 1)
                    end
                  end
                end
              end
            end
            local file = ("ui/gen3_shot_%s%d.png"):format(name, n)
            self:saveImage(image, file)
            layers[n] = {
              image = "assets/generated/" .. file,
              width = cols * 8, height = rows * 8,
              backdrop = layer.backdrop or nil,
            }
          end
        end
        -- THE THINGS THAT MOVE IN THE SHOT: the water drops that run down
        -- the leaves, the sparkles, and the silhouette that crosses the sky
        -- near the end of the scene.  Each is a compressed sprite sheet with
        -- a palette carrying its own tag.
        --
        -- A GBA sprite is stored ONE-DIMENSIONALLY -- a frame's tiles run
        -- left to right across the frame and then down it, and the next
        -- frame's tiles follow immediately -- so a sheet laid out as a flat
        -- strip of tiles is scrambled.  Each frame is composed at the size
        -- the discovery pass names for its tag, and the frames are laid side
        -- by side, which is the same layout the intro cast already uses.  A
        -- sheet with no named size keeps the flat strip: it is at least
        -- extracted, and nothing draws it.
        local sprites = {}
        for n, spr in ipairs(shot.sprites or {}) do
          local okSpr = pcall(function()
            local sart = self.rom:lz77(spr.graphics)
            if not sart then error("did not decompress") end
            local praw = spr.paletteCompressed and self.rom:lz77(spr.palette)
                         or self.rom:bytes(spr.palette, 32)
            if not praw then error("palette did not decompress") end
            local pcols = RomGba.palette(praw)
            local tiles = math.floor(#sart / 32)
            local fw = math.floor(tonumber(spr.frameWidth) or 0)
            local fh = math.floor(tonumber(spr.frameHeight) or 0)
            local frames = math.floor(tonumber(spr.frames) or 0)
            local tw, th = math.floor(fw / 8), math.floor(fh / 8)
            if frames < 1 or tw < 1 or th < 1 or tw * th * frames ~= tiles then
              fw, fh, frames = 64, math.ceil(tiles / 8) * 8, 1
              tw, th = 8, math.ceil(tiles / 8)
            end
            local image = ImageWriter.blank(fw * frames, fh)
            for t = 0, tiles - 1 do
              local frame = math.floor(t / (tw * th))
              local within = t % (tw * th)
              local ox = frame * fw + (within % tw) * 8
              local oy = math.floor(within / tw) * 8
              for y = 0, 7 do
                for px = 0, 7 do
                  local byte = sart[t * 32 + y * 4 + math.floor(px / 2) + 1]
                  local index = byte and ((px % 2 == 0) and byte % 16
                                          or math.floor(byte / 16))
                  local c = index and index ~= 0 and pcols[index + 1]
                  if c then
                    image:setPixel(ox + px, oy + y,
                                   c[1] / 255, c[2] / 255, c[3] / 255, 1)
                  end
                end
              end
            end
            local sfile = ("ui/gen3_shot_%s_spr%d.png"):format(name, n)
            self:saveImage(image, sfile)
            sprites[n] = {
              image = "assets/generated/" .. sfile,
              width = fw * frames, height = fh, tiles = tiles,
              frameWidth = fw, frameHeight = fh, frames = frames,
              role = spr.role, drop = spr.drop, ripple = spr.ripple,
              tag = spr.tag,
            }
            if spr.role then sprites[spr.role] = sprites[n] end
          end)
          if not okSpr then
            Logger.warn("gen3 intro shot %s sprite %d could not be composed",
                        name, n)
          end
        end
        if layers[1] then
          out[name] = { layers = layers, sprites = next(sprites) and sprites,
                        source = ("ROM:%07X, %d stacked tilemaps, %d sprite "
                                  .. "sheets"):format(shot.graphics,
                                                      #(shot.layers or {}),
                                                      #(shot.sprites or {})) }
        end
      end)
      if not ok then Logger.warn("gen3 intro shot %s: %s", name, tostring(err)) end
    end
    if next(out) then
      constants.gen3IntroShots = out
      Logger.info("Gen3 intro shots: %d", (function()
        local n = 0
        for _ in pairs(out) do n = n + 1 end
        return n
      end)())
    end
  end

  local spawn = self.manifest.newGame and self.manifest.newGame.spawn
  if type(spawn) == "table" and spawn.group and spawn.number then
    constants.gen3NewGameSpawn = {
      map = ("MAP_G%02d_N%02d"):format(spawn.group, spawn.number),
      x = spawn.x or 0, y = spawn.y or 0,
      source = ("ROM:NewGameInitData -> WarpToTruck(group %d, map %d), "
                .. "centre of a %dx%d layout")
               :format(spawn.group, spawn.number,
                       spawn.width or 0, spawn.height or 0),
    }
  end

  -- WHAT THE NEIGHBOURS CALL THE PLAYER.
  --
  -- `special GetPlayerBigGuyGirlString` fills the first string buffer with a
  -- word that depends on the player's gender, and lines all over Hoenn splice
  -- it in.  Unfilled, those lines print with a hole in the middle of a
  -- sentence.  The pair is the cartridge's own -- two short strings stored
  -- one after the other, which is what identifies them as a pair rather than
  -- two words that happen to exist.
  local titles = self.manifest.playerTitles
  if type(titles) == "table" and type(titles.title) == "table" then
    local record = {
      -- what an NPC calls the PLAYER, by the player's own gender
      boy = titles.title.boy.text, girl = titles.title.girl.text,
      source = ("ROM:%07X"):format(titles.title.boy.at or 0),
    }
    if type(titles.child) == "table" then
      -- ...and what a parent calls the RIVAL, which is the OPPOSITE gender:
      -- a boy's rival is somebody's daughter
      record.rivalBoy = titles.child.boy.text
      record.rivalGirl = titles.child.girl.text
    end
    constants.gen3PlayerTitles = record
  end

  -- THE STATE A NEW GAME OPENS THE WORLD IN.
  --
  -- Every flag on this cartridge starts clear and a SET flag hides its
  -- object, so on those two facts alone every gated NPC in Hoenn is on screen
  -- from the first frame -- Birch standing in Littleroot while he is also on
  -- Route 101, trainers out before their story has started, a family in a
  -- house they have not moved into.  That is what the port was showing.
  --
  -- They are not clear.  A new game runs one script whose whole body is a
  -- batch of 159 `setflag` commands, and that batch IS the opening state.
  -- The names are the same ones the script VM gives a flag, so a script that
  -- later clears one of these and the object it uncovers cannot drift apart.
  local hide = self.manifest.newGame and self.manifest.newGame.hideFlags
  if type(hide) == "table" and #hide > 0 then
    local names = {}
    for i, flag in ipairs(hide) do
      names[i] = Gen3ScriptVM.flagName(flag)
    end
    constants.gen3NewGameFlags = {
      flags = names,
      source = ("ROM:EventScript_ResetAllMapFlags, %d flags"):format(#names),
    }
    Logger.info("Gen3 new game: %d flags set, hiding the objects the world "
                .. "does not open with", #names)
  end

  local speciesIds, taken = {}, {}
  if speciesNames then
    for i = 1, numSpecies - 1 do
      speciesIds[i] = uniqueId(taken, slug(speciesNames[i]), i, "SPECIES")
    end
    constants.speciesOrder = {}
    for i = 1, numSpecies - 1 do constants.speciesOrder[i] = speciesIds[i] end

    -- THE THREE STARTERS, resolved to the ids the rest of the dataset uses.
    --
    -- `special ChooseStarter` is the most load-bearing call in the game:
    -- Route 101's rescue script hands over to it and there is no `givemon`
    -- anywhere near, so without it the player never gets a Pokemon at all
    -- and the story cannot move.  The three are the cartridge's own table --
    -- the only word-aligned place those three species ids appear in order in
    -- sixteen megabytes -- and they are mapped through the same name table
    -- everything else uses, so nothing here is a typed-in number.
    local starters = self.manifest.starters
    if type(starters) == "table" and type(starters.species) == "table" then
      local list = {}
      for n, index in ipairs(starters.species) do
        list[n] = speciesIds[index]
      end
      -- ...AND THE VAR THE CHOICE IS REMEMBERED IN, which is the half that
      -- was missing.
      --
      -- Reported from play: "it also seems like whoever i pick may still gets
      -- torchic instead of it changing based on my starter".  She did, and
      -- every other script that asks what you picked was reading the same
      -- zero -- the rival's three parties, her Route 103 battle, the Pokemon
      -- she is holding in every scene after it.
      --
      -- THE SCRIPT DOES NOT RECORD IT: `special ChooseStarter / waitstate`
      -- and nothing else.  The cartridge writes it inside the special --
      -- ChooseStarter (0B1138) hands the chooser a callback, and that
      -- callback opens with `*GetVarPointer(VAR_STARTER_MON) =
      -- gSpecialVar_Result` before it gives the Pokemon out at all.  So the
      -- var is read off that instruction rather than typed in.
      local starterVar
      do
        local S = RomExtractorGen3.STARTER
        local fn = self:specialAddress(S.SPECIAL)
        local give = fn and self:thumbLiteral(fn + S.AT_CB)
        local at = give and (give - 0x08000000 - (give % 2))
        local var = at and self:thumbLiteral(at + S.AT_VAR)
        if var and var >= 0x4000 and var < 0x8000 then
          starterVar = var
        else
          Logger.warn("gen3 starters: ChooseStarter's callback does not open "
                      .. "by writing a var, so which one you picked is not "
                      .. "recorded and every script that asks reads the same "
                      .. "answer")
        end
      end
      if list[1] and list[2] and list[3] then
        constants.gen3Starters = {
          species = list,
          level = 5,
          -- what the cartridge stores is the POSITION in this list counted
          -- from zero, which is what gSpecialVar_Result holds
          var = starterVar,
          source = ("ROM:sStarterMon %07X, the var off gSpecials[%d]'s own "
                    .. "callback (%s)")
                   :format(starters.at or 0,
                           RomExtractorGen3.STARTER.SPECIAL,
                           starterVar and ("%04X"):format(starterVar)
                           or "not found"),
        }
        Logger.info("Gen3 starters: %s, %s, %s -- what you picked is "
                    .. "remembered in var %s", list[1], list[2], list[3],
                    starterVar and ("%04X"):format(starterVar) or "nothing")
      end
    end
  end

  local moveIds, mtaken = {}, {}
  if moveNames then
    for i = 1, numMoves - 1 do
      moveIds[i] = uniqueId(mtaken, slug(moveNames[i]), i, "MOVE")
    end
    constants.moveOrder = {}
    for i = 1, numMoves - 1 do constants.moveOrder[i] = moveIds[i] end
  end

  if typeNames then
    constants.types = {}
    constants.typeOrder = {}
    for i = 0, numTypes - 1 do
      local id = slug(typeNames[i])
      if id == "" then id = ("TYPE_%02d"):format(i) end
      -- ONE-BASED, unlike speciesOrder / moveOrder / itemOrder, which are
      -- keyed by the cartridge's own number.  It is not an accident and it
      -- must not be "tidied": these two are only ever read inside this file,
      -- always as order[n + 1], and a Lua array with a [0] key makes `#`
      -- answer one short -- which is exactly what happened when this was
      -- changed to match the others: the type chart lost a type.
      --
      -- Anything OUTSIDE this file that wants a type or an ability by number
      -- must add one, the way the four readers below do.  The identifier
      -- suite pins that difference so it stays a decision rather than a trap.
      constants.typeOrder[i + 1] = id
      constants.types[id] = { id = id, index = i, name = typeNames[i] }
    end
  end

  if abilityNames then
    constants.abilities = {}
    constants.abilityOrder = {}
    local ataken = {}
    for i = 0, numAbilities - 1 do
      local id = uniqueId(ataken, slug(abilityNames[i]), i, "ABILITY")
      constants.abilityOrder[i + 1] = id
      constants.abilities[id] = { id = id, index = i, name = abilityNames[i] }
    end
  end

  -- kept on the extractor so later stages share one numbering
  self._speciesIds, self._moveIds = speciesIds, moveIds
  self._constants = constants
  self:write("constants", constants)
  self.counts.species = speciesIds and #speciesIds or 0
  self.counts.moves = moveIds and #moveIds or 0
  Logger.info("Gen3 constants: %d species, %d moves, %d types, %d abilities",
              self.counts.species, self.counts.moves, numTypes, numAbilities)
end

-- ---------------------------------------------------------------------------
-- STAGE: moves
--
-- struct BattleMove is twelve bytes: effect, power, type, accuracy, pp,
-- secondaryEffectChance, target, priority (SIGNED), flags, then padding.
-- Accuracy and the secondary chance are already percentages here, unlike
-- Gen 1/2's 0-255 scaling -- so nothing is divided on the way out.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- WHAT A MOVE DOES, in the engine's own words.
--
-- gBattleMoves gives each move an EFFECT NUMBER, and the battle engine
-- dispatches on a NAME through data.move_effects.  So every Gen 3 move
-- arrived carrying a number the registry had never heard of: 331 of the 354
-- moves in Hoenn had no effect at all -- THUNDER WAVE did not paralyse,
-- EMBER never burned, SOLARBEAM fired on the first turn, nothing lowered a
-- stat -- and each one logged an unknown effect on its way past.
--
-- THE MAP IS DERIVED, not typed.  Gen 2 and Gen 3 share 250 move NAMES, and
-- the port's Crystal import already names an effect for each of them, so a
-- shared move VOTES its Gen 3 number onto the name Johto gives it.  141 of
-- the cartridge's 198 effect numbers are covered that way and 138 of them
-- are unanimous -- every move that uses the number agrees on the name.  The
-- vote count is kept beside each row so the evidence travels with it.
--
-- THE THREE THAT DISAGREED ARE NOT DISAGREEMENTS.  Gen 1 and Gen 2 put the
-- ODDS in the effect -- BURN_SIDE_EFFECT1 is the one in ten and
-- BURN_SIDE_EFFECT2 the three in ten -- while Gen 3 has one burn effect and
-- a chance byte beside it.  So the split falls out of the cartridge's own
-- byte, and it falls out exactly: all sixteen moves across the three pairs
-- land on the side their chance says.
--
-- The 57 numbers no shared move uses are Gen 3's own -- abilities, weather,
-- SKY UPPERCUT, SUPERPOWER -- and are left as numbers so each logs itself
-- once rather than pretending to be a plain hit.
-- ---------------------------------------------------------------------------
-- HOLD EFFECTS
--
-- gItems[i].holdEffect is a number and the engine had no name for any of
-- them, so LEFTOVERS, every berry, CHOICE BAND, QUICK CLAW, FOCUS BAND and
-- the whole type-boosting family were inert -- extracted correctly and read
-- by nothing.
--
-- The names below were DERIVED before they were checked: each one is
-- confirmed by the items that carry it, which is evidence the cartridge
-- itself supplies:
-- 43 is carried by LEFTOVERS and nothing else, 39 by FOCUS BAND, 26 by
-- QUICK CLAW, 66 by STICK, 65 by THICK CLUB.  A table off by one anywhere
-- would put LEFTOVERS' name on DRAGON SCALE and be obvious the moment the
-- item list is printed beside it, which is what tests/gen3_battle_test does.
--
-- AND THEN CHECKED AGAINST pret/pokeemerald's include/constants/hold_effects.h,
-- which agrees on all 66 -- the single difference being that pret spells 27
-- FRIENDSHIP_UP where this table first said HAPPINESS_UP, and the spelling
-- here has been moved to pret's so the two can be diffed by eye.
--
-- holdEffectParam is the number the effect needs and its meaning is per
-- effect: HP for RESTORE_HP (ORAN 10, SITRUS 30), PP for RESTORE_PP, a
-- percentage for QUICK_CLAW and FOCUS_BAND and the type boosters, and an HP
-- DIVISOR for the berries that trigger in a pinch (4 = at a quarter).
local GEN3_HOLD_EFFECTS = {
  [1] = "RESTORE_HP", [2] = "CURE_PAR", [3] = "CURE_SLP", [4] = "CURE_PSN",
  [5] = "CURE_BRN", [6] = "CURE_FRZ", [7] = "RESTORE_PP",
  [8] = "CURE_CONFUSION", [9] = "CURE_STATUS",
  [10] = "CONFUSE_SPICY", [11] = "CONFUSE_DRY", [12] = "CONFUSE_SWEET",
  [13] = "CONFUSE_BITTER", [14] = "CONFUSE_SOUR",
  [15] = "ATTACK_UP", [16] = "DEFENSE_UP", [17] = "SPEED_UP",
  [18] = "SP_ATTACK_UP", [19] = "SP_DEFENSE_UP", [20] = "CRITICAL_UP",
  [21] = "RANDOM_STAT_UP", [22] = "EVASION_UP", [23] = "RESTORE_STATS",
  [24] = "MACHO_BRACE", [25] = "EXP_SHARE", [26] = "QUICK_CLAW",
  [27] = "FRIENDSHIP_UP", [28] = "CURE_ATTRACT", [29] = "CHOICE_BAND",
  [30] = "FLINCH", [31] = "BUG_POWER", [32] = "DOUBLE_PRIZE",
  [33] = "REPEL", [34] = "SOUL_DEW", [35] = "DEEP_SEA_TOOTH",
  [36] = "DEEP_SEA_SCALE", [37] = "CAN_ALWAYS_RUN", [38] = "PREVENT_EVOLVE",
  [39] = "FOCUS_BAND", [40] = "LUCKY_EGG", [41] = "SCOPE_LENS",
  [42] = "STEEL_POWER", [43] = "LEFTOVERS", [44] = "DRAGON_SCALE",
  [45] = "LIGHT_BALL", [46] = "GROUND_POWER", [47] = "ROCK_POWER",
  [48] = "GRASS_POWER", [49] = "DARK_POWER", [50] = "FIGHTING_POWER",
  [51] = "ELECTRIC_POWER", [52] = "WATER_POWER", [53] = "FLYING_POWER",
  [54] = "POISON_POWER", [55] = "ICE_POWER", [56] = "GHOST_POWER",
  [57] = "PSYCHIC_POWER", [58] = "FIRE_POWER", [59] = "DRAGON_POWER",
  [60] = "NORMAL_POWER", [61] = "UP_GRADE", [62] = "SHELL_BELL",
  [63] = "LUCKY_PUNCH", [64] = "METAL_POWDER", [65] = "THICK_CLUB",
  [66] = "STICK",
}

local GEN3_MOVE_EFFECTS = {
  [0] = { "NO_ADDITIONAL_EFFECT", votes = 21 },
  [1] = { "SLEEP_EFFECT", votes = 5 },
  [2] = { "POISON_SIDE_EFFECT2", votes = 4 },
  [3] = { "DRAIN_HP_EFFECT", votes = 4 },
  [4] = { "BURN_SIDE_EFFECT1", votes = 4 },
  [5] = { "FREEZE_SIDE_EFFECT1", votes = 4 },
  [6] = { "PARALYZE_SIDE_EFFECT1", "PARALYZE_SIDE_EFFECT2", votes = 8 },
  [7] = { "EXPLODE_EFFECT", votes = 2 },
  [8] = { "DREAM_EATER_EFFECT", votes = 1 },
  [9] = { "MIRROR_MOVE_EFFECT", votes = 1 },
  [10] = { "ATTACK_UP1_EFFECT", votes = 2 },
  [11] = { "DEFENSE_UP1_EFFECT", votes = 2 },
  [13] = { "SP_ATK_UP1_EFFECT", votes = 1 },
  [16] = { "EVASION_UP1_EFFECT", votes = 1 },
  [17] = { "SWIFT_EFFECT", votes = 2 },
  [18] = { "ATTACK_DOWN1_EFFECT", votes = 1 },
  [19] = { "DEFENSE_DOWN1_EFFECT", votes = 2 },
  [20] = { "SPEED_DOWN1_EFFECT", votes = 1 },
