  [27] = { "THRASH_PETAL_DANCE_EFFECT", votes = 3 },
  [28] = { "SWITCH_AND_TELEPORT_EFFECT", votes = 2 },
  [29] = { "TWO_TO_FIVE_ATTACKS_EFFECT", votes = 8 },
  [30] = { "CONVERSION_EFFECT", votes = 1 },
  [31] = { "FLINCH_SIDE_EFFECT1", "FLINCH_SIDE_EFFECT2", votes = 6 },
  [32] = { "HEAL_EFFECT", votes = 1 },
  [33] = { "POISON_EFFECT", votes = 1 },
  [34] = { "PAY_DAY_EFFECT", votes = 1 },
  [35] = { "LIGHT_SCREEN_EFFECT", votes = 1 },
  [36] = { "TRI_ATTACK_EFFECT", votes = 1 },
  [37] = { "HEAL_EFFECT", votes = 1 },
  [38] = { "OHKO_EFFECT", votes = 3 },
  [39] = { "CHARGE_EFFECT", votes = 1 },
  [40] = { "SUPER_FANG_EFFECT", votes = 1 },
  [41] = { "SPECIAL_DAMAGE_EFFECT", votes = 1 },
  [42] = { "TRAPPING_EFFECT", votes = 5 },
  [43] = { "NO_ADDITIONAL_EFFECT", votes = 6 },
  [44] = { "ATTACK_TWICE_EFFECT", votes = 2 },
  [45] = { "JUMP_KICK_EFFECT", votes = 2 },
