  "M_SWEET_SCENT", "M_YAWN", "M_SKY_UPPERCUT", "M_STAT_INCREASE",
  "M_HEAT_WAVE", "M_UPROAR", "M_HAIL", "M_COSMIC_POWER", "M_TEETER_DANCE",
  "M_STAT_DECREASE", "M_HAZE", "M_HYPER_BEAM2", "RG_DOOR", "RG_CARD_FLIP",
  "RG_CARD_FLIPPING", "RG_CARD_OPEN", "RG_BAG_CURSOR", "RG_BAG_POCKET",
  "RG_BALL_CLICK", "RG_SHOP", "RG_SS_ANNE_HORN", "RG_HELP_OPEN",
  "RG_HELP_CLOSE", "RG_HELP_ERROR", "RG_DEOXYS_MOVE",
  "RG_POKE_JUMP_SUCCESS", "RG_POKE_JUMP_FAILURE", "POKENAV_CALL",
  "POKENAV_HANG_UP", "ARENA_TIMEUP1", "ARENA_TIMEUP2",
  "PIKE_CURTAIN_CLOSE", "PIKE_CURTAIN_OPEN", "SUDOWOODO_SHAKE"
}

local GEN3_PHONEME_NAMES = {
  "TRAP_BLEND", "TRAP_HELD", "TRAP_SOLO", "FACE_BLEND", "FACE_HELD",
  "FACE_SOLO", "CLOTH_BLEND", "CLOTH_HELD", "CLOTH_SOLO", "DRESS_BLEND",
  "DRESS_HELD", "DRESS_SOLO", "FLEECE_BLEND", "FLEECE_HELD", "FLEECE_SOLO",
  "KIT_BLEND", "KIT_HELD", "KIT_SOLO", "PRICE_BLEND", "PRICE_HELD",
  "PRICE_SOLO", "LOT_BLEND", "LOT_HELD", "LOT_SOLO", "GOAT_BLEND",
  "GOAT_HELD", "GOAT_SOLO", "THOUGHT_BLEND", "THOUGHT_HELD",
  "THOUGHT_SOLO", "CHOICE_BLEND", "CHOICE_HELD", "CHOICE_SOLO",
  "MOUTH_BLEND", "MOUTH_HELD", "MOUTH_SOLO", "FOOT_BLEND", "FOOT_HELD",
  "FOOT_SOLO", "GOOSE_BLEND", "GOOSE_HELD", "GOOSE_SOLO", "STRUT_BLEND",
  "STRUT_HELD", "STRUT_SOLO", "CURE_BLEND", "CURE_HELD", "CURE_SOLO",
  "NURSE_BLEND", "NURSE_HELD", "NURSE_SOLO"
}

-- the engine's own role names, against the Emerald sound that IS that sound
local GEN3_SFX_ROLES = {
  Cut = "M_CUT",
  Call = "POKENAV_CALL",
  Hang_Up = "POKENAV_HANG_UP",
  Press_AB = "SELECT",
  Menu = "WIN_OPEN",
  Squeak = "DOOR",
  Get_Item = "USE_ITEM",
  Exp = "EXP",
  Faint = "FAINT",
  Run = "FLEE",
  Not_Very_Effective = "NOT_EFFECTIVE",
  Super_Effective = "SUPER_EFFECTIVE",
  Save = "SAVE",
  Escape_Rope = "REPEL",
  Switch_Pokemon = "SWITCH",
}

local GEN3_SFX_LAST = 269          -- the last sound effect
local GEN3_MUSIC_FIRST = 350       -- the first piece of music
local GEN3_PHONEME_FIRST = 559     -- the first recorded syllable
local GEN3_SFX_LOOPING_MAX = 0.15  -- an effect that loops is the exception
local GEN3_MUSIC_LOOPING_MIN = 0.5 -- a theme that does not is the exception
local GEN3_SFX_TRACKS_MAX = 3      -- an effect is one or two voices
local GEN3_MUSIC_TRACKS_MIN = 5    -- a theme is most of the eight

function RomExtractorGen3:extractSfxNames()
  self:beginStage("Gen3 sound effect names")
  local songs = self._songs
  if type(songs) ~= "table" then
    Logger.warn("gen3 sfx names: the music has to be read first")
    return
  end

  local byIndex = {}
  for _, song in pairs(songs) do
    if type(song) == "table" and song.index and song.tracks
       and #song.tracks > 0 then
      byIndex[song.index] = song
    end
  end

  -- ---- THE PROOF: the three blocks are three different shapes -------------
  local function shape(lo, hi)
    local n, loops, tracks = 0, 0, 0
    for index = lo, hi do
      local song = byIndex[index]
      if song then
        n = n + 1
        if song.loops then loops = loops + 1 end
        tracks = tracks + #song.tracks
      end
    end
    if n == 0 then return nil end
    return { count = n, looping = loops / n, tracks = tracks / n }
  end

  local effects = shape(1, GEN3_SFX_LAST)
  local music = shape(GEN3_MUSIC_FIRST, GEN3_PHONEME_FIRST - 1)
  local voice = shape(GEN3_PHONEME_FIRST, GEN3_PHONEME_FIRST + 50)
  if not (effects and music and voice) then
    Logger.warn("gen3 sfx names: this dump does not have all three blocks of "
                  .. "the sound table")
    return
  end
  if effects.looping > GEN3_SFX_LOOPING_MAX
     or effects.tracks > GEN3_SFX_TRACKS_MAX then
    Logger.warn("gen3 sfx names: the songs below %d are not shaped like sound "
                  .. "effects (%d%% loop, %.1f tracks each), so the numbering "
                  .. "the names assume is not this cartridge's",
                GEN3_SFX_LAST, math.floor(effects.looping * 100),
                effects.tracks)
    return
  end
  if music.looping < GEN3_MUSIC_LOOPING_MIN
     or music.tracks < GEN3_MUSIC_TRACKS_MIN then
    Logger.warn("gen3 sfx names: the songs from %d up are not shaped like "
                  .. "music (%d%% loop, %.1f tracks each)", GEN3_MUSIC_FIRST,
                math.floor(music.looping * 100), music.tracks)
    return
  end
  if voice.tracks > 1.01 then
    Logger.warn("gen3 sfx names: the songs from %d up are not single-track "
                  .. "recordings (%.2f tracks each), so that boundary is not "
                  .. "where the syllables start", GEN3_PHONEME_FIRST,
                voice.tracks)
    return
  end

  -- ---- name them ----------------------------------------------------------
  local names, named = {}, 0
  local numbers = {}
  for i, name in ipairs(GEN3_SFX_NAMES) do
    if byIndex[i] then
      names[i] = name
      numbers[name] = i
      byIndex[i].sfxName = name
      named = named + 1
    end
  end
  local syllables = 0
  for i, name in ipairs(GEN3_PHONEME_NAMES) do
    local index = GEN3_PHONEME_FIRST + i - 1
    if byIndex[index] then
      names[index] = name
      numbers[name] = index
      byIndex[index].sfxName = name
      syllables = syllables + 1
    end
  end

  -- ---- and answer the roles that have an exact Emerald sound --------------
  local audio = self._audio or {}
  local sfx = audio.sfx or {}
  local roles, unanswered = 0, {}
  for role, name in pairs(GEN3_SFX_ROLES) do
    local index = numbers[name]
    if index and byIndex[index] then
      sfx[role] = { m4a = index, song = ("SONG_%03X"):format(index),
                    sound = name }
      roles = roles + 1
    else
      unanswered[#unanswered + 1] = role
    end
  end
  audio.sfx = sfx
  audio.songs = songs
  self._audio = audio

  local constants = self._constants or {}
  constants.gen3SfxNames = {
    names = names,
    numbers = numbers,
    effects = effects,
    music = music,
    voice = voice,
    source = ("ROM:song table shape; %d effects below %d (%d%% loop, %.1f "
              .. "tracks), %d themes from %d (%d%% loop, %.1f tracks), %d "
              .. "single-track syllables from %d")
             :format(effects.count, GEN3_SFX_LAST,
                     math.floor(effects.looping * 100), effects.tracks,
                     music.count, GEN3_MUSIC_FIRST,
                     math.floor(music.looping * 100), music.tracks,
                     voice.count, GEN3_PHONEME_FIRST),
  }
  self._constants = constants
  self:write("constants", constants)
  self:write("audio", audio)
  Logger.info("Gen3 sound effect names: %d effects and %d syllables named; "
                .. "%d engine roles answered%s", named, syllables, roles,
              #unanswered > 0
                and ((", %d have no Emerald sound that is them (%s)")
                     :format(#unanswered, table.concat(unanswered, ", ")))
                or "")
end

-- ---------------------------------------------------------------------------
-- STAGE: the sting a trainer plays when they spot you
--
-- Every trainer record carries an encounter-music id in byte 2 -- a number
-- from 0 to 13 with the trainer's gender in the top bit -- and the engine had
-- no idea what any of those numbers meant, so it fell back on a Gen 1 list of
-- class names and played the same sting for the whole region.
--
-- THERE IS NO TABLE.  The cartridge turns the id into a song in code, with a
-- switch, which is why searching for fourteen song numbers side by side finds
-- nothing.  What a switch DOES leave in the ROM is a jump table: fourteen
-- pointers that all land within a couple of hundred bytes of themselves,
-- preceded by the word the code loads to index them -- the table's own
-- address.  Eighty-three places in Emerald have that shape.  Exactly one of
-- them has fourteen arms that each load a DIFFERENT number in the song range,
-- and that one is this.
--
-- The arms are read rather than guessed: a song number under 512 fits an
-- immediate if you halve it, so the compiler emitted `mov r0,#imm; lsl r0,#1`
-- for the even ones and a literal load for the rest, and both forms are
-- decoded.  The cross-check comes from a table that knows nothing about any
-- of this: byte 2 of the 855 trainer records has to land inside 0..13, and it
-- does, using every one of the fourteen.
-- ---------------------------------------------------------------------------

local GEN3_ENCOUNTER_MUSIC = {
  "MALE", "FEMALE", "GIRL", "SUSPICIOUS", "INTENSE", "COOL", "AQUA", "MAGMA",
  "SWIMMER", "TWINS", "ELITE_FOUR", "HIKER", "INTERVIEWER", "RICH",
}
local GEN3_ENCOUNTER_ARMS = 14
local GEN3_ENCOUNTER_SPAN = 0x200
-- which of the fourteen answers each of the engine's three roles
local GEN3_ENCOUNTER_ROLES = { meetMale = 1, meetFemale = 2, meetEvil = 7 }

function RomExtractorGen3:extractEncounterMusic()
  self:beginStage("Gen3 encounter music")
  local songs = self._songs
  if type(songs) ~= "table" then
    Logger.warn("gen3 encounter music: the music has to be read first")
    return
  end
  local rom = self.rom
  local playable = {}
  for _, song in pairs(songs) do
    if type(song) == "table" and song.index then playable[song.index] = song end
  end

  -- the two shapes a switch arm takes for a number this size
  local function arm(a)
    local h = rom:u16(a)
    if not h then return nil end
    if h >= 0x2000 and h <= 0x20FF and rom:u16(a + 2) == 0x0040 then
      return (h % 256) * 2                       -- mov r0,#imm ; lsl r0,r0,#1
    end
    if h >= 0x4800 and h <= 0x48FF then          -- ldr r0,[pc,#imm*4]
      local pc = a + 4
      pc = pc - (pc % 4)
      return rom:u32(pc + (h % 256) * 4)
    end
    return nil
  end

  local found = nil
  local at = 4
  local limit = rom.size - GEN3_ENCOUNTER_ARMS * 4 - GEN3_ENCOUNTER_SPAN - 16
  while at < limit do
    -- one byte first: the word before the table is the table's own ROM
    -- address, so its top byte is 08 and nothing else in the scan is read
    -- for the other 255 positions in 256
    if rom:u8(at - 1) == 0x08 and rom:u32(at - 4) == 0x08000000 + at then
      local body, ok = at + GEN3_ENCOUNTER_ARMS * 4, true
      for i = 0, GEN3_ENCOUNTER_ARMS - 1 do
        local v = rom:u32(at + i * 4)
        local a = v - 0x08000000
        if math.floor(v / 0x1000000) ~= 8 or v % 2 == 1
           or a < body or a > body + GEN3_ENCOUNTER_SPAN then
          ok = false
          break
        end
      end
      if ok then
        local vals, seen = {}, {}
        for i = 0, GEN3_ENCOUNTER_ARMS - 1 do
          local okArm, v = pcall(arm, rom:u32(at + i * 4) - 0x08000000)
          if not okArm then v = nil end
          if not (v and playable[v] and v >= 300 and not seen[v]) then
            vals = nil
            break
          end
          seen[v] = true
          vals[i + 1] = v
        end
        if vals then
          if found then
            Logger.warn("gen3 encounter music: %07X and %07X are both a "
                          .. "fourteen-way switch over songs, so neither is "
                          .. "used", found.at, at)
            return
          end
          found = { at = at, songs = vals }
        end
      end
    end
    at = at + 4
  end
  if not found then
    Logger.warn("gen3 encounter music: nothing in the cartridge is a "
                  .. "fourteen-arm switch whose arms each load a different "
                  .. "song")
    return
  end

  -- ---- THE CROSS-CHECK: the trainers' own byte ---------------------------
  local used, high, rows = {}, 0, 0
  for _, def in pairs(self._trainers or {}) do
    local id = tonumber(def.encounterMusic)
    if id then
      rows = rows + 1
      used[id] = (used[id] or 0) + 1
      if id > high then high = id end
    end
  end
  if rows > 0 then
    if high >= GEN3_ENCOUNTER_ARMS then
      Logger.warn("gen3 encounter music: a trainer asks for sting %d and the "
                    .. "switch at %07X only has %d, so that switch is not "
                    .. "what the byte indexes", high, found.at,
                  GEN3_ENCOUNTER_ARMS)
      return
    end
    local covered = 0
    for i = 0, GEN3_ENCOUNTER_ARMS - 1 do
      if used[i] then covered = covered + 1 end
    end
    if covered < GEN3_ENCOUNTER_ARMS - 1 then
      Logger.warn("gen3 encounter music: the trainers only ever ask for %d of "
                    .. "the %d stings at %07X", covered, GEN3_ENCOUNTER_ARMS,
                  found.at)
      return
    end
  end

  local list = {}
  for i, number in ipairs(found.songs) do
    list[i - 1] = {
      name = GEN3_ENCOUNTER_MUSIC[i] or ("STING_%d"):format(i - 1),
      song = ("SONG_%03X"):format(number),
      index = number,
    }
  end

  local audio = self._audio or {}
  local special = audio.special or {}
  for role, slot in pairs(GEN3_ENCOUNTER_ROLES) do
    local row = list[slot - 1]
    if row then special[role] = row.song end
  end
  audio.special = special
  self._audio = audio

  local constants = self._constants or {}
  constants.gen3EncounterMusic = {
    switch = found.at,
    stings = list,
    trainers = rows,
    source = ("ROM:PlayTrainerEncounterMusic switch %07X, %d stings; %d "
              .. "trainer records index it"):format(found.at,
                                                    GEN3_ENCOUNTER_ARMS, rows),
  }
  self._constants = constants
  self:write("constants", constants)
  self:write("audio", audio)
  Logger.info("Gen3 encounter music: %d stings from the switch at %07X, "
                .. "indexed by %d trainers (male %s, female %s, MAGMA %s)",
              GEN3_ENCOUNTER_ARMS, found.at, rows,
              tostring(special.meetMale), tostring(special.meetFemale),
              tostring(special.meetEvil))
end

-- ---------------------------------------------------------------------------
-- STAGE: the starter select screen
--
-- Emerald does not present the three starters as a list.  It draws a patch of
-- grass with three Poke Balls sitting on it, a hand you move between them,
-- and the Pokemon's picture and name above the one you are pointing at.  A
-- text menu is not a stand-in for that, it is a different screen.
--
-- EVERYTHING HERE IS FOUND FROM sStarterMon, which the manifest has already
-- located and checked.  pokeemerald keeps starter_choose.c's data in one
-- .rodata block, and the block reads, in ROM order:
--
--     ...   the compressed background TILEMAP        (2048 bytes = 32x32)
--     ...   the compressed background TILES          (8192 bytes = 256 tiles)
--     ...   the compressed BALL AND HAND sheet       (2048 bytes = 4 frames)
--     ...   the white circle behind the chosen ball
--     $..EC the three ball positions                 (6 bytes)
--     $..F8 sStarterMon                              <- the anchor
--     ...   the three label positions                (6 bytes)
--
-- so the sweep below walks the LZ77 blobs on either side of the anchor and
-- identifies each by its decompressed SIZE, which is unambiguous: only one
-- blob in the block is a full 256-tile character block, only one is a 32x32
-- tilemap, and the sheet is the 64-tile one after the tiles.  The positions
-- are read as three (x,y) pairs that have to lie on a 240x160 screen with x
-- increasing, which the six bytes before sStarterMon do and no neighbouring
-- six do not.
--
-- The check that it all belongs together: the tilemap's every entry must
-- index a tile the 256-tile block actually has.  A tilemap paired with the
-- wrong art fails that immediately.
-- ---------------------------------------------------------------------------

local STARTER_TILEMAP_BYTES = 32 * 32 * 2   -- one screen of BG entries
local STARTER_TILES_BYTES   = 256 * 32      -- one whole character block
local STARTER_SHEET_BYTES   = 4 * 16 * 32   -- four 32x32 OBJ frames

function RomExtractorGen3:extractStarterSelect()
  self:beginStage("Gen3 starter select")
  local constants = self._constants or {}
  local starters = self.manifest.starters
  local anchor = type(starters) == "table" and tonumber(starters.at)
  if not anchor then
    Logger.warn("Gen3 starter select: sStarterMon is not located, so its "
                  .. "screen cannot be found from it")
    return
  end

  -- ---- the three ball positions, and the three label positions ----------
  --
  -- Three (x,y) pairs on a 240x160 screen with x strictly increasing.  The
  -- balls sit in a shallow V, so their y values are not all equal; the labels
  -- sit above them at the same three x values, which is what tells the two
  -- tables apart without knowing either address.
  local function coordsAt(at)
    local xs, ys = {}, {}
    for i = 0, 2 do
      xs[i + 1] = self.rom:u8(at + i * 2)
      ys[i + 1] = self.rom:u8(at + i * 2 + 1)
    end
    for i = 1, 3 do
      if not (xs[i] and ys[i]) then return nil end
      if xs[i] < 8 or xs[i] > 232 or ys[i] < 8 or ys[i] > 152 then return nil end
    end
    if not (xs[1] < xs[2] and xs[2] < xs[3]) then return nil end
    return xs, ys
  end

  local ballAt, ballX, ballY
  for back = 4, 24, 2 do
    local xs, ys = coordsAt(anchor - back)
    if xs then ballAt, ballX, ballY = anchor - back, xs, ys break end
  end
  if not ballAt then
    Logger.warn("Gen3 starter select: no three-position table before "
                  .. "sStarterMon -- not building the screen")
    return
  end

  -- the labels are the next such table AFTER the anchor with the same x values
  local labelAt, labelY
  for ahead = 6, 96, 2 do
    local xs, ys = coordsAt(anchor + ahead)
    if xs and xs[1] == ballX[1] and xs[2] == ballX[2] and xs[3] == ballX[3]
       and ys[1] < ballY[1] then
      labelAt, labelY = anchor + ahead, ys
      break
    end
  end

  -- ---- the art, by decompressed size ------------------------------------
  local blobs = {}
  local at = anchor - 0x2000
  local stop = anchor + 0x400
  while at < stop do
    if self.rom:u8(at) == 0x10 then
      local size = self.rom:u8(at + 1) + self.rom:u8(at + 2) * 256
                   + self.rom:u8(at + 3) * 65536
      if size == STARTER_TILEMAP_BYTES or size == STARTER_TILES_BYTES
         or size == STARTER_SHEET_BYTES then
        local ok, raw = pcall(function() return self.rom:lz77(at) end)
        if ok and raw and #raw == size then
          blobs[#blobs + 1] = { at = at, size = size, raw = raw }
          at = at + 3
        end
      end
    end
    at = at + 1
  end

  local tiles, tilemap, sheet
  for i, b in ipairs(blobs) do
    if b.size == STARTER_TILES_BYTES and not tiles then
      tiles = b
      -- the tilemap is the 32x32 blob immediately BEFORE the tiles, the
      -- sheet the 64-tile blob immediately after
      for j = i - 1, 1, -1 do
        if blobs[j].size == STARTER_TILEMAP_BYTES then tilemap = blobs[j] break end
      end
      for j = i + 1, #blobs do
        if blobs[j].size == STARTER_SHEET_BYTES then sheet = blobs[j] break end
      end
    end
  end
  if not (tiles and tilemap and sheet) then
    Logger.warn("Gen3 starter select: found %s of the three art blobs near "
                  .. "sStarterMon -- not building the screen",
                tostring((tiles and 1 or 0) + (tilemap and 1 or 0)
                         + (sheet and 1 or 0)))
    return
  end

  -- the pairing check: every tilemap entry must index a tile the block has
  local highest = 0
  for i = 1, #tilemap.raw, 2 do
    local entry = tilemap.raw[i] + tilemap.raw[i + 1] * 256
    local tile = entry % 1024
    if tile > highest then highest = tile end
  end
  if highest >= 256 then
    Logger.warn("Gen3 starter select: the tilemap at %07X wants tile %d and "
                  .. "the art at %07X has 256 -- not the pair",
                tilemap.at, highest, tiles.at)
    return
  end

  -- ---- the palettes, from the loader that draws the screen --------------
  --
  -- The scene sweep has already read the code: it records, for every screen
  -- the game loads this way, the compressed art it unpacks and the
  -- LoadPalette calls it makes, with the destination COLOUR INDEX each one
  -- writes at.  The starter screen's is one call -- 31 colours at index 1,
  -- which is BG palette 0 from its second entry and the whole of palette 1 --
  -- so the scene whose graphics ARE these tiles carries the answer and
  -- nothing has to be guessed from the layout.
  --
  -- The OBJ palette the balls and the hand are drawn in is the sixteen
  -- colours immediately after that load's source range.  That is checked
  -- below rather than assumed: with the right palette the three ball frames
  -- come out RED and the fourth frame -- the hand -- comes out grey, and
  -- with a neighbouring one they do not.
  local scene
  for _, record in pairs(self._scenes or {}) do
    if type(record) == "table" and record.graphics == tiles.at then
      scene = record
      break
    end
  end
  local load1 = scene and scene.paletteLoads and scene.paletteLoads[1]
  local bgPalAt, bgPalIndex, bgPalSize, objPalAt
  if load1 and load1.source and not load1.compressed then
    bgPalAt = load1.source
    bgPalIndex = tonumber(load1.offset) or 0
    bgPalSize = tonumber(load1.size) or 0
    objPalAt = bgPalAt + bgPalSize
  end

  constants.gen3StarterSelect = {
    tiles = ("%07X"):format(tiles.at),
    tilemap = ("%07X"):format(tilemap.at),
    sheet = ("%07X"):format(sheet.at),
    ballX = ballX, ballY = ballY,
    labelY = labelY,
    frames = 4,
    frameWidth = 32, frameHeight = 32,
    -- the last of the four frames is the hand; the first three are the ball
    -- at rest and its two bounce frames
    handFrame = 4,
    source = ("ROM:starter_choose.c near sStarterMon %07X (tiles %07X, "
              .. "tilemap %07X, sheet %07X, positions %07X)")
             :format(anchor, tiles.at, tilemap.at, sheet.at, ballAt),
  }

  -- ------------------------------------------------------------------------
  -- THE QUESTION THE SCREEN ASKS, AND THE FIGHT THAT FOLLOWS IT.
  --
  -- Two things happen inside `special ChooseStarter` that no script command
  -- anywhere on the cartridge spells out, which is why both were missing:
  -- Route 101's rescue script decodes as `special 159 / waitstate` and then
  -- goes straight to Birch's "Whew..." line.  Everything between those two
  -- rows is C, and C is not in the script pool.
  --
  --   THE CONFIRM BOX.  Pointing the hand at a ball does not choose it.  The
  --   cartridge draws the Pokemon's front picture over the ball, puts its
  --   name and its dex category in a label window, and asks.  Only YES hands
  --   it over.  The question is ONE string in twelve thousand -- the only one
  --   in sixteen megabytes containing "choose this" -- so it is found by that
  --   rather than by an address somebody wrote down.
  --
  --   THE FIRST BATTLE.  The Pokemon that jumps Birch is an object event on
  --   Route 101 (local id 4, an overworld POKEMON sprite) which the rescue
  --   script `removeobject`s one row before it calls the special.  The
  --   species name is pokeemerald's -- starter_choose.c fights POOCHYENA at
  --   level 2 -- and it is written here ONLY if this cartridge's Route 101
  --   really carries that species in its own grass, at which point the LEVEL
  --   is read off that slot rather than typed in.  A wrong name therefore
  --   writes no record at all instead of a wrong one, and the port falls back
  --   to the shortened scene it had before.
  -- ------------------------------------------------------------------------
  do
    local text = self._text or {}
    local asked = {}
    for id, line in pairs(text) do
      if type(line) == "string" and line:find("choose this", 1, true) then
        asked[#asked + 1] = id
      end
    end
    if #asked == 1 then
      constants.gen3StarterSelect.confirmText = asked[1]
    else
      Logger.warn("Gen3 starter select: %d strings ask the confirm question, "
                    .. "so none is named -- the screen will fall back to its "
                    .. "own wording", #asked)
    end

    local FIRST_BATTLE_SPECIES = "POOCHYENA"
    local route = (self._encounters or {})["MAP_G00_N16"]
    local grass = route and route.grass
    local level
    for _, slot in ipairs(grass and grass.slots or {}) do
      if slot.species == FIRST_BATTLE_SPECIES then
        local low = tonumber(slot.min)
        if low and (not level or low < level) then level = low end
      end
    end
    -- the map really has to carry the animal, too -- object 4 is the one the
    -- rescue script removes, and 98 is the overworld sprite it wears
    local route101 = (self._maps or {})["MAP_G00_N16"]
    local object
    for _, o in ipairs(route101 and route101.objects or {}) do
      if tonumber(o.localId) == 4 then object = o end
    end
    if level and object then
      constants.gen3FirstBattle = {
        species = FIRST_BATTLE_SPECIES,
        level = level,
        mapId = "MAP_G00_N16",
        localId = 4,
        graphicsId = object.graphicsId,
        -- a loss does NOT black the player out: the script's very next
        -- commands are Birch's line and `special 0`, which is HealPlayerParty
        canLose = true,
        source = ("ROM:MAP_G00_N16 object 4 (sprite %s) + its own grass slot")
                 :format(tostring(object.graphicsId)),
      }
      Logger.info("Gen3 first battle: %s at level %d -- Route 101's own "
                    .. "slot, and its object 4 wears sprite %s",
                  FIRST_BATTLE_SPECIES, level, tostring(object.graphicsId))
    else
      Logger.warn("Gen3 first battle: Route 101 carries no %s in its grass "
                    .. "(or no object 4), so the scene keeps its shortened "
                    .. "form", FIRST_BATTLE_SPECIES)
    end
  end

  -- ---- and the pictures, if there is an image backend --------------------
  if love and love.image and love.image.newImageData and bgPalAt and objPalAt then
    local ok, err = pcall(function()
      -- replay the load the way the hardware sees it: colour `bgPalIndex`
      -- takes the first source colour, and everything below it is whatever
      -- the palette buffer already held (nothing, here)
      -- RomGba.palette stops at sixteen colours, which is one palette; this
      -- load is thirty-one and spans two, and taking only the first sixteen
      -- leaves palette 1 black -- which is the palette the whole background
      -- is drawn in.
      local raw = self.rom:bytes(bgPalAt, bgPalSize) or {}
      local bg = {}
      for i = 1, 32 do bg[i] = { 0, 0, 0 } end
      for i = 1, math.floor(#raw / 2) do
        local lo, hi = raw[i * 2 - 1], raw[i * 2]
        local r, g, b = RomGba.bgr555(lo + hi * 256)
        bg[bgPalIndex + i] = { r, g, b }
      end
      local obj = RomGba.palette(self.rom:bytes(objPalAt, 32) or {})

      -- the background: 32x32 entries of 8x8 tiles, but only the top 240x160
      -- is ever on screen
      local image = ImageWriter.blank(256, 256)
      for entry = 0, 32 * 32 - 1 do
        local lo = tilemap.raw[entry * 2 + 1] or 0
        local hi = tilemap.raw[entry * 2 + 2] or 0
        local word = hi * 256 + lo
        local tile = word % 1024
        local flipX = math.floor(word / 1024) % 2 == 1
        local flipY = math.floor(word / 2048) % 2 == 1
        local pal = math.floor(word / 4096) % 16
        local ox, oy = (entry % 32) * 8, math.floor(entry / 32) * 8
        for y = 0, 7 do
          for px = 0, 7 do
            local sx = flipX and (7 - px) or px
            local sy = flipY and (7 - y) or y
            local byte = tiles.raw[tile * 32 + sy * 4 + math.floor(sx / 2) + 1]
            local index = byte
              and ((sx % 2 == 0) and byte % 16 or math.floor(byte / 16))
            local c = index and bg[pal * 16 + index + 1]
            if c then
              image:setPixel(ox + px, oy + y, c[1] / 255, c[2] / 255, c[3] / 255, 1)
            end
          end
        end
      end
      self:saveImage(image, "ui/gen3_starter_bg.png")
      constants.gen3StarterSelect.background =
        "assets/generated/ui/gen3_starter_bg.png"

      -- the balls and the hand, four 32x32 frames laid side by side.  GBA
      -- OBJ tiles are 1D-mapped: a frame's sixteen tiles run four across and
      -- four down within the frame, and the next frame follows immediately.
      local sprites = ImageWriter.blank(32 * 4, 32)
      for frame = 0, 3 do
        for t = 0, 15 do
          local ox = frame * 32 + (t % 4) * 8
          local oy = math.floor(t / 4) * 8
          local base = (frame * 16 + t) * 32
          for y = 0, 7 do
            for px = 0, 7 do
              local byte = sheet.raw[base + y * 4 + math.floor(px / 2) + 1]
              local index = byte
                and ((px % 2 == 0) and byte % 16 or math.floor(byte / 16))
              local c = index and index ~= 0 and obj[index + 1]
              if c then
                sprites:setPixel(ox + px, oy + y,
                                 c[1] / 255, c[2] / 255, c[3] / 255, 1)
              end
            end
          end
        end
      end
      self:saveImage(sprites, "ui/gen3_starter_balls.png")
      constants.gen3StarterSelect.sprites =
        "assets/generated/ui/gen3_starter_balls.png"
    end)
    if not ok then
      Logger.warn("Gen3 starter select: the pictures were not composed (%s) "
                    .. "-- the layout is still written", tostring(err))
    end
  end

  self._constants = constants
  self:write("constants", constants)
  Logger.info("Gen3 starter select: balls at (%d,%d) (%d,%d) (%d,%d), "
                .. "art %07X/%07X, sheet %07X",
              ballX[1], ballY[1], ballX[2], ballY[2], ballX[3], ballY[3],
              tiles.at, tilemap.at, sheet.at)
end

-- ---------------------------------------------------------------------------
-- STAGE: the naming keyboard
--
-- The screen that asks for the player's name and every nickname after it.
-- The port was drawing GEN 1's -- five rows of nine, "×():;[]", a PK and an
-- MN cell -- on Emerald, where the keyboard is a different shape entirely:
-- four rows of EIGHT, three pages, digits and typographic quotes instead of
-- the Game Boy's symbol row.  Nothing about it is wrong in Gen 1; it is
-- simply the wrong cartridge's keyboard, and it is on screen at the first
-- thing a new game asks anybody to type.
--
-- FOUND BY SHAPE, not by an address.  sNamingScreenKeyboardText is twelve
-- rows of exactly eight bytes with no terminators between them -- 96 bytes --
-- and the block is identified by what it CONTAINS:
--
--     rows  1-4   the 26 lowercase letters, in order, nothing else but
--                 spaces and two punctuation marks
--     rows  5-8   the 26 uppercase letters, in the same positions
--     rows  9-12  the ten digits in order, then symbols and no letters
--
-- Nothing else in sixteen megabytes satisfies all three at once, so the
-- candidate list coming back with exactly one entry IS the identification --
-- and if a re-derivation ever finds two, the stage writes nothing rather than
-- picking one.
--
-- The three page buttons are three consecutive strings ("UPPER", "lower",
-- "OTHERS"), and which page each names is read off the strings themselves --
-- the all-uppercase one names the uppercase page -- rather than by trusting
-- the order they happen to sit in.
-- ---------------------------------------------------------------------------

function RomExtractorGen3:extractNamingKeyboard()
  self:beginStage("Gen3 naming keyboard")
  local map = self:charmap()
  local byteOf = self:charmapReverse()

  local COLUMNS, ROWS, PAGES = 8, 4, 3
  local PAGE_BYTES = COLUMNS * ROWS
  local BLOCK = PAGE_BYTES * PAGES

  local function letters(text, from, to)
    local out = {}
    for ch in tostring(text):gmatch("[%a]") do out[#out + 1] = ch end
    local want = {}
    for b = from, to do want[#want + 1] = string.char(b) end
    return table.concat(out) == table.concat(want)
  end

  local function pageRows(off)
    local rows = {}
    for r = 1, ROWS do
      rows[r] = self:readString(off + (r - 1) * COLUMNS, COLUMNS)
      if #rows[r] == 0 or rows[r]:find("{BYTE:") then return nil end
    end
    return rows
  end

  -- ...AND THE SAME ROWS AS CELLS, one byte at a time.
  --
  -- A keyboard row is not a word, it is eight BUTTONS, and the difference
  -- matters: decoded as a string and cut up again by the font's own splitter,
  -- the uppercase row "MNOPQRS" comes back with M and N joined -- because
  -- "MN" is a LIGATURE in the Game Boy charmap (the <PK><MN> of POKeMON), and
  -- the splitter is right to join it in a word and wrong to join it here.  On
  -- screen that put two letters in one key and left the row a cell short.
  local function pageCells(off)
    local rows = {}
    for r = 1, ROWS do
      local row = {}
      for c = 1, COLUMNS do
        row[c] = self:readString(off + (r - 1) * COLUMNS + (c - 1), 1)
      end
      rows[r] = row
    end
    return rows
  end

  -- the needle is the first six lowercase letters, which every candidate
  -- block starts with; the checks below are what decide
  local needle = {}
  for i = 0, 5 do
    local b = byteOf[string.char(string.byte("a") + i)]
    if not b then
      Logger.warn("gen3 naming keyboard: this charmap has no lowercase "
                    .. "letters, so the block cannot be found")
      return
    end
    needle[#needle + 1] = string.char(b)
  end
  needle = table.concat(needle)

  local found = {}
  local at = 1
  while true do
    local i = self.rom.data:find(needle, at, true)
    if not i then break end
    at = i + 1
    local off = i - 1
    if off + BLOCK <= self.rom.size then
      local lower = pageRows(off)
      local upper = lower and pageRows(off + PAGE_BYTES)
      local other = upper and pageRows(off + PAGE_BYTES * 2)
      if other
        and letters(table.concat(lower), string.byte("a"), string.byte("z"))
        and letters(table.concat(upper), string.byte("A"), string.byte("Z"))
        and table.concat(other):find("%a") == nil
        and table.concat(other):gsub("%D", "") == "0123456789" then
        found[#found + 1] = {
          at = off,
          pages = { lower, upper, other },
          cells = { pageCells(off), pageCells(off + PAGE_BYTES),
                    pageCells(off + PAGE_BYTES * 2) },
        }
      end
    end
  end

  if #found ~= 1 then
    Logger.warn("gen3 naming keyboard: %d blocks match the keyboard's shape, "
                  .. "so none is used -- the screen keeps whatever layout it "
                  .. "had", #found)
    return
  end
  local block = found[1]

  -- the order the block STORES them in, which is not the order the button
  -- walks them in
  local NAMES = { "lower", "upper", "symbols" }

  -- ---- the three page buttons ---------------------------------------------
  --
  -- Three consecutive terminated strings, and the ORDER THEY SIT IN IS THE
  -- ORDER THE BUTTON CYCLES: pressing it on the uppercase page gives you the
  -- lowercase one, then the symbols one, then back.  Positional, but not
  -- unchecked -- the first has to be the all-uppercase word and the second
  -- the all-lowercase one, or the run found is not this run.
  local CYCLE = { "upper", "lower", "symbols" }
  local labels = {}
  do
    local eos = string.char(0xFF)
    local function encode(word)
      local out = {}
      for ch in word:gmatch(".") do
        local b = byteOf[ch]
        if not b then return nil end
        out[#out + 1] = string.char(b)
      end
      return table.concat(out)
    end
    local words = { "UPPER", "lower", "OTHERS" }
    local parts = {}
    for i, word in ipairs(words) do parts[i] = encode(word) end
    local run = parts[1] and parts[2] and parts[3]
                and (parts[1] .. eos .. parts[2] .. eos .. parts[3] .. eos)
    local buttonsAt = run and self.rom.data:find(run, 1, true)
    if buttonsAt and words[1] == words[1]:upper()
       and words[2] == words[2]:lower() then
      for i, name in ipairs(CYCLE) do labels[name] = words[i] end
      labels.at = buttonsAt - 1
    else
      Logger.warn("gen3 naming keyboard: the three page buttons were not "
                    .. "found together, so the pages are unlabelled")
    end
  end

  local pages = {}
  for i, rows in ipairs(block.pages) do
    pages[i] = {
      name = NAMES[i],
      label = labels[NAMES[i]],
      rows = rows,
      -- one entry per KEY, so nothing has to cut the row up again
      cells = block.cells and block.cells[i] or nil,
    }
  end

  -- ---- where the keys are DRAWN ------------------------------------------
  --
  -- The port had the right keys in the wrong place: eight columns on an even
  -- pitch, on a bare white screen.  Emerald's are not evenly spaced, and the
  -- gap is not decoration -- "abcdef ." is three letters, a gap, three more
  -- and a space, then the full stop set apart on its own at the right.  That
  -- shape is a table in the cartridge, and it sits WITH the keyboard:
  -- naming_screen.c's read-only data is one run, and the 96 bytes found above
  -- are in the middle of it.
  --
  --     block - 0x30   sWindowTemplates: the keyboard window, the text entry
  --                    and the box above it, as {bg, left, top, w, h, pal,
  --                    baseBlock} -- ending in the 0xFF that closes every
  --                    window template list, which is what makes the guess
  --                    checkable
  --     block          the 96 bytes of keys
  --     block + 96     sPageColumnCounts {8, 8, 6}
  --     block + 99     sPageColumnXPos, three rows of eight
  --
  -- Read at a fixed distance from a block that was found by SHAPE, so the
  -- only thing trusted is that the compiler emitted one translation unit's
  -- rodata in order.  Every field is checked against what it has to be -- the
  -- terminator, the counts, x positions that increase and fit on a 240-pixel
  -- screen -- and a single failure drops the whole layout rather than half of
  -- it, leaving the screen on the even pitch it drew before.
  local layout = nil
  do
    local rom = self.rom
    local ok, built = pcall(function()
      local templates = {}
      local base = block.at - 0x30
      if base < 0 then return nil end
      -- the four templates, then a fifth and the 0xFF that closes the list
      if rom:u8(block.at - 8) ~= 0xFF then return nil end
      for i = 0, 3 do
        local off = base + i * 8
        local win = { bg = rom:u8(off), left = rom:u8(off + 1),
                      top = rom:u8(off + 2), width = rom:u8(off + 3),
                      height = rom:u8(off + 4) }
        if win.left + win.width > 32 or win.top + win.height > 32
           or win.width == 0 or win.height == 0 then
          return nil
        end
        templates[i + 1] = win
      end
      local counts, columns = {}, {}
      for i = 1, PAGES do
        local n = rom:u8(block.at + BLOCK + (i - 1))
        if n < 1 or n > COLUMNS then return nil end
        counts[i] = n
      end
      for i = 1, PAGES do
        local xs, last = {}, -1
        for c = 1, counts[i] do
          local x = rom:u8(block.at + BLOCK + PAGES + (i - 1) * COLUMNS + (c - 1))
          if x <= last or x >= 240 then return nil end
          last = x
          xs[c] = x
        end
        columns[NAMES[i]] = xs
      end
      return { keyboard = templates[1], entry = templates[3],
               entryBox = templates[4], columns = columns,
               source = ("ROM:sNamingScreenWindowTemplates %07X + "
                         .. "sPageColumnXPos %07X")
                        :format(base, block.at + BLOCK + PAGES) }
    end)
    if ok and built then
      layout = built
    else
      Logger.warn("gen3 naming keyboard: the screen's own geometry did not "
                    .. "check out beside the keys, so the keys are laid out "
                    .. "on an even pitch instead")
    end
  end

  local constants = self._constants or {}
  constants.gen3Keyboard = {
    columns = COLUMNS,
    rows = ROWS,
    pages = pages,
    -- the order the page button walks them in, which is not the order they
    -- are stored in
    cycle = CYCLE,
    -- ...and the one a fresh screen opens on
    opensOn = CYCLE[1],
    -- WHERE THE CARTRIDGE PUTS THEM, when the run beside the keys checks out
    layout = layout,
    source = ("ROM:sNamingScreenKeyboardText %07X%s")
             :format(block.at,
                     labels.at and (" + its page buttons %07X")
                                   :format(labels.at) or ""),
  }
  self._constants = constants
  self:write("constants", constants)

  local shown = {}
  for _, page in ipairs(pages) do
    shown[#shown + 1] = ("%s[%s]"):format(page.name,
                                          (page.rows[1] or ""):gsub(" ", "_"))
  end
  Logger.info("Gen3 naming keyboard: %d rows of %d over %d pages at %07X -- %s",
              ROWS, COLUMNS, PAGES, block.at, table.concat(shown, " "))
end

-- ---------------------------------------------------------------------------
-- STAGE: the battle menu
--
-- FIGHT / BAG / POKeMON / RUN, and the question above them.  Gen 1's menu is
-- FIGHT / <PK><MN> over ITEM / RUN and the port was drawing that in Hoenn --
-- four words, two of them wrong, and the two that survive are in the other
-- diagonal.  It is on screen for most of every battle.
--
-- THE WHOLE MENU IS ONE STRING, and the layout is inside it:
--
--     FIGHT {CLEAR_TO 56} BAG {NEWLINE} POKeMON {CLEAR_TO 56} RUN
--
-- CLEAR_TO is $FC $13 <pixels> -- "pad to this x within the window" -- so the
-- cartridge itself says there are two columns, that the second starts 56
-- pixels in, and that the split between the rows is after BAG.  None of that
-- has to be measured off a screenshot, and a re-derivation that finds a
-- different offset moves the menu rather than needing this file edited.
--
-- The question above it is the string immediately before, and it is told from
-- its two neighbours -- there are three "What will ... do?" lines -- by
-- carrying a PLACEHOLDER where the name goes: the third names WALLY outright,
-- because the tutorial battle is fought with somebody else's Pokemon.
-- ---------------------------------------------------------------------------

local GEN3_EXTRA = 0xFC          -- the "next byte is a control code" escape
local GEN3_CLEAR_TO = 0x13       -- ...and the one that pads to an x position
local GEN3_NEWLINE = 0xFE
local GEN3_PLACEHOLDER = 0xFD
local GEN3_EOS = 0xFF

function RomExtractorGen3:extractBattleMenu()
  self:beginStage("Gen3 battle menu")
  local map = self:charmap()
  local byteOf = self:charmapReverse()
  local function encode(word)
    local out = {}
    for ch in word:gmatch(".") do
      local b = byteOf[ch]
      if not b then return nil end
      out[#out + 1] = string.char(b)
    end
    return table.concat(out)
  end

  -- a run of ordinary glyphs, stopping at the first control byte
  local function word(off)
    local out, at = {}, off
    while true do
      local b = self.rom:u8(at)
      if b == GEN3_EOS or b == GEN3_NEWLINE or b == GEN3_EXTRA
         or b == GEN3_PLACEHOLDER then
        break
      end
      local glyph = map[b]
      if not glyph then return nil end
      out[#out + 1] = glyph
      at = at + 1
    end
    if #out == 0 then return nil end
    return table.concat(out), at
  end

  -- ---- the menu itself ----------------------------------------------------
  local needle = encode("FIGHT")
  if not needle then
    Logger.warn("gen3 battle menu: this charmap cannot spell the first entry")
    return
  end

  local found = {}
  local at = 1
  while true do
    local i = self.rom.data:find(needle, at, true)
    if not i then break end
    at = i + 1
    local off = i - 1
    local ok = true
    local rows, gap = {}, nil
    local cursor = off
    for r = 1, 2 do
      local left, after = word(cursor)
      if not left then ok = false break end
      -- CLEAR_TO, which is what says there is a second column at all
      if self.rom:u8(after) ~= GEN3_EXTRA
         or self.rom:u8(after + 1) ~= GEN3_CLEAR_TO then
        ok = false break
      end
      local px = self.rom:u8(after + 2)
      if gap and gap ~= px then ok = false break end
      gap = px
      local right, tail = word(after + 3)
      if not right then ok = false break end
      rows[r] = { left, right }
      local terminator = self.rom:u8(tail)
      if r == 1 then
        if terminator ~= GEN3_NEWLINE then ok = false break end
        cursor = tail + 1
      else
        if terminator ~= GEN3_EOS then ok = false break end
      end
    end
    if ok and gap and gap > 0 then
      found[#found + 1] = { at = off, rows = rows, gap = gap }
    end
  end

  if #found ~= 1 then
    Logger.warn("gen3 battle menu: %d strings have the menu's shape, so none "
                  .. "is used -- the battle keeps the Game Boy's four words",
                #found)
    return
  end
  local menu = found[1]

  -- ---- the question above it ----------------------------------------------
  local prompt, promptAt
  do
    local head = encode("What will")
    local from = 1
    while head do
      local i = self.rom.data:find(head, from, true)
      if not i then break end
      from = i + 1
      local off = i - 1
      local first, after = word(off)
      -- "What will" then a line break then a PLACEHOLDER: the variant that
      -- names WALLY outright is the tutorial's and is not this one
      if first and self.rom:u8(after) == GEN3_NEWLINE
         and self.rom:u8(after + 1) == GEN3_PLACEHOLDER then
        local rest = word(after + 3)
        if rest then
          prompt = { first, "{MON}" .. rest }
          promptAt = off
          break
        end
      end
    end
    if not prompt then
      Logger.warn("gen3 battle menu: the question above it was not found, so "
                    .. "the prompt half keeps its own wording")
    end
  end

  local constants = self._constants or {}
  constants.gen3BattleMenu = {
    rows = { { menu.rows[1][1], menu.rows[1][2] },
             { menu.rows[2][1], menu.rows[2][2] } },
    -- the second column's x, in pixels, off the string's own CLEAR_TO
    columnX = menu.gap,
    prompt = prompt,
    source = ("ROM:gText_BattleMenu %07X%s")
             :format(menu.at,
                     promptAt and (" + the question at %07X"):format(promptAt)
                     or ""),
  }
  self._constants = constants
  self:itemMenuActions(constants)
  self:trainerCardBadges(constants)
  self:write("constants", constants)
  Logger.info("Gen3 battle menu: %s | %s // %s | %s, second column at %dpx%s",
              menu.rows[1][1], menu.rows[1][2], menu.rows[2][1],
              menu.rows[2][2], menu.gap,
              prompt and (" -- %q / %q"):format(prompt[1], prompt[2]) or "")
end


-- ---------------------------------------------------------------------------
-- WHAT THE BAG OFFERS TO DO WITH AN ITEM, and the words the flow says.
--
-- Reported from play, twice: nothing happens when a TM or an HM is chosen in
-- Hoenn.  The cause was that Emerald's bag pushed a screen called
-- `ItemUseMenu` that does not exist anywhere in this port, inside a pcall
-- that logged "no item flow yet" and swallowed it -- so EVERY out-of-battle
-- item use in Hoenn silently did nothing, TMs and HMs among them, while the
-- machine data and the teaching code were both already present.
--
-- The screen that belongs there is the cartridge's little context menu, and
-- what it offers is not the same in every pocket: a POKe BALL cannot be USED
-- from the bag, a TM cannot be TOSSED, a KEY ITEM can be REGISTERED to
-- SELECT and nothing else, and a BERRY offers CHECK TAG above all of it.
-- Those five lists are in the cartridge.
--
-- FINDING THEM.  sItemMenuActions is a run of {text pointer, function
-- pointer} records, and the run's first record points at the same "USE" the
-- bag's own label block already gave this port an address for -- so the
-- anchor is a string the import already knows, not an offset.  Immediately
-- after the run come the per-pocket lists, one byte per action.
--
-- READING THEM WITHOUT BEING TOLD.  Three things fall out of the run itself:
--
--   * THE FUNCTION POINTERS GROUP THE ACTIONS.  Three records share one
--     function -- USE, CHECK and WALK -- and no other function is shared
--     three ways, so that group is "use it out here" whatever the words say.
--     Two more share another (REGISTER and DESELECT), which is the same
--     action seen from both sides of a registration.
--   * THE LISTS END ON THE SAME ACTION.  Trying each action id as the
--     terminator, exactly one splits the bytes into five lists of a
--     believable length -- and only that one produces the arrangement the
--     cartridge is known for, where four pockets offer the use action and the
--     BALL pocket does not.  That is the check, and it is refused if it
--     fails.
--   * THE REST NAME THEMSELVES BY WHERE THEY APPEAR.  GIVE is the action the
--     TM pocket offers besides USE; TOSS is the one the ITEM pocket offers
--     that the TM pocket does not; REGISTER is what the KEY ITEM pocket has
--     instead; CHECK TAG is what the BERRY pocket puts first.
--
-- The blank is real: one record has no text and no function, and the lists
-- use it to hold a cell open so the two-column grid lines up.  Dropping it
-- would move CANCEL under USE in the key-item menu, which is not where the
-- cartridge puts it.
-- ---------------------------------------------------------------------------

-- The fragments of the item flow's own dialogue, and what the engine calls
-- each.  Matched on the cartridge's words rather than an address, exactly as
-- the hidden-item lines are.
local ITEM_TEXT = {
  { key = "bootedTM",   find = "Booted up a TM" },
  { key = "bootedHM",   find = "Booted up an HM" },
  { key = "contained",  find = "It contained" },
  { key = "tossPrompt", find = "Throw away this" },
  { key = "tossed",     find = "was thrown away" },
}

-- AND THE MART'S, which is the same block: the clerk's whole script sits a
-- few hundred bytes past the bag's labels, so one walk finds both.
--
-- Reported from play: "the pokemart menu isn't gen3's pokemart menu for buy
-- or sell, it's falling back to gen1".  It was -- ShopMenu is pokered's
-- DisplayPokemartDialogue_ with Kanto's strings and Kanto's yen sign, and no
-- Gen 3 dataset carries the `_Pokemart*` keys it looks for, so every line
-- fell through to the engine's own English.  These are Hoenn's.
--
-- ORDER MATTERS in two places: "How many would you like to sell?" contains
-- "How many would you like", so the sell line is tested first; and the
-- apostrophe in "I can't buy that" is the cartridge's curly one, so the
-- fragment stops short of it.
local MART_TEXT = {
  { key = "sellHowMany",  find = "How many would you like to sell" },
  { key = "buyHowMany",   find = "How many would you like?" },
  { key = "buyTotal",     find = "And you wanted" },
  { key = "boughtBag",    find = "Here you go!" },
  { key = "boughtPC",     find = "send it to your home PC" },
  { key = "noMoney",      find = "enough money" },
  { key = "bagFull",      find = "no more room for this" },
  { key = "spaceFull",    find = "space for" },
  { key = "anythingElse", find = "anything else I can help" },
  { key = "premierBall",  find = "PREMIER BALL, too" },
  { key = "cantBuy",      find = "buy that" },
  { key = "sellPrice",    find = "I can pay" },
  { key = "sold",         find = "Turned over the" },
  { key = "quitShopping", find = "Quit shopping" },
  { key = "inBag",        find = "IN BAG:" },
}
-- the three menu words, matched whole
local MART_WORDS = { BUY = "buy", SELL = "sell", QUIT = "quit" }

-- ---------------------------------------------------------------------------
-- THE EIGHT BADGES ON THE TRAINER CARD.
--
-- Reported from play: "badge graphics for emerald are still missing... in the
-- trainer card".  The card drew eight rectangles, filled for the ones earned,
-- because the art had not been found -- and it had not been found because
-- every search for it looked for a SPRITE.  It is not one.
--
-- The cartridge draws the badges as BACKGROUND TILES.  Its own routine writes
-- four tilemap cells per badge -- t, t+1 on one row and t+16, t+17 on the
-- next, starting at tile 192 and stepping by two -- which says three things at
-- once: the sheet is sixteen tiles wide, it is two rows tall, and the eight
-- badges sit side by side across it.  Thirty-two tiles, 1024 bytes, one shared
-- palette for all eight.
--
-- FINDING IT WITHOUT AN ADDRESS.
--
--   * THE STRIP.  A 1024-byte LZ77 stream that, read as a sixteen-wide
--     two-row grid, holds eight inked and mutually distinct emblems.  There
--     are more of those than one would like.
--   * THE PAIR.  Hoenn's and Kanto's sit end to end -- the second stream
--     begins where the first one's compressed bytes stop.  Five such pairs
--     exist in the cartridge, so this is not enough either.
--   * WHAT LOADS THEM.  The badges are drawn on BG palette 3, and the
--     cartridge fills that palette with `LoadPalette(pal, 0x30, 0x20)` --
--     which compiles to `ldr r0, [pc, #x] / movs r1, #0x30 / movs r2, #0x20`
--     and occurs twelve times in sixteen megabytes.  Exactly one of the five
--     pairs has TWO of those sites pointing at palettes thirty-two bytes
--     apart in the kilobyte before it, which is a card that has a Hoenn side
--     and a Kanto side and a palette for each.  That is the pair.
--
-- The badges come out greyed and embossed rather than coloured, which is
-- right: one palette serves all eight, and the eight of them use five inks
-- between them.
-- ---------------------------------------------------------------------------
function RomExtractorGen3:trainerCardBadges(constants)
  local rom = self.rom
  if not rom then return end
  local BADGES, STRIP_TILES, TILE_BYTES = 8, 32, 32
  local STRIP_BYTES = STRIP_TILES * TILE_BYTES

  -- one strip, or nil
  local function strip(off)
    local clen, size = lz77Length(rom, off)
    if not (clen and size == STRIP_BYTES) then return nil end
    local ok, raw = pcall(rom.lz77, rom, off)
    if not (ok and type(raw) == "table" and #raw == STRIP_BYTES) then
      return nil
    end
    local seen = {}
    for i = 0, BADGES - 1 do
      local sig, inked = {}, 0
      for _, t in ipairs({ 2 * i, 2 * i + 1, 16 + 2 * i, 17 + 2 * i }) do
        for k = 1, TILE_BYTES do
          local v = raw[t * TILE_BYTES + k] or 0
          if v ~= 0 then inked = inked + 1 end
          sig[#sig + 1] = string.char(v)
        end
      end
      local s = table.concat(sig)
      if inked < 50 or seen[s] then return nil end
      seen[s] = true
    end
    return clen, raw
  end

  local candidates = {}
  for o = 0, rom.size - 8, 4 do
    if rom:u8(o) == 0x10 then
      local clen, raw = strip(o)
      if clen then
        local nxt = align4(o + clen)
        local clen2, raw2 = strip(nxt)
        if clen2 then
          candidates[#candidates + 1] = { first = o, second = nxt,
                                          a = raw, b = raw2 }
        end
      end
    end
  end
  if not candidates[1] then
    Logger.warn("gen3 trainer card: no pair of eight-emblem strips found -- "
                .. "the card keeps its rectangles")
    return
  end

  -- every LoadPalette(x, BG_PLTT_ID(3), PLTT_SIZE_4BPP) in the cartridge
  local loads = {}
  for o = 2, rom.size - 8, 2 do
    if rom:u16(o) == 0x2130 and rom:u16(o + 2) == 0x2220 then
      local ldr = rom:u16(o - 2)
      if math.floor(ldr / 256) == 0x48 then
        local at = math.floor((o + 2) / 4) * 4 + (ldr % 256) * 4
        local w = rom:u32(at)
        if w >= 0x08000000 and w - 0x08000000 < rom.size then
          loads[#loads + 1] = w - 0x08000000
        end
      end
    end
  end

  local chosen
  for _, cand in ipairs(candidates) do
    for _, first in ipairs(loads) do
      for _, second in ipairs(loads) do
        if second - first == 32 and first < cand.first
           and cand.first - first <= 0x1000 then
          if chosen then
            Logger.warn("gen3 trainer card: more than one emblem pair has a "
                        .. "palette pair before it -- the card keeps its "
                        .. "rectangles")
            return
          end
          chosen = { pair = cand, hoennPal = first, kantoPal = second }
        end
      end
    end
  end
  if not chosen then
    Logger.warn("gen3 trainer card: %d emblem pair(s), none of them with two "
                  .. "BG-palette-3 loads before it -- the card keeps its "
                  .. "rectangles", #candidates)
    return
  end

  local function blob(t)
    local out = {}
    for i = 1, #t do out[i] = string.char(t[i] % 256) end
    return table.concat(out)
  end

  constants.gen3TrainerCardBadges = {
    -- the sheet as the cartridge stores it, and the arithmetic its own
    -- drawing routine uses to find a badge in it
    tiles = blob(chosen.pair.a),
    palette = RomGba.palette(rom:bytes(chosen.hoennPal, 32)),
    columns = 16,
    rows = 2,
    count = BADGES,
    -- badge n (from 1) is tiles (2n-2, 2n-1) on row 0 and the two beneath
    kanto = { tiles = blob(chosen.pair.b),
              palette = RomGba.palette(rom:bytes(chosen.kantoPal, 32)) },
    source = ("ROM:sTrainerCardBadges %07X gfx, %07X palette")
             :format(chosen.pair.first, chosen.hoennPal),
  }
  self._constants = constants
  Logger.info("Gen3 trainer card badges: %d emblems at %07X (palette %07X), "
                .. "Kanto's at %07X (palette %07X), from %d candidate pair(s)",
              BADGES, chosen.pair.first, chosen.hoennPal, chosen.pair.second,
              chosen.kantoPal, #candidates)
end

-- ---------------------------------------------------------------------------
-- THE WORDS THE PARTY MENU SAYS WHEN A TM IS OPEN
--
-- Reported from play: "when teaching a move its falling back to the gen1
-- party menu instead of emerald".  It was, and the reason was a whitelist:
-- Screens only routes a party-menu push to Emerald's screen when every option
-- on it is one that screen serves, and `tmhm` -- the TM/HM display mode --
-- was not on the list, so every teach opened Kanto's Game Boy party list.
--
-- Emerald's screen needs four words to serve it, and it has them: the four
-- learnability labels sit CONSECUTIVELY in the cartridge -- ABLE, NOT ABLE,
-- ABLE!, NOT ABLE!, LEARNED -- which is a run nothing else in 16 MiB is, and
-- the prompt is its own string a few hundred bytes earlier.
--
-- Found by ENCODING the words and looking for them, rather than by an
-- address: the charmap the manifest already carries turns "ABLE" into bytes,
-- and the run is the one place where the five of them follow each other with
-- nothing in between.
-- ---------------------------------------------------------------------------

local GEN3_TEACH_RUN = { "ABLE", "NOT ABLE", "ABLE!", "NOT ABLE!", "LEARNED" }
local GEN3_TEACH_PROMPT = "Teach which"

function RomExtractorGen3:encodeText(text)
  local reverse = self:charmapReverse()
  local out = {}
  local i = 1
  while i <= #text do
    -- the charmap's glyphs are not all one byte of UTF-8 (POKe's accented e
    -- is two), so the longest glyph that matches here wins
    local matched
    for width = 4, 1, -1 do
      local piece = text:sub(i, i + width - 1)
      if reverse[piece] then matched = { piece, reverse[piece] } break end
    end
    if not matched then return nil end
    out[#out + 1] = string.char(matched[2])
    i = i + #matched[1]
  end
  return table.concat(out)
end

function RomExtractorGen3:partyTeachText(constants)
  local rom = self.rom
  local EOS = "\255"

  local function findRun()
    local first = self:encodeText(GEN3_TEACH_RUN[1])
    if not first then return nil end
    local needle = first .. EOS
    local hits, from = {}, 1
    while true do
      local i = rom.data:find(needle, from, true)
      if not i then break end
      from = i + 1
      local at = i - 1
      local ok = true
      local p = at
      for _, word in ipairs(GEN3_TEACH_RUN) do
        local bytes = self:encodeText(word)
        if not bytes then ok = false break end
        if rom.data:sub(p + 1, p + #bytes + 1) ~= bytes .. EOS then
          ok = false break
        end
        p = p + #bytes + 1
      end
      if ok then hits[#hits + 1] = at end
    end
    return hits
  end

  local runs = findRun()
  if not runs or #runs ~= 1 then
    Logger.warn("gen3 party teach words: %d runs read ABLE / NOT ABLE / "
                  .. "ABLE! / NOT ABLE! / LEARNED in a row, so none is used",
                runs and #runs or 0)
    return
  end
  local at = runs[1]
  local words, p = {}, at
  for _, word in ipairs(GEN3_TEACH_RUN) do
    local ok, text = pcall(self.readText, self, p, 64)
    if not (ok and type(text) == "string") then return end
    words[#words + 1] = text
    p = p + #(self:encodeText(word) or "") + 1
  end

  -- the prompt, which is one string rather than a run and is taken only when
  -- the cartridge says it exactly once
  local prompt
  do
    local needle = self:encodeText(GEN3_TEACH_PROMPT)
    local seen, from = {}, 1
    while needle do
      local i = rom.data:find(needle, from, true)
      if not i then break end
      from = i + 1
      local s = i - 1
      while s > 0 and rom:u8(s - 1) ~= 0xFF do s = s - 1 end
      local ok, text = pcall(self.readText, self, s, 120)
      -- "Teach which move to {VAR1}?" starts the same way and is the SUMMARY
      -- screen's question, not the party menu's; the one being looked for
      -- names no variable
      if ok and type(text) == "string" and not text:find("{", 1, true) then
        seen[text] = true
      end
    end
    local only, count = nil, 0
    for text in pairs(seen) do only, count = text, count + 1 end
    if count == 1 then prompt = only end
  end

  constants.gen3TeachText = {
    able = words[1], notAble = words[2],
    ableNow = words[3], notAbleNow = words[4], learned = words[5],
    prompt = prompt,
    source = ("ROM:party learnability words %07X%s")
             :format(at, prompt and ", prompt found" or ""),
  }
end

function RomExtractorGen3:itemMenuActions(constants)
  local rom = self.rom
  local screens = (self.manifest or {}).screenText or {}
  local anchor = screens.bagActions and tonumber(screens.bagActions.at)
  if not anchor then
    Logger.warn("gen3 item menu: no bagActions anchor in the manifest -- the "
                .. "bag keeps the engine's own options")
    return
  end

  -- ONE RECORD of the run, or nil.
  local function record(o)
    local p = rom:pointer(o)
    if not p or p >= rom.size then return nil end
    local ok, text = pcall(self.readText, self, p, 20)
    if not ok or type(text) ~= "string" or #text > 12 then return nil end
    if text ~= "" and not text:match("^[A-Z][A-Z ]*$") then return nil end
    local fn = rom:u32(o + 4)
    if fn ~= 0 and (fn < 0x08000000 or fn - 0x08000000 >= rom.size) then
      return nil
    end
    return { text = text, fn = fn }
  end

  local want = 0x08000000 + anchor
  local actions, at
  for o = 0, rom.size - 8, 4 do
    if rom:u32(o) == want and record(o) then
      local run = {}
      local p = o
      while #run < 24 do
        local r = record(p)
        if not r then break end
        run[#run + 1] = r
        p = p + 8
      end
      if #run >= 12 and run[#run].text == "" and run[#run].fn == 0 then
        actions, at = run, o
        break
      end
    end
  end
  if not actions then
    Logger.warn("gen3 item menu: no run of menu-action records found from the "
                .. "bag's own labels -- the bag keeps the engine's own options")
    return
  end

  local n = #actions
  local blank
  for i, a in ipairs(actions) do
    if a.text == "" and a.fn == 0 then blank = i end
  end

  -- the function shared three ways is "use it out of the bag"
  local byFn = {}
  for i, a in ipairs(actions) do
    if a.fn ~= 0 then
      byFn[a.fn] = byFn[a.fn] or {}
      table.insert(byFn[a.fn], i)
    end
  end
  local useGroup, registerGroup
  for _, group in pairs(byFn) do
    if #group == 3 and not useGroup then useGroup = group
    elseif #group == 2 and not registerGroup then registerGroup = group end
  end
  if not useGroup then
    Logger.warn("gen3 item menu: no action is shared three ways, so the use "
                .. "action cannot be told from the words -- the bag keeps the "
                .. "engine's own options")
    return
  end
  local isUse = {}
  for _, i in ipairs(useGroup) do isUse[i] = true end

  -- THE FIVE LISTS.  Try every action as the terminator and keep the one that
  -- splits the bytes the way the cartridge is known to.
  local POCKET_ORDER = { "ITEM", "KEY_ITEM", "BALL", "TM_HM", "BERRY" }
  local listsAt = at + n * 8
  local best
  for cancel = 1, n do
    local lists, p, ok = {}, listsAt, true
    while #lists < #POCKET_ORDER and ok do
      local list = {}
      while true do
        local b = rom:u8(p) + 1
        p = p + 1
        if b < 1 or b > n or #list > 8 then ok = false break end
        list[#list + 1] = b
        if b == cancel then break end
      end
      if ok and #list >= 3 then lists[#lists + 1] = list
      else ok = false end
    end
    if ok and #lists == #POCKET_ORDER then
      -- the arrangement: four pockets can use, the ball pocket cannot
      local canUse = {}
      for k, list in ipairs(lists) do
        canUse[k] = false
        for _, id in ipairs(list) do
          if isUse[id] then canUse[k] = true end
        end
      end
      if canUse[1] and canUse[2] and not canUse[3] and canUse[4]
         and canUse[5] then
        if best then
          Logger.warn("gen3 item menu: more than one terminator fits, so the "
                      .. "pocket lists are ambiguous -- the bag keeps the "
                      .. "engine's own options")
          return
        end
        best = { cancel = cancel, lists = lists }
      end
    end
  end
  if not best then
    Logger.warn("gen3 item menu: no terminator splits the pocket lists into "
                .. "the arrangement the cartridge has -- the bag keeps the "
                .. "engine's own options")
    return
  end

  local pockets = {}
  for k, id in ipairs(POCKET_ORDER) do pockets[id] = best.lists[k] end

  -- and the rest name themselves by which pocket carries them
  local function inList(list, id)
    for _, v in ipairs(list) do if v == id then return true end end
    return false
  end
  local special = { [best.cancel] = true }
  if blank then special[blank] = true end
  local give, toss, register, checkTag
  for _, id in ipairs(pockets.TM_HM) do
    if not (isUse[id] or special[id]) then give = id end
  end
  for _, id in ipairs(pockets.ITEM) do
    if not (isUse[id] or special[id] or id == give) then toss = id end
  end
  for _, id in ipairs(pockets.KEY_ITEM) do
    if not (isUse[id] or special[id]) then register = id end
  end
  for _, id in ipairs(pockets.BERRY) do
    if not (isUse[id] or special[id] or id == give or id == toss) then
      checkTag = checkTag or id
    end
  end
  local _ = inList

  local kinds = {}
  for i = 1, n do
    if isUse[i] then kinds[i] = "use"
    elseif i == best.cancel then kinds[i] = "cancel"
    elseif i == blank then kinds[i] = "blank"
    elseif i == give then kinds[i] = "give"
    elseif i == toss then kinds[i] = "toss"
    elseif i == register then kinds[i] = "register"
    elseif i == checkTag then kinds[i] = "checkTag"
    else kinds[i] = "other" end
  end
  -- DESELECT is REGISTER seen from the other side, and shares its function
  if registerGroup and register then
    for _, i in ipairs(registerGroup) do
      if kinds[i] == "other" then kinds[i] = "register" end
    end
  end

  local labels = {}
  for i, a in ipairs(actions) do labels[i] = a.text end

  constants.gen3ItemMenu = {
    labels = labels,
    kinds = kinds,
    pockets = pockets,
    -- the cartridge lays these out two across, which is what the blank is
    -- for; a list with an odd count would leave its last cell empty
    columns = 2,
    cancel = best.cancel,
    blank = blank,
    source = ("ROM:sItemMenuActions %07X, %d actions"):format(at, n),
  }

  -- THE WORDS THE FLOW SAYS.  In the same text block as the labels the
  -- anchor came from, which is why the search is bounded by it rather than
  -- sweeping the cartridge.
  local said, found = {}, 0
  local mart, martFound = {}, 0
  local o = anchor
  local stop = math.min(rom.size, anchor + 0x1800)
  while o < stop do
    if rom:u8(o) == 0xFF then
      o = o + 1
    else
      local ok, text, used = pcall(self.readText, self, o, 200)
      if ok and type(text) == "string" and #text > 0 then
        for _, want2 in ipairs(ITEM_TEXT) do
          if not said[want2.key] and text:find(want2.find, 1, true) then
            said[want2.key] = text
            found = found + 1
          end
        end
        for _, want2 in ipairs(MART_TEXT) do
          if not mart[want2.key] and text:find(want2.find, 1, true) then
            mart[want2.key] = text
            martFound = martFound + 1
          end
        end
        local word = MART_WORDS[text]
        if word and not mart[word] then
          mart[word] = text
          martFound = martFound + 1
        end
        -- TWO SHORT STRINGS, and telling them apart matters: the mart
        -- shows a price and the bag shows a count, and both are one glyph
        -- and one variable.  The clerk's own "I can pay <glyph>{VAR1}." says
        -- which glyph is the money, so the other one is the multiplier.
        if #text <= 12 and text:sub(-6) == "{VAR1}" and text:sub(1, 1) ~= "{" then
          local glyph = text:sub(1, #text - 6)
          local pays = mart.sellPrice or ""
          if glyph ~= "" and pays:find(glyph .. "{VAR1}", 1, true) then
            if not mart.money then
              mart.money, mart.currency = text, glyph
              martFound = martFound + 1
            end
          elseif not mart.quantity then
            mart.quantity = text
            martFound = martFound + 1
          end
        end
        -- the plain "used the" line, and not the two that go on about REPELs
        if text:find("used the", 1, true) and text:find("{", 1, true)
           and (not said.used or #text < #said.used) then
          said.used = text
        end
      end
      -- to just past this run's terminator, whatever readText made of it
      local p2 = o
      while p2 < rom.size and rom:u8(p2) ~= 0xFF do p2 = p2 + 1 end
      o = math.max(o + (tonumber(used) or 0), p2 + 1)
    end
  end
  if said.used then found = found + 1 end
  if found > 0 then
    said.source = ("ROM:item flow text near %07X"):format(anchor)
    constants.gen3ItemText = said
  end
  -- ...and the party menu's own words, which the TM the bag just booted up
  -- is about to need
  self:partyTeachText(constants)
  if mart.buy and mart.sell and martFound >= 10 then
    mart.source = ("ROM:mart text near %07X"):format(anchor)
    constants.gen3MartText = mart
  elseif martFound > 0 then
    Logger.warn("gen3 mart text: only %d of the clerk's lines were found -- "
                .. "the shop keeps the engine's own words", martFound)
  end

  local shown = {}
  for _, id in ipairs(POCKET_ORDER) do
    local words = {}
    for _, a in ipairs(pockets[id]) do
      words[#words + 1] = (labels[a] ~= "" and labels[a]) or "-"
    end
    shown[#shown + 1] = ("%s[%s]"):format(id, table.concat(words, " "))
  end
  Logger.info("Gen3 item menu: %d actions at %07X -- %s; %d flow lines, "
                .. "%d mart lines", n, at, table.concat(shown, " "), found,
              martFound)
end

-- ---------------------------------------------------------------------------
-- STAGE: the summary screen's own words
--
-- Every label on the four summary pages, and the four page names, off the
-- cartridge instead of typed into the UI file.  It matters more than it
-- sounds: the port was writing its own English, and "its own English" is how
-- a screen ends up ALMOST right -- "SP.ATK" where the cartridge says
-- "SP. ATK", "EXP" where it says "EXP. POINTS", "CONTEST MOVES" where the
-- cartridge, famously, says "C0NTEST MOVES" with a ZERO.
--
-- FOUND FROM ONE ANCHOR.  The six stat labels are six consecutive terminated
-- strings -- ATTACK, DEFENSE, SP. ATK, SP. DEF, SPEED, HP -- and that run
-- occurs once.  Everything else is read forward from it in the order the
-- block stores them, which is checkable rather than assumed: the four page
-- names have to be four strings that all contain MOVES, INFO or SKILLS, and
-- the fourth has to be the one with the zero in it.  A block found somewhere
-- else fails that.
-- ---------------------------------------------------------------------------

local GEN3_SUMMARY_STATS = { "ATTACK", "DEFENSE", "SP. ATK", "SP. DEF",
                             "SPEED", "HP" }
-- what the strings after the stat run are, in the order the block holds them
local GEN3_SUMMARY_AFTER = {
  "ot", "rental", "type", "power", "accuracy", "appeal", "jam", "status",
  "expPoints", "nextLevel", "ribbons", "events", "switch",
  "pageInfo", "pageSkills", "pageBattleMoves", "pageContestMoves", "info",
}

function RomExtractorGen3:extractSummaryText()
  self:beginStage("Gen3 summary screen")
  local map = self:charmap()
  local byteOf = self:charmapReverse()
  local function encode(word)
    local out = {}
    for ch in word:gmatch(".") do
      local b = byteOf[ch]
      if not b then return nil end
      out[#out + 1] = string.char(b)
    end
    return table.concat(out)
  end

  local eos = string.char(0xFF)
  local parts = {}
  for i, label in ipairs(GEN3_SUMMARY_STATS) do
    parts[i] = encode(label)
    if not parts[i] then
      Logger.warn("gen3 summary: this charmap cannot spell %q", label)
      return
    end
  end
  local needle = table.concat(parts, eos) .. eos

  local hits = {}
  local from = 1
  while true do
    local i = self.rom.data:find(needle, from, true)
    if not i then break end
    hits[#hits + 1] = i - 1
    from = i + 1
  end
  if #hits ~= 1 then
    Logger.warn("gen3 summary: %d places hold the six stat labels in a row, "
                  .. "so none is used -- the screen keeps its own wording",
                #hits)
    return
  end

  -- read forward, one terminated string at a time
  local out = { stats = {} }
  for i, label in ipairs(GEN3_SUMMARY_STATS) do out.stats[i] = label end
  local at = hits[1] + #needle
  -- EMPTY STRINGS SIT BETWEEN SOME OF THEM.  Two terminators in a row is the
  -- assembler's padding, not an entry -- and counting one as an entry shifts
  -- everything after it by one, which is how the four page names came back as
  -- two page names and two labels.
  for _, key in ipairs(GEN3_SUMMARY_AFTER) do
    local text
    repeat
      local start = at
      while at < self.rom.size and self.rom:u8(at) ~= 0xFF do at = at + 1 end
      text = (at > start) and self:readString(start, at - start) or nil
      at = at + 1
    until text or at >= self.rom.size
    if not text then
      Logger.warn("gen3 summary: the block ran out at %s", key)
      return
    end
    out[key] = text
  end

  -- THE CHECKS THAT MAKE THE POSITIONS AN IDENTIFICATION.
  local titles = { out.pageInfo, out.pageSkills, out.pageBattleMoves,
                   out.pageContestMoves }
  local named = 0
  for _, t in ipairs(titles) do
    if type(t) == "string" and (t:find("MOVES", 1, true)
                                or t:find("INFO", 1, true)
                                or t:find("SKILLS", 1, true)) then
      named = named + 1
    end
  end
  if named ~= 4 then
    Logger.warn("gen3 summary: %d of the four page names read as page names, "
                  .. "so the block is not where it was expected", named)
    return
  end

  local constants = self._constants or {}
  constants.gen3Summary = {
    stats = out.stats,
    ot = out.ot, type = out.type, power = out.power, accuracy = out.accuracy,
    appeal = out.appeal, jam = out.jam, status = out.status,
    expPoints = out.expPoints, nextLevel = out.nextLevel,
    ribbons = out.ribbons, events = out.events, switch = out.switch,
    info = out.info,
    pages = { out.pageInfo, out.pageSkills, out.pageBattleMoves,
              out.pageContestMoves },
    source = ("ROM:the summary screen's text block at %07X"):format(hits[1]),
  }
  self._constants = constants
  self:write("constants", constants)
  Logger.info("Gen3 summary screen: %s | %s | %s | %s -- %s, %s, %s",
              out.pageInfo, out.pageSkills, out.pageBattleMoves,
              out.pageContestMoves, out.expPoints, out.nextLevel, out.accuracy)
end

-- ---------------------------------------------------------------------------
-- STAGE: the battle screen's own windows
--
-- Where the message goes, where "What will {MON} do?" goes, where the command
-- menu goes and where each of the four move names goes.  Every one of those
-- was a reconstructed number in the battle screen -- a strip at tile 15, a
-- split at tile 17, move columns eight pixels off -- and the cartridge ships
-- the lot as one array of window templates.
--
-- A WindowTemplate is eight bytes: bg, tilemapLeft, tilemapTop, width,
-- height, paletteNum, and a u16 baseBlock.  Runs of them are everywhere in a
-- GBA game, so the array is identified by its CONTENTS rather than its shape:
--
--   * it opens with the battle message window, 26 columns by 4 rows -- the
--     same record the manifest already carries and the field text box is
--     already drawn from
--   * the next two are the prompt and the command menu, four rows each, side
--     by side and on the same row as each other
--   * then FOUR equal windows, 8 by 2, in two columns and two rows -- the
--     move menu, and nothing else in the game is shaped like that
--
-- THE ROWS WRAP.  A battle's background is taller than the screen and these
-- windows are laid out down it in twenty-row pages: the message is at row 15,
-- the prompt and the menu at 35 and the move names at 55 and 57.  Every one
-- of those is row 15 or 17 of the screen -- 35 % 20, 55 % 20 -- which is the
-- arithmetic that puts them all in the same strip along the bottom, and is
-- checked here rather than assumed: every window in the array has to land in
-- the bottom five rows once it is folded.
--
-- What it changes on screen: the message box is INSET (its frame runs tile 1
-- to 29) while the prompt and the menu together span the full width, which is
-- what the cartridge does and what a single reconstructed strip could not
-- express.
-- ---------------------------------------------------------------------------

local GEN3_BW_PAGE = 20              -- screen rows; the bg is pages of these
local GEN3_BW_MOVE_W = 8
local GEN3_BW_MOVE_H = 2

function RomExtractorGen3:extractBattleWindows()
  self:beginStage("Gen3 battle windows")
  local rom = self.rom
  local function rec(o)
    if o + 8 > rom.size then return nil end
    return { bg = rom:u8(o), left = rom:u8(o + 1), top = rom:u8(o + 2),
             w = rom:u8(o + 3), h = rom:u8(o + 4), pal = rom:u8(o + 5),
             base = rom:u16(o + 6), at = o }
  end

  -- the message window as the manifest already knows it; the array opens with
  -- it, which is the anchor
  local mw = self.manifest.messageWindow
  if type(mw) ~= "table" or not (mw.width and mw.height) then
    Logger.warn("gen3 battle windows: no message window in the manifest to "
                  .. "anchor on -- the screen keeps its own numbers")
    return
  end

  local function isArray(o)
    local r = {}
    for i = 0, 6 do
      r[i] = rec(o + i * 8)
      if not r[i] then return nil end
    end
    -- 1. the message window itself
    if not (r[0].left == mw.left and r[0].top == mw.top
            and r[0].w == mw.width and r[0].h == mw.height) then
      return nil
    end
    -- 2. a prompt and a menu, the same height, side by side, in that order
    if r[1].h ~= r[0].h or r[2].h ~= r[0].h then return nil end
    if r[1].top ~= r[2].top then return nil end
    if r[2].left <= r[1].left then return nil end
    if r[1].left + r[1].w > r[2].left then return nil end
    -- 3. four equal move windows in two columns and two rows
    for i = 3, 6 do
      if r[i].w ~= GEN3_BW_MOVE_W or r[i].h ~= GEN3_BW_MOVE_H then return nil end
    end
    if r[3].left ~= r[5].left or r[4].left ~= r[6].left then return nil end
    if r[3].top ~= r[4].top or r[5].top ~= r[6].top then return nil end
    if r[5].top <= r[3].top or r[4].left <= r[3].left then return nil end
    -- 4. ...AND EVERY ONE OF THEM FOLDS INTO THE BOTTOM STRIP.  The rows wrap
    --    in twenty-row pages, and a run that satisfies everything above but
    --    lands its menu halfway up the screen is not this array.
    for i = 0, 6 do
      local row = r[i].top % GEN3_BW_PAGE
      if row < 12 or row + r[i].h > GEN3_BW_PAGE then return nil end
    end
    return r
  end

  local found
  for o = 0, rom.size - 56, 4 do
    local r = isArray(o)
    if r then found = r break end
  end
  if not found then
    Logger.warn("gen3 battle windows: no template array opens with the "
                  .. "message window and closes with a 2x2 of move names")
    return
  end

  local function win(r)
    return { left = r.left, top = r.top % GEN3_BW_PAGE, width = r.w,
             height = r.h }
  end

  local constants = self._constants or {}
  constants.gen3BattleWindows = {
    message = win(found[0]),
    prompt = win(found[1]),
    action = win(found[2]),
    moves = { win(found[3]), win(found[4]), win(found[5]), win(found[6]) },
    page = GEN3_BW_PAGE,
    source = ("ROM:sStandardBattleWindowTemplates %07X"):format(found[0].at),
  }
  self._constants = constants
  self:write("constants", constants)
  Logger.info("Gen3 battle windows: message %dx%d at (%d,%d), prompt %d wide, "
                .. "menu %d wide at column %d, moves at columns %d and %d "
                .. "(array %07X)",
              found[0].w, found[0].h, found[0].left, found[0].top % GEN3_BW_PAGE,
              found[1].w, found[2].w, found[2].left, found[3].left,
              found[4].left, found[0].at)
end

-- ---------------------------------------------------------------------------
-- STAGE: the TRAINER MEMO
--
-- The bottom half of the summary screen's first page, and the port printed
-- nothing there.  On the cartridge it is three lines and it is the only place
-- in the game that tells you where a Pokemon came from:
--
--     BOLD nature,
--     met at Lv5,
--     ROUTE 101.
--
-- It is not one string.  It is EIGHT templates, and which one is used says
-- something the player is meant to be able to read: a mon you caught says
-- "met at", one you hatched says "hatched at", one that came from someone
-- else says "probably met at" -- because your game genuinely does not know --
-- and one from a trade with no location at all says "obtained in a trade".
-- Printing "met at" for all of them would be a lie the cartridge is careful
-- not to tell.
--
-- FOUND BY A SIGNATURE, not an address.  Every one of the eight opens with
-- the same eight bytes -- four DYNAMIC placeholders, $F7 with ids 0, 2, 1 and
-- 5 -- and then the literal word " nature".  Sixteen megabytes hold that
-- fifteen-byte run exactly eight times, and they are consecutive, which is
-- both the find and the proof there are no more.
--
-- WHICH ONE IS WHICH IS READ FROM THE ENGLISH, not from the order they sit
-- in.  A template naming "somewhere" is the one for a mon from another
-- cartridge; "fateful" is the event one; "probably" is the traded one that
-- still has a place.  Every one of the eight keys has to be claimed exactly
-- once or the block is not what it looks like -- an ordering read off
-- addresses would pass silently the day a revision moves one.
--
-- The five EGG memos follow immediately, and they are their own strings with
-- no placeholders at all; they are taken as the next five and each has to
-- name an EGG.
--
-- The colour placeholders (0, 1, 5) are DROPPED.  On hardware they swap the
-- text palette so the nature and the place come out in a different colour
-- from the words around them; this port's font draws one colour, and a
-- placeholder left in would print as a literal token in the middle of a
-- sentence.
-- ---------------------------------------------------------------------------

local GEN3_MEMO_DYNAMIC = 0xF7
local GEN3_MEMO_EXTRA = 0xF9
local GEN3_MEMO_LV = 0x05
-- the three placeholders that carry CONTENT.  0, 1 and 5 are text colours.
local GEN3_MEMO_SLOTS = { [2] = "{NATURE}", [3] = "{LEVEL}", [4] = "{LOCATION}" }
-- claimed in this order: the first rule that matches a template wins, so the
-- narrower words are tested before the ones they contain
local GEN3_MEMO_RULES = {
  { key = "hatchedSomewhere", all = { "hatched", "somewhere" } },
  { key = "metSomewhere", all = { "somewhere" } },
  { key = "fateful", all = { "fateful" } },
  { key = "probablyMet", all = { "probably" } },
  { key = "trade", all = { "trade" } },
  { key = "hatched", all = { "hatched" } },
  { key = "met", all = { "met" } },
  { key = "bare", all = {} },
}

function RomExtractorGen3:extractTrainerMemo()
  self:beginStage("Gen3 trainer memo")
  local rom = self.rom
  local map = self:charmap()
  local byteOf = self:charmapReverse()
  local function encode(word)
    local out = {}
    for ch in word:gmatch(".") do
      local b = byteOf[ch]
      if not b then return nil end
      out[#out + 1] = string.char(b)
    end
    return table.concat(out)
  end

  local tail = encode(" nature")
  if not tail then
    Logger.warn("gen3 memo: this charmap cannot spell the word the templates "
                  .. "are found by")
    return
  end
  local needle = string.char(GEN3_MEMO_DYNAMIC, 0x00, GEN3_MEMO_DYNAMIC, 0x02,
                             GEN3_MEMO_DYNAMIC, 0x01, GEN3_MEMO_DYNAMIC, 0x05)
                 .. tail

  local hits, from = {}, 1
  while true do
    local i = rom.data:find(needle, from, true)
    if not i then break end
    hits[#hits + 1] = i - 1
    from = i + 1
  end
  if #hits ~= 8 then
    Logger.warn("gen3 memo: %d templates open with the nature run, not eight "
                  .. "-- the memo keeps its own wording", #hits)
    return
  end

  -- DECODE ONE, keeping the content placeholders and dropping the colours.
  -- Returns the text and the offset just past the terminator, so the egg
  -- memos can be read straight on from the last template.
  local function decode(off)
    local out, at = {}, off
    while at < rom.size do
      local b = rom:u8(at)
      if b == 0xFF then return table.concat(out), at + 1 end
      if b == 0xFE then
        out[#out + 1] = "\n"; at = at + 1
      elseif b == GEN3_MEMO_DYNAMIC then
        out[#out + 1] = GEN3_MEMO_SLOTS[rom:u8(at + 1)] or ""
        at = at + 2
      elseif b == GEN3_MEMO_EXTRA then
        -- the only extra symbol these templates use is the Lv ligature, and
        -- this port's font spells it out
        out[#out + 1] = (rom:u8(at + 1) == GEN3_MEMO_LV) and "Lv" or ""
        at = at + 2
      elseif b == 0xFC then
        local operands = EXTENDED_OPERANDS[rom:u8(at + 1)]
        if not operands then return nil end
        at = at + 2 + operands
      else
        local glyph = map[b]
        if glyph == nil then return nil end
        out[#out + 1] = glyph
        at = at + 1
      end
    end
    return nil
  end

  local templates, after = {}, nil
  local claimed = {}
  for _, off in ipairs(hits) do
    local text, past = decode(off)
    if not text then
      Logger.warn("gen3 memo: the template at %07X does not decode", off)
      return
    end
    after = past
    local lower = text:lower()
    local key
    for _, rule in ipairs(GEN3_MEMO_RULES) do
      local ok = true
      for _, word in ipairs(rule.all) do
        if not lower:find(word, 1, true) then ok = false break end
      end
      if ok and not claimed[rule.key] then key = rule.key break end
    end
    if not key then
      Logger.warn("gen3 memo: %q matches no template this screen knows", text)
      return
    end
    claimed[key] = true
    templates[key] = text
  end

  -- EVERY KEY CLAIMED EXACTLY ONCE.  Eight templates and eight keys is not
  -- the same statement as eight DISTINCT keys, and the second is the one that
  -- says the block was read rather than guessed at.
  local missing = {}
  for _, rule in ipairs(GEN3_MEMO_RULES) do
    if not templates[rule.key] then missing[#missing + 1] = rule.key end
  end
  if #missing > 0 then
    Logger.warn("gen3 memo: no template claimed %s", table.concat(missing, ", "))
    return
  end

  -- ...AND THE SLOTS FALL WHERE THEY MUST.  All eight name the nature; only
  -- the ones that talk about a place name a place; the bare one and the
  -- plain trade one name neither a level nor a place.
  for key, text in pairs(templates) do
    if not text:find("{NATURE}", 1, true) then
      Logger.warn("gen3 memo: the %s template names no nature", key)
      return
    end
  end
  if templates.bare:find("{LEVEL}", 1, true)
     or templates.trade:find("{LEVEL}", 1, true) then
    Logger.warn("gen3 memo: a template with no encounter still names a level")
    return
  end
  if not (templates.met:find("{LOCATION}", 1, true)
          and templates.met:find("{LEVEL}", 1, true)) then
    Logger.warn("gen3 memo: the ordinary 'met at' template names no place")
    return
  end

  -- THE EGG MEMOS, the next five strings, each of which has to name an EGG
  local eggs = {}
  local at = after
  for _ = 1, 5 do
    local text, past = decode(at)
    if not text then break end
    at = past
    if text:find("EGG", 1, true) then eggs[#eggs + 1] = text end
  end
  if #eggs ~= 5 then
    Logger.warn("gen3 memo: %d of the five egg memos follow the templates, so "
                  .. "none is used", #eggs)
    eggs = nil
  end

  local constants = self._constants or {}
  constants.gen3Memo = {
    templates = templates,
    eggs = eggs,
    slots = { nature = "{NATURE}", level = "{LEVEL}", location = "{LOCATION}" },
    source = ("ROM:the eight nature templates at %07X..%07X")
             :format(hits[1], hits[#hits]),
  }
  self._constants = constants
  self:write("constants", constants)
  Logger.info("Gen3 trainer memo: 8 templates%s -- %q",
              eggs and " and 5 egg memos" or "",
              (templates.met:gsub("\n", " / ")))
end


-- ---------------------------------------------------------------------------
-- STAGE: what each ABILITY does
--
-- The second box down the summary screen's info page is ABILITY, and it is
-- TWO lines: the ability's name, and a sentence saying what it does.  The port
-- had the name -- gAbilityNames is in the manifest -- and nothing at all for
-- the sentence, so half of that box was blank on every Pokemon in the game.
-- It is also the only explanation of an ability anywhere: nothing else in
-- Emerald tells you what OVERGROW means.
--
-- FOUND THE SAME WAY THE MOVE DESCRIPTIONS ARE -- a run of consecutive
-- pointers that all land on text -- with one difference that matters.  There
-- are 354 moves and only 78 abilities, and 78 is short enough that several
-- longer runs elsewhere in the cartridge contain one: the sweep finds seven
-- runs at least that long.  So the length is required to be EXACT, and on
-- this cartridge exactly one run is 78 pointers and no more.
--
-- AND THEN IT IS PROVED, by something a wrong table cannot pass by accident:
-- the three starter abilities say which type they power up, and they have to
-- say the right one.  OVERGROW is GRASS, BLAZE is FIRE, TORRENT is WATER.  A
-- run of the right length in the wrong place fails all three; a run read one
-- entry out of step fails at least two.
-- ---------------------------------------------------------------------------

-- ability -> the word its own description must contain.  Three, so a
-- coincidence has to happen three times.
local GEN3_ABILITY_PROOF = {
  { id = "OVERGROW", word = "GRASS" },
  { id = "BLAZE", word = "FIRE" },
  { id = "TORRENT", word = "WATER" },
}

function RomExtractorGen3:extractAbilityDescriptions()
  self:beginStage("Gen3 ability descriptions")
  local constants = self._constants or {}
  local order = constants.abilityOrder
  local abilities = constants.abilities
  if not (order and abilities) then
    Logger.warn("gen3 ability descriptions: the ability names have to be read "
                  .. "first")
    return
  end
  local count = #order
  if count < 40 then
    Logger.warn("gen3 ability descriptions: only %d abilities are named", count)
    return
  end

  local rom = self.rom
  local map = self:charmap()

  -- the same "is this a sentence" test the move descriptions use: terminated,
  -- a sentence long, and mostly letters rather than mostly control bytes
  local function looksLikeText(p)
    if not p or p + 8 >= rom.size then return false end
    local n, letters = 0, 0
    while n < 220 do
      local b = rom:u8(p + n)
      if b == 0xFF then break end
      local glyph = map[b]
      if glyph and glyph:match("%a") then letters = letters + 1 end
      n = n + 1
    end
    if n < 8 or n >= 220 then return false end
    return letters * 2 >= n
  end

  local runs = {}
  local at = 0
  while at < rom.size - 4 do
    if looksLikeText(rom:pointer(at)) then
      local n, o = 0, at
      while o < rom.size - 4 and looksLikeText(rom:pointer(o)) do
        n = n + 1
        o = o + 4
      end
      -- EXACTLY as long as the cartridge has abilities.  "At least" finds
      -- seven runs here; "exactly" finds one.
      if n == count then runs[#runs + 1] = { at = at, n = n } end
      at = o
    else
      at = at + 4
    end
  end

  if #runs ~= 1 then
    Logger.warn("gen3 ability descriptions: %d runs are exactly %d pointers "
                  .. "long, so none is used", #runs, count)
    return
  end
  local run = runs[1]

  local function textAt(index)
    local ptr = rom:pointer(run.at + (index - 1) * 4)
    if not ptr then return nil end
    local ok, text = pcall(self.readText, self, ptr, 256)
    if ok and type(text) == "string" and #text > 0 then return text end
    local okRaw, raw = pcall(self.readString, self, ptr, 220)
    return okRaw and raw or nil
  end

  -- THE PROOF, before anything is written
  local indexOf = {}
  for i, id in ipairs(order) do indexOf[id] = i end
  for _, proof in ipairs(GEN3_ABILITY_PROOF) do
    local i = indexOf[proof.id]
    local text = i and textAt(i)
    if not (type(text) == "string" and text:find(proof.word, 1, true)) then
      Logger.warn("gen3 ability descriptions: %s's sentence does not mention "
                    .. "%s (%q), so the run at %07X is not the table",
                  proof.id, proof.word, tostring(text), run.at)
      return
    end
  end

  local written = 0
  for i = 1, count do
    local id = order[i]
    local record = id and abilities[id]
    local text = record and textAt(i)
    if record and type(text) == "string" and #text > 0 then
      record.description = text
      written = written + 1
    end
  end

  constants.abilityDescriptionSource =
    ("ROM:gAbilityDescriptionPointers %07X, %d entries"):format(run.at, count)
  self._constants = constants
  self:write("constants", constants)
  Logger.info("Gen3 ability descriptions: %d of %d abilities say what they do "
                .. "(table at %07X) -- %s: %q",
              written, count, run.at, GEN3_ABILITY_PROOF[1].id,
              tostring(abilities[GEN3_ABILITY_PROOF[1].id]
                       and abilities[GEN3_ABILITY_PROOF[1].id].description))
end

-- ---------------------------------------------------------------------------
-- STAGE: how each species MOVES when it is sent out
--
-- Emerald's front pic does two separate things when a mon appears.  One is
-- the two-frame swap the port already had (PicAnim).  The other -- the one
-- the eye actually reads as "the Pokemon is alive" -- is a PROCEDURAL
-- animation: the sprite itself is squashed, hopped, rotated, slid, flashed.
-- Every species picks exactly one of those routines, and the pick is a
-- single byte in sMonFrontAnimIdsTable.
--
-- FOUND BY SHAPE, and the shape here is a hole rather than a run.  The
-- cartridge's species list has twenty-five dead slots in the middle of it
-- (252..276, the placeholders left where Ruby's unreleased mons were), and
-- the C table is written with designated initialisers -- so those twenty-five
-- entries were never assigned and are still zero.  A 411-byte table with a
-- 25-byte hole at exactly offset 251, small values, and NOT mostly zero
-- anywhere else is a very specific object; sixteen megabytes hold one.
--
-- AND THEN IT IS PROVED.  Immediately after it sits its sibling,
-- sMonAnimationDelayTable -- 411 more bytes, nearly all zero, holding the
-- handful of species whose animation waits before it starts.  Four of those
-- delays are known quantities, and they have to land on the right species:
-- BLASTOISE waits 0x32, WEEDLE 0x0A, KAKUNA 0x14, BEEDRILL 0x23.  A table
-- read one byte out of step fails all four.  Then one more, from the other
-- table and of a different kind entirely: PIKACHU's animation is
-- ANIM_FLASH_YELLOW, id 44.  It could not be anything else, and a wrong
-- table cannot make it 44 by accident.
-- ---------------------------------------------------------------------------

-- sMonAnimFunctions, in order.  The ids are an index into that table, so the
-- names ARE the order -- the runtime switches on the name, never the number.
local GEN3_MON_ANIM_NAMES = {
  [0] = "V_SQUISH_AND_BOUNCE",
  "CIRCULAR_STRETCH_TWICE", "H_VIBRATE", "H_SLIDE", "V_SLIDE",
  "BOUNCE_ROTATE_TO_SIDES", "V_JUMPS_H_JUMPS", "ROTATE_TO_SIDES",
  "ROTATE_TO_SIDES_TWICE", "GROW_VIBRATE", "ZIGZAG_FAST",
  "SWING_CONCAVE", "SWING_CONCAVE_FAST", "SWING_CONVEX",
  "SWING_CONVEX_FAST", "H_SHAKE", "V_SHAKE", "CIRCULAR_VIBRATE",
  "TWIST", "SHRINK_GROW", "CIRCLE_C_CLOCKWISE", "GLOW_BLACK",
  "H_STRETCH", "V_STRETCH", "RISING_WOBBLE", "V_SHAKE_TWICE",
  "TIP_MOVE_FORWARD", "H_PIVOT", "V_SLIDE_WOBBLE", "H_SLIDE_WOBBLE",
  "V_JUMPS_BIG", "SPIN_LONG", "GLOW_ORANGE", "GLOW_RED", "GLOW_BLUE",
  "GLOW_YELLOW", "GLOW_PURPLE", "BACK_AND_LUNGE", "BACK_FLIP",
  "FLICKER", "BACK_FLIP_BIG", "FRONT_FLIP", "TUMBLING_FRONT_FLIP",
  "FIGURE_8", "FLASH_YELLOW", "SWING_CONCAVE_FAST_SHORT",
  "SWING_CONVEX_FAST_SHORT", "ROTATE_UP_SLAM_DOWN",
  "DEEP_V_SQUISH_AND_BOUNCE", "H_JUMPS", "H_JUMPS_V_STRETCH",
  "ROTATE_TO_SIDES_FAST", "ROTATE_UP_TO_SIDES", "FLICKER_INCREASING",
  "TIP_HOP_FORWARD", "PIVOT_SHAKE", "TIP_AND_SHAKE",
  "VIBRATE_TO_CORNERS", "GROW_IN_STAGES", "V_SPRING",
  "V_REPEATED_SPRING", "SPRING_RISING", "H_SPRING",
  "H_REPEATED_SPRING_SLOW", "H_SLIDE_SHRINK", "LUNGE_GROW",
  "CIRCLE_INTO_BG", "RAPID_H_HOPS", "FOUR_PETAL",
  "V_SQUISH_AND_BOUNCE_SLOW", "H_SLIDE_SLOW", "V_SLIDE_SLOW",
  "BOUNCE_ROTATE_TO_SIDES_SMALL", "BOUNCE_ROTATE_TO_SIDES_SLOW",
  "BOUNCE_ROTATE_TO_SIDES_SMALL_SLOW", "ZIGZAG_SLOW", "H_SHAKE_SLOW",
  "V_SHAKE_SLOW", "TWIST_TWICE", "CIRCLE_C_CLOCKWISE_SLOW",
  "V_SHAKE_TWICE_SLOW", "V_SLIDE_WOBBLE_SMALL", "V_JUMPS_SMALL",
  "SPIN", "TUMBLING_FRONT_FLIP_TWICE",
  "DEEP_V_SQUISH_AND_BOUNCE_TWICE", "H_SLIDE_WOBBLE_TWICE",
}

-- the dead slots, 1-based species numbers
local GEN3_ANIM_HOLE_FIRST, GEN3_ANIM_HOLE_LAST = 252, 276

-- species -> the delay its animation waits, in 60Hz frames
local GEN3_ANIM_DELAY_PROOF = {
  { id = "BLASTOISE", delay = 0x32 },
  { id = "WEEDLE", delay = 0x0A },
  { id = "KAKUNA", delay = 0x14 },
  { id = "BEEDRILL", delay = 0x23 },
}
-- and one from the other table, of a different kind
local GEN3_ANIM_ID_PROOF = { id = "PIKACHU", anim = "FLASH_YELLOW" }

function RomExtractorGen3:extractMonAnims()
  self:beginStage("Gen3 mon animations")
  local constants = self._constants or {}
  local order = constants.speciesOrder
  if type(order) ~= "table" or #order < 300 then
    Logger.warn("gen3 mon animations: the species have to be read first")
    return
  end
  local count = #order
  local hole = GEN3_ANIM_HOLE_FIRST - 1        -- 0-based offset of the hole
  local holeLen = GEN3_ANIM_HOLE_LAST - GEN3_ANIM_HOLE_FIRST + 1
  if hole + holeLen > count then
    Logger.warn("gen3 mon animations: %d species is too few for the hole at "
                  .. "%d", count, GEN3_ANIM_HOLE_FIRST)
    return
  end

  local rom = self.rom
  local maxAnim = #GEN3_MON_ANIM_NAMES          -- names are 0..#names

  local function tableAt(at)
    local bytes = {}
    for i = 0, count - 1 do bytes[i] = rom:u8(at + i) end
    return bytes
  end

  -- shape: a hole of exactly `holeLen` zeros at `hole`, values inside the
  -- animation table's range, plenty of variety, and NOT zeros everywhere
  local function looksLikeIds(at)
    if at < 0 or at + count * 2 >= rom.size then return false end
    for i = hole, hole + holeLen - 1 do
      if rom:u8(at + i) ~= 0 then return false end
    end
    -- the byte on each side of the hole has to be a real animation, or this
    -- is just a stretch of padding
    if hole > 0 and rom:u8(at + hole - 1) == 0 then return false end
    local seen, zeros = {}, 0
    for i = 0, count - 1 do
      local b = rom:u8(at + i)
      if b > maxAnim then return false end
      if b == 0 then zeros = zeros + 1 end
      seen[b] = true
    end
    local distinct = 0
    for _ in pairs(seen) do distinct = distinct + 1 end
    if distinct < 40 then return false end
    if zeros - holeLen > 80 then return false end
    return true
  end

  local found
  local at = 0
  while at < rom.size - count * 2 do
    if looksLikeIds(at) then
      if found then
        Logger.warn("gen3 mon animations: %07X and %07X both look like the "
                      .. "table, so neither is used", found, at)
        return
      end
      found = at
      at = at + count
    else
      at = at + 1
    end
  end
  if not found then
    Logger.warn("gen3 mon animations: nothing in the cartridge has a "
                  .. "%d-byte hole at species %d",
                holeLen, GEN3_ANIM_HOLE_FIRST)
    return
  end

  local ids = tableAt(found)
  local delays = tableAt(found + count)

  -- THE PROOF, before anything is written
  local indexOf = {}
  for i, id in ipairs(order) do indexOf[id] = i end
  for _, proof in ipairs(GEN3_ANIM_DELAY_PROOF) do
    local i = indexOf[proof.id]
    local got = i and delays[i - 1]
    if got ~= proof.delay then
      Logger.warn("gen3 mon animations: %s waits %s, not %d -- the table at "
                    .. "%07X is not sMonFrontAnimIdsTable",
                  proof.id, tostring(got), proof.delay, found)
      return
    end
  end
  do
    local i = indexOf[GEN3_ANIM_ID_PROOF.id]
    local got = i and GEN3_MON_ANIM_NAMES[ids[i - 1] or -1]
    if got ~= GEN3_ANIM_ID_PROOF.anim then
      Logger.warn("gen3 mon animations: %s animates as %s, not %s -- the "
                    .. "table at %07X is not sMonFrontAnimIdsTable",
                  GEN3_ANIM_ID_PROOF.id, tostring(got),
                  GEN3_ANIM_ID_PROOF.anim, found)
      return
    end
  end

  local anims, written, delayed = {}, 0, 0
  for i, id in ipairs(order) do
    local raw = ids[i - 1]
    local name = raw and GEN3_MON_ANIM_NAMES[raw]
    if name and not (i >= GEN3_ANIM_HOLE_FIRST and i <= GEN3_ANIM_HOLE_LAST) then
      local delay = delays[i - 1] or 0
      anims[id] = { anim = name, id = raw, delay = delay }
      written = written + 1
      if delay > 0 then delayed = delayed + 1 end
    end
  end

  constants.gen3MonAnim = {
    anims = anims,
    names = GEN3_MON_ANIM_NAMES,
    source = ("ROM:sMonFrontAnimIdsTable %07X, sMonAnimationDelayTable %07X, "
              .. "%d species"):format(found, found + count, written),
  }
  self._constants = constants
  self:write("constants", constants)
  Logger.info("Gen3 mon animations: %d species animate (%d after a delay); "
                .. "table at %07X -- %s is %s",
              written, delayed, found, GEN3_ANIM_ID_PROOF.id,
              anims[GEN3_ANIM_ID_PROOF.id]
                and anims[GEN3_ANIM_ID_PROOF.id].anim or "?")
end

-- ---------------------------------------------------------------------------
-- STAGE: which Pokemon do not touch the ground
--
-- Emerald's battlers stand on a platform, and some of them do not: a ZUBAT
-- hangs above its own shadow, a MAGNEMITE floats, a GEODUDE hovers.  That is
-- not a property of the picture -- the picture is the same 64x64 frame for
-- everyone -- it is one byte per species saying how far off the platform the
-- sprite sits.
--
-- FOUND BY SHAPE and PROVED BY MEANING.  The shape is weak on its own: a
-- table one byte per species, small values, mostly zero.  What makes it
-- certain is which species are the nonzero ones, and that is a testable
-- statement about the cartridge rather than about the reader.  BUTTERFREE,
-- BEEDRILL, ZUBAT, GOLBAT, VENOMOTH, GEODUDE, MAGNEMITE, MAGNETON, GASTLY,
-- HAUNTER, KOFFING, WEEZING and AERODACTYL all hover, and BULBASAUR,
-- PIKACHU, ONIX and SNORLAX all stand on the ground.  Sixteen megabytes hold
-- one table that says all of that at once.
--
-- (CHARIZARD is a zero, and that is the cartridge's own choice rather than a
-- miss: its picture is drawn already standing.)
-- ---------------------------------------------------------------------------

local GEN3_HOVERS = {
  "BUTTERFREE", "BEEDRILL", "ZUBAT", "GOLBAT", "VENOMOTH", "GEODUDE",
  "MAGNEMITE", "MAGNETON", "GASTLY", "HAUNTER", "KOFFING", "WEEZING",
  "AERODACTYL",
}
local GEN3_STANDS = { "BULBASAUR", "PIKACHU", "ONIX", "SNORLAX", "MACHOP" }
local GEN3_ELEVATION_MAX = 24

function RomExtractorGen3:extractElevation()
  self:beginStage("Gen3 battle elevation")
  local constants = self._constants or {}
  local order = constants.speciesOrder
  if type(order) ~= "table" or #order < 300 then
    Logger.warn("gen3 elevation: the species have to be read first")
    return
  end
  local rom = self.rom
  -- the table is indexed by SPECIES, so slot 0 belongs to nothing
  local count = #order + 1

  local indexOf = {}
  for i, id in ipairs(order) do indexOf[id] = i end
  for _, id in ipairs(GEN3_HOVERS) do
    if not indexOf[id] then
      Logger.warn("gen3 elevation: this dataset has no %s to check against", id)
      return
    end
  end

  -- THE PROOF IS ALSO THE SEARCH.  Sweeping sixteen megabytes and measuring
  -- four hundred bytes at every one of them is a minute and a half of import
  -- for one table; asking the two questions that actually discriminate FIRST
  -- -- does this one hover, does that one stand -- throws away seven eighths
  -- of the cartridge per question and leaves the measuring for the handful
  -- that survive.
  local data = rom.data
  local byteAt = string.byte
  local hoverAt, standAt = {}, {}
  for _, id in ipairs(GEN3_HOVERS) do hoverAt[#hoverAt + 1] = indexOf[id] end
  for _, id in ipairs(GEN3_STANDS) do
    if indexOf[id] then standAt[#standAt + 1] = indexOf[id] end
  end

  local found
  local last = rom.size - count
  for at = 0, last do
    -- the three cheapest questions, in the order that discards the most
    local b = byteAt(data, at + standAt[1] + 1)
    if b == 0 then
      local h = byteAt(data, at + hoverAt[1] + 1)
      if h ~= 0 and h <= GEN3_ELEVATION_MAX then
        local good = true
        for i = 2, #standAt do
          if byteAt(data, at + standAt[i] + 1) ~= 0 then good = false break end
        end
        if good then
          for i = 2, #hoverAt do
            local v = byteAt(data, at + hoverAt[i] + 1)
            if v == 0 or v > GEN3_ELEVATION_MAX then good = false break end
          end
        end
        if good then
          -- ...and only now the shape: small values, mostly zero
          local zeros = 0
          for i = 0, count - 1 do
            local v = byteAt(data, at + i + 1)
            if not v or v > GEN3_ELEVATION_MAX then good = false break end
            if v == 0 then zeros = zeros + 1 end
          end
          if good and zeros > count * 0.55 and zeros < count * 0.97 then
            if found then
              Logger.warn("gen3 elevation: %07X and %07X both say the same "
                            .. "thing about which Pokemon hover, so neither "
                            .. "is used", found, at)
              return
            end
            found = at
          end
        end
      end
    end
  end

  if not found then
    Logger.warn("gen3 elevation: nothing in the cartridge lifts %s and leaves "
                  .. "%s on the ground", GEN3_HOVERS[1], GEN3_STANDS[1])
    return
  end

  local elevation, lifted, highest = {}, 0, 0
  for i, id in ipairs(order) do
    local n = rom:u8(found + i) or 0
    if n > 0 then
      elevation[id] = n
      lifted = lifted + 1
      if n > highest then highest = n end
    end
  end

  constants.gen3Elevation = elevation
  constants.gen3ElevationSource =
    ("ROM:gEnemyMonElevation %07X, %d species"):format(found, count)
  self._constants = constants
  self:write("constants", constants)
  Logger.info("Gen3 battle elevation: %d species do not touch the platform "
                .. "(up to %d pixels) -- table at %07X; %s is %d, %s is 0",
              lifted, highest, found, GEN3_HOVERS[1],
              elevation[GEN3_HOVERS[1]] or 0, GEN3_STANDS[1])
end

-- ---------------------------------------------------------------------------
-- STAGE: what a Pokemon SOUNDS like
--
-- Gen 1 and Gen 2 build a cry out of three bytes -- a base program, a pitch
-- shift and a length -- so a hundred and fifty cries fit in a few hundred
-- bytes of chip parameters.  Gen 3 does not do that.  Every one of Hoenn's
-- cries is a RECORDING, and the cartridge holds three hundred and eighty
-- eight of them.
--
-- FOUND BY SHAPE, and this one proves itself.  The cries sit in two arrays of
-- twelve-byte instrument records, and the two are not independent: they are
-- the SAME samples twice, one flagged for the ordinary cry and one for the
-- variant the game plays when a Pokemon is behind glass.  So the test is a
-- pair rather than a table:
--
--   * two runs at a twelve-byte stride, each record naming a real sample
--   * both runs EXACTLY the same length, and the second starting exactly
--     where the first ends
--   * record k of one and record k of the other pointing at the SAME sample,
--     for all three hundred and eighty eight of them
--   * and the two runs' type bytes differing, which is the only thing that
--     distinguishes them
--
-- Nothing but the cry tables satisfies that, and a run read at the wrong
-- offset cannot mirror another run at the wrong offset.
--
-- AND THEN ONE MORE, from what a cry IS: every sample has to be between a
-- twentieth of a second and four seconds long.  A run of pointers into music
-- would fail that immediately.
--
-- WHICH SPECIES GETS WHICH is arithmetic, not a table: the cartridge's
-- species list has twenty-five dead slots in the middle of it (the same ones
-- the animation stage finds), and the cries are numbered over the species
-- that are really there.  So a species' cry is its position among the REAL
-- species -- and the dead slots, which the game can still be made to ask
-- about, borrow UNOWN's.
-- ---------------------------------------------------------------------------

local GEN3_CRY_STRIDE = 12
local GEN3_CRY_MIN = 300           -- fewer than this is not a cry table
local GEN3_CRY_KEY = 0x3C          -- every cry plays at its recorded pitch
local GEN3_CRY_SHORTEST = 0.05     -- seconds
local GEN3_CRY_LONGEST = 4.0

function RomExtractorGen3:extractCries()
  self:beginStage("Gen3 cries")
  local constants = self._constants or {}
  local order = constants.speciesOrder
  if type(order) ~= "table" or #order < 300 then
    Logger.warn("gen3 cries: the species have to be read first")
    return
  end
  local rom = self.rom

  local function pointerAt(off)
    local ok, value = pcall(rom.pointer, rom, off)
    return ok and value or nil
  end

  -- a record names a real sample when the header at the far end describes one
  local function sampleAt(off)
    local wav = pointerAt(off + 4)
    if not wav or wav + 16 > rom.size then return nil end
    local okFreq, freq = pcall(rom.u32, rom, wav + 4)
    local okSize, size = pcall(rom.u32, rom, wav + 12)
    if not (okFreq and okSize) then return nil end
    if size == 0 or wav + 16 + size > rom.size then return nil end
    -- freq is the playback rate shifted ten places
    local rate = freq / 1024
    if rate < 1000 or rate > 44100 * 2 then return nil end
    local seconds = size / rate
    if seconds < GEN3_CRY_SHORTEST or seconds > GEN3_CRY_LONGEST then
      return nil
    end
    return wav, seconds
  end

  local function runAt(at)
    local kind = rom:u8(at)
    local n = 0
    while true do
      local o = at + n * GEN3_CRY_STRIDE
      if o + GEN3_CRY_STRIDE > rom.size then break end
      if rom:u8(o) ~= kind or rom:u8(o + 1) ~= GEN3_CRY_KEY then break end
      if not sampleAt(o) then break end
      n = n + 1
    end
    return n, kind
  end

  local pairs_ = {}
  local at = 0
  while at < rom.size - GEN3_CRY_STRIDE do
    if rom:u8(at + 1) == GEN3_CRY_KEY and sampleAt(at) then
      local n, kind = runAt(at)
      if n >= GEN3_CRY_MIN then
        local second = at + n * GEN3_CRY_STRIDE
        local m, kind2 = runAt(second)
        if m == n and kind2 ~= kind then
          local mirrors = true
          for k = 0, n - 1 do
            if pointerAt(at + k * GEN3_CRY_STRIDE + 4)
               ~= pointerAt(second + k * GEN3_CRY_STRIDE + 4) then
              mirrors = false
              break
            end
          end
          if mirrors then
            pairs_[#pairs_ + 1] = { at = at, reverse = second, count = n }
          end
        end
        at = at + math.max(1, n) * GEN3_CRY_STRIDE
      else
        at = at + 4
      end
    else
      at = at + 4
    end
  end

  if #pairs_ ~= 1 then
    Logger.warn("gen3 cries: %d mirrored pairs of cry tables, not one -- "
                  .. "no cries are written", #pairs_)
    return
  end
  local found = pairs_[1]

  -- which species are really there: the dead slots have no cry of their own
  local hole = {}
  for i = GEN3_ANIM_HOLE_FIRST, GEN3_ANIM_HOLE_LAST do hole[i] = true end

  local cries, written, longest = {}, 0, 0
  local cryId, unownId = 0, nil
  for i, id in ipairs(order) do
    if not hole[i] then
      if id == "UNOWN" then unownId = cryId end
      local _, seconds = sampleAt(found.at + cryId * GEN3_CRY_STRIDE)
      if cryId < found.count and seconds then
        cries[id] = { m4a = cryId, seconds = seconds }
        written = written + 1
        if seconds > longest then longest = seconds end
      end
      cryId = cryId + 1
    end
  end
  -- the dead slots borrow UNOWN's, which is what the cartridge does with them
  if unownId then
    for i, id in ipairs(order) do
      if hole[i] and not cries[id] then cries[id] = { m4a = unownId } end
    end
  end

  if written < 300 then
    Logger.warn("gen3 cries: only %d species got one -- not written", written)
    return
  end

  local audio = self._audio or {}
  audio.cries = cries
  audio.gen3Cries = {
    table = found.at,
    reverse = found.reverse,
    count = found.count,
    species = written,
    source = ("ROM:%07X and its mirror at %07X, %d cries")
             :format(found.at, found.reverse, found.count),
  }
  self._audio = audio
  self:write("audio", audio)
  Logger.info("Gen3 cries: %d recordings at %07X (mirrored at %07X); %d "
                .. "species have one, the longest %.2fs",
              found.count, found.at, found.reverse, written, longest)
end

-- ---------------------------------------------------------------------------
-- STAGE: what each move DOES, in the cartridge's own words
--
-- The summary screen's third and fourth pages have a DESCRIPTION panel under
-- the move list, and the port had nothing to put in it -- so the biggest box
-- on those two pages was empty.  It is also what the move-learning screen
-- shows, and the only place in the game that explains what a move does.
--
-- FOUND BY SHAPE, and the shape is a strong one: gMoveDescriptionPointers is
-- a run of consecutive cartridge pointers, one per move, and EVERY one of
-- them lands on a string that decodes cleanly through this cartridge's own
-- charmap and is more than half letters.  Nothing else in sixteen megabytes
-- is 354 of those in a row.
--
-- The run is one shorter than the move table because move 0 is "no move": the
-- first pointer is POUND's, so the index is the move number minus one.  That
-- is checked rather than assumed -- the run has to be exactly as long as the
-- cartridge's own move count minus one, or the stage writes nothing.
-- ---------------------------------------------------------------------------

function RomExtractorGen3:extractMoveDescriptions()
  self:beginStage("Gen3 move descriptions")
  local moves = self._moves
  local order = self._constants and self._constants.moveOrder
  if not (moves and order) then
    Logger.warn("gen3 move descriptions: the move table has to be read first")
    return
  end
  local count = 0
  for _ in pairs(order) do count = count + 1 end
  if count < 100 then
    Logger.warn("gen3 move descriptions: only %d moves are named", count)
    return
  end

  local rom = self.rom
  local map = self:charmap()

  -- a run that decodes as one description: terminated, a sentence long, and
  -- mostly letters rather than mostly control bytes
  local function looksLikeText(p)
    if not p or p + 8 >= rom.size then return false end
    local n, letters = 0, 0
    while n < 220 do
      local b = rom:u8(p + n)
      if b == 0xFF then break end
      -- A BYTE THIS CHARMAP DOES NOT NAME IS NOT A REJECTION.  Two of the
      -- 354 descriptions carry a glyph the table has no entry for, and
      -- refusing those broke the run at 243 -- which is a hundred short and
      -- looks exactly like "the table is not here".  What decides is the
      -- proportion of real letters, which no run of code or graphics passes.
      local glyph = map[b]
      if glyph and glyph:match("%a") then letters = letters + 1 end
      n = n + 1
    end
    if n < 8 or n >= 220 then return false end
    return letters * 2 >= n
  end

  local runs = {}
  local at = 0
  while at < rom.size - 4 do
    if looksLikeText(rom:pointer(at)) then
      local n, o = 0, at
      while o < rom.size - 4 and looksLikeText(rom:pointer(o)) do
        n = n + 1
        o = o + 4
      end
      if n >= count - 8 then runs[#runs + 1] = { at = at, n = n } end
      at = o
    else
      at = at + 4
    end
  end

  if #runs ~= 1 then
    Logger.warn("gen3 move descriptions: %d runs are long enough to be the "
                  .. "table, so none is used", #runs)
    return
  end
  local run = runs[1]
  if run.n ~= count then
    Logger.warn("gen3 move descriptions: the run is %d long and the cartridge "
                  .. "names %d moves, so it is not one description per move",
                run.n, count)
    return
  end

  local written, unnamed = 0, {}
  for i = 1, count do
    -- ONE PER NAMED MOVE, in the same order.  `moveOrder` starts at the first
    -- real move -- move 0 is "no move" and is not in it -- so the first
    -- pointer is the first named move's, which is POUND's.
    local ptr = rom:pointer(run.at + (i - 1) * 4)
    local id = order[i]
    local def = id and moves[id]
    if ptr and def then
      local ok, text = pcall(self.readText, self, ptr, 256)
      if not (ok and type(text) == "string" and #text > 0) then
        -- TWO OF THE 354 CARRY A GLYPH THIS CHARMAP DOES NOT NAME, and the
        -- dialogue reader refuses a run it cannot fully decode -- which is
        -- right for dialogue and wrong here, because the alternative is a
        -- move with no description at all.  readString keeps going and marks
        -- the byte it could not name, so the gap is visible in the text
        -- rather than invisible in a count.
        local okRaw, raw = pcall(self.readString, self, ptr, 220)
        text = okRaw and raw or nil
        if type(text) == "string" and text:find("{BYTE:", 1, true) then
          unnamed[#unnamed + 1] = id
        end
      end
      if type(text) == "string" and #text > 0 then
        def.description = text
        written = written + 1
      end
    end
  end
  if #unnamed > 0 then
    table.sort(unnamed)
    Logger.warn("gen3 move descriptions: %d of them use a byte this "
                  .. "charmap has no entry for (%s) -- the text is kept with "
                  .. "the byte marked, so adding the entry fixes it",
                #unnamed, table.concat(unnamed, ", "))
  end

  if written == 0 then
    Logger.warn("gen3 move descriptions: nothing decoded")
    return
  end
  self:write("moves", moves)
  Logger.info("Gen3 move descriptions: %d of %d moves say what they do "
                .. "(table at %07X)", written, count - 1, run.at)
end

-- ---------------------------------------------------------------------------
-- STAGE: the contest side of every move
--
-- The summary screen's fourth page is CONTEST MOVES, and it had nothing on it
-- but four move names: the category each move appeals in, its appeal and jam
-- values, and the sentence describing what it does in a contest were all
-- missing, so the biggest panel on that page was blank.
--
-- THREE TABLES, none of them named anywhere, and each found by a different
-- property that only it has:
--
--   gContestEffects        four-byte rows of { type, appeal, jam, 0 } where
--                          appeal and jam are TENTHS -- always a multiple of
--                          ten, never above eighty.  Forty of those in a row
--                          is a shape nothing else in the cartridge has.
--   gContestMoves          eight-byte rows, one per move including move zero,
--                          whose second byte is the contest category: always
--                          0..4, all five present, and none of them rare.
--                          Searched only among addresses something POINTS at,
--                          which is what makes a 355-row validation cheap.
--   the descriptions       a run of consecutive pointers to strings, the same
--                          shape the move descriptions are found by, and told
--                          from them by length: fifty rather than 354.
--
-- WHAT MAKES THE CATEGORY READING FALSIFIABLE: the five categories are COOL,
-- BEAUTY, CUTE, SMART and TOUGH in that order, and the suite checks moves
-- whose category everybody knows -- SURF is BEAUTY, PSYCHIC is SMART, CHARM
-- is CUTE, STRENGTH is TOUGH.  A table read at the wrong address, or with the
-- categories in a different order, fails those.
-- ---------------------------------------------------------------------------

local GEN3_CONTEST_CATEGORIES = { "COOL", "BEAUTY", "CUTE", "SMART", "TOUGH" }
local GEN3_CONTEST_MOVE_STRIDE = 8
local GEN3_CONTEST_EFFECT_STRIDE = 4
local GEN3_CONTEST_EFFECT_MIN = 40

function RomExtractorGen3:extractContestMoves()
  self:beginStage("Gen3 contest moves")
  local moves = self._moves
  local order = self._constants and self._constants.moveOrder
  if not (moves and order) then
    Logger.warn("gen3 contest moves: the move table has to be read first")
    return
  end
  local named = 0
  for _ in pairs(order) do named = named + 1 end
  local rom = self.rom

  -- ---- the effects: appeal and jam, in tenths ----------------------------
  local function effectRow(o)
    local kind, appeal, jam, pad =
      rom:u8(o), rom:u8(o + 1), rom:u8(o + 2), rom:u8(o + 3)
    if kind > 8 or pad ~= 0 then return nil end
    if appeal > 80 or jam > 80 then return nil end
    if appeal % 10 ~= 0 or jam % 10 ~= 0 then return nil end
    return { kind = kind, appeal = appeal, jam = jam }
  end

  local effectRuns = {}
  local at = 0
  while at < rom.size - GEN3_CONTEST_EFFECT_MIN * GEN3_CONTEST_EFFECT_STRIDE do
    if effectRow(at) then
      local n, o = 0, at
      while effectRow(o) do n = n + 1; o = o + GEN3_CONTEST_EFFECT_STRIDE end
      -- A ZERO-FILLED REGION SATISFIES THE SHAPE PERFECTLY -- type 0, appeal
      -- 0, jam 0, pad 0 -- and there are eleven hundred of those.  What a
      -- real effect table has and a hole does not is VARIETY: several
      -- different appeal values, and at least one move that jams.
      if n >= GEN3_CONTEST_EFFECT_MIN then
        local appeals, jams = {}, 0
        local distinct = 0
        for i = 0, n - 1 do
          local row = effectRow(at + i * GEN3_CONTEST_EFFECT_STRIDE)
          if row then
            if not appeals[row.appeal] then
              appeals[row.appeal] = true
              distinct = distinct + 1
            end
            if row.jam > 0 then jams = jams + 1 end
          end
        end
        if distinct >= 4 and jams >= 4 then
          effectRuns[#effectRuns + 1] = { at = at, n = n }
        end
      end
      at = o
    else
      at = at + 4
    end
  end
  if #effectRuns ~= 1 then
    Logger.warn("gen3 contest moves: %d runs have the effect table's shape, "
                  .. "so none is used", #effectRuns)
    return
  end
  local effectsAt, effectCount = effectRuns[1].at, effectRuns[1].n
  -- TRIM THE LEADING PADDING.  A row of four zeros satisfies the shape and
  -- the run picks up however many sit in front of the table -- but an effect
  -- that neither appeals nor jams does nothing at all, so it is not one.  The
  -- first real row is where the table starts, and getting that wrong shifts
  -- every move's effect by one.
  while effectCount > 0 do
    local first = effectRow(effectsAt)
    if first and (first.appeal > 0 or first.jam > 0) then break end
    effectsAt = effectsAt + GEN3_CONTEST_EFFECT_STRIDE
    effectCount = effectCount - 1
  end
  if effectCount < GEN3_CONTEST_EFFECT_MIN then
    Logger.warn("gen3 contest moves: the effect table is only %d rows once "
                  .. "its padding is trimmed", effectCount)
    return
  end

  -- ---- the move rows: only where something points ------------------------
  -- `spread` is only asked of the FULL table: sixteen rows cannot contain all
  -- five categories twenty times each, so asking it of the cheap pass would
  -- reject the very table being looked for.
  local function looksLikeMoveTable(o, rows, spread)
    local seen, kinds = {}, 0
    for i = 0, rows - 1 do
      local base = o + i * GEN3_CONTEST_MOVE_STRIDE
      local effect, category = rom:u8(base), rom:u8(base + 1)
      if category > 4 or effect >= effectCount then return nil end
      if not seen[category] then seen[category] = 0; kinds = kinds + 1 end
      seen[category] = seen[category] + 1
    end
    if not spread then return true end
    if kinds ~= 5 then return nil end
    for _, n in pairs(seen) do
      if n < 20 then return nil end
    end
    return true
  end

  local targets, candidates = {}, {}
  for o = 0, rom.size - 8, 4 do
    local p = rom:pointer(o)
    if p and p % 4 == 0 and not targets[p] then
      targets[p] = true
      -- the cheap reject first: sixteen rows is enough to throw out
      -- everything that is not a table of this shape
      if p + named * GEN3_CONTEST_MOVE_STRIDE < rom.size
         and looksLikeMoveTable(p, 16) then
        candidates[#candidates + 1] = p
      end
    end
  end

  local movesAt
  local full = {}
  for _, p in ipairs(candidates) do
    if looksLikeMoveTable(p, named + 1, true) then full[#full + 1] = p end
  end
  if #full ~= 1 then
    Logger.warn("gen3 contest moves: %d tables have one row per move with a "
                  .. "category in it, so none is used", #full)
    return
  end
  movesAt = full[1]
  -- kept for extractContests, which reads the combo bytes (+2 and +3..+6) off
  -- the same rows rather than finding the table a second time
  self._contestMovesAt = movesAt

  -- ---- and the sentences -------------------------------------------------
  local map = self:charmap()
  local function looksLikeText(p)
    if not p or p + 8 >= rom.size then return false end
    local n, letters = 0, 0
    while n < 220 do
      local b = rom:u8(p + n)
      if b == 0xFF then break end
      local glyph = map[b]
      if glyph and glyph:match("%a") then letters = letters + 1 end
      n = n + 1
    end
    if n < 8 or n >= 220 then return false end
    return letters * 2 >= n
  end

  local descriptionsAt
  do
    local runs = {}
    local o = 0
    while o < rom.size - 4 do
      if looksLikeText(rom:pointer(o)) then
        local n, q = 0, o
        while q < rom.size - 4 and looksLikeText(rom:pointer(q)) do
          n = n + 1
          q = q + 4
        end
        -- one per effect, give or take the junk entry the run picks up past
        -- the end of the table
        if n >= effectCount and n <= effectCount + 8 then
          runs[#runs + 1] = o
        end
        o = q
      else
        o = o + 4
      end
    end
    if #runs == 1 then
      descriptionsAt = runs[1]
    elseif #runs > 1 then
      -- MORE THAN ONE RUN IS THE RIGHT LENGTH, so the tiebreak is company:
      -- the effect descriptions and the move rows are read by the same code,
      -- so their two pointers sit in the same literal pool.  The run that is
      -- named a few words away from gContestMoves is the one.
      -- the pointer is little-endian with the $08000000 base in the top byte
      local needle = string.char(movesAt % 256,
                                 math.floor(movesAt / 256) % 256,
                                 math.floor(movesAt / 65536) % 256,
                                 0x08)
      local near = {}
      local from = 1
      while true do
        local i = rom.data:find(needle, from, true)
        if not i then break end
        from = i + 1
        local site = i - 1
        for probe = math.max(0, site - 0x40), site + 0x40, 4 do
          local p = rom:pointer(probe)
          if p then near[p] = true end
        end
      end
      local picked = {}
      for _, o in ipairs(runs) do
        local target = rom:pointer(o)
        if near[o] or (target and near[target]) then picked[#picked + 1] = o end
      end
      if #picked == 1 then descriptionsAt = picked[1] end
    end
    if not descriptionsAt then
      Logger.warn("gen3 contest moves: %d runs could be the effect "
                    .. "descriptions and none is named beside the move rows, "
                    .. "so the sentences are left out", #runs)
    end
  end

  -- ---- stamp it on the move rows ----------------------------------------
  local effects = {}
  for i = 0, effectCount - 1 do
    local row = effectRow(effectsAt + i * GEN3_CONTEST_EFFECT_STRIDE)
    if row then
      if descriptionsAt then
        local ptr = rom:pointer(descriptionsAt + i * 4)
        local ok, text = pcall(self.readText, self, ptr, 256)
        if not (ok and type(text) == "string") then
          local okRaw, raw = pcall(self.readString, self, ptr, 220)
          text = okRaw and raw or nil
        end
        row.description = text
      end
      effects[i] = row
    end
  end

  local stamped = 0
  for i = 1, named do
    local id = order[i]
    local def = id and moves[id]
    -- row 0 is "no move", so a named move's row is its own number
    local base = movesAt + i * GEN3_CONTEST_MOVE_STRIDE
    if def then
      local effect = rom:u8(base)
      local category = GEN3_CONTEST_CATEGORIES[rom:u8(base + 1) + 1]
      local record = effects[effect]
      def.contestCategory = category
      def.contestEffect = effect
      if record then
        def.contestAppeal = record.appeal
        def.contestJam = record.jam
        def.contestDescription = record.description
      end
      stamped = stamped + 1
    end
  end

  self:write("moves", moves)
  local constants = self._constants or {}
  constants.gen3Contest = {
    categories = GEN3_CONTEST_CATEGORIES,
    effectCount = effectCount,
    -- appeal and jam are stored in tenths: 40 is four hearts
    heartUnit = 10,
    source = ("ROM:gContestMoves %07X, gContestEffects %07X (%d)%s")
             :format(movesAt, effectsAt, effectCount,
                     descriptionsAt
                       and (", descriptions %07X"):format(descriptionsAt)
                       or ""),
  }
  self._constants = constants
  self:write("constants", constants)
  Logger.info("Gen3 contest moves: %d moves carry a category, appeal and jam "
                .. "(%d effects at %07X, rows at %07X)",
              stamped, effectCount, effectsAt, movesAt)
end

-- ---------------------------------------------------------------------------
-- STAGE: the sound every move makes
--
-- Hoenn's battles were SILENT.  Not quiet -- silent: a move resolved, the
-- damage landed, and nothing played.  The engine has had a fallback for this
-- since Gen 1 -- BattleState reads `moves[id].anim` and plays `anim.sound`
-- when there is no frame-by-frame animation player -- and for Gen 3 that
-- record was never written, so the branch that plays a move's sound could not
-- be reached by any move in the game.
--
-- WHERE THE SOUND LIVES.  A Gen 3 move animation is not a table of rows the
-- way a Game Boy one is; it is a BYTECODE PROGRAM.  gBattleAnims_Moves is one
-- pointer per move to a little script -- load these sprites, spawn that task,
-- wait, play this sound, end -- and the sound is a `playse` command somewhere
-- inside it.  Reading it means running the program far enough to find the
-- first sound it plays.
--
-- THE COMMAND TABLE IS THE WHOLE PROBLEM, and it is also the proof.  Every
-- command is one opcode byte and a fixed number of argument bytes; get one
-- length wrong and the walk steps into the middle of an argument, reads a
-- byte that is not an opcode, and desyncs for the rest of the script.  So the
-- test is not "does this look right" but "does EVERY script in the cartridge
-- walk from its first byte to an `end` without ever meeting a byte that is
-- not a command".  Four lengths were wrong on the first pass -- panse,
-- loopsewithpan, waitplaysewithpan and jumpargeq were each short by one to
-- three bytes -- and the walk found all four by failing, one script at a
-- time, until 355 of 355 came out clean.
--
-- FOLLOWING THE PROGRAM, not just reading it.  Three commands move the
-- program counter and all three have to be obeyed or the sound is missed:
-- `goto` jumps, `call` jumps and comes back (so the walker keeps a return
-- stack), and `choosetwoturnanim` picks between two whole sub-scripts -- which
-- is exactly where FLY, DIG, SOLARBEAM, SKULL BASH, SKY ATTACK and BOUNCE
-- keep their sounds, and why a walker that only read straight-line code found
-- nothing for the two-turn moves.  Conditional jumps are followed as well as
-- fallen through, because either arm's sound is the move's sound.
--
-- HOW THE TABLE IS FOUND, with no symbol to name it: sweep the cartridge for
-- runs of at least 355 consecutive words that are all valid ROM pointers --
-- twelve of those exist -- then ask each run the question above.  Five other
-- runs also walk 355 for 355 clean, because a run of pointers into text or
-- graphics lands on a byte that happens to be `end` and a one-command script
-- is trivially clean.  What separates them is that NONE of those plays a
-- sound: the real table gives 342 moves a sound and the best impostor gives
-- 29.  That gap is not a threshold anybody tuned, it is the difference
-- between a table of animation programs and a table of something else.
--
-- WHAT THIS DOES NOT DO.  `shake` and `flash` -- the other two fields the
-- fallback understands -- are NOT derivable here.  In Gen 1 they are opcodes;
-- in Gen 3 they are `createvisualtask` with the address of a C function, and
-- naming AnimTask_ShakeMon apart from four hundred other task addresses needs
-- a symbol table this cartridge does not ship.  So this stage writes the
-- sound and nothing else, and the hit reaction keeps coming from applyHitFx
-- where it already did.
-- ---------------------------------------------------------------------------

-- One table rather than a dozen file locals: this module is already close to
-- Lua's 200-local ceiling for a chunk.
local GEN3_ANIM = {
  ENDSCRIPT = 0x08,
  RETURNTO = 0x0F,
  CALLSUB = 0x0E,
  JUMP = 0x13,
  TWOTURN = 0x11,
  SPRITE = 0x02,        -- createsprite:     7 header + 2/arg
  TASK = 0x03,          -- createvisualtask: 7 header + 2/arg
  SOUNDTASK = 0x1F,     -- createsoundtask:  6 header + 2/arg
  ARGEQ = 0x21,         -- jumpargeq: the move picking one of its own variants
  ARGC_LONG = 6,        -- where createsprite/createvisualtask...
  ARGC_SHORT = 5,       -- ...and createsoundtask count their args
  ROWS = 355,           -- move 0 ("no move") plus 354 moves
  MIN_SOUNDS = 200,     -- the real table gives 342; the best impostor gives 29
  MAX_STEPS = 4000,     -- a script is tens of commands long
  MAX_DEPTH = 24,       -- nesting of call/branch arms
  DELAY = 0x04,         -- the only command that spends time
  LOADGFX = 0x00,       -- loadspritegfx: which particle sheet is brought in
  FADETOBG = 0x14,      -- the two commands that replace the whole battle
  FADETOBGSET = 0x25,   -- background, which is a screen-wide event
  TARGET_USER = 16,     -- MOVE_TARGET_USER, out of gBattleMoves' own field
  -- struct SpriteTemplate: u16 tileTag, u16 paletteTag, then five pointers --
  -- the OAM, the animations, the frame images, the affine animations and the
  -- callback.
  TEMPLATE_OAM = 4,
  TEMPLATE_ANIMS = 8,
  TEMPLATE_CALLBACK = 20,
  -- union AnimCmd is one word: the low halfword is the image index, or one of
  -- three terminators -- END (-1), JUMP (-2), LOOP (-3) -- and the next six
  -- bits are how many frames that image is held for.
  ANIM_END = 0xFFFD,    -- the lowest of the three terminator halfwords
  ANIM_STOP = 0xFFFF,   -- ...and the one that ends rather than repeats
  ANIM_MAX = 32,        -- a particle's animation is a handful of frames long
  -- The four SQUARE OBJ sizes, biggest first, in bytes of 4bpp art.  Used
  -- only where no sprite template names a sheet's frame size.
  SQUARES = { { 64, 2048 }, { 32, 512 }, { 16, 128 }, { 8, 32 } },
  TAG_FIRST = 10000,    -- ANIM_TAG_BONE, the first particle tag
  TAG_MIN_RUN = 200,    -- how long a tag run has to be to be the table
  -- createsprite's battler byte, bit 7 = ANIMSPRITE_IS_TARGET.  IT PICKS A
  -- SUBPRIORITY, NOT A PLACE: Cmd_createsprite reads it only to decide whose
  -- draw order the particle borrows, and then spawns the sprite at
  -- GetBattlerSpriteCoord(gBattleAnimTarget, ...) whether the bit is set or
  -- not.  Kept because it is a fact about the byte; not used to place
  -- anything.  See the note over the event list below.
  IS_TARGET = 0x80,
  MAX_OFFSET = 64,      -- an argument bigger than a battler's own box is
                        -- not a pixel offset, whatever else it is
  MAX_EVENTS = 64,      -- a move's particle list, capped
  -- the shape a mon-shake task call has, checked against every call a
  -- function makes before any of them is believed (see the shake pass)
  SHAKE_MAX_BATTLER = 8,
  -- 255, not 64: the bound has to be loose enough to admit a function whose
  -- every OTHER call is obviously a shake.  PSYCHO BOOST asks for 240 swings
  -- and MIST BALL for 70, and rejecting those two threw away the whole of the
  -- 99-call function they belong to -- which is the one that shakes the
  -- Pokemon being hit in most of the game.  Raising it admits exactly that
  -- one function and nothing else.
  SHAKE_MAX_COUNT = 255,
  SHAKE_MAX_DELAY = 16,
  -- ...and the shape a palette-blend call has
  BLEND_MAX_SELECTOR = 31,   -- five bits: bg, attacker, target, two partners
  BLEND_MAX_STEP = 32,       -- a delay, a count, two 0..16 coefficients
  COLOUR_MAX = 32767,        -- 15-bit BGR, 32767 being white
}

-- struct SpriteTemplate: u16 tileTag, u16 paletteTag, then five pointers --
-- the OAM, the animations, the frame images, the affine animations and the
-- callback.
-- Where the tag halfword sits in each of the two particle tables:
-- CompressedSpriteSheet is { pointer, u16 size, u16 tag } and
-- CompressedSpritePalette is { pointer, u16 tag }.
local GEN3_ANIM_PIC_SIZE = 4
local GEN3_ANIM_PIC_TAG = 6
local GEN3_ANIM_PAL_TAG = 4

-- OBJ size, by the OAM's shape and size bits.  The hardware's table, not a
-- choice: shape 0 is square, 1 wide, 2 tall.
GEN3_ANIM.OBJ_DIM = {
  [0] = { [0] = { 8, 8 }, [1] = { 16, 16 }, [2] = { 32, 32 }, [3] = { 64, 64 } },
  [1] = { [0] = { 16, 8 }, [1] = { 32, 8 }, [2] = { 32, 16 }, [3] = { 64, 32 } },
  [2] = { [0] = { 8, 16 }, [1] = { 8, 32 }, [2] = { 16, 32 }, [3] = { 32, 64 } },
}

-- Command lengths, in bytes including the opcode.  Straight off
-- asm/macros/battle_anim_script.inc: every macro is `.byte <op>` and then a
-- fixed run of .byte/.2byte/.4byte, and this is the sum of that run.  Three
-- commands are variable-length and are computed instead (see below); the two
-- terminators and the four jumps are here for their length even though the
-- walker handles their control flow itself.
GEN3_ANIM.LEN = {
  [0x00] = 3,  -- loadspritegfx        .2byte tag
  [0x01] = 3,  -- unloadspritegfx      .2byte tag
  [0x04] = 2,  -- delay                .byte frames
  [0x05] = 1,  -- waitforvisualfinish
  [0x06] = 1,  -- nop
  [0x07] = 1,  -- nop2
  [0x08] = 1,  -- end
  [0x09] = 3,  -- playse               .2byte song
  [0x0A] = 2,  -- monbg
  [0x0B] = 2,  -- clearmonbg
  [0x0C] = 3,  -- setalpha             .2byte
  [0x0D] = 1,  -- blendoff
  [0x0E] = 5,  -- call                 .4byte address
  [0x0F] = 1,  -- return
  [0x10] = 4,  -- setarg               .byte, .2byte
  [0x11] = 9,  -- choosetwoturnanim    .4byte, .4byte
  [0x12] = 6,  -- jumpifmoveturn       .byte, .4byte
  [0x13] = 5,  -- goto                 .4byte address
  [0x14] = 2,  -- fadetobg
  [0x15] = 1,  -- restorebg
  [0x16] = 1,  -- waitbgfadeout
  [0x17] = 1,  -- waitbgfadein
  [0x18] = 2,  -- changebg
  [0x19] = 4,  -- playsewithpan        .2byte song, .byte pan
  [0x1A] = 2,  -- setpan
  [0x1B] = 7,  -- panse                .2byte song, .byte x4
  [0x1C] = 6,  -- loopsewithpan        .2byte song, .byte x3
  [0x1D] = 5,  -- waitplaysewithpan    .2byte song, .byte pan, .byte wait
  [0x1E] = 3,  -- setbldcnt            .2byte
  [0x20] = 1,  -- waitsound
  [0x21] = 8,  -- jumpargeq            .byte, .2byte, .4byte
  [0x22] = 2,  -- monbg_static
  [0x23] = 2,  -- clearmonbg_static
  [0x24] = 5,  -- jumpifcontest        .4byte
  [0x25] = 4,  -- fadetobgfromset      .byte x3
  [0x26] = 7,  -- panse_adjustnone     .2byte song, .byte x4
  [0x27] = 7,  -- panse_adjustall      .2byte song, .byte x4
  [0x28] = 2,  -- splitbgprio
  [0x29] = 1,  -- splitbgprio_all
  [0x2A] = 2,  -- splitbgprio_foes
  [0x2B] = 2,  -- invisible
  [0x2C] = 2,  -- visible
  [0x2D] = 2,  -- teamattack_moveback
  [0x2E] = 2,  -- teamattack_movefwd
  [0x2F] = 1,  -- stopsound
}

-- Every command whose FIRST argument is a song number.  All seven are
-- `.byte <op>` followed immediately by `.2byte <song>`, so the number is at
-- the same place in each and the walker does not need to know which is which.
GEN3_ANIM.SOUND_OPS = {
  [0x09] = true,  -- playse
  [0x19] = true,  -- playsewithpan
  [0x1B] = true,  -- panse
  [0x1C] = true,  -- loopsewithpan
  [0x1D] = true,  -- waitplaysewithpan
  [0x26] = true,  -- panse_adjustnone
  [0x27] = true,  -- panse_adjustall
}

-- Conditional jumps, and the byte offset of each pointer argument.  These are
-- followed AND fallen through -- whichever arm plays first is the move's
-- sound.  choosetwoturnanim is here with both of its pointers and is the one
-- that never falls through.
GEN3_ANIM.BRANCH = {
  [0x11] = { 1, 5 },  -- choosetwoturnanim: first-turn script, second-turn
  [0x12] = { 2 },     -- jumpifmoveturn
  [0x21] = { 4 },     -- jumpargeq
  [0x24] = { 1 },     -- jumpifcontest
}


-- Run one animation script and report what it does: the first sound it plays,
-- every particle it spawns and when, how long it runs, and whether every byte
-- it reached was a command.  `clean` is the falsifiable half: it is false the
-- moment the walk meets an opcode the table does not have, a pointer that
-- leaves the cartridge, or a program that will not stop.
--
-- WHAT A PARTICLE EVENT IS.  `createsprite` names a sprite TEMPLATE, and the
-- template's first halfword is the tag of the sheet the particle is drawn
-- from while its OAM gives the frame's size.  The command's own battler byte
-- carries ANIMSPRITE_IS_TARGET in bit 7 -- which is how the script says the
-- particle belongs over the DEFENDER rather than the attacker -- and its
-- first two arguments are, for the overwhelming majority of the callbacks, a
-- pixel offset from that battler.  An argument outside a battler's own box is
-- not an offset (it is a duration, a count, a subpriority for some other
-- callback) and is dropped rather than guessed at.
--
-- WHAT IS NOT READ, and cannot be: the callback itself.  Where a particle
-- goes after it is spawned is a C function in the cartridge, and no symbol
-- names it.  So this is the move's own art, on the right battler, at the
-- right offset, at the right moment -- and not the flight path.
function RomExtractorGen3:animScriptRead(entry)
  local rom = self.rom
  -- A VISITED SET PER INVOCATION, not one for the whole walk.
  --
  -- Reported from play: "ice beam doesnt look right".  It was two frames of
  -- five crystals where the cartridge draws forty-eight over fifty-seven.
  --
  -- ICE BEAM's script is a burst of three `createsprite` in a subroutine and
  -- then TWELVE `call`s of it -- which is what a beam IS, a stream of the
  -- same particle.  A single visited set marks that subroutine's bytes on the
  -- first call, so every call after it met a byte it had "already run" and
  -- returned at once.  The move came out with one burst and a two-frame
  -- duration.
  --
  -- The guard is there to stop a `goto` that loops forever, and that is a
  -- real thing a script does.  But a `call` that RETURNS is not a loop, it is
  -- a repeat: the outer position moves on afterwards.  So the set is pushed
  -- and popped with the call stack -- a cycle inside one invocation is still
  -- caught, and the same subroutine reached again from a different call site
  -- is walked again, which is the whole of the animation.
  --
  -- MAX_STEPS is what bounds the walk now rather than the visited set, and it
  -- was already there.
  local sound, clean = nil, true
  local frames = { {} }
  local seen = setmetatable({}, {
    __index = function(_, k) return frames[#frames][k] end,
    __newindex = function(_, k, v) frames[#frames][k] = v end,
  })
  local events, duration = {}, 0
  local loaded, backgrounds = {}, 0
  -- WHICH C FUNCTIONS THE SCRIPT HANDS ITS ANIMATION TO.  A retail dump names
  -- none of them, but two moves whose scripts call the SAME address are
  -- calling the same function, and that is a fact about the cartridge rather
  -- than a reading of it.  Collected for the moves that spawn no particles of
  -- their own, where the task is the entire animation.
  local tasks = {}
  -- ...AND THE SPRITES THAT ARE NOT PICTURES.
  --
  -- A `createsprite` whose template has NO tile tag draws nothing.  It exists
  -- so that its CALLBACK can move or tint the battler -- eight such callbacks
  -- between them carry the run-up on most of the physical moves in the game,
  -- and TACKLE's whole animation is one of them.  `particle` refuses these,
  -- correctly: they have no art.  They are collected here instead, by the
  -- callback that is the entire point of them.
  local helpers = {}
  local limit = rom.size - 16
  -- TWO PASSES OVER ONE SCRIPT, and they need separate visited sets.
  --
  -- The sound pass follows every conditional arm, because either arm's
  -- `playse` is the move's sound.  The particle pass follows only the path
  -- the move actually takes.  Sharing one visited set let the sound pass walk
  -- into a subroutine FIRST and mark it seen, and the particle pass then
  -- returned from the same `call` having recorded nothing -- which is why
  -- BLIZZARD, MEGAHORN, DRILL PECK and sixty others came out with a sound and
  -- no picture even though their art is right there in the subroutine.

  local function particle(p)
    local template = rom:pointer(p + 1)
    if not template then return nil end
    local tag = rom:u16(template)
    if tag < GEN3_ANIM.TAG_FIRST then return nil end
    local oam = rom:pointer(template + 4)
    if not oam then return nil end
    local shape = math.floor(rom:u16(oam) / 16384) % 4
    local size = math.floor(rom:u16(oam + 2) / 16384) % 4
    local dim = GEN3_ANIM.OBJ_DIM[shape] and GEN3_ANIM.OBJ_DIM[shape][size]
    if not dim then return nil end
    local argc = rom:u8(p + 6)
    local function offset(i)
      if argc < i then return 0 end
      local v = rom:u16(p + 7 + (i - 1) * 2)
      if v >= 32768 then v = v - 65536 end
      if v > GEN3_ANIM.MAX_OFFSET or v < -GEN3_ANIM.MAX_OFFSET then return 0 end
      return v
    end
    local battler = rom:u8(p + 5)
    -- the template also says how its own picture is timed, and for how long
    -- the particle is meant to be up (spriteAnimTimeline)
    local held, loops = self:spriteAnimTimeline(template, dim[1], dim[2])
    -- ...and its callback says where it goes; see animMotionOf
    local callback = rom:pointer(template + 20)
    local from, motion = self:animMotionOf(callback)
    -- ...and the one callback whose whole path is arithmetic rather than a
    -- shared helper: PERISH SONG's notes.  Its three arguments are not the
    -- pixel offsets every other createsprite passes -- they are the note's
    -- number, its picture and its phase -- so they are read raw here and the
    -- offsets are left at zero.  See animOrbit.
    local orbit = nil
    local O = RomExtractorGen3.ANIM_ORBIT
    if callback and callback - (callback % 2) == O.CALLBACK
       and self:animOrbit() then
      local function raw(i)
        if argc < i then return 0 end
        return rom:u16(p + 7 + (i - 1) * 2) % 256
      end
      motion, from = "orbit", nil
      orbit = { index = raw(1), pic = raw(2), phase = raw(3) }
    end
    -- ...and the note script's seventeenth sprite, which hides itself on its
    -- own first frame and exists only to time the sound
    local shape = self:animOrbit()
    if callback and shape and shape.silent
       and callback - (callback % 2) == shape.silent then
      return nil
    end
    -- HOW LONG THE CROSSING TAKES.  The projectile family passes it as the
    -- fifth argument -- `sprite->data[0] = gBattleAnimArgs[4]` -- and that is
    -- the one operand of the five this port can name.  A script that passes
    -- fewer, or a number that is not a frame count, leaves it nil and the
    -- particle crosses over its own visible life instead.
    local travel = nil
    if motion and argc >= 5 then
      local M = RomExtractorGen3.ANIM_MOTION
      local v = rom:u16(p + 7 + 4 * 2)
      if v >= 32768 then v = v - 65536 end
      if v >= M.MIN_FRAMES and v <= M.MAX_FRAMES then travel = v end
    end
    return {
      tag = tag, width = dim[1], height = dim[2],
      subpriorityOfTarget = battler >= GEN3_ANIM.IS_TARGET or nil,
      x = offset(1), y = offset(2),
      held = held, loops = loops or nil,
      -- struct SpriteTemplate is { u16 tileTag, u16 paletteTag, *oam, *anims,
      -- *images, *affineAnims, callback } -- the callback is the last word,
      -- twenty bytes in, and every one reads back with bit 0 set because they
      -- are Thumb.  It is what decides where the particle GOES, and
      -- animMotionOf reads it.
      from = from, motion = motion, travel = travel, orbit = orbit,
    }
  end

  local firstArm = nil
  local function run(at, stack, depth, t, record)
    if depth > GEN3_ANIM.MAX_DEPTH then clean = false return t end
    local p, steps = at, 0
    while true do
      steps = steps + 1
      if steps > GEN3_ANIM.MAX_STEPS then clean = false return t end
      if p < 0 or p >= limit then clean = false return t end
      -- a script that meets a byte it has already run is looping through a
      -- path this walk has taken; there is nothing new to find down it
      if seen[p] then return t end
      seen[p] = true

      local op = rom:u8(p)
      if op == GEN3_ANIM.ENDSCRIPT then return t end
      if op == GEN3_ANIM.RETURNTO then
        local back = stack[#stack]
        if not back then return t end
        stack[#stack] = nil
        -- ...and the subroutine's own visited bytes go with it, so the next
        -- call of the same subroutine walks it again
        if #frames > 1 then frames[#frames] = nil end
        p = back
      else
        local step = GEN3_ANIM.LEN[op]
        if op == GEN3_ANIM.SPRITE or op == GEN3_ANIM.TASK then
          step = 7 + 2 * rom:u8(p + GEN3_ANIM.ARGC_LONG)
        elseif op == GEN3_ANIM.SOUNDTASK then
          step = 6 + 2 * rom:u8(p + GEN3_ANIM.ARGC_SHORT)
        end
        if not step then clean = false return t end
        if GEN3_ANIM.SOUND_OPS[op] and not sound then sound = rom:u16(p + 1) end
        if op == GEN3_ANIM.DELAY and record then t = t + rom:u8(p + 1) end
        if record and op == GEN3_ANIM.TASK then
          local fn = rom:u32(p + 1)
          if fn and fn >= 0x08000000 then
            local argc = rom:u8(p + GEN3_ANIM.ARGC_LONG)
            local args = {}
            for i = 1, math.min(argc, 8) do
              local v = rom:u16(p + 7 + (i - 1) * 2)
              if v >= 32768 then v = v - 65536 end
              args[i] = v
            end
            tasks[#tasks + 1] = { fn = fn - 0x08000000, args = args, at = t }
          end
        end
        if record and op == GEN3_ANIM.SPRITE then
          local template = rom:pointer(p + 1)
          if template and rom:u16(template) < GEN3_ANIM.TAG_FIRST then
            local cb = rom:pointer(template + GEN3_ANIM.TEMPLATE_CALLBACK)
            if cb then
              local argc = rom:u8(p + GEN3_ANIM.ARGC_LONG)
              local args = {}
              for i = 1, math.min(argc, 8) do
                local v = rom:u16(p + 7 + (i - 1) * 2)
                if v >= 32768 then v = v - 65536 end
                args[i] = v
              end
              -- `pointer` already answers a flat offset; the low bit is the
              -- Thumb marker every function pointer in this cartridge carries
              helpers[#helpers + 1] = { cb = cb - (cb % 2),
                                        args = args, at = t }
            end
          end
        end
        if record and op == GEN3_ANIM.LOADGFX then
          -- which particle SHEETS the move brings in, whether or not it
          -- spawns them itself: a task that spawns its own sprites still has
          -- to have the art loaded for it first
          loaded[#loaded + 1] = rom:u16(p + 1)
        end
        if record and (op == GEN3_ANIM.FADETOBG
                       or op == GEN3_ANIM.FADETOBGSET) then
          backgrounds = backgrounds + 1
        end
        if op == GEN3_ANIM.SPRITE and record and #events < GEN3_ANIM.MAX_EVENTS then
          local one = particle(p)
          if one then
            one.at = t
            events[#events + 1] = one
          end
        end

        local branch = GEN3_ANIM.BRANCH[op]
        if branch then
          for i, off in ipairs(branch) do
            local target = rom:pointer(p + off)
            if not target then clean = false return t end
            -- ON THE PARTICLE PASS only choosetwoturnanim's FIRST arm is
            -- taken: that is the animation the move plays on the turn it is
            -- used.  Every other conditional is a path the move might not
            -- take -- the contest version, the second hit -- and walking it
            -- would spawn particles the battle never sees.  The sound pass
            -- takes them all.
            -- ...and the FIRST `jumpargeq` arm is remembered, not walked.
            -- MAGNITUDE's whole animation is behind two of them: the script
            -- sets an argument, waits, and then every one of its pictures is
            -- down a branch this walk cannot evaluate, so the fall-through
            -- is `end` and the move came out with nothing at all.  A
            -- `jumpargeq` arm is not a path the battle might not take -- it
            -- is one of the move's own variants, and all of them are real
            -- battle animations.  See below, where it is used only if the
            -- straight path found no picture.
            if record and op == GEN3_ANIM.ARGEQ and not firstArm then
              firstArm = rom:pointer(p + off)
            end
            local follow = not record or op == GEN3_ANIM.TWOTURN
            if follow then
              local copy = {}
              for k, v in ipairs(stack) do copy[k] = v end
              run(target, copy, depth + 1, t,
                  record and op == GEN3_ANIM.TWOTURN and i == 1)
            end
          end
        end
        if op == GEN3_ANIM.TWOTURN then return t end

        if op == GEN3_ANIM.CALLSUB or op == GEN3_ANIM.JUMP then
          local target = rom:pointer(p + 1)
          if not target then clean = false return t end
          if op == GEN3_ANIM.CALLSUB then
            stack[#stack + 1] = p + step
            frames[#frames + 1] = {}
          end
          p = target
        else
          p = p + step
        end
      end
    end
  end

  -- the particles first, on the path the move takes
  frames = { {} }
  duration = run(entry, {}, 0, 0, true)
  -- ...and if that path drew NOTHING and the script had a `jumpargeq`, the
  -- move's pictures are all down its arms.  Take the first one: it is one of
  -- the move's own variants rather than a guess, and one variant is nearer
  -- the cartridge than the blank screen this produced before.  Which variant
  -- the cartridge would have picked depends on a value the script sets at run
  -- time, and that is not read here -- so MAGNITUDE always plays its first.
  if #events == 0 and firstArm then
    frames = { {} }
    local more = run(firstArm, {}, 0, 0, true)
    if (more or 0) > (duration or 0) then duration = more end
  end
  -- ...then the sound, over everything, with a fresh set of visited bytes
  frames = { {} }
  run(entry, {}, 0, 0, false)
  return sound, clean, events, duration, loaded, backgrounds, tasks,
         helpers
end

-- The sound alone, which is what the table search asks for.
function RomExtractorGen3:animScriptSound(entry)
  local sound, clean = self:animScriptRead(entry)
  return sound, clean
end

-- Walk all 355 scripts a candidate table points at and score it: how many
-- came out clean, and how many play a sound.  Both numbers are needed --
-- clean alone is satisfied by any run of pointers that happens to land on an
-- `end` byte.
function RomExtractorGen3:animTableScore(at)
  local rom = self.rom
  local clean, sounds = 0, 0
  for i = 0, GEN3_ANIM.ROWS - 1 do
    local entry = rom:pointer(at + i * 4)
    if not entry then return 0, 0 end
    local sound, ok = self:animScriptSound(entry)
    if ok then clean = clean + 1 end
    if sound then sounds = sounds + 1 end
  end
  return clean, sounds
end

-- The cartridge ships no symbol table, so the table is found rather than
-- named: runs of at least 355 consecutive cartridge pointers are the
-- candidates, and the one whose 355 scripts ALL walk clean AND play sounds is
-- the answer.  Returns the address, or nil plus the three numbers the warning
-- needs (how many runs qualified, how many were looked at, and the most
-- sounds any of them played).
function RomExtractorGen3:moveAnimTable()
  local rom = self.rom
  local runs, start, len = {}, nil, 0
  local p = 0
  while p <= rom.size - 4 do
    if rom:pointer(p) then
      if not start then start, len = p, 0 end
      len = len + 1
    else
      if start and len >= GEN3_ANIM.ROWS then runs[#runs + 1] = start end
      start, len = nil, 0
    end
    p = p + 4
  end
  if start and len >= GEN3_ANIM.ROWS then runs[#runs + 1] = start end

  local picked, best = {}, 0
  for _, at in ipairs(runs) do
    local clean, sounds = self:animTableScore(at)
    if sounds > best then best = sounds end
    if clean == GEN3_ANIM.ROWS and sounds >= GEN3_ANIM.MIN_SOUNDS then
      picked[#picked + 1] = at
    end
  end
  if #picked ~= 1 then return nil, #picked, #runs, best end
  return picked[1], 1, #runs, best
end

-- WHERE THE PARTICLE ART IS.  Two tables, neither named, both found by the
-- same property and nothing else: a long run of eight-byte records whose
-- first word is a cartridge pointer and whose tag halfword counts up from
-- ANIM_TAG_BONE.  They differ only in where the tag sits -- the sheets carry
-- a decompressed byte count before theirs, the palettes do not -- so one
-- routine finds both and the offset says which.
--
-- ONE TAG IS WRITTEN TWICE in the palette table, and that is the cartridge's
-- own duplicate rather than a misread, so a step of zero is allowed as well
-- as a step of one.  Everything else has to be consecutive, which is what
-- makes a run of a hundred pointers into text fail on its second entry.
function RomExtractorGen3:battleAnimTagTable(tagOffset)
  local rom = self.rom
  local best, bestN = nil, 0
  local at = 0
  while at <= rom.size - 8 do
    if rom:pointer(at) and rom:u16(at + tagOffset) == GEN3_ANIM.TAG_FIRST then
      local n = 0
      while rom:pointer(at + n * 8) do
        local tag = rom:u16(at + n * 8 + tagOffset)
        local want = GEN3_ANIM.TAG_FIRST + n
        if tag ~= want and tag ~= want - 1 then break end
        n = n + 1
      end
      if n > bestN then best, bestN = at, n end
      at = at + math.max(n, 1) * 8
    else
      at = at + 4
    end
  end
  if bestN < GEN3_ANIM.TAG_MIN_RUN then return nil, bestN end
  return best, bestN
end

-- HOW BIG ONE FRAME OF A SHEET IS, when no move spawns it itself.
--
-- A particle spawned by a task has no `createsprite` to name its template, so
-- the frame size has to come from somewhere else -- and it is in the
-- cartridge: every sprite template begins `u16 tileTag, u16 paletteTag`, and
-- for these particles the two are THE SAME NUMBER.  A halfword pair that
-- reads (tag, tag), four-aligned, followed by a pointer where the OAM goes
-- and a THUMB code address where the callback goes, is a template for that
-- tag; its OAM's shape and size bits are the answer.
--
-- Where several templates name one tag at different sizes -- twelve do, for
-- the sheets that serve more than one move -- only the sizes whose frames
-- divide the sheet evenly are candidates, and the largest of those wins: a
-- sheet cut into frames that do not fill it has been cut wrong.
-- HOW A PARTICLE'S OWN ART IS TIMED, which is the difference between a
-- picture that animates the way the cartridge does and one that riffles its
-- frames at a rate nobody chose.
--
-- Reported from play: "some arent animating properly as they would on the
-- rom".  Every frame of every particle used to be held for the same six
-- frames and the sheet looped forever, because the player had nothing else
-- to go on.  It is in the cartridge: `struct SpriteTemplate` carries an
-- `anims` pointer at +8, which points at a table of pointers, whose first
-- entry is the sprite's animation -- a run of one-word commands, each the
-- image index in its low halfword and the number of frames to hold it in the
-- next six bits, ending in ANIMCMD_END, ANIMCMD_JUMP or ANIMCMD_LOOP.
--
-- END means the picture is finished and the sprite goes; the other two mean
-- it repeats.  That is both the frame timing AND how long the particle is
-- meant to be on screen, and neither had been read.
--
-- THE IMAGE NUMBER IS A TILE, NOT A FRAME.  A particle is drawn out of a
-- sprite SHEET, so ANIMCMD_FRAME's imageValue counts 8x8 tiles into the
-- loaded art, not pictures: EMBER's second step is 16, which on a 32x32
-- particle -- sixteen tiles to the frame -- is frame one.  Read as a frame
-- number it is off the end of a five-frame sheet, which is how a timing that
-- is right in the cartridge turns into a blank particle here.  A step that
-- does not land on a frame boundary means this is not a sheet-backed sprite
-- and the whole reading is dropped rather than rounded.
function RomExtractorGen3:spriteAnimTimeline(template, width, height)
  local rom = self.rom
  local perFrame = math.floor((width or 0) / 8) * math.floor((height or 0) / 8)
  if perFrame < 1 then return nil end
  local at = rom:pointer(template + GEN3_ANIM.TEMPLATE_ANIMS)
  if not at then return nil end
  local first = rom:pointer(at)
  if not first then return nil end
  local held, loops, total = {}, false, 0
  for i = 0, GEN3_ANIM.ANIM_MAX - 1 do
    local o = first + i * 4
    if o < 0 or o + 3 >= rom.size then return nil end
    local word = rom:u32(o)
    if not word then return nil end
    local low = word % 65536
    if low >= GEN3_ANIM.ANIM_END then
      loops = (low ~= GEN3_ANIM.ANIM_STOP)
      break
    end
    if low % perFrame ~= 0 then return nil end
    local duration = math.floor(word / 65536) % 64
    if duration < 1 then duration = 1 end
    held[#held + 1] = { math.floor(low / perFrame), duration }
    total = total + duration
  end
  if #held == 0 or total < 1 then return nil end
  return held, loops, total
end

function RomExtractorGen3:battleAnimFrameSize(tag, sheetBytes)
  local rom = self.rom
  local needle = string.char(tag % 256, math.floor(tag / 256) % 256,
                             tag % 256, math.floor(tag / 256) % 256)
  local best, bestArea = nil, 0
  local bestHeld, bestLoops = nil, nil
  local from = 1
  while true do
    local i = rom.data:find(needle, from, true)
    if not i then break end
    from = i + 1
    local at = i - 1
    if at % 4 == 0 then
      local oam = rom:pointer(at + GEN3_ANIM.TEMPLATE_OAM)
      local callback = rom:u32(at + GEN3_ANIM.TEMPLATE_CALLBACK)
      -- a Thumb function address is odd, and inside the cartridge
      if oam and callback % 2 == 1
         and callback >= RomGba.BASE and callback - RomGba.BASE < rom.size then
        local shape = math.floor(rom:u16(oam) / 16384) % 4
        local size = math.floor(rom:u16(oam + 2) / 16384) % 4
        local dim = GEN3_ANIM.OBJ_DIM[shape] and GEN3_ANIM.OBJ_DIM[shape][size]
        if dim then
          local frameBytes = dim[1] * dim[2] / 2
          if frameBytes > 0 and sheetBytes % frameBytes == 0 then
            local area = dim[1] * dim[2]
            if area > bestArea then
              best, bestArea = dim, area
              bestHeld, bestLoops = self:spriteAnimTimeline(at, dim[1], dim[2])
            end
          end
        end
      end
    end
  end
  return best, bestHeld, bestLoops
end

function RomExtractorGen3:extractMoveAnimations()
  self:beginStage("Gen3 move animations")
  local moves = self._moves
  local order = self._constants and self._constants.moveOrder
  if not (moves and order) then
    Logger.warn("gen3 move animations: the move table has to be read first")
    return
  end
  local named = 0
  for _ in pairs(order) do named = named + 1 end
  if named < 100 then
    Logger.warn("gen3 move animations: only %d moves are named", named)
    return
  end

  local rom = self.rom

  local tableAt, picked, runs, best = self:moveAnimTable()
  if not tableAt then
    Logger.warn("gen3 move animations: %d of %d pointer runs walk every "
                  .. "script cleanly and play sounds (best run played %d), "
                  .. "so no move gets a sound", picked, runs, best)
    return
  end

  -- ---- the particle sheets those scripts draw from -----------------------
  local picAt, picCount = self:battleAnimTagTable(GEN3_ANIM_PIC_TAG)
  local palAt, palCount = self:battleAnimTagTable(GEN3_ANIM_PAL_TAG)
  if picAt and palAt and picCount ~= palCount then
    Logger.warn("gen3 move animations: %d particle sheets against %d "
                  .. "palettes, so the two tables are not the same table's "
                  .. "halves and no picture is written", picCount, palCount)
    picAt, palAt = nil, nil
  end

  -- ---- stamp the sound and the particles on each move --------------------
  -- A derived number has to name a song this cartridge actually has, or the
  -- table was misread: extractSongs has already written every song header, so
  -- that is a fact to check against rather than an assumption.
  local songs = self._songs
  local stamped, unknown, animated, spawned = 0, 0, 0, 0
  local orbited = 0
  -- move id -> the C function addresses its script hands the animation to
  local animTasks = {}
  self._animTasks = animTasks
  -- ...and the set of songs a MOVE plays, which the audio image needs: see
  -- the note beside it about SE_M_GUST.
  local moveSongs = {}
  -- ...and the sheets they draw from, each with the frame size the template
  -- that spawns it gives.  A sheet used at two sizes keeps the one whose
  -- frames divide it evenly.
  local used = {}
  -- what the second pass needs about each move, gathered while the first runs
  local leftovers = {}
  for i = 1, named do
    local id = order[i]
    local def = id and moves[id]
    local entry = rom:pointer(tableAt + i * 4)
    if def and entry then
      local sound, _, events, duration, loaded, backgrounds, tasks, helpers =
        self:animScriptRead(entry)
      local record
      if sound then
        local key = ("SONG_%03X"):format(sound)
        local song = songs and songs[key]
        if songs and not (type(song) == "table" and song.tracks) then
          unknown = unknown + 1
        else
          record = { sound = key }
          moveSongs[key] = true
          stamped = stamped + 1
        end
      end
      if picAt and events and #events > 0 then
        local list = {}
        for _, one in ipairs(events) do
          local slot = ("%d"):format(one.tag)
          local sheetBytes = rom:u16(picAt + (one.tag - GEN3_ANIM.TAG_FIRST) * 8
                                       + GEN3_ANIM_PIC_SIZE)
          local frameBytes = one.width * one.height / 2
          if one.tag - GEN3_ANIM.TAG_FIRST < picCount and sheetBytes > 0
             and frameBytes > 0 and sheetBytes % frameBytes == 0 then
            local before = used[slot]
            if not before then
              used[slot] = { tag = one.tag, width = one.width,
                             height = one.height,
                             frames = math.floor(sheetBytes / frameBytes),
                             held = one.held, loops = one.loops }
            elseif not before.held and one.held then
              -- a sheet several moves share takes the first timing any of
              -- their templates carries
              before.held, before.loops = one.held, one.loops
            end
            -- WHICH POKEMON A PARTICLE IS DRAWN OVER, and the bit that
            -- does not say.
            --
            -- Reported from play: "when an enemy pokemon attacks me the
            -- attack animation shows on itself rather than me".  Both halves
            -- of that were this line.  It read bit 7 of createsprite's
            -- battler byte -- ANIMSPRITE_IS_TARGET -- as "this particle
            -- belongs over the defender", which sounds like what a bit of
            -- that name would mean and is not what the cartridge does with
            -- it.  Cmd_createsprite reads the bit ONLY to choose whose
            -- subpriority the sprite borrows, and then, in both arms:
            --
            --     CreateSpriteAndAnimate(template,
            --       GetBattlerSpriteCoord(gBattleAnimTarget, X_2),
            --       GetBattlerSpriteCoord(gBattleAnimTarget, Y_PIC_OFFSET),
            --       subpriority);
            --
            -- Every particle in the game spawns on the TARGET.  The bit is
            -- draw order.  So 954 of the 1657 particles Hoenn creates -- ICE
            -- BEAM's crystals, TACKLE's impact, SCRATCH's claws, 165 whole
            -- moves' worth -- were being drawn on whoever attacked, which on
            -- the enemy's turn is the enemy hitting itself.
            --
            -- A particle that ends up somewhere else gets there in its own
            -- callback (InitSpritePosToAnimAttacker and friends), and that
            -- is the part a retail dump cannot name -- so the spawn point is
            -- the answer, and it is the cartridge's own.  The move's target
            -- field is what says which battler that is: a MOVE_TARGET_USER
            -- animation has gBattleAnimTarget pointing at the user, which is
            -- how SWORDS DANCE and REST play on the mon that used them.
            list[#list + 1] = { at = one.at, sheet = slot,
                                x = one.x, y = one.y,
                                from = one.from, motion = one.motion,
                                travel = one.travel, orbit = one.orbit,
                                target = def.target ~= GEN3_ANIM.TARGET_USER
                                         or nil }
          end
        end
        if #list > 0 then
          record = record or {}
          record.events = list
          record.duration = duration
          -- the notes' shared arithmetic goes on the record, once, rather
          -- than on each of the sixteen events that read it
          for _, e in ipairs(list) do
            if e.motion == "orbit" then
              local shape = self:animOrbit()
              if shape then
                record.orbit = shape
                orbited = orbited + 1
                record.duration = math.max(record.duration or 0,
                                           shape.life + 1)
              end
              break
            end
          end
          animated = animated + 1
          spawned = spawned + #list
        end
      end
      if record then def.anim = record end
      -- keep what the second pass needs: a move with no particles of its own
      -- still knows which sheets it loaded and whether it swapped the
      -- background, and both decide what it gets instead
      leftovers[i] = { def = def, record = record, loaded = loaded,
                       backgrounds = backgrounds or 0, tasks = tasks or {},
                       helpers = helpers or {},
                       -- the script's OWN length, which is the one thing a
                       -- task-drawn animation still says about itself
                       duration = duration or 0,
                       hasEvents = record and record.events ~= nil }
      animTasks[id] = tasks
    end
  end

  -- ---- THE MON THAT FLINCHES ---------------------------------------------
  --
  -- Reported from play: "many move fx animations dont seem to be working
  -- correctly".  A move animation is not only particles.  The other half is
  -- `createvisualtask` -- the script handing the animation to a C function --
  -- and a retail dump names none of those functions, so this port drew none
  -- of them.  Which means no Pokemon in Hoenn ever flinched when it was hit.
  --
  -- A NAME IS NOT NEEDED TO KNOW A FUNCTION IS THE SAME FUNCTION.  Two moves
  -- whose scripts call the same address are calling the same code, and that
  -- is a fact about the cartridge rather than a reading of it.  Group all 700
  -- task calls in the game by address and one shape stands out and holds for
  -- every call a function makes:
  --
  --     five arguments; the first a battler selector; the next two a pixel
  --     offset inside a battler's own box; then a count and a frame delay.
  --
    -- Six functions satisfy that for every one of their calls, over 256 calls,
  -- and no other function in the game does -- the palette
  -- blends fail it (their last argument is a 15-bit colour, 32767 for white),
  -- the screen shakes fail it (three arguments), the translations fail it (a
  -- sub-pixel offset in the hundreds).  It is one argument shape, checked
  -- against every use, and the suite checks it again.
  --
  -- HOW IT MOVES.  AnimTask_ShakeMon's step toggles the sprite between its
  -- own place and the offset every `delay + 1` frames, and one shake is a
  -- full out-and-back -- so the whole thing is count * 2 * (delay + 1) frames
  -- and it ends where it started.  That is the arithmetic below, and it is
  -- the reason a hit reads as a hit: EGG BOMB shakes the target four pixels,
  -- sixteen times, one frame apart.
  local shakeFns, shakeCalls, shakeMoves = {}, 0, 0
  do
    local function shapeOk(t)
      if type(t) ~= "table" or #t.args ~= 5 then return false end
      local who = t.args[1]
      if not who or who < 0 or who > GEN3_ANIM.SHAKE_MAX_BATTLER then
        return false
      end
      for i = 2, 3 do
        local v = t.args[i] or 0
        if v > GEN3_ANIM.MAX_OFFSET or v < -GEN3_ANIM.MAX_OFFSET then
          return false
        end
      end
      local count, delay = t.args[4] or 0, t.args[5] or -1
      if count < 1 or count > GEN3_ANIM.SHAKE_MAX_COUNT then return false end
      if delay < 0 or delay > GEN3_ANIM.SHAKE_MAX_DELAY then return false end
      return true
    end
    for _, list in pairs(animTasks) do
      for _, t in ipairs(list) do
        local fn = t.fn
        if shakeFns[fn] ~= false then
          shakeFns[fn] = shapeOk(t) and (shakeFns[fn] ~= false) or false
        end
      end
    end
    for _, row in pairs(leftovers) do
      local list = {}
      for _, t in ipairs(row.tasks or {}) do
        if shakeFns[t.fn] then
          -- ANIM_ATTACKER is 0 and ANIM_TARGET is 1; the partner selectors
          -- above them are the same two sides in a double battle, which this
          -- port draws as one apiece
          list[#list + 1] = { at = t.at or 0,
                              target = (t.args[1] % 2 == 1) or nil,
                              x = t.args[2], y = t.args[3],
                              count = t.args[4], delay = t.args[5] }
          shakeCalls = shakeCalls + 1
        end
      end
      if #list > 0 then
        row.record = row.record or {}
        row.record.shakes = list
        row.def.anim = row.record
        row.hasShakes = true
        shakeMoves = shakeMoves + 1
      end
    end
  end

  -- ---- AND THE MON THAT GLOWS --------------------------------------------
  --
  -- The same argument -- a function is known by what holds for every call it
  -- makes -- reaches one more family, and it is the other thing a Gen 3
  -- battle does that this port did not: RECOVER's green pulse, PSYCHIC's,
  -- BIDE's red flush.  Exactly ONE function in the game satisfies all of:
  --
  --     six arguments on every call; the first a palette selector inside
  --     five bits; the last a 15-bit BGR colour, and a bright one somewhere;
  --     the four in between small enough to be a delay, a count and two
  --     blend coefficients.
  --
  -- Its selector reads as UnpackSelectedBattleAnimPalettes' five bits and
  -- nothing else does: bit 0 the background, bit 1 the attacker, bit 2 the
  -- target, bits 3 and 4 their partners -- and across 34 calls the values
  -- are 1, 2, 3, 4, 7, 10, 20 and 31, which is that field being used and not
  -- a raw palette mask.  (The other blend-shaped function in the game passes
  -- 1920 and 1921, which those five bits cannot mean, so it is left alone.)
  --
  -- WHAT IS READ AND WHAT IS NOT.  The colour, the two coefficients, the
  -- number of pulses and the frame delay are all the cartridge's.  How the
  -- coefficient RAMPS between them -- one step per delay, out and back -- is
  -- the shape of the task's own loop rather than a number in the script, and
  -- it is the one thing here that is a reading of the family rather than of
  -- the call.
  local blendFns, blendCalls, blendMoves = {}, 0, 0
  do
    -- TWO SHAPES, and they are two functions.
    --
    -- The six-argument one PULSES: a selector, a delay, a number of blends,
    -- two coefficients and a colour.  The five-argument one ramps ONE WAY and
    -- stays there -- a selector, a delay, two coefficients and a colour -- and
    -- it is how the white flash on an impact is done.
    --
    -- The selector is the only field the rule does not constrain, and
    -- deliberately.  The five-argument function passes 1920 and 1921 in six of
    -- its 58 calls, which cannot be a five-bit field; read as one anyway they
    -- name NO battler, so those calls affect nothing this port draws.  A rule
    -- that threw out the whole function over them would cost the other 52.
    local function blendOk(t)
      if type(t) ~= "table" then return false end
      local n = #t.args
      if n ~= 5 and n ~= 6 then return false end
      if n == 6 then
        local sel = t.args[1]
        if not sel or sel < 0 or sel > GEN3_ANIM.BLEND_MAX_SELECTOR then
          return false
        end
      end
      for i = 2, n - 1 do
        local v = t.args[i] or 999
        if v > GEN3_ANIM.BLEND_MAX_STEP or v < -GEN3_ANIM.BLEND_MAX_STEP then
          return false
        end
      end
      local colour = t.args[n]
      return colour ~= nil and colour >= 0 and colour <= GEN3_ANIM.COLOUR_MAX
    end
    local bright = {}
    for _, list in pairs(animTasks) do
      for _, t in ipairs(list) do
        local fn = t.fn
        if blendFns[fn] ~= false then
          blendFns[fn] = blendOk(t) and (blendFns[fn] ~= false) or false
        end
        if (t.args[#t.args] or 0) > 255 then bright[fn] = true end
      end
    end
    for fn, ok in pairs(blendFns) do
      if ok and not bright[fn] then blendFns[fn] = false end
    end
    -- a function has to keep ONE shape, or the two readings are being mixed
    local argc = {}
    for _, list in pairs(animTasks) do
      for _, t in ipairs(list) do
        if blendFns[t.fn] then
          if argc[t.fn] == nil then argc[t.fn] = #t.args
          elseif argc[t.fn] ~= #t.args then blendFns[t.fn] = false end
        end
      end
    end
    -- ...AND THE FORTY-THREE THAT ASK FOR IT WITH AN INVISIBLE SPRITE.
    -- Same five arguments, same order, same meanings -- a different door.
    local fadeSprite = self:monFade()
    if fadeSprite then blendFns[fadeSprite.callback] = true end
    for _, row in pairs(leftovers) do
      local list = {}
      local calls = row.tasks or {}
      if fadeSprite then
        local merged = nil
        for _, h in ipairs(row.helpers or {}) do
          if h.cb == fadeSprite.callback
             and #h.args == RomExtractorGen3.MON_FADE.ARGS then
            if not merged then
              merged = {}
              for _, t in ipairs(calls) do merged[#merged + 1] = t end
            end
            merged[#merged + 1] = { fn = fadeSprite.callback, args = h.args,
                                    at = h.at or 0, sprite = true }
          end
        end
        calls = merged or calls
      end
      for _, t in ipairs(calls) do
        if blendFns[t.fn] then
          local oneWay = #t.args == 5
          local sel = t.args[1]
          local function bit(n) return math.floor(sel / 2 ^ n) % 2 == 1 end
          -- bit 1 and bit 3 are the attacker's side, bit 2 and bit 4 the
          -- target's; a call naming both gets one record each
          local sides = {}
          if bit(1) or bit(3) then sides[#sides + 1] = { target = false } end
          if bit(2) or bit(4) then sides[#sides + 1] = { target = true } end
          -- ...AND FOUR MORE BITS, which is what HAZE was missing.
          --
          -- The five-argument function's selector is not one field, it is
          -- two.  Bits 0..6 go to the unpacker the six-argument one uses;
          -- bits 7..10 go somewhere else entirely (08:$0A76C4), and there
          -- each bit is a battle POSITION rather than a role:
          --
          --     bit 7 -> GetBattlerAtPosition(0)   bit 8 -> position 2
          --     bit 9 -> GetBattlerAtPosition(1)   bit 10 -> position 3
          --
          -- ...read straight off that function, which asks for exactly those
          -- four positions in that order.  Even positions are one side and
          -- odd the other -- the helper pairs them that way itself -- and the
          -- even one is the player's: the surf task's own arms take side 1
          -- for the Pokemon whose wave comes DOWN the screen, which is the
          -- one on the far side.
          --
          -- This port draws one Pokemon a side, so a position and its
          -- partner are the same Pokemon here.  HAZE passes 1920: all four
          -- positions, no role bits at all.  Read as the five-bit field it
          -- named nobody, and HAZE faded nothing.
          if bit(7) or bit(8) then sides[#sides + 1] = { side = "player" } end
          if bit(9) or bit(10) then sides[#sides + 1] = { side = "enemy" } end
          for _, who in ipairs(sides) do
            list[#list + 1] = { at = t.at or 0, target = who.target or nil,
                                side = who.side,
                                oneWay = oneWay or nil,
                                step = math.max(1, (t.args[2] or 0) + 1),
                                cycles = oneWay and 1
                                         or math.max(1, t.args[3] or 1),
                                from = (oneWay and t.args[3] or t.args[4]) or 0,
                                to = (oneWay and t.args[4] or t.args[5]) or 0,
                                colour = t.args[#t.args] }
            blendCalls = blendCalls + 1
          end
        end
      end
      -- A CALL WHOSE TWO COEFFICIENTS ARE THE SAME IS NOT A PULSE: it sets
      -- the blend and stops, and on the cartridge the palette STAYS there
      -- until something else moves it.  SPARK is the shape -- set 5, set 0,
      -- set 7, set 0, then a real pulse -- so a held level runs until the
      -- next call on its own side, or to the end of the script the move's
      -- own delays measure.  Reverting it after two frames would flicker.
      for _, one in ipairs(list) do
        if one.oneWay or one.from == one.to then
          local nextAt = nil
          for _, other in ipairs(list) do
            if other ~= one and (other.target or false) == (one.target or false)
               and other.side == one.side
               and other.at > one.at
               and (nextAt == nil or other.at < nextAt) then
              nextAt = other.at
            end
          end
          one.hold = math.max(1, (nextAt or (row.record and row.record.duration)
                                    or (one.at + 1)) - one.at)
        end
      end
      if #list > 0 then
        row.record = row.record or {}
        row.record.blends = list
        row.def.anim = row.record
        row.hasShakes = true       -- a real reaction, so no coarse fallback
        blendMoves = blendMoves + 1
      end
    end
  end

  -- ---- ...AND THE GROUND THAT HEAVES -------------------------------------
  local heaveMoves = 0
  do
    local shape = self:screenHeave()
    local H = RomExtractorGen3.SCREEN_HEAVE
    if shape then
      for _, row in pairs(leftovers) do
        local best = nil
        for _, t in ipairs(row.tasks or {}) do
          local fn = t.fn and (t.fn - (t.fn % 2)) or -1
          if (fn == shape.task or fn == shape.task + 0x08000000)
             and #t.args == 3 then
            local mode = t.args[1]
            if mode == shape.ground or mode == shape.mons then
              local amplitude = (t.args[2] or 0) + shape.bias
              local swings = t.args[3] or 0
              if amplitude > 0 and amplitude <= H.MAX_AMPLITUDE
                 and swings > 0 and swings <= H.MAX_SWINGS then
                -- the two calls are one heave here; take the larger
                if not best or amplitude > best.amplitude then
                  best = { at = t.at or 0, amplitude = amplitude,
                           every = shape.every, swings = swings }
                end
              end
            end
          end
        end
        if best then
          row.record = row.record or {}
          row.record.heave = best
          row.record.duration = math.max(row.record.duration or 0,
                                         best.swings * best.every)
          row.def.anim = row.record
          -- a real reaction, so the coarse one below leaves it alone
          row.hasShakes = true
          heaveMoves = heaveMoves + 1
        end
      end
      if heaveMoves > 0 then
        Logger.info("Gen3 move animations: %d move(s) heave the whole field "
                      .. "(%s)", heaveMoves, shape.source)
      end
    end
  end

  -- ---- ...AND THE POKEMON THAT SQUASHES ----------------------------------
  do
    local marked, shown = 0, nil
    for _, row in pairs(leftovers) do
      for _, t in ipairs(row.tasks or {}) do
        local shape = t.fn and self:affineTable(t.fn)
        if shape then
          -- HOW MANY TIMES.  SPLASH's task keeps the second script argument
          -- as a countdown and plays the table that many times; the other two
          -- take no arguments at all and play it once.  So the count is the
          -- argument where there is one, and one where there is not.
          local repeats = 1
          local second = t.args and t.args[2]
          if second and second >= 1 and second <= 8 then repeats = second end
          row.record = row.record or {}
          row.record.affine = { steps = shape.steps, base = shape.base,
                                repeats = repeats, closes = shape.closes,
                                life = shape.life * repeats,
                                source = ("ROM:the affine table at %07X, "
                                          .. "through the preparer at %07X")
                                         :format(shape.at,
                                                 RomExtractorGen3.MON_AFFINE
                                                   .PREPARE) }
          if row.record.shake or row.record.flash then coarse = coarse - 1 end
          row.record.shake, row.record.flash = nil, nil
          row.record.duration = math.max(row.record.duration or 0,
                                         shape.life * repeats)
          row.def.anim = row.record
          row.hasShakes = true
          marked = marked + 1
          shown = shown or row.record.affine
          break
        end
      end
    end
    if marked > 0 then
      Logger.info("Gen3 move animations: %d move(s) squash and stretch the "
                    .. "Pokemon off an affine table the cartridge keeps as "
                    .. "data (%s)", marked, shown.source)
    end
  end

  -- ---- ...AND THE POKEMON THAT TIPS --------------------------------------
  do
    local shape = self:monRotate()
    local marked = 0
    if shape then
      for _, row in pairs(leftovers) do
        for _, t in ipairs(row.tasks or {}) do
          local fn = t.fn and (t.fn - (t.fn % 2)) or -1
          if fn == shape.task or fn == shape.task + 0x08000000 then
            row.record = row.record or {}
            row.record.rotate = shape
            if row.record.shake or row.record.flash then coarse = coarse - 1 end
            row.record.shake, row.record.flash = nil, nil
            row.record.duration = math.max(row.record.duration or 0, shape.life)
            row.def.anim = row.record
            row.hasShakes = true
            marked = marked + 1
            break
          end
        end
      end
    end
    if marked > 0 then
      Logger.info("Gen3 move animations: %d move(s) tip the Pokemon %d "
                    .. "hundredths of a turn and lift it %d pixels over %d "
                    .. "frames (%s)", marked,
                  math.floor(shape.limit * 100 / shape.turn),
                  shape.frames * shape.rise, shape.life, shape.source)
    end
  end

  -- ---- ...AND THE RUN-UP -------------------------------------------------
  do
    local shape = self:monRunup()
    local marked, calls = 0, 0
    if shape then
      for _, row in pairs(leftovers) do
        local list = nil
        for _, h in ipairs(row.helpers or {}) do
          if h.cb == shape.callback then
            local built = self:runupTrack(h.args, shape)
            if built then
              built.at = h.at or 0
              list = list or {}
              list[#list + 1] = built
              calls = calls + 1
            end
          end
        end
        if list then
          row.record = row.record or {}
          local existing = row.record.shakes or {}
          for _, entry in ipairs(list) do existing[#existing + 1] = entry end
          row.record.shakes = existing
          if row.record.shake or row.record.flash then coarse = coarse - 1 end
          row.record.shake, row.record.flash = nil, nil
          local longest = 0
          for _, entry in ipairs(list) do
            longest = math.max(longest, (entry.at or 0) + entry.life)
          end
          row.record.duration = math.max(row.record.duration or 0, longest)
          row.def.anim = row.record
          row.hasShakes = true
          marked = marked + 1
        end
      end
    end
    if marked > 0 then
      Logger.info("Gen3 move animations: %d move(s) run at what they are "
                    .. "hitting and back over %d call(s) (%s)", marked, calls,
                  shape.source)
    end
  end

  -- ---- ...AND THE POKEMON THAT CHANGES COLOUR ----------------------------
  do
    local shape = self:monCycle()
    local marked, calls = 0, 0
    if shape then
      for _, row in pairs(leftovers) do
        local list = nil
        for _, t in ipairs(row.tasks or {}) do
          local fn = t.fn and (t.fn - (t.fn % 2)) or -1
          if fn == shape.task or fn == shape.task + 0x08000000 then
            local built = self:cycleBlend(t.args, shape)
            if built then
              built.at = t.at or 0
              list = list or {}
              list[#list + 1] = built
              calls = calls + 1
            end
          end
        end
        if list then
          row.record = row.record or {}
          local existing = row.record.blends or {}
          for _, entry in ipairs(list) do existing[#existing + 1] = entry end
          row.record.blends = existing
          if row.record.shake or row.record.flash then coarse = coarse - 1 end
          row.record.shake, row.record.flash = nil, nil
          local longest = 0
          for _, entry in ipairs(list) do
            longest = math.max(longest,
                               (entry.at or 0)
                               + entry.cycles * 2 * entry.to * entry.step)
          end
          row.record.duration = math.max(row.record.duration or 0, longest)
          row.def.anim = row.record
          row.hasShakes = true
          marked = marked + 1
        end
      end
    end
    if marked > 0 then
      Logger.info("Gen3 move animations: %d move(s) flash one Pokemon's own "
                    .. "palette over %d call(s) (%s)", marked, calls,
                  shape.source)
    end
  end

  -- ---- ...AND THE POKEMON THAT LUNGES ------------------------------------
  do
    local shape = self:monLunge()
    local sway = self:monSway()          -- for the cartridge's own sine table
    local marked = 0
    if shape and sway then
      for _, row in pairs(leftovers) do
        local list = nil
        for _, t in ipairs(row.tasks or {}) do
          local fn = t.fn and (t.fn - (t.fn % 2)) or -1
          if fn == shape.task or fn == shape.task + 0x08000000 then
            local built = self:lungeTrack(t.args, shape, sway.sine)
            if built then
              built.at = t.at or 0
              list = list or {}
              list[#list + 1] = built
            end
          end
        end
        if list then
          row.record = row.record or {}
          local existing = row.record.shakes or {}
          for _, entry in ipairs(list) do existing[#existing + 1] = entry end
          row.record.shakes = existing
          if row.record.shake or row.record.flash then coarse = coarse - 1 end
          row.record.shake, row.record.flash = nil, nil
          local longest = 0
          for _, entry in ipairs(list) do
            longest = math.max(longest, (entry.at or 0) + entry.life)
          end
          row.record.duration = math.max(row.record.duration or 0, longest)
          row.def.anim = row.record
          row.hasShakes = true
          marked = marked + 1
        end
      end
    end
    if marked > 0 then
      Logger.info("Gen3 move animations: %d move(s) lunge the Pokemon across "
                    .. "the field on an arc and back (%s)", marked,
                  shape.source)
    end
  end

  -- ---- ...AND THE POKEMON THAT SWAYS -------------------------------------
  do
    local shape = self:monSway()
    local marked, calls = 0, 0
    if shape then
      for _, row in pairs(leftovers) do
        local list = nil
        for _, t in ipairs(row.tasks or {}) do
          local fn = t.fn and (t.fn - (t.fn % 2)) or -1
          if fn == shape.task or fn == shape.task + 0x08000000 then
            local built = self:swayOffsets(t.args, shape)
            if built then
              built.at = t.at or 0
              list = list or {}
              list[#list + 1] = built
              calls = calls + 1
            end
          end
        end
        if list then
          -- written into the same list the square-wave shakes go in, because
          -- it is the same thing to the renderer: an offset on the sprite's
          -- own pos2, one number a frame
          row.record = row.record or {}
          local existing = row.record.shakes or {}
          for _, entry in ipairs(list) do existing[#existing + 1] = entry end
          row.record.shakes = existing
          if row.record.shake or row.record.flash then coarse = coarse - 1 end
          row.record.shake, row.record.flash = nil, nil
          local longest = 0
          for _, entry in ipairs(list) do
            longest = math.max(longest, (entry.at or 0) + entry.life)
          end
          row.record.duration = math.max(row.record.duration or 0, longest)
          row.def.anim = row.record
          row.hasShakes = true
          marked = marked + 1
        end
      end
    end
    if marked > 0 then
      Logger.info("Gen3 move animations: %d move(s) sway the Pokemon on a "
                    .. "sine over %d call(s) (%s)", marked, calls, shape.source)
    end
  end

  -- ---- ...AND THE POKEMON THAT PULSES ------------------------------------
  do
    local shape = self:monPulse()
    local marked = 0
    if shape then
      for _, row in pairs(leftovers) do
        -- a move may call it more than once; identical calls in a row are the
        -- same pulse repeated, and anything else takes the first
        local first, same = nil, 0
        for _, t in ipairs(row.tasks or {}) do
          local fn = t.fn and (t.fn - (t.fn % 2)) or -1
          if fn == shape.task or fn == shape.task + 0x08000000 then
            local built = self:pulseShape(t.args, shape)
            if built then
              if not first then first, same = built, 1
              elseif first.steps[1].dx == built.steps[1].dx
                     and first.steps[1].dy == built.steps[1].dy
                     and first.steps[1].dur == built.steps[1].dur
                     and first.onTarget == built.onTarget then
                same = same + 1
              end
            end
          end
        end
        -- ...AND NEVER OVER A SHAPE THE TABLE PASS ALREADY FOUND.  A move
        -- with an affine table of its own is playing that; this is the
        -- fallback for the fourteen that keep theirs in the script.
        if first and not (row.record and row.record.affine) then
          first.repeats = same
          first.life = first.life * same
          row.record = row.record or {}
          row.record.affine = first
          if row.record.shake or row.record.flash then coarse = coarse - 1 end
          row.record.shake, row.record.flash = nil, nil
          row.record.duration = math.max(row.record.duration or 0, first.life)
          row.def.anim = row.record
          row.hasShakes = true
          marked = marked + 1
        end
      end
    end
    if marked > 0 then
      Logger.info("Gen3 move animations: %d move(s) pulse the Pokemon off "
                    .. "numbers their own script carries (%s)",
                  marked, shape.source)
    end
  end

  -- ---- ...AND THE POKEMON THAT SQUEEZES AND GOES -------------------------
  do
    local shape = self:monSqueeze()
    local marked = 0
    if shape then
      for _, row in pairs(leftovers) do
        for _, t in ipairs(row.tasks or {}) do
          local fn = t.fn and (t.fn - (t.fn % 2)) or -1
          if fn == shape.task or fn == shape.task + 0x08000000 then
            row.record = row.record or {}
            -- written into the SAME field the affine table fills, because it
            -- is the same shape and the engine already plays it
            row.record.affine = shape
            if row.record.shake or row.record.flash then coarse = coarse - 1 end
            row.record.shake, row.record.flash = nil, nil
            row.record.duration = math.max(row.record.duration or 0, shape.life)
            row.def.anim = row.record
            row.hasShakes = true
            marked = marked + 1
            break
          end
        end
      end
    end
    if marked > 0 then
      Logger.info("Gen3 move animations: %d move(s) squeeze the Pokemon to a "
                    .. "%dth of its width over %d frames and go (%s)", marked,
                  math.floor((shape.base + shape.wide * shape.frames)
                             / shape.base), shape.frames, shape.source)
    end
  end

  -- ---- ...AND THE SCREEN THAT GOES WHITE ---------------------------------
  do
    local shape = self:screenWhite()
    local marked = 0
    if shape then
      for _, row in pairs(leftovers) do
        for _, t in ipairs(row.tasks or {}) do
          local fn = t.fn and (t.fn - (t.fn % 2)) or -1
          if fn == shape.task or fn == shape.task + 0x08000000 then
            row.record = row.record or {}
            -- the coarse pass would have SHAKEN this one, because the script
            -- touches no background and does not aim at the user; what it
            -- actually does is the flash the fallback draws for the other
            -- half of that test
            if row.record.shake then coarse = coarse - 1 end
            row.record.shake = nil
            row.record.flash = true
            row.record.whiteout = shape
            row.record.duration = math.max(row.record.duration or 0, shape.life)
            row.def.anim = row.record
            row.hasShakes = true
            marked = marked + 1
            break
          end
        end
      end
    end
    if marked > 0 then
      Logger.info("Gen3 move animations: %d move(s) white the screen out for "
                    .. "%d frames and fade it back over %d (%s)", marked,
                  shape.hold, shape.steps * shape.every, shape.source)
    end
  end

  -- ---- ...AND THE FLOURISH A STAT-UP MOVE MAKES --------------------------
  do
    local shape = self:statFlourish()
    local F = RomExtractorGen3.STAT_FLOURISH
    local marked = 0
    if shape then
      for _, row in pairs(leftovers) do
        for _, t in ipairs(row.tasks or {}) do
          local fn = t.fn and (t.fn - (t.fn % 2)) or -1
          if fn == F.TASK or fn == F.TASK + 0x08000000 then
            row.record = row.record or {}
            row.record.flourish = shape
            if row.record.shake or row.record.flash then coarse = coarse - 1 end
            row.record.shake, row.record.flash = nil, nil
            row.record.duration = math.max(row.record.duration or 0, shape.life)
            row.def.anim = row.record
            row.hasShakes = true
            marked = marked + 1
            break
          end
        end
      end
    end
    if marked > 0 then
      Logger.info("Gen3 move animations: %d move(s) sparkle over the Pokemon "
                    .. "for %d frames instead of flashing the whole screen "
                    .. "(%s)", marked, shape.life, shape.source)
    end
  end

  -- ---- ...AND THE POKEMON THAT SHRINKS -----------------------------------
  do
    local shape = self:monScale()
    local marked = 0
    if shape then
      for _, row in pairs(leftovers) do
        for _, t in ipairs(row.tasks or {}) do
          local fn = t.fn and (t.fn - (t.fn % 2)) or -1
          if fn == shape.task or fn == shape.task + 0x08000000 then
            row.record = row.record or {}
            row.record.scale = shape
            local life = shape.rounds * (shape.shrinkFrames + 2)
                         + shape.holdFrames + shape.growFrames
            row.record.duration = math.max(row.record.duration or 0, life)
            row.def.anim = row.record
            row.hasShakes = true
            marked = marked + 1
            break
          end
        end
      end
    end
    if marked > 0 then
      Logger.info("Gen3 move animations: %d move(s) shrink the Pokemon to a "
                    .. "%dth of itself and back (%s)", marked,
                  math.floor((shape.base + shape.shrinkFrames
                              * shape.shrinkStep) / shape.base), shape.source)
    end
  end

  -- ---- THE MOVES THAT SPAWN NOTHING THEMSELVES ---------------------------
  --
  -- Fifty-seven of Hoenn's moves reach the end of their script without one
  -- `createsprite` in it, and they split cleanly in two.
  --
  -- SOME LOAD ART AND LET A TASK SPAWN IT.  BLIZZARD's gale, MUD-SLAP's
  -- spatter, SHEER COLD's crystals: the `loadspritegfx` at the top of the
  -- script names the sheet, and the C function that puts it on screen is the
  -- part that cannot be read.  The sheet is the move's own picture either
  -- way, so it is drawn once on the battler the move's own target field
  -- names -- MOVE_TARGET_USER on the user, everything else on the defender.
  -- Where no sprite template anywhere names that sheet's frame size, the
  -- largest SQUARE object size that divides the sheet evenly is used, which
  -- is a hardware constraint rather than a guess at the art.
  --
  -- THE REST HAVE NO ART AT ALL.  HARDEN, AGILITY, WITHDRAW, EARTHQUAKE,
  -- SURF: every pixel of those animations is drawn by a task -- a mon that
  -- swells, a screen that heaves, a wave built out of a background layer --
  -- and there is nothing in the script to read but the shape of the event.
  -- They get the coarse reaction the engine has had since Gen 1, and which
  -- of the two is decided by two things the cartridge does say: a move that
  -- REPLACES THE BATTLE BACKGROUND is a screen-wide event and flashes, a
  -- move aimed at ITS OWN USER is a flourish on the user and flashes too,
  -- and everything else shakes.  That is a class, not the cartridge's
  -- animation, and it is named as one here so nobody later mistakes it for
  -- a reading.
  local fromLoaded, coarse = 0, 0
  if picAt then
    for _, row in pairs(leftovers) do
      local def = row.def
      if def and not row.hasEvents then
        local tag = row.loaded and row.loaded[1]
        local sheet
        if tag and tag >= GEN3_ANIM.TAG_FIRST
           and tag - GEN3_ANIM.TAG_FIRST < picCount then
          local slot = ("%d"):format(tag)
          local bytes = rom:u16(picAt + (tag - GEN3_ANIM.TAG_FIRST) * 8
                                  + GEN3_ANIM_PIC_SIZE)
          local known = used[slot]
          if known then
            sheet = known
          elseif bytes > 0 then
            -- the cartridge's own template for this tag, wherever it is
            local dim, held, loops = self:battleAnimFrameSize(tag, bytes)
            if dim then
              sheet = { tag = tag, width = dim[1], height = dim[2],
                        frames = math.max(1,
                                          math.floor(bytes
                                                     / (dim[1] * dim[2] / 2))),
                        held = held, loops = loops }
            else
              -- ...and only if nothing in 16 MiB names it, the largest square
              -- object size that divides the sheet evenly
              for _, square in ipairs(GEN3_ANIM.SQUARES) do
                if bytes % square[2] == 0 then
                  sheet = { tag = tag, width = square[1], height = square[1],
                            frames = math.floor(bytes / square[2]) }
                  break
                end
              end
            end
          end
          if sheet then
            used[slot] = used[slot] or sheet
            record = row.record or {}
            record.events = { { at = 0, sheet = slot, x = 0, y = 0,
                                target = def.target ~= GEN3_ANIM.TARGET_USER
                                         or nil } }
            record.duration = 0
            def.anim = record
            animated = animated + 1
            spawned = spawned + 1
            fromLoaded = fromLoaded + 1
          end
        end
        -- ...and a move whose mon already flinches has a real reaction
        -- already; the coarse one is for the moves with nothing at all
        if not sheet and not row.hasShakes then
          record = row.record or {}
          if row.backgrounds > 0 or def.target == GEN3_ANIM.TARGET_USER then
            record.flash = true
          else
            record.shake = true
          end
          -- ...AND IT LASTS AS LONG AS THE MOVE DOES.
          --
          -- The class is this port's; the LENGTH is not.  Every one of these
          -- scripts still walks its own delays, and that walk is already done
          -- -- so EARTHQUAKE, whose script runs for over a hundred frames,
          -- heaves for as long as it does on the cartridge, and HARDEN's
          -- flourish is over in its own handful.  A single fixed number for
          -- both is the one part of the coarse reaction that did not have to
          -- be invented.
          if (row.duration or 0) > 0 then record.duration = row.duration end
          def.anim = record
          coarse = coarse + 1
        end
      end
    end
  end

  -- ---- ...THE WAVE THAT CROSSES THE FIELD -------------------------------
  --
  -- Same shape as the afterimage below: one task function, read by hand, and
  -- every move whose script calls it gets the layer.  SURF is the move the
  -- report named; whatever else calls the same task gets it for the same
  -- reason.
  do
    local shape = self:surfWave()
    local S = RomExtractorGen3.SURF_WAVE
    local marked = 0
    if shape then
      for _, row in pairs(leftovers) do
        for _, t in ipairs(row.tasks or {}) do
          local fn = t.fn and (t.fn - (t.fn % 2)) or -1
          if fn == S.TASK or fn == S.TASK + 0x08000000 then
            local record = row.record or {}
            record.surf = shape
            -- the coarse pass has already been past and given this move a
            -- screen wobble for having nothing; it has something now, so the
            -- consolation goes
            if record.shake or record.flash then coarse = coarse - 1 end
            record.shake, record.flash = nil, nil
            record.duration = math.max(record.duration or 0, shape.life)
            row.def.anim = record
            row.record = record
            marked = marked + 1
            break
          end
        end
      end
    end
    if marked > 0 then
      Logger.info("Gen3 move animations: %d move(s) sweep a %dx%d wave across "
                    .. "the field over %d frames (%s)", marked, shape.width,
                  shape.height, shape.life, shape.source)
    end
  end

  -- ---- ...AND THE MON THAT SPLITS IN TWO ---------------------------------
  --
  -- One task function, read by hand (animAfterimage), and every move whose
  -- script calls it gets the ghosts.  It is not a family and it is not
  -- claimed to be one: the general decode for `createvisualtask` does not
  -- exist -- 174 distinct functions, most of them one move's own -- so this
  -- is one of them, done properly, for the move the report named.
  do
    local shape = self:animAfterimage()
    local A = RomExtractorGen3.ANIM_AFTERIMAGE
    local marked = 0
    if shape then
      for _, row in pairs(leftovers) do
        for _, t in ipairs(row.tasks or {}) do
          -- the script stores a THUMB pointer, so the low bit is set and the
          -- table may hold it as a flat offset or a full address
          local fn = t.fn and (t.fn - (t.fn % 2)) or -1
          if fn == A.TASK or fn == A.TASK + 0x08000000 then
            local record = row.record or {}
            record.afterimage = shape
            if record.shake or record.flash then coarse = coarse - 1 end
            record.shake, record.flash = nil, nil
            -- the copies live 64 steps of two frames, and the script's own
            -- delays agree with that to within a few frames
            record.duration = math.max(record.duration or 0,
                                       shape.steps * shape.framesPerStep)
            row.def.anim = record
            row.record = record
            marked = marked + 1
            break
          end
        end
      end
    end
  if orbited > 0 then
    local shape = self:animOrbit()
    Logger.info("Gen3 move animations: %d move(s) send %d-frame "
                  .. "notes round the screen (%s)", orbited,
                shape.life + 1, shape.source)
  end

    if marked > 0 then
      Logger.info("Gen3 move animations: %d move(s) split the Pokemon into "
                    .. "%d ghosts over %d frames (%s)", marked, shape.copies,
                  shape.steps * shape.framesPerStep, shape.source)
    end
  end

  if unknown > 0 then
    Logger.warn("gen3 move animations: %d moves name a song the cartridge "
                  .. "does not have, and were left silent", unknown)
  end

  self._moveSongs = moveSongs

  -- ---- and the pictures themselves ---------------------------------------
  local gfx, drawn = {}, 0
  if picAt and palAt then
    for slot, sheet in pairs(used) do
      gfx[slot] = {
        image = ("assets/generated/battle_anim/p%d.png"):format(sheet.tag),
        frameWidth = sheet.width,
        frameHeight = sheet.height,
        frames = sheet.frames,
        -- the template's own animation: { imageIndex, framesHeld } per step,
        -- and whether it repeats.  A particle whose table ends is gone when
        -- it ends -- that is its lifetime as well as its timing.
        held = sheet.held,
        loops = sheet.loops or nil,
        trueColor = true,
      }
    end
    local okArt, artErr = pcall(function()
      for slot, sheet in pairs(used) do
        local row = (sheet.tag - GEN3_ANIM.TAG_FIRST) * 8
        local art = self.rom:lz77(self.rom:pointer(picAt + row))
        local pal = self.rom:lz77(self.rom:pointer(palAt + row))
        if art and pal and #pal >= 32 then
          local colors = RomGba.palette(pal)
          local tw = math.floor(sheet.width / 8)
          local th = math.floor(sheet.height / 8)
          local frameBytes = sheet.width * sheet.height / 2
          local image = ImageWriter.blank(sheet.width,
                                          sheet.height * sheet.frames)
          if not image then return end
          for frame = 0, sheet.frames - 1 do
            -- lz77 hands back a LIST of bytes, not a string
            local bytes = {}
            for k = 1, frameBytes do
              bytes[k] = art[frame * frameBytes + k] or 0
            end
            local px = RomGba.tiles4bpp(bytes, tw, th)
            local top = frame * sheet.height
            for y = 1, sheet.height do
              for xx = 1, sheet.width do
                local index = px[y][xx]
                local c = colors[index + 1]
                if index ~= 0 and c then
                  image:setPixel(xx - 1, top + y - 1, c[1] / 255, c[2] / 255,
                                 c[3] / 255, 1)
                else
                  image:setPixel(xx - 1, top + y - 1, 0, 0, 0, 0)
                end
              end
            end
          end
          self:saveImage(image, ("battle_anim/p%d.png"):format(sheet.tag))
          drawn = drawn + 1
        end
      end
    end)
    if not okArt then
      Logger.warn("gen3 move animations: the particle sheets could not be "
                    .. "composed (%s) -- the move records are still written",
                  tostring(artErr))
    end
  end

  self:write("moves", moves)
  local constants = self._constants or {}
  constants.gen3MoveAnims = {
    table = tableAt,
    rows = GEN3_ANIM.ROWS,
    sounds = stamped,
    animated = animated,
    particles = spawned,
    -- of those, the ones whose art is named by a loadspritegfx rather than
    -- spawned by the script itself
    fromLoaded = fromLoaded,
    -- ...and the ones with no art at all, which get a screen reaction
    coarse = coarse,
    -- shake and flash are createvisualtask function addresses in this
    -- generation, and nothing in the cartridge names them
    fields = { "sound", "events" },
    source = ("ROM:gBattleAnims_Moves %07X, %d scripts walked clean%s")
             :format(tableAt, GEN3_ANIM.ROWS,
                     picAt and (", gBattleAnimPicTable %07X (%d)")
                               :format(picAt, picCount) or ""),
  }
  local sheetCount = 0
  for _ in pairs(gfx) do sheetCount = sheetCount + 1 end
  if sheetCount > 0 then
    gfx.source = ("ROM:gBattleAnimPicTable %07X, gBattleAnimPaletteTable %07X"
                  .. " (%d tags, %d drawn on)"):format(picAt, palAt,
                                                       picCount, sheetCount)
    constants.gen3BattleAnimGfx = gfx
  end
  self._constants = constants
  self:write("constants", constants)
  Logger.info("Gen3 move animations: %d of %d moves play a sound, %d spawn "
                .. "%d particles off %d sheets (%d drawn, %d from a loaded "
                .. "sheet); %d shake the mon over %d calls and %d blend it "
                .. "over %d; %d more shake or flash the screen",
              stamped, named, animated, spawned, sheetCount, drawn,
              fromLoaded, shakeMoves, shakeCalls, blendMoves, blendCalls,
              coarse)
end

-- ---------------------------------------------------------------------------
-- STAGE: the party screen's own menu
--
-- Reported from play: "in the party menu when i click a pokemon theres no
-- summary, switch, item, hm use etc option it goes straight to an hm or the
-- summary when clicked".  The screen had a VOCABULARY -- the run of labels
-- the discovery pass found sitting end to end in the text region -- and that
-- run is only ten words long: SHIFT, SEND OUT, SWITCH, SUMMARY, MOVES, ENTER,
-- NO ENTRY, TAKE, READ, TRADE.  ITEM, GIVE, MAIL and CANCEL are not in it,
-- which is why a field pick could never be offered as a list: four of the
-- words it needs were missing.
--
-- They are all in ONE table.  sPartyMenuActions is { const u8 *text; TaskFunc
-- func; } and its rows are the MENU_ enum in order:
--
--   0 SUMMARY  1 SWITCH  2 CANCEL   3 ITEM   4 GIVE   5 TAKE   6 MAIL
--   7 TAKE     8 READ    9 CANCEL  10 SHIFT 11 SEND OUT 12 ENTER 13 NO ENTRY
--  14 STORE   15 REGISTER 16 TRADE 17 TRADE 18 TOSS
--
-- ...and then MENU_FIELD_MOVES, one row per field move, every one of them
-- pointing at CursorCb_FieldMove.  That shared callback is what says where
-- the fixed rows stop and the moves begin, and the move each row names is
-- read off the pointer: the text is gMoveNames[move], so subtracting the
-- table's base and dividing by the name length gives the move NUMBER rather
-- than a name this side would have to match by spelling.
--
-- The table is found from the one address the manifest already carries -- the
-- SHIFT string -- because row 10 is the only pointer to it in the ROM.
-- ---------------------------------------------------------------------------

RomExtractorGen3.PARTY_ACTIONS = {
  -- the MENU_ enum, in the cartridge's order; two rows share CANCEL and two
  -- share TAKE, which is the check that says the table is not misaligned
  KEYS = { "summary", "switch", "cancel", "item", "give", "takeItem", "mail",
           "takeMail", "read", "cancel2", "shift", "sendOut", "enter",
           "noEntry", "store", "register", "trade1", "trade2", "toss" },
  SHIFT_ROW = 10,        -- MENU_SHIFT, the row the anchor string belongs to
  STRIDE = 8,
  MAX_FIELD_MOVES = 24,
  -- ...AND THE LINES THE SCREEN SAYS, which are the table immediately in
  -- front of the actions: sActionStringTable, forty pointers into the text
  -- region, indexed by the PARTY_MSG enum.  It is found by walking back from
  -- the actions table while the words still read as pointers to text, and
  -- the check that it is aligned is index 20 -- the cartridge leaves that
  -- slot pointing at an EMPTY string, so a table off by one cannot pass.
  MSG_EMPTY_SLOT = 20,
  MSG_MAX = 64,
  MSG_GAP = 64,
  MSG_KEYS = {
    chooseMon = 0, chooseMonOrCancel = 1, chooseMonAndConfirm = 2,
    moveToWhere = 3, teachWhichMon = 4, useOnWhichMon = 5,
    giveToWhichMon = 6, nothingToCut = 7, cantSurfHere = 8,
    alreadySurfing = 9, currentTooFast = 10, enjoyCycling = 11,
    inUseAlready = 12, cantUseHere = 13, noMonForBattle = 14,
    notEnoughHp = 16, doWhatWithMon = 21, restoreWhichMove = 22,
    boostPpWhichMove = 23, doWhatWithItem = 24, doWhatWithMail = 25,
  },
}

function RomExtractorGen3:extractPartyActions()
  self:beginStage("Gen3 party menu actions")
  local A = RomExtractorGen3.PARTY_ACTIONS
  local rom = self.rom
  local anchor = self:symbol("sPartyMenuActions")
  local moveNames = self:symbol("gMoveNames")
  if not anchor then
    Logger.warn("gen3 party actions: no anchor string -- the party screen "
                .. "keeps the ten words it had")
    return
  end

  -- the ONE pointer to it.  More than one and this is not the row it looks
  -- like, so nothing is written rather than something wrong.
  local want = anchor + 0x08000000
  local hit, hits = nil, 0
  for o = 0, rom.size - 4, 4 do
    if rom:u32(o) == want then hit, hits = o, hits + 1 end
  end
  if hits ~= 1 then
    Logger.warn("gen3 party actions: %d pointers to the SHIFT string, not "
                .. "one -- the party screen keeps the ten words it had", hits)
    return
  end
  local base = hit - A.SHIFT_ROW * A.STRIDE
  if base < 0 then return end

  local rows, funcs = {}, {}
  for i = 0, #A.KEYS - 1 + A.MAX_FIELD_MOVES do
    local o = base + i * A.STRIDE
    local text = rom:pointer(o)
    local func = rom:u32(o + 4)
    if not (text and func and func >= 0x08000000 and func < 0x09000000) then
      break
    end
    -- rom:pointer already hands back a FLAT offset
    rows[i] = self:readString(text, 24)
    funcs[i] = { text = text, func = func }
    if rows[i] == nil or rows[i] == "" then break end
  end

  local labels = {}
  for i, key in ipairs(A.KEYS) do
    local word = rows[i - 1]
    if not word then
      Logger.warn("gen3 party actions: row %d (%s) did not read back -- the "
                  .. "party screen keeps the ten words it had", i - 1, key)
      return
    end
    -- the second CANCEL and the second TAKE are the same words as the first;
    -- one key each is what the screen wants
    if key ~= "cancel2" then labels[key] = word end
  end
  if labels.cancel ~= rows[9] or labels.takeItem ~= rows[7] then
    Logger.warn("gen3 party actions: CANCEL/TAKE do not repeat where the "
                .. "enum says they do -- the table is not aligned")
    return
  end

  -- ...and the field moves, which are every row after the fixed ones that
  -- shares CursorCb_FieldMove
  local fieldMoves = {}
  local first = funcs[#A.KEYS]
  if first and moveNames then
    local stride = self:layoutValue("moveNameLength", 13)
    local shared = first.func
    for i = #A.KEYS, #A.KEYS + A.MAX_FIELD_MOVES do
      local row = funcs[i]
      if not (row and row.func == shared) then break end
      local delta = row.text - moveNames
      if delta >= 0 and delta % stride == 0 then
        local index = math.floor(delta / stride)
        fieldMoves[#fieldMoves + 1] = {
          move = (self._moveIds and self._moveIds[index]) or index,
          index = index,
          label = rows[i],
        }
      end
    end
  end

  -- ---- the lines, off the table in front of this one --------------------
  local messages, msgFrom = nil, nil
  do
    local function textAt(o)
      local at = rom:pointer(o)
      if not at then return nil end
      local ok, word = pcall(self.readString, self, at, 64)
      if not (ok and type(word) == "string") then return nil end
      return word
    end
    -- back up to the LAST pointer before the actions table, then keep going
    -- while they are still pointers
    local last = nil
    -- the two tables are not adjacent: a block of packed data sits between
    -- them, so the search reaches past it rather than giving up at the gap
    for step = 1, A.MSG_GAP do
      if textAt(base - step * 4) then last = base - step * 4 break end
    end
    if last then
      local first = last
      while first - 4 >= 0 and textAt(first - 4) do first = first - 4 end
      local count = (last - first) / 4 + 1
      if count > A.MSG_MAX then first = last - (A.MSG_MAX - 1) * 4 end
      local rows = {}
      for i = 0, (last - first) / 4 do rows[i] = textAt(first + i * 4) end
      if rows[A.MSG_EMPTY_SLOT] == "" then
        messages, msgFrom = {}, first
        for key, index in pairs(A.MSG_KEYS) do
          if rows[index] and rows[index] ~= "" then messages[key] = rows[index] end
        end
      else
        Logger.warn("gen3 party actions: slot %d of the message table is %q "
                    .. "and not empty -- the lines are left off",
                    A.MSG_EMPTY_SLOT, tostring(rows[A.MSG_EMPTY_SLOT]))
      end
    end
  end

  local constants = self._constants or {}
  constants.gen3PartyActions = {
    labels = labels,
    fieldMoves = fieldMoves,
    messages = messages,
    source = ("ROM:sPartyMenuActions %07X (%d rows, %d field moves off "
              .. "gMoveNames %07X, sActionStringTable %07X)")
             :format(base, #A.KEYS, #fieldMoves, moveNames or 0, msgFrom or 0),
  }
  self._constants = constants
  self:write("constants", constants)
  local said = 0
  for _ in pairs(messages or {}) do said = said + 1 end
  Logger.info("Gen3 party actions: %d words, %d field moves and %d lines "
              .. "off %07X", #A.KEYS - 1, #fieldMoves, said, base)
end

-- ---------------------------------------------------------------------------
-- STAGE: the two size-record houses
--
-- Sootopolis judges SEEDOTs and Dewford judges LOTADs, and both work the same
-- way: `special ChoosePartyMon`, then a special that measures what you picked
-- against the biggest one this save has ever shown, and a four-way branch on
-- the answer.
--
-- WHAT MAKES A POKEMON BIG is not its level and not its species height alone.
-- GetMonSizeHash (0F97C8) folds the personality and the six IVs into sixteen
-- bits:
--
--     ((atkIV ^ defIV) * hpIV) ^ (personality & 0xFF)          -> high byte
--     (speedIV * (spAtkIV ^ spDefIV)) ^ ((personality >> 8) & 0xFF) -> low
--
-- and GetMonSize (0F989C) turns that into millimetres through a
-- FOURTEEN-ROW piecewise-linear table -- the table this stage rips -- scaled
-- by the species' own dex height.  The table is what makes the distribution
-- bell-shaped: its middle rows step by 150 hash units per unit of size and
-- its ends by one, so the extremes are rare.
--
-- The record itself is a VAR holding the winning HASH, not the size, which is
-- why the house can re-measure the old record against a new species height.
-- Its untouched value is 0x8000 -- dead centre of the table.
--
-- Both (species, var) pairs are read out of the specials' own prologues
-- rather than named here: 122 loads its var as a literal and its species as
-- `mov r0,#149 / lsl r0,r0,#1`, and 124 loads both as literals, so the scan
-- accepts either shape and checks what it finds.
-- ---------------------------------------------------------------------------

RomExtractorGen3.SIZE_RECORD = {
  -- GetSeedotSizeRecordInfo / GetLotadSizeRecordInfo, and the two that
  -- compare against them
  PAIRS = { { info = 122, compare = 123 }, { info = 124, compare = 125 } },
  SCAN = 10,                 -- halfwords of the prologue worth reading
  -- GetMonSize's own literal load of sBigMonSizeTable
  SIZE_FN = 0x0F989C, AT_TABLE = 0x28,
  ROWS = 14, STRIDE = 8,
  -- GetSizeRecordInfo, whose own literals give the name printed against an
  -- untouched record and the compare that says what "untouched" is
  INFO_FN = 0x0F9A14, AT_HOLDER = 0x34,
  DEFAULT = 0x8000,          -- 0F9A3E's `mov r0,#128 / lsl r0,r0,#8`
  MOV_R0 = 0x2000, LSL_R0_1 = 0x0040,
  VAR_LO = 0x4000, VAR_HI = 0x40FF,
}

function RomExtractorGen3:extractSizeRecords()
  self:beginStage("Gen3 size records")
  local R = RomExtractorGen3.SIZE_RECORD
  local rom = self.rom

  local tableAt = self:thumbLiteral(R.SIZE_FN + R.AT_TABLE)
  if not (tableAt and tableAt >= 0x08000000 and tableAt < 0x09000000) then
    Logger.warn("gen3 size records: the table load at %07X does not read "
                .. "back as a literal", R.SIZE_FN + R.AT_TABLE)
    return
  end
  local base = tableAt - 0x08000000
  local rows, last = {}, -1
  for i = 0, R.ROWS - 1 do
    local o = base + i * R.STRIDE
    local row = { size = rom:u16(o), step = rom:u8(o + 2),
                  from = rom:u16(o + 4) }
    -- the shape is the check: the thresholds climb, the steps are never
    -- zero (they are divisors) and the sizes climb with them
    if not (row.step > 0 and row.from > last and row.size > 0) then
      Logger.warn("gen3 size records: row %d of %08X does not read as "
                  .. "{size, step, from}", i, tableAt)
      return
    end
    last = row.from
    rows[i + 1] = row
  end

  -- the name the sign prints when nobody has beaten the record yet, which is
  -- a real name in the cartridge and not an empty string
  local holder
  local holderAt = self:thumbLiteral(R.INFO_FN + R.AT_HOLDER)
  if holderAt and holderAt >= 0x08000000 and holderAt < 0x09000000 then
    holder = self:readString(holderAt - 0x08000000, 12)
    if holder == "" then holder = nil end
  end

  local records = {}
  for _, pair in ipairs(R.PAIRS) do
    local at = self:specialAddress(pair.info)
    local var, index
    if at then
      for i = 0, R.SCAN - 1 do
        local lit = self:thumbLiteral(at + i * 2)
        if lit and lit >= R.VAR_LO and lit <= R.VAR_HI then
          var = var or lit
        elseif lit and lit >= 1 and lit <= 500 then
          index = index or lit
        else
          local hw = rom:u16(at + i * 2)
          local nxt = rom:u16(at + i * 2 + 2)
          -- `mov r0,#n / lsl r0,r0,#1`, which is how the assembler reached
          -- 298 without spending a pool word on it
          if hw and nxt and hw >= R.MOV_R0 and hw < R.MOV_R0 + 256
             and nxt == R.LSL_R0_1 then
            index = index or ((hw - R.MOV_R0) * 2)
          end
        end
      end
    end
    local species = index and self._speciesIds and self._speciesIds[index]
    if var and species then
      records[#records + 1] = { info = pair.info, compare = pair.compare,
                                species = species, index = index, var = var }
    else
      Logger.warn("gen3 size records: special %d does not read as a species "
                  .. "and a var (%s / %s)", pair.info, tostring(index),
                  tostring(var))
    end
  end
  if #records == 0 then return end

  local constants = self._constants or {}
  constants.gen3SizeRecords = {
    rows = rows,
    default = R.DEFAULT,
    defaultHolder = holder,
    records = records,
    source = ("ROM:sBigMonSizeTable %08X (%d rows), pairs off gSpecials "
              .. "%d/%d"):format(tableAt, R.ROWS, R.PAIRS[1].info,
                                 R.PAIRS[2].info),
  }
  self._constants = constants
  self:write("constants", constants)
  local names = {}
  for _, r in ipairs(records) do
    names[#names + 1] = ("%s(var %04X)"):format(r.species, r.var)
  end
  Logger.info("Gen3 size records: %d rows at %08X, judged for %s; the "
              .. "standing record is %s's", R.ROWS, tableAt,
              table.concat(names, " and "), tostring(holder))
end

-- ---------------------------------------------------------------------------
-- STAGE: the Pokemon Jump roster
--
-- The Mossdeep minigame will not take just anything: IsSpeciesInJumpTable
-- (0802AC00) walks a hundred-row table and a Pokemon that is not in it cannot
-- play.  The rows are { u16 species, u8 kind } -- the kind being which of the
-- three jump styles it has -- and the species are INTERNAL indices, so they
-- go through the same numbering every other stage uses.
--
-- The table is not sorted and has no terminator; the hundred is the loop's
-- own bound (`cmp r1,#99 / bls`), which is why the count is stated and then
-- checked rather than scanned for.
-- ---------------------------------------------------------------------------

RomExtractorGen3.POKEMON_JUMP = {
  TABLE = 0x02FB464,      -- the literal in IsSpeciesInJumpTable's pool
  ROWS = 100, STRIDE = 4, KINDS = 3,
}

function RomExtractorGen3:extractPokemonJump()
  self:beginStage("Gen3 Pokemon Jump")
  local J = RomExtractorGen3.POKEMON_JUMP
  local rom = self.rom
  if not self._speciesIds then return end
  local species, kinds, taken = {}, {}, {}
  for i = 0, J.ROWS - 1 do
    local o = J.TABLE + i * J.STRIDE
    local index = rom:u16(o)
    local kind = rom:u16(o + 2)
    local id = self._speciesIds[index]
    -- the shape is the check: a real species, a kind inside the three the
    -- minigame has, and no row repeated
    if not (id and kind < J.KINDS and not taken[index]) then
      Logger.warn("gen3 Pokemon Jump: row %d of %08X is species %d kind %d, "
                  .. "which is not a roster row -- the table is not read", i,
                  J.TABLE + 0x08000000, index, kind)
      return
    end
    taken[index] = true
    species[#species + 1] = id
    kinds[id] = kind
  end
  local constants = self._constants or {}
  constants.gen3PokemonJump = {
    species = species,
    kinds = kinds,
    source = ("ROM:sPokemonJumpSpecies %08X (%d rows of %d)")
             :format(J.TABLE + 0x08000000, J.ROWS, J.STRIDE),
  }
  self._constants = constants
  self:write("constants", constants)
  Logger.info("Gen3 Pokemon Jump: %d species may play, %s first",
              #species, tostring(species[1]))
end

-- ---------------------------------------------------------------------------
-- THE NATURE GIRL'S TWENTY-FIVE LINES
--
-- Special 454 (0813A7B8) is four steps and no state:
--
--     if VAR_0x8004 > 5: VAR_0x8004 = 0        @ a bad slot means the lead
--     nature = GetNature(&party[VAR_0x8004])
--     ShowFieldMessage(sNatureGirlMessages[nature])
--
-- so the whole of her is a table of twenty-five pointers at 085B3040, one a
-- nature, and the port had none of them: she stood there and said nothing.
--
-- TWENTY-FIVE IS PROVED BY THE STRINGS, and it has to be, because the
-- pointers do NOT tell you where the table stops: four of them repeat, and
-- the repeats are not where a reader expects them.  They land on natures 6,
-- 14, 17 and 24, which are not the five that change no stat -- her lines are
-- keyed on the raised and lowered stat reduced to three characters ("likes
-- to battle", "likes to be sneaky", "looks after itself"), so twenty-five
-- natures make only ten distinct lines and the assembler left the duplicates
-- unshared.  Reading a neutral-nature pattern into those four repeats would
-- have been a wrong answer wearing a right one's clothes.
--
-- What the table does say about itself is that every one of the twenty-five
-- opens the same way -- she has one greeting -- and the row after the last
-- does not.  So the count is checked by taking the common prefix of the
-- twenty-five and asking whether the twenty-sixth shares it, which is a
-- question the cartridge answers rather than one pret is asked.
-- ---------------------------------------------------------------------------

RomExtractorGen3.NATURE_GIRL = {
  TABLE = 0x05B3040,      -- sNatureGirlMessages, the literal in 0813A7B8's pool
  ROWS = 25,              -- one a nature
  TEXT = 256,
  MIN_PREFIX = 8,         -- a greeting, not an accident
}

-- ...on the class rather than as a file local: this file is one chunk and Lua
-- allows two hundred locals in it, a ceiling three earlier stages have
-- already met.
function RomExtractorGen3.commonPrefix(a, b)
  local n = 0
  while n < #a and n < #b and a:sub(n + 1, n + 1) == b:sub(n + 1, n + 1) do
    n = n + 1
  end
  return a:sub(1, n)
end

function RomExtractorGen3:extractNatureGirl()
  self:beginStage("Gen3 nature girl")
  local N = RomExtractorGen3.NATURE_GIRL
  local rom = self.rom
  local lines, prefix = {}, nil
  for i = 0, N.ROWS - 1 do
    local at = rom:pointer(N.TABLE + i * 4)
    local text = at and self:readText(at, N.TEXT)
    if not (text and #text > 0) then
      Logger.warn("gen3 nature girl: row %d of %08X reads no line, so she is "
                  .. "left silent", i, N.TABLE + 0x08000000)
      return
    end
    lines[i + 1] = text
    prefix = prefix and RomExtractorGen3.commonPrefix(prefix, text)
              or text
  end
  if #prefix < N.MIN_PREFIX then
    Logger.warn("gen3 nature girl: the twenty-five rows at %08X share only "
                .. "%d leading characters, which is not one speaker's -- "
                .. "nothing is written", N.TABLE + 0x08000000, #prefix)
    return
  end
  -- ...and the row after the last must NOT be one of hers, or the table runs
  -- on past where this reads it
  local after = rom:pointer(N.TABLE + N.ROWS * 4)
  local next_ = after and self:readText(after, N.TEXT)
  if next_ and next_:sub(1, #prefix) == prefix then
    Logger.warn("gen3 nature girl: row %d at %08X opens the same way as the "
                .. "twenty-five, so the table is longer than this reads it "
                .. "-- nothing is written", N.ROWS, N.TABLE + 0x08000000)
    return
  end
  local constants = self._constants or {}
  constants.gen3NatureGirl = {
    lines = lines,
    source = ("ROM:sNatureGirlMessages %08X (%d pointers)")
             :format(N.TABLE + 0x08000000, N.ROWS),
  }
  self._constants = constants
  self:write("constants", constants)
  local distinct, count = {}, 0
  for _, line in ipairs(lines) do
    if not distinct[line] then distinct[line] = true; count = count + 1 end
  end
  Logger.info("Gen3 nature girl: %d lines over %d natures, sharing %d "
              .. "leading characters", count, #lines, #prefix)
end

-- ---------------------------------------------------------------------------
-- HOENN'S TWELVE BALLS, AND THE ONE SUM THAT DECIDES A CATCH
--
-- Seven of Emerald's balls were not balls at all in this port: DIVE, LUXURY,
-- NEST, NET, PREMIER, REPEAT and TIMER are not in the Gen 1 name list
-- ItemEffects keys on, so throwing one did nothing.  The five that were
-- recognised then ran Gen 1's arithmetic -- randMax against a wobble divisor
-- -- which is not the sum Hoenn does.
--
-- Cmd_handleballthrow reads in two halves and BOTH are read here rather than
-- typed in.  Balls 2..5 take a CONSTANT bonus out of sBallCatchBonuses
-- (0831C48D, indexed ball - 2); balls 6..12 take a jump table
-- (080563F4, indexed ball - 6) and compute theirs:
--
--   NET     30 when the target's type1 or type2 is WATER or BUG, else 10
--   DIVE    35 when the map type is UNDERWATER, else 10
--   NEST    40 - level, never below 10
--   REPEAT  30 when the species is already caught, else 10
--   TIMER   the turn count + 10, capped at 40
--   LUXURY  and PREMIER share the plain branch: 10
--
-- ...AND THE LAST TWO ARE HOW THE READING PROVES ITSELF.  Past SAFARI the
-- bonus table holds 0, 0, 0, 61, 68, 61, 68 -- zeros where the code overrides
-- it and nonsense after that -- so the table alone cannot say where it stops.
-- The jump table can: its last two entries are the SAME ADDRESS, which is the
-- cartridge saying LUXURY and PREMIER behave alike, and seven entries landing
-- in one narrow window of code is not what a misplaced table looks like.
--
-- The bonus is a tenth: 10 is x1, 15 is x1.5, 35 is x3.5.  What the engine
-- then does with it is Gen3Catching's business; this stage only reads.
-- ---------------------------------------------------------------------------

RomExtractorGen3.BALLS = {
  COUNT = 12,                -- MASTER through PREMIER, item ids 1..12
  BONUS = 0x031C48D,         -- sBallCatchBonuses
  BONUS_FIRST = 2,           -- ...indexed ball - 2, from ULTRA
  BONUS_COUNT = 4,           -- and only four of its entries are real
  BONUS_EXPECT = { 20, 15, 10, 15 },
  JUMP = 0x00563F4,          -- the switch for the seven that compute theirs
  JUMP_FIRST = 6,            -- ...indexed ball - 6, from NET
  JUMP_COUNT = 7,
  JUMP_SPAN = 0x400,         -- all seven land inside this much code
  SCALE = 10,                -- a bonus is tenths
  PLAIN = 10,
  NET = 30, DIVE = 35, REPEAT = 30,
  NEST_FROM = 40, TIMER_ADD = 10, TIMER_CAP = 40,
  UNDERWATER = 5,            -- MAP_TYPE_UNDERWATER, GetCurrentMapType
  NET_TYPES = { 11, 6 },     -- WATER and BUG, by the cartridge's own numbers
  -- status1 & 0x27 doubles the odds; status1 & 0xD8 takes them to 15/10
  STATUS_DOUBLE = { "SLP", "FRZ" },
  STATUS_HALF = { "PSN", "BRN", "PAR", "TOX" },
}

function RomExtractorGen3:extractBalls()
  self:beginStage("Gen3 balls")
  local B = RomExtractorGen3.BALLS
  local rom = self.rom
  local constants = self._constants or {}
  local order = constants.itemOrder
  local items = self._items
  if not (type(order) == "table" and type(items) == "table") then
    Logger.warn("gen3 balls: the item table has to have been read first, so "
                .. "no ball is named")
    return
  end

  -- ---- the twelve, said by the items themselves --------------------------
  local ids = {}
  for i = 1, B.COUNT do
    local id = order[i]
    local def = id and items[id]
    if not (def and def.pocket == "BALL") then
      Logger.warn("gen3 balls: item %d is %s, which is not in the BALL "
                  .. "pocket -- the twelve are not items 1..%d and nothing "
                  .. "is written", i, tostring(id), B.COUNT)
      return
    end
    ids[i] = id
  end
  -- ...and nothing past them is one, which is what fixes the count
  local after = order[B.COUNT + 1]
  if after and items[after] and items[after].pocket == "BALL" then
    Logger.warn("gen3 balls: item %d is also a ball, so there are more than "
                .. "%d and this reads too few -- nothing is written",
                B.COUNT + 1, B.COUNT)
    return
  end

  -- ---- the four constant bonuses -----------------------------------------
  local bonus = {}
  for i = 0, B.BONUS_COUNT - 1 do
    local value = rom:u8(B.BONUS + i)
    if value ~= B.BONUS_EXPECT[i + 1] then
      Logger.warn("gen3 balls: sBallCatchBonuses[%d] at %08X reads %d and not "
                  .. "%d, so this is not the table -- nothing is written",
                  i, B.BONUS + 0x08000000, value, B.BONUS_EXPECT[i + 1])
      return
    end
    bonus[ids[B.BONUS_FIRST + i]] = value
  end

  -- ---- and the switch, which is what says where the table stops ----------
  local jump, lo, hi = {}, nil, nil
  for i = 0, B.JUMP_COUNT - 1 do
    local at = rom:pointer(B.JUMP + i * 4)
    if not at then
      Logger.warn("gen3 balls: the switch at %08X has no entry %d -- nothing "
                  .. "is written", B.JUMP + 0x08000000, i)
      return
    end
    jump[i + 1] = at
    lo = (lo == nil or at < lo) and at or lo
    hi = (hi == nil or at > hi) and at or hi
  end
  if hi - lo > B.JUMP_SPAN then
    Logger.warn("gen3 balls: the switch's seven entries span %d bytes, which "
                .. "is not one function -- nothing is written", hi - lo)
    return
  end
  -- LUXURY and PREMIER share the plain branch, and that is the reading's own
  -- proof: two balls the cartridge treats alike, one address apart from none
  if jump[6] ~= jump[7] then
    Logger.warn("gen3 balls: the switch sends LUXURY to %07X and PREMIER to "
                .. "%07X; the cartridge sends both to the same plain branch, "
                .. "so this is not the switch -- nothing is written",
                jump[6], jump[7])
    return
  end
  bonus[ids[11]] = B.PLAIN
  bonus[ids[12]] = B.PLAIN

  -- ---- the five that compute their own ------------------------------------
  local types = constants.typeOrder or {}
  local netTypes = {}
  for _, n in ipairs(B.NET_TYPES) do
    local id = types[n + 1]
    if not id then
      Logger.warn("gen3 balls: type %d has no name, so the NET BALL's rule "
                  .. "cannot be written", n)
      return
    end
    netTypes[#netTypes + 1] = id
  end

  local rule = {
    [ids[6]] = { kind = "type", types = netTypes, bonus = B.NET,
                 otherwise = B.PLAIN },
    [ids[7]] = { kind = "underwater", mapType = B.UNDERWATER, bonus = B.DIVE,
                 otherwise = B.PLAIN },
    [ids[8]] = { kind = "level", from = B.NEST_FROM, floor = B.PLAIN },
    [ids[9]] = { kind = "caught", bonus = B.REPEAT, otherwise = B.PLAIN },
    [ids[10]] = { kind = "turns", add = B.TIMER_ADD, cap = B.TIMER_CAP,
                  floor = B.PLAIN },
  }

  constants.gen3Balls = {
    order = ids,
    master = ids[1],
    bonus = bonus,
    rule = rule,
    scale = B.SCALE,
    -- the DIVE BALL's question, hoisted beside the rule that asks it: the
    -- caller has to answer "am I underwater" and the rule only says which
    -- map type counts
    underwaterType = B.UNDERWATER,
    statusDouble = B.STATUS_DOUBLE,
    statusHalf = B.STATUS_HALF,
    source = ("ROM:sBallCatchBonuses %08X (%d real entries) and the switch at "
              .. "%08X (%d entries, LUXURY and PREMIER sharing one)")
             :format(B.BONUS + 0x08000000, B.BONUS_COUNT,
                     B.JUMP + 0x08000000, B.JUMP_COUNT),
  }
  self._constants = constants
  self:write("constants", constants)
  Logger.info("Gen3 balls: %d, %s catches outright; NET x%.1f on %s, DIVE "
              .. "x%.1f underwater, TIMER up to x%.1f",
              B.COUNT, tostring(ids[1]), B.NET / B.SCALE,
              table.concat(netTypes, "/"), B.DIVE / B.SCALE,
              B.TIMER_CAP / B.SCALE)
end

-- ---------------------------------------------------------------------------
-- WHAT A POTION ACTUALLY DOES, and the thirty-seven other things beside it
--
-- ItemEffects' tables are Gen 1's and Gen 2's, keyed by name.  Emerald's items
-- carry no such key, so they matched by ACCIDENT wherever the slug happened to
-- agree -- POTION worked; ORAN BERRY, SITRUS BERRY, the five status berries,
-- ENERGY POWDER, ENERGY ROOT, HEAL POWDER, REVIVAL HERB, LAVA COOKIE, the
-- flutes and ZINC did nothing at all.  CALCIUM was worse than nothing: the Gen
-- 1 table sends it to "special", a stat a Gen 3 Pokemon does not have.
--
-- The numbers are gItemEffectTable (0831E58C), indexed item - 13, and the
-- reading of its bitfield is NOT guessed from the values.  GetItemEffectType
-- (081B7CEC) is a classifier over the same bytes and it names every bit by
-- the type it returns -- which is how CALCIUM is known to be SP.ATK
-- (effect[5] bit 3) rather than the "special" the Gen 1 table calls it:
--
--   effect[3]  the status cure mask -- 01 confusion, 02 paralysis, 04 freeze,
--              08 burn, 10 poison, 20 sleep (3F is all six); 40 level up;
--              80 mist
--   effect[4]  01 HP EV, 02 ATTACK EV, 04 heal HP, 08 restore PP on every
--              move, 10 restore PP on ONE (18 together is an ETHER), 20 PP
--              UP, 40 revive, 80 evolution stone
--   effect[5]  01 DEFENSE EV, 02 SPEED EV, 04 SP.DEF EV, 08 SP.ATK EV,
--              10 PP MAX, and 20/40/80 the three friendship deltas
--
-- THE ARGUMENTS FOLLOW FROM BYTE SIX, in that order: one amount if any amount
-- bit is set (revive shares the heal's, which is why REVIVAL HERB carries one
-- number and not two), then one byte per friendship bit.  An amount of FF is
-- "all of it" and FE is "half"; a byte over 127 in a friendship slot is
-- NEGATIVE, which is what makes the bitter herbs bitter.
--
-- Sixty-nine of the hundred and sixty-six entries carry a blob and this reads
-- every one of them.  A bit combination it has not been shown is REFUSED and
-- named rather than guessed at -- an item that does nothing is a bug you can
-- see, and an item that does the wrong thing is one you cannot.
-- ---------------------------------------------------------------------------

RomExtractorGen3.ITEM_EFFECTS = {
  TABLE = 0x031E58C,      -- gItemEffectTable
  FIRST = 13,             -- ...indexed item - ITEM_POTION
  COUNT = 166,
  ARGS_AT = 6,
  FULL = 0xFF, HALF = 0xFE, LEVEL_UP_HP = 0xFD, FULL_PP = 0x7F,
  -- effect[3]
  CURE = { [0x01] = "CONFUSION", [0x02] = "PAR", [0x04] = "FRZ",
           [0x08] = "BRN", [0x10] = "PSN", [0x20] = "SLP" },
  CURE_ALL = 0x3F, LEVEL_UP = 0x40, MIST = 0x80,
  -- effect[4]: which bit, what it is, and whether it eats an argument
  E4 = {
    [0x01] = { ev = "hp", amount = true },
    [0x02] = { ev = "attack", amount = true },
    [0x04] = { heal = true, amount = true },
    [0x08] = { pp = "all", amount = true },
    [0x10] = { pp = "one", amount = true },
    [0x20] = { ppUp = true },
    [0x40] = { revive = true },          -- shares the heal's argument
    [0x80] = { stone = true },
  },
  -- effect[5]
  E5 = {
    [0x01] = { ev = "defense", amount = true },
    [0x02] = { ev = "speed", amount = true },
    [0x04] = { ev = "spdef", amount = true },
    [0x08] = { ev = "spatk", amount = true },
    [0x10] = { ppMax = true },
  },
  FRIENDSHIP = { 0x20, 0x40, 0x80 },     -- low, middle and high friendship
  -- the three bytes in front of the cure mask are battle-only: the X items,
  -- DIRE HIT and RED FLUTE's infatuation.  Recognised so they are not
  -- refused, and recorded so the battle side can find them, but nothing here
  -- pretends to run them.
  BATTLE_ONLY = true,
}

-- a friendship byte, and the herbs are the reason it is signed.  On the class
-- rather than as a file local: this file is one chunk and Lua allows two
-- hundred locals in it, a ceiling several stages have already met.
function RomExtractorGen3.signedByte(v)
  v = math.floor(tonumber(v) or 0)
  return v > 127 and (v - 256) or v
end

function RomExtractorGen3:extractItemEffects()
  self:beginStage("Gen3 item effects")
  local E = RomExtractorGen3.ITEM_EFFECTS
  local rom = self.rom
  local constants = self._constants or {}
  local order = constants.itemOrder
  if type(order) ~= "table" then
    Logger.warn("gen3 item effects: the item table has to have been read "
                .. "first, so nothing is written")
    return
  end

  local out, read, refused = {}, 0, 0
  for k = 0, E.COUNT - 1 do
    local item = E.FIRST + k
    local id = order[item]
    local at = rom:pointer(E.TABLE + k * 4)
    if id and at then
      local b = {}
      for i = 0, 5 do b[i] = rom:u8(at + i) end
      local effect, arg, ok = { source = ("ROM:gItemEffectTable[%d] %08X")
                                         :format(k, at + 0x08000000) }, E.ARGS_AT, true

      -- ---- the battle-only three, recorded and not run ------------------
      if b[0] % 0x40 ~= 0 or b[1] ~= 0 or b[2] ~= 0 then
        effect.battle = true
      end
      if b[0] % 0x80 >= 0x40 then effect.sacredAsh = true end
      if b[0] >= 0x80 then effect.infatuation = true end

      -- ---- the cure mask -------------------------------------------------
      local mask = b[3] % 0x40
      if mask == E.CURE_ALL then
        effect.cureAll = true
      elseif mask ~= 0 then
        local cures = {}
        for bit, name in pairs(E.CURE) do
          if math.floor(mask / bit) % 2 == 1 then cures[#cures + 1] = name end
        end
        table.sort(cures)
        effect.cures = cures
      end
      if math.floor(b[3] / E.LEVEL_UP) % 2 == 1 then effect.levelUp = true end
      if math.floor(b[3] / E.MIST) % 2 == 1 then effect.mist = true end

      -- ---- the amount bits, in order, and the ONE argument they share ----
      local wantsAmount = false
      for _, pair in ipairs({ { b[4], E.E4 }, { b[5], E.E5 } }) do
        local value, table_ = pair[1], pair[2]
        for bit = 0, 7 do
          local flag = 2 ^ bit
          if math.floor(value / flag) % 2 == 1 then
            local meaning = table_[flag]
            -- the three friendship bits live in effect[5] alongside the EV
            -- ones and are consumed below rather than here, so they are
            -- KNOWN and not a refusal
            if not meaning and table_ == E.E5
               and (flag == 0x20 or flag == 0x40 or flag == 0x80) then
              meaning = false
            end
            if meaning == nil then
              ok = false
            elseif meaning then
              if meaning.ev then effect.ev = meaning.ev end
              if meaning.heal then effect.heal = true end
              if meaning.pp then effect.pp = meaning.pp end
              if meaning.ppUp then effect.ppUp = true end
              if meaning.ppMax then effect.ppMax = true end
              if meaning.revive then effect.revive = true end
              if meaning.stone then effect.stone = true end
              if meaning.amount then wantsAmount = true end
            end
          end
        end
      end
      if not ok then
        Logger.warn("gen3 item effects: %s (item %d) sets a bit this reads no "
                    .. "meaning for (%02X %02X %02X %02X %02X %02X) -- it is "
                    .. "left out rather than guessed at", tostring(id), item,
                    b[0], b[1], b[2], b[3], b[4], b[5])
        refused = refused + 1
      else
        if wantsAmount then
          local value = rom:u8(at + arg)
          arg = arg + 1
          if effect.ev then
            effect.amount = RomExtractorGen3.signedByte(value)
          elseif effect.pp then
            effect.amount = (value == E.FULL_PP) and "all" or value
          elseif effect.levelUp then
            effect.amount = "levelUp"
          elseif value == E.FULL then
            effect.amount = "all"
          elseif value == E.HALF then
            effect.amount = "half"
          else
            effect.amount = value
          end
        end
        local friendship = {}
        for _, flag in ipairs(E.FRIENDSHIP) do
          if math.floor(b[5] / flag) % 2 == 1 then
            friendship[#friendship + 1] =
              RomExtractorGen3.signedByte(rom:u8(at + arg))
            arg = arg + 1
          end
        end
        if #friendship > 0 then effect.friendship = friendship end
        out[id] = effect
        read = read + 1
      end
    end
  end

  if read == 0 then
    Logger.warn("gen3 item effects: not one of the %d entries read, so the "
                .. "table is not at %08X -- nothing is written", E.COUNT,
                E.TABLE + 0x08000000)
    return
  end
  constants.gen3ItemEffects = out
  constants.gen3ItemEffectSource =
    ("ROM:gItemEffectTable %08X (%d entries from item %d), read against "
     .. "GetItemEffectType 081B7CEC")
    :format(E.TABLE + 0x08000000, E.COUNT, E.FIRST)
  self._constants = constants
  self:write("constants", constants)
  Logger.info("Gen3 item effects: %d items do something, %d refused", read,
              refused)
end

